#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TraceEncryptedObjectStoreKind {
    LegacyArtifactSidecar,
    ServiceLocal,
    ServiceRemote,
}

impl TraceEncryptedObjectStoreKind {
    fn from_config(
        raw_mode: Option<&str>,
        encrypted_artifacts_requested: bool,
    ) -> anyhow::Result<Option<Self>> {
        let Some(raw_mode) = raw_mode else {
            return Ok(encrypted_artifacts_requested.then_some(Self::LegacyArtifactSidecar));
        };
        let normalized = raw_mode.trim().to_ascii_lowercase();
        match normalized.as_str() {
            "" => Ok(encrypted_artifacts_requested.then_some(Self::LegacyArtifactSidecar)),
            "file" | "none" => Ok(None),
            "local_encrypted" | "encrypted_artifact" => Ok(Some(Self::LegacyArtifactSidecar)),
            "local_service" | "local_service_encrypted" | "service_local_encrypted" => {
                Ok(Some(Self::ServiceLocal))
            }
            "remote_service"
            | "service_remote"
            | "service_owned_remote"
            | "remote_service_owned" => Ok(Some(Self::ServiceRemote)),
            other => anyhow::bail!("unsupported TRACE_COMMONS_OBJECT_STORE value: {other}"),
        }
    }

    fn object_store_name(self) -> &'static str {
        match self {
            Self::LegacyArtifactSidecar => TRACE_COMMONS_LEGACY_ENCRYPTED_OBJECT_STORE,
            Self::ServiceLocal => TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE,
            Self::ServiceRemote => TRACE_COMMONS_SERVICE_REMOTE_OBJECT_STORE,
        }
    }

    fn root_from_env(self, default_root: &Path) -> PathBuf {
        match self {
            Self::LegacyArtifactSidecar => std::env::var("TRACE_COMMONS_ARTIFACT_DIR")
                .map(PathBuf::from)
                .unwrap_or_else(|_| default_root.join("encrypted_artifacts")),
            Self::ServiceLocal => std::env::var("TRACE_COMMONS_SERVICE_OBJECT_STORE_DIR")
                .or_else(|_| std::env::var("TRACE_COMMONS_ARTIFACT_DIR"))
                .map(PathBuf::from)
                .unwrap_or_else(|_| default_root.join("service_object_store")),
            Self::ServiceRemote => default_root.join("remote_object_store_disabled"),
        }
    }
}

#[derive(Debug, Clone)]
struct TenantAuth {
    tenant_id: String,
    role: TokenRole,
    principal_ref: String,
    expires_at: Option<DateTime<Utc>>,
    auth_method: TraceAuthMethod,
    signed_claim_issuer: Option<String>,
    signed_claim_audiences: BTreeSet<String>,
    signed_claim_subject: Option<String>,
    allowed_consent_scopes: BTreeSet<ConsentScope>,
    allowed_uses: BTreeSet<TraceAllowedUse>,
}

#[derive(Debug, Clone)]
struct TenantCtx {
    auth: TenantAuth,
}

impl TenantCtx {
    fn from_auth(auth: TenantAuth) -> Self {
        Self { auth }
    }

    fn auth(&self) -> &TenantAuth {
        &self.auth
    }

    fn tenant_id(&self) -> &str {
        &self.auth.tenant_id
    }

    fn role(&self) -> TokenRole {
        self.auth.role
    }

    fn principal_ref(&self) -> &str {
        &self.auth.principal_ref
    }

    fn tenant_storage_ref(&self) -> String {
        tenant_storage_ref(self.tenant_id())
    }

    fn safe_auth_method(&self) -> TraceAuthMethod {
        self.auth.auth_method
    }

    fn auth_method_reason(&self) -> String {
        format!("auth_method={}", self.safe_auth_method().storage_name())
    }

    fn submitted_tenant_scope_ref(&self) -> Option<String> {
        Some(self.tenant_storage_ref())
    }

    fn allowed_consent_scopes(&self) -> &BTreeSet<ConsentScope> {
        &self.auth.allowed_consent_scopes
    }

    fn allowed_uses(&self) -> &BTreeSet<TraceAllowedUse> {
        &self.auth.allowed_uses
    }

    fn can_access_submission(&self, record: &TraceCommonsSubmissionRecord) -> bool {
        can_access_submission(self.auth(), record)
    }

    fn can_access_storage_submission(&self, record: &StorageTraceSubmissionRecord) -> bool {
        can_access_storage_submission(self.auth(), record)
    }

    fn read_submission_record(
        &self,
        root: &Path,
        submission_id: Uuid,
    ) -> anyhow::Result<Option<TraceCommonsSubmissionRecord>> {
        read_submission_record(root, self.tenant_id(), submission_id)
    }

    fn read_derived_record(
        &self,
        root: &Path,
        submission_id: Uuid,
    ) -> anyhow::Result<Option<TraceCommonsDerivedRecord>> {
        read_derived_record(root, self.tenant_id(), submission_id)
    }

    fn idempotent_submit_audit_event(&self, submission_id: Uuid) -> TraceCommonsAuditEvent {
        TraceCommonsAuditEvent::idempotent_submit(self.auth(), submission_id)
    }

    fn submitted_audit_event(
        &self,
        record: &TraceCommonsSubmissionRecord,
    ) -> TraceCommonsAuditEvent {
        let mut event = TraceCommonsAuditEvent::submitted(record, self.auth());
        event.reason = Some(self.auth_method_reason());
        event
    }

    fn revoked_audit_event(&self, submission_id: Uuid, reason: &str) -> TraceCommonsAuditEvent {
        TraceCommonsAuditEvent::revoked(self.auth(), submission_id, reason)
    }

    fn read_audit_event(&self, surface: &str, item_count: usize) -> TraceCommonsAuditEvent {
        TraceCommonsAuditEvent::read(self.auth(), surface, item_count)
    }
}

