fn parse_tenant_tokens_from_env() -> anyhow::Result<BTreeMap<String, TenantAuth>> {
    let mut tokens = BTreeMap::new();
    if let Ok(configured) = std::env::var("TRACE_COMMONS_TENANT_TOKENS") {
        tokens.extend(parse_tenant_tokens(&configured)?);
    }

    if let Ok(token) = std::env::var("TRACE_COMMONS_INGEST_TOKEN") {
        let (token, expires_at) = parse_token_secret_and_expiry(&token)?;
        insert_token_with_expiry(
            &mut tokens,
            "default",
            &token,
            TokenRole::Contributor,
            expires_at,
        )?;
    }

    Ok(tokens)
}

fn parse_tenant_tokens(configured: &str) -> anyhow::Result<BTreeMap<String, TenantAuth>> {
    let mut tokens = BTreeMap::new();
    parse_tenant_token_entries(configured, &mut tokens)?;
    Ok(tokens)
}

fn parse_tenant_token_entries(
    configured: &str,
    tokens: &mut BTreeMap<String, TenantAuth>,
) -> anyhow::Result<()> {
    for pair in configured.split(',') {
        let pair = pair.trim();
        if pair.is_empty() {
            continue;
        }
        let Some((tenant_id, auth_spec)) = pair.split_once(':') else {
            anyhow::bail!(
                "TRACE_COMMONS_TENANT_TOKENS entries must use tenant_id:token or tenant_id:role:token syntax"
            );
        };

        let auth_spec = auth_spec.trim();
        let (role, token_spec) = match auth_spec.split_once(':') {
            Some((maybe_role, token_spec)) if !maybe_role.contains(';') => {
                (TokenRole::parse(maybe_role)?, token_spec)
            }
            _ => (TokenRole::Contributor, auth_spec),
        };
        let (token, expires_at) = parse_token_secret_and_expiry(token_spec)?;
        insert_token_with_expiry(tokens, tenant_id, &token, role, expires_at)?;
    }
    Ok(())
}

fn parse_token_secret_and_expiry(raw: &str) -> anyhow::Result<(String, Option<DateTime<Utc>>)> {
    let mut parts = raw.split(';');
    let token = parts.next().unwrap_or_default().trim();
    if token.is_empty() {
        anyhow::bail!("TRACE_COMMONS_TENANT_TOKENS entries must include a non-empty token");
    }

    let mut expires_at = None;
    for attribute in parts {
        let attribute = attribute.trim();
        if attribute.is_empty() {
            continue;
        }
        let Some((key, value)) = attribute.split_once('=') else {
            anyhow::bail!("TRACE_COMMONS_TENANT_TOKENS token attributes must use key=value syntax");
        };
        let key = key.trim();
        let value = value.trim();
        match key {
            "expires" | "expires_at" => {
                if expires_at.is_some() {
                    anyhow::bail!(
                        "TRACE_COMMONS_TENANT_TOKENS token expiry must be configured at most once"
                    );
                }
                let parsed = DateTime::parse_from_rfc3339(value)
                    .context(
                        "TRACE_COMMONS_TENANT_TOKENS expires_at attributes must be RFC3339 timestamps",
                    )?
                    .with_timezone(&Utc);
                expires_at = Some(parsed);
            }
            other => {
                anyhow::bail!("unknown TRACE_COMMONS_TENANT_TOKENS token attribute: {other}");
            }
        }
    }

    Ok((token.to_string(), expires_at))
}

fn shared_signed_token_verifier(
    verifier: TraceCommonsSignedTokenVerifier,
) -> SharedTraceCommonsSignedTokenVerifier {
    Arc::new(RwLock::new(verifier))
}

async fn trace_commons_signed_token_verifier_from_env()
-> anyhow::Result<TraceCommonsSignedTokenVerifierEnvConfig> {
    let default_secret = match std::env::var(TRACE_COMMONS_SIGNED_TOKEN_SECRET) {
        Ok(secret) => {
            let secret = secret.trim();
            if secret.is_empty() {
                anyhow::bail!("{TRACE_COMMONS_SIGNED_TOKEN_SECRET} must not be empty");
            }
            Some(SecretString::from(secret.to_string()))
        }
        Err(std::env::VarError::NotPresent) => None,
        Err(error) => {
            return Err(error)
                .with_context(|| format!("failed to read {TRACE_COMMONS_SIGNED_TOKEN_SECRET}"));
        }
    };
    let keyed_secrets = parse_signed_token_keyed_secrets_from_env()?;
    let default_eddsa_public_key = parse_signed_token_default_eddsa_public_key_from_env()?;
    let mut keyed_eddsa_public_keys = parse_signed_token_keyed_eddsa_public_key_files_from_env()?;
    let managed_eddsa_keyset = parse_signed_token_eddsa_keyset_from_env().await?;
    let managed_eddsa_public_keys = managed_eddsa_keyset.keys;
    let managed_eddsa_key_ids = managed_eddsa_public_keys.keys().cloned().collect();
    for (kid, key) in managed_eddsa_public_keys {
        if keyed_eddsa_public_keys.insert(kid.clone(), key).is_some() {
            anyhow::bail!("signed tenant token EdDSA key id {kid} is configured more than once");
        }
    }
    for kid in keyed_secrets.keys() {
        anyhow::ensure!(
            !keyed_eddsa_public_keys.contains_key(kid),
            "signed tenant token key id {kid} is configured for both HMAC and EdDSA"
        );
    }

    if default_secret.is_none()
        && keyed_secrets.is_empty()
        && default_eddsa_public_key.is_none()
        && keyed_eddsa_public_keys.is_empty()
    {
        return Ok(TraceCommonsSignedTokenVerifierEnvConfig {
            verifier: None,
            managed_eddsa_keyset_refresh: None,
        });
    }

    Ok(TraceCommonsSignedTokenVerifierEnvConfig {
        verifier: Some(TraceCommonsSignedTokenVerifier {
            default_secret,
            keyed_secrets,
            default_eddsa_public_key,
            keyed_eddsa_public_keys,
            managed_eddsa_key_ids,
            managed_eddsa_keyset_last_refreshed_at: managed_eddsa_keyset.fetched_at,
            managed_eddsa_keyset_last_refresh_failed_at: None,
            issuer: optional_trimmed_env(TRACE_COMMONS_SIGNED_TOKEN_ISSUER)?,
            audience: optional_trimmed_env(TRACE_COMMONS_SIGNED_TOKEN_AUDIENCE)?,
            revoked_jtis: parse_signed_token_revoked_jtis_from_env()?,
            max_ttl_seconds: parse_signed_token_max_ttl_seconds_from_env()?,
            require_jti: env_truthy(TRACE_COMMONS_SIGNED_TOKEN_REQUIRE_JTI),
        }),
        managed_eddsa_keyset_refresh: managed_eddsa_keyset.refresh,
    })
}

fn validate_required_eddsa_signed_tokens_config(
    enabled: bool,
    verifier: Option<&TraceCommonsSignedTokenVerifier>,
) -> anyhow::Result<()> {
    if !enabled {
        return Ok(());
    }
    let eddsa_key_count = verifier.map_or(
        0,
        TraceCommonsSignedTokenVerifier::configured_eddsa_key_count,
    );
    anyhow::ensure!(
        eddsa_key_count > 0,
        "{TRACE_COMMONS_REQUIRE_EDDSA_SIGNED_TOKENS} requires a configured EdDSA/Ed25519 public key"
    );
    Ok(())
}

fn validate_required_managed_eddsa_signed_tokens_config(
    enabled: bool,
    verifier: Option<&TraceCommonsSignedTokenVerifier>,
) -> anyhow::Result<()> {
    if !enabled {
        return Ok(());
    }
    let verifier = verifier.ok_or_else(|| {
        anyhow::anyhow!(
            "{TRACE_COMMONS_REQUIRE_MANAGED_EDDSA_SIGNED_TOKENS} requires signed token verification"
        )
    })?;
    anyhow::ensure!(
        verifier.default_secret.is_none() && verifier.keyed_secrets.is_empty(),
        "{TRACE_COMMONS_REQUIRE_MANAGED_EDDSA_SIGNED_TOKENS} rejects HS256 signed-token secrets"
    );
    anyhow::ensure!(
        verifier.default_eddsa_public_key.is_none(),
        "{TRACE_COMMONS_REQUIRE_MANAGED_EDDSA_SIGNED_TOKENS} requires keyed EdDSA keyset keys, not a default EdDSA key"
    );
    anyhow::ensure!(
        !verifier.managed_eddsa_key_ids.is_empty(),
        "{TRACE_COMMONS_REQUIRE_MANAGED_EDDSA_SIGNED_TOKENS} requires TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_JSON, TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_FILE, or TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL"
    );
    anyhow::ensure!(
        verifier.keyed_eddsa_public_keys.len() == verifier.managed_eddsa_key_ids.len()
            && verifier
                .keyed_eddsa_public_keys
                .keys()
                .all(|kid| verifier.managed_eddsa_key_ids.contains(kid)),
        "{TRACE_COMMONS_REQUIRE_MANAGED_EDDSA_SIGNED_TOKENS} requires all EdDSA keys to come from the managed keyset"
    );
    anyhow::ensure!(
        verifier
            .issuer
            .as_ref()
            .is_some_and(|issuer| !issuer.is_empty()),
        "{TRACE_COMMONS_REQUIRE_MANAGED_EDDSA_SIGNED_TOKENS} requires TRACE_COMMONS_SIGNED_TOKEN_ISSUER"
    );
    anyhow::ensure!(
        verifier
            .audience
            .as_ref()
            .is_some_and(|audience| !audience.is_empty()),
        "{TRACE_COMMONS_REQUIRE_MANAGED_EDDSA_SIGNED_TOKENS} requires TRACE_COMMONS_SIGNED_TOKEN_AUDIENCE"
    );
    let active_managed_keys = verifier.configured_active_managed_eddsa_key_count(Utc::now());
    anyhow::ensure!(
        active_managed_keys > 0,
        "{TRACE_COMMONS_REQUIRE_MANAGED_EDDSA_SIGNED_TOKENS} requires at least one active managed EdDSA key"
    );
    Ok(())
}

fn parse_signed_token_keyed_secrets_from_env() -> anyhow::Result<BTreeMap<String, SecretString>> {
    let configured = match std::env::var(TRACE_COMMONS_SIGNED_TOKEN_SECRETS) {
        Ok(configured) => configured,
        Err(std::env::VarError::NotPresent) => return Ok(BTreeMap::new()),
        Err(error) => {
            return Err(error)
                .with_context(|| format!("failed to read {TRACE_COMMONS_SIGNED_TOKEN_SECRETS}"));
        }
    };
    let mut secrets = BTreeMap::new();
    for entry in configured.split(',').map(str::trim) {
        if entry.is_empty() {
            continue;
        }
        let Some((kid, secret)) = entry.split_once(':') else {
            anyhow::bail!(
                "{TRACE_COMMONS_SIGNED_TOKEN_SECRETS} entries must use kid:secret syntax"
            );
        };
        let kid = kid.trim();
        let secret = secret.trim();
        if kid.is_empty() || secret.is_empty() {
            anyhow::bail!(
                "{TRACE_COMMONS_SIGNED_TOKEN_SECRETS} entries must include non-empty kid and secret"
            );
        }
        secrets.insert(kid.to_string(), SecretString::from(secret.to_string()));
    }
    Ok(secrets)
}

fn parse_signed_token_default_eddsa_public_key_from_env()
-> anyhow::Result<Option<TraceCommonsSignedEddsaPublicKey>> {
    let inline = optional_trimmed_env(TRACE_COMMONS_SIGNED_TOKEN_EDDSA_PUBLIC_KEY_PEM)?;
    let file = optional_trimmed_env(TRACE_COMMONS_SIGNED_TOKEN_EDDSA_PUBLIC_KEY_FILE)?;
    match (inline, file) {
        (Some(_), Some(_)) => anyhow::bail!(
            "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_PUBLIC_KEY_PEM} and {TRACE_COMMONS_SIGNED_TOKEN_EDDSA_PUBLIC_KEY_FILE} cannot both be configured"
        ),
        (Some(pem), None) => Ok(Some(TraceCommonsSignedEddsaPublicKey {
            pem,
            not_before: None,
            not_after: None,
        })),
        (None, Some(path)) => Ok(Some(TraceCommonsSignedEddsaPublicKey {
            pem: read_eddsa_public_key_file(&path)?,
            not_before: None,
            not_after: None,
        })),
        (None, None) => Ok(None),
    }
}

fn parse_signed_token_keyed_eddsa_public_key_files_from_env()
-> anyhow::Result<BTreeMap<String, TraceCommonsSignedEddsaPublicKey>> {
    let configured = match std::env::var(TRACE_COMMONS_SIGNED_TOKEN_EDDSA_PUBLIC_KEY_FILES) {
        Ok(configured) => configured,
        Err(std::env::VarError::NotPresent) => return Ok(BTreeMap::new()),
        Err(error) => {
            return Err(error).with_context(|| {
                format!("failed to read {TRACE_COMMONS_SIGNED_TOKEN_EDDSA_PUBLIC_KEY_FILES}")
            });
        }
    };
    let mut keys = BTreeMap::new();
    for entry in configured.split(',').map(str::trim) {
        if entry.is_empty() {
            continue;
        }
        let Some((kid, path)) = entry.split_once(':') else {
            anyhow::bail!(
                "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_PUBLIC_KEY_FILES} entries must use kid:path syntax"
            );
        };
        let kid = kid.trim();
        let path = path.trim();
        if kid.is_empty() || path.is_empty() {
            anyhow::bail!(
                "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_PUBLIC_KEY_FILES} entries must include non-empty kid and path"
            );
        }
        if keys
            .insert(
                kid.to_string(),
                TraceCommonsSignedEddsaPublicKey {
                    pem: read_eddsa_public_key_file(path)?,
                    not_before: None,
                    not_after: None,
                },
            )
            .is_some()
        {
            anyhow::bail!(
                "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_PUBLIC_KEY_FILES} contains duplicate kid {kid}"
            );
        }
    }
    Ok(keys)
}

async fn parse_signed_token_eddsa_keyset_from_env()
-> anyhow::Result<TraceCommonsSignedEddsaKeysetEnvConfig> {
    let inline = optional_trimmed_env(TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_JSON)?;
    let file = optional_trimmed_env(TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_FILE)?;
    let url = optional_trimmed_env(TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL)?;
    ensure_single_eddsa_keyset_source(inline.is_some(), file.is_some(), url.is_some())?;
    match (inline, file, url) {
        (Some(configured), None, None) => Ok(TraceCommonsSignedEddsaKeysetEnvConfig {
            keys: parse_signed_token_eddsa_keyset_config(&configured)?,
            refresh: None,
            fetched_at: None,
        }),
        (None, Some(path), None) => {
            let configured = std::fs::read_to_string(&path)
                .with_context(|| format!("failed to read EdDSA keyset file {path}"))?;
            Ok(TraceCommonsSignedEddsaKeysetEnvConfig {
                keys: parse_signed_token_eddsa_keyset_config(&configured)?,
                refresh: None,
                fetched_at: None,
            })
        }
        (None, None, Some(url)) => {
            let refresh = parse_signed_token_eddsa_keyset_refresh_config_from_env(url)?;
            let configured = fetch_signed_token_eddsa_keyset_url_with_config(&refresh).await?;
            Ok(TraceCommonsSignedEddsaKeysetEnvConfig {
                keys: parse_signed_token_eddsa_keyset_config(&configured)?,
                refresh: Some(refresh),
                fetched_at: Some(Utc::now()),
            })
        }
        (None, None, None) => Ok(TraceCommonsSignedEddsaKeysetEnvConfig {
            keys: BTreeMap::new(),
            refresh: None,
            fetched_at: None,
        }),
        _ => unreachable!("ensure_single_eddsa_keyset_source rejects multiple keyset sources"),
    }
}

fn ensure_single_eddsa_keyset_source(inline: bool, file: bool, url: bool) -> anyhow::Result<()> {
    let configured_count = usize::from(inline) + usize::from(file) + usize::from(url);
    anyhow::ensure!(
        configured_count <= 1,
        "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_JSON}, {TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_FILE}, and {TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL} are mutually exclusive"
    );
    Ok(())
}

fn parse_signed_token_eddsa_keyset_refresh_config_from_env(
    url: String,
) -> anyhow::Result<TraceCommonsManagedEddsaKeysetRefreshConfig> {
    Ok(TraceCommonsManagedEddsaKeysetRefreshConfig {
        url,
        allowed_hosts: parse_signed_token_eddsa_keyset_url_allowed_hosts_from_env()?,
        bearer_token: optional_trimmed_env(TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_BEARER_TOKEN)?
            .map(SecretString::from),
        timeout: parse_signed_token_eddsa_keyset_url_timeout_from_env()?,
        refresh_interval: parse_signed_token_eddsa_keyset_refresh_interval_from_env()?,
        max_stale: parse_signed_token_eddsa_keyset_max_stale_from_env()?,
    })
}

async fn fetch_signed_token_eddsa_keyset_url_with_config(
    refresh: &TraceCommonsManagedEddsaKeysetRefreshConfig,
) -> anyhow::Result<String> {
    let parsed = reqwest::Url::parse(&refresh.url)
        .with_context(|| format!("invalid {TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL}"))?;
    validate_signed_token_eddsa_keyset_url(&parsed, &refresh.allowed_hosts)?;
    let host = parsed
        .host_str()
        .ok_or_else(|| {
            anyhow::anyhow!("{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL} requires a host")
        })?
        .to_ascii_lowercase();
    let port = parsed.port_or_known_default().ok_or_else(|| {
        anyhow::anyhow!("{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL} requires a known port")
    })?;
    let resolved_addrs = resolve_signed_token_eddsa_keyset_url_host(&host, port).await?;
    let client = reqwest::Client::builder()
        .timeout(refresh.timeout)
        .connect_timeout(refresh.timeout.min(StdDuration::from_secs(3)))
        .redirect(reqwest::redirect::Policy::none())
        .user_agent("ironclaw-trace-commons-keyset/0.1")
        .resolve_to_addrs(&host, &resolved_addrs)
        .build()
        .context("failed to build EdDSA keyset HTTP client")?;
    let mut request = client
        .get(parsed.clone())
        .header(reqwest::header::ACCEPT, "application/json");
    if let Some(bearer_token) = &refresh.bearer_token {
        request = request.bearer_auth(bearer_token.expose_secret());
    }
    let response = request.send().await.with_context(|| {
        format!(
            "failed to fetch EdDSA keyset from {}",
            safe_keyset_url_label(&parsed)
        )
    })?;
    let status = response.status();
    anyhow::ensure!(
        status.is_success(),
        "failed to fetch EdDSA keyset from {}: HTTP {}",
        safe_keyset_url_label(&parsed),
        status.as_u16()
    );
    if let Some(content_length) = response.content_length() {
        anyhow::ensure!(
            content_length <= MAX_EDDSA_KEYSET_URL_BYTES as u64,
            "EdDSA keyset response from {} exceeded {} bytes",
            safe_keyset_url_label(&parsed),
            MAX_EDDSA_KEYSET_URL_BYTES
        );
    }
    let mut response = response;
    let mut bytes = Vec::new();
    while let Some(chunk) = response.chunk().await.with_context(|| {
        format!(
            "failed to read EdDSA keyset response from {}",
            safe_keyset_url_label(&parsed)
        )
    })? {
        bytes.extend_from_slice(&chunk);
        anyhow::ensure!(
            bytes.len() <= MAX_EDDSA_KEYSET_URL_BYTES,
            "EdDSA keyset response from {} exceeded {} bytes",
            safe_keyset_url_label(&parsed),
            MAX_EDDSA_KEYSET_URL_BYTES
        );
    }
    anyhow::ensure!(
        bytes.len() <= MAX_EDDSA_KEYSET_URL_BYTES,
        "EdDSA keyset response from {} exceeded {} bytes",
        safe_keyset_url_label(&parsed),
        MAX_EDDSA_KEYSET_URL_BYTES
    );
    String::from_utf8(bytes).with_context(|| {
        format!(
            "EdDSA keyset response from {} was not valid UTF-8",
            safe_keyset_url_label(&parsed)
        )
    })
}

fn parse_signed_token_eddsa_keyset_url_allowed_hosts_from_env() -> anyhow::Result<BTreeSet<String>>
{
    let configured =
        match optional_trimmed_env(TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL_ALLOWED_HOSTS)? {
            Some(configured) => configured,
            None => return Ok(BTreeSet::new()),
        };
    parse_signed_token_eddsa_keyset_url_allowed_hosts(&configured)
}

fn parse_signed_token_eddsa_keyset_url_allowed_hosts(
    configured: &str,
) -> anyhow::Result<BTreeSet<String>> {
    let mut hosts = BTreeSet::new();
    for host in configured
        .split(',')
        .map(str::trim)
        .filter(|host| !host.is_empty())
    {
        anyhow::ensure!(
            !host.contains('/') && !host.contains(':') && !host.contains('@'),
            "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL_ALLOWED_HOSTS} entries must be hostnames without scheme, port, or credentials"
        );
        hosts.insert(host.to_ascii_lowercase());
    }
    Ok(hosts)
}

fn validate_signed_token_eddsa_keyset_url(
    url: &reqwest::Url,
    allowed_hosts: &BTreeSet<String>,
) -> anyhow::Result<()> {
    anyhow::ensure!(
        url.scheme() == "https",
        "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL} must use https"
    );
    anyhow::ensure!(
        url.username().is_empty() && url.password().is_none(),
        "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL} must not include embedded credentials"
    );
    anyhow::ensure!(
        url.query().is_none() && url.fragment().is_none(),
        "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL} must not include query strings or fragments"
    );
    let host = url.host_str().map(str::to_ascii_lowercase).ok_or_else(|| {
        anyhow::anyhow!("{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL} requires a host")
    })?;
    anyhow::ensure!(
        !is_internal_keyset_hostname(&host),
        "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL} must not use localhost or internal hostnames"
    );
    if let Ok(ip) = host.parse::<IpAddr>() {
        anyhow::ensure!(
            !is_disallowed_keyset_ip(ip),
            "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL} must not use private, local, or reserved IP addresses"
        );
    }
    anyhow::ensure!(
        !allowed_hosts.is_empty(),
        "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL} requires {TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL_ALLOWED_HOSTS}"
    );
    anyhow::ensure!(
        allowed_hosts.contains(&host),
        "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL} host is not allowlisted"
    );
    Ok(())
}

async fn resolve_signed_token_eddsa_keyset_url_host(
    host: &str,
    port: u16,
) -> anyhow::Result<Vec<SocketAddr>> {
    let addrs: Vec<SocketAddr> = tokio::net::lookup_host((host, port))
        .await
        .with_context(|| format!("failed to resolve EdDSA keyset host {host}"))?
        .collect();
    anyhow::ensure!(
        !addrs.is_empty(),
        "EdDSA keyset host {host} resolved to no addresses"
    );
    for addr in &addrs {
        anyhow::ensure!(
            !is_disallowed_keyset_ip(addr.ip()),
            "EdDSA keyset host {host} resolved to disallowed address"
        );
    }
    Ok(addrs)
}

fn is_internal_keyset_hostname(host: &str) -> bool {
    let host = host.trim_end_matches('.').to_ascii_lowercase();
    host == "localhost"
        || host.ends_with(".localhost")
        || host.ends_with(".local")
        || host.ends_with(".internal")
        || host == "metadata.google.internal"
}

fn is_disallowed_keyset_ip(ip: IpAddr) -> bool {
    match normalize_keyset_ip(ip) {
        IpAddr::V4(v4) => {
            let octets = v4.octets();
            octets[0] == 0
                || octets[0] == 10
                || octets[0] == 127
                || (octets[0] == 100 && (64..=127).contains(&octets[1]))
                || (octets[0] == 169 && octets[1] == 254)
                || (octets[0] == 172 && (16..=31).contains(&octets[1]))
                || (octets[0] == 192 && octets[1] == 168)
                || (octets[0] == 198 && (18..=19).contains(&octets[1]))
                || octets[0] >= 224
        }
        IpAddr::V6(v6) => {
            let segments = v6.segments();
            v6.is_loopback()
                || v6.is_unspecified()
                || (segments[0] & 0xfe00) == 0xfc00
                || (segments[0] & 0xffc0) == 0xfe80
                || (segments[0] & 0xff00) == 0xff00
        }
    }
}

fn normalize_keyset_ip(ip: IpAddr) -> IpAddr {
    match ip {
        IpAddr::V4(v4) => IpAddr::V4(v4),
        IpAddr::V6(v6) => v6
            .to_ipv4_mapped()
            .map(IpAddr::V4)
            .unwrap_or(IpAddr::V6(v6)),
    }
}

fn parse_signed_token_eddsa_keyset_url_timeout_from_env() -> anyhow::Result<StdDuration> {
    let timeout_ms =
        match optional_trimmed_env(TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL_TIMEOUT_MS)? {
            Some(configured) => configured.parse::<u64>().with_context(|| {
                format!(
                    "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL_TIMEOUT_MS} must be milliseconds"
                )
            })?,
            None => DEFAULT_EDDSA_KEYSET_URL_TIMEOUT_MS,
        };
    anyhow::ensure!(
        (1..=30_000).contains(&timeout_ms),
        "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL_TIMEOUT_MS} must be between 1 and 30000"
    );
    Ok(StdDuration::from_millis(timeout_ms))
}

fn parse_signed_token_eddsa_keyset_refresh_interval_from_env() -> anyhow::Result<StdDuration> {
    let seconds = match optional_trimmed_env(
        TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL_REFRESH_INTERVAL_SECONDS,
    )? {
        Some(configured) => configured.parse::<u64>().with_context(|| {
            format!(
                "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL_REFRESH_INTERVAL_SECONDS} must be seconds"
            )
        })?,
        None => DEFAULT_EDDSA_KEYSET_REFRESH_INTERVAL_SECONDS,
    };
    anyhow::ensure!(
        (30..=86_400).contains(&seconds),
        "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL_REFRESH_INTERVAL_SECONDS} must be between 30 and 86400"
    );
    Ok(StdDuration::from_secs(seconds))
}

fn parse_signed_token_eddsa_keyset_max_stale_from_env() -> anyhow::Result<Option<StdDuration>> {
    let Some(configured) =
        optional_trimmed_env(TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL_MAX_STALE_SECONDS)?
    else {
        return Ok(None);
    };
    let seconds = configured.parse::<u64>().with_context(|| {
        format!("{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL_MAX_STALE_SECONDS} must be seconds")
    })?;
    anyhow::ensure!(
        (60..=2_592_000).contains(&seconds),
        "{TRACE_COMMONS_SIGNED_TOKEN_EDDSA_KEYSET_URL_MAX_STALE_SECONDS} must be between 60 and 2592000"
    );
    Ok(Some(StdDuration::from_secs(seconds)))
}

fn safe_keyset_url_label(url: &reqwest::Url) -> String {
    let host = url.host_str().unwrap_or("<unknown-host>");
    format!("{}://{}", url.scheme(), host)
}

fn parse_signed_token_eddsa_keyset_config(
    configured: &str,
) -> anyhow::Result<BTreeMap<String, TraceCommonsSignedEddsaPublicKey>> {
    let keyset: TraceCommonsSignedEddsaKeysetConfig = serde_json::from_str(configured)
        .context("invalid EdDSA signed tenant token keyset JSON")?;
    anyhow::ensure!(
        !keyset.keys.is_empty(),
        "EdDSA signed tenant token keyset must include at least one key"
    );

    let mut keys = BTreeMap::new();
    for key in keyset.keys {
        let kid = key.kid.trim();
        let public_key_pem = key.public_key_pem.trim();
        let not_before = key.not_before;
        let not_after = key.not_after;
        anyhow::ensure!(
            !kid.is_empty(),
            "EdDSA signed tenant token keyset entries must include non-empty kid"
        );
        anyhow::ensure!(
            !public_key_pem.is_empty(),
            "EdDSA signed tenant token keyset entries must include non-empty public_key_pem"
        );
        if let (Some(not_before), Some(not_after)) = (&not_before, &not_after) {
            anyhow::ensure!(
                not_after > not_before,
                "EdDSA signed tenant token keyset entry {kid} has not_after before not_before"
            );
        }
        let public_key = TraceCommonsSignedEddsaPublicKey {
            pem: public_key_pem.to_string(),
            not_before,
            not_after,
        };
        if keys.insert(kid.to_string(), public_key).is_some() {
            anyhow::bail!("EdDSA signed tenant token keyset contains duplicate kid {kid}");
        }
    }
    Ok(keys)
}

fn read_eddsa_public_key_file(path: &str) -> anyhow::Result<String> {
    let pem = std::fs::read_to_string(path)
        .with_context(|| format!("failed to read EdDSA public key file {path}"))?;
    let pem = pem.trim();
    anyhow::ensure!(!pem.is_empty(), "EdDSA public key file {path} is empty");
    Ok(pem.to_string())
}

fn parse_signed_token_revoked_jtis_from_env() -> anyhow::Result<BTreeSet<String>> {
    match std::env::var(TRACE_COMMONS_SIGNED_TOKEN_REVOKED_JTIS) {
        Ok(configured) => Ok(configured
            .split(',')
            .map(str::trim)
            .filter(|jti| !jti.is_empty())
            .map(str::to_string)
            .collect()),
        Err(std::env::VarError::NotPresent) => Ok(BTreeSet::new()),
        Err(error) => Err(error)
            .with_context(|| format!("failed to read {TRACE_COMMONS_SIGNED_TOKEN_REVOKED_JTIS}")),
    }
}

fn parse_signed_token_max_ttl_seconds_from_env() -> anyhow::Result<Option<i64>> {
    match std::env::var(TRACE_COMMONS_SIGNED_TOKEN_MAX_TTL_SECONDS) {
        Ok(configured) => {
            let configured = configured.trim();
            if configured.is_empty() {
                return Ok(None);
            }
            let seconds = configured.parse::<i64>().with_context(|| {
                format!("{TRACE_COMMONS_SIGNED_TOKEN_MAX_TTL_SECONDS} must be an integer")
            })?;
            anyhow::ensure!(
                seconds > 0,
                "{TRACE_COMMONS_SIGNED_TOKEN_MAX_TTL_SECONDS} must be greater than zero"
            );
            Ok(Some(seconds))
        }
        Err(std::env::VarError::NotPresent) => Ok(None),
        Err(error) => Err(error).with_context(|| {
            format!("failed to read {TRACE_COMMONS_SIGNED_TOKEN_MAX_TTL_SECONDS}")
        }),
    }
}

fn optional_trimmed_env(name: &'static str) -> anyhow::Result<Option<String>> {
    match std::env::var(name) {
        Ok(value) => {
            let value = value.trim();
            if value.is_empty() {
                Ok(None)
            } else {
                Ok(Some(value.to_string()))
            }
        }
        Err(std::env::VarError::NotPresent) => Ok(None),
        Err(error) => Err(error).with_context(|| format!("failed to read {name}")),
    }
}

impl TraceCommonsSignedTokenVerifier {
    fn authenticate(
        &self,
        token: &str,
        require_eddsa_signed_tokens: bool,
        require_managed_eddsa_signed_tokens: bool,
    ) -> ApiResult<TenantAuth> {
        let header = jsonwebtoken::decode_header(token)
            .map_err(|_| api_error(StatusCode::FORBIDDEN, "invalid signed tenant token"))?;
        let (algorithm, decoding_key) = self.verification_key_for_header(
            &header,
            require_eddsa_signed_tokens,
            require_managed_eddsa_signed_tokens,
        )?;
        let mut validation = Validation::new(algorithm);
        validation.validate_nbf = true;
        let mut required_claims = vec!["exp".to_string(), "tenant_id".to_string()];
        if let Some(issuer) = &self.issuer {
            validation.set_issuer(&[issuer]);
            required_claims.push("iss".to_string());
        }
        if let Some(audience) = &self.audience {
            validation.set_audience(&[audience]);
            required_claims.push("aud".to_string());
        } else {
            validation.validate_aud = false;
        }
        validation.set_required_spec_claims(&required_claims);

        let token_data = jsonwebtoken::decode::<TraceCommonsSignedTokenClaims>(
            token,
            &decoding_key,
            &validation,
        )
        .map_err(|error| {
            let message = match error.kind() {
                JwtErrorKind::ExpiredSignature => "expired signed tenant token",
                JwtErrorKind::ImmatureSignature => "not-yet-valid signed tenant token",
                _ => "invalid signed tenant token",
            };
            api_error(StatusCode::FORBIDDEN, message)
        })?;

        let claims = token_data.claims;
        self.enforce_max_ttl(&claims)?;
        if self.require_jti
            && claims
                .jti
                .as_deref()
                .map(str::trim)
                .is_none_or(str::is_empty)
        {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "signed tenant token requires jti",
            ));
        }
        if claims
            .jti
            .as_deref()
            .map(str::trim)
            .is_some_and(|jti| self.revoked_jtis.contains(jti))
        {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "revoked signed tenant token",
            ));
        }

        signed_token_claims_to_auth(claims)
    }

    fn verification_key_for_header(
        &self,
        header: &jsonwebtoken::Header,
        require_eddsa_signed_tokens: bool,
        require_managed_eddsa_signed_tokens: bool,
    ) -> ApiResult<(Algorithm, DecodingKey)> {
        match header.alg {
            Algorithm::HS256 => {
                if require_eddsa_signed_tokens || require_managed_eddsa_signed_tokens {
                    return Err(api_error(
                        StatusCode::FORBIDDEN,
                        "Trace Commons requires EdDSA signed tenant tokens",
                    ));
                }
                let Some(secret) = self.secret_for_kid(header.kid.as_deref()) else {
                    return Err(api_error(
                        StatusCode::FORBIDDEN,
                        "invalid signed tenant token",
                    ));
                };
                Ok((
                    Algorithm::HS256,
                    DecodingKey::from_secret(secret.expose_secret().as_bytes()),
                ))
            }
            Algorithm::EdDSA => {
                let Some(public_key) = self.eddsa_public_key_for_kid(
                    header.kid.as_deref(),
                    require_managed_eddsa_signed_tokens,
                ) else {
                    return Err(api_error(
                        StatusCode::FORBIDDEN,
                        "invalid signed tenant token",
                    ));
                };
                public_key.ensure_active()?;
                let decoding_key = DecodingKey::from_ed_pem(public_key.pem.as_bytes())
                    .map_err(|_| api_error(StatusCode::FORBIDDEN, "invalid signed tenant token"))?;
                Ok((Algorithm::EdDSA, decoding_key))
            }
            _ => Err(api_error(
                StatusCode::FORBIDDEN,
                "unsupported signed tenant token algorithm",
            )),
        }
    }

    fn enforce_max_ttl(&self, claims: &TraceCommonsSignedTokenClaims) -> ApiResult<()> {
        let Some(max_ttl_seconds) = self.max_ttl_seconds else {
            return Ok(());
        };
        let iat = claims
            .iat
            .ok_or_else(|| api_error(StatusCode::FORBIDDEN, "signed tenant token requires iat"))?;
        if claims.exp <= iat {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "invalid signed tenant token",
            ));
        }
        if iat > Utc::now().timestamp() + 60 {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "not-yet-valid signed tenant token",
            ));
        }
        if claims.exp.saturating_sub(iat) > max_ttl_seconds {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "signed tenant token ttl exceeds policy",
            ));
        }
        Ok(())
    }

    fn secret_for_kid(&self, kid: Option<&str>) -> Option<&SecretString> {
        match kid.map(str::trim).filter(|kid| !kid.is_empty()) {
            Some(kid) => self.keyed_secrets.get(kid),
            None => self.default_secret.as_ref(),
        }
    }

    fn eddsa_public_key_for_kid(
        &self,
        kid: Option<&str>,
        require_managed_eddsa_signed_tokens: bool,
    ) -> Option<&TraceCommonsSignedEddsaPublicKey> {
        match kid.map(str::trim).filter(|kid| !kid.is_empty()) {
            Some(kid) if !require_managed_eddsa_signed_tokens => {
                self.keyed_eddsa_public_keys.get(kid)
            }
            Some(kid) if self.managed_eddsa_key_ids.contains(kid) => {
                self.keyed_eddsa_public_keys.get(kid)
            }
            Some(_) => None,
            None if require_managed_eddsa_signed_tokens => None,
            None => self.default_eddsa_public_key.as_ref(),
        }
    }

    fn configured_key_count(&self) -> usize {
        usize::from(self.default_secret.is_some())
            + self.keyed_secrets.len()
            + self.configured_eddsa_key_count()
    }

    fn configured_eddsa_key_count(&self) -> usize {
        usize::from(self.default_eddsa_public_key.is_some()) + self.keyed_eddsa_public_keys.len()
    }

    fn configured_active_eddsa_key_count(&self, now: DateTime<Utc>) -> usize {
        self.default_eddsa_public_key
            .as_ref()
            .filter(|key| key.is_active_at(now))
            .map_or(0, |_| 1)
            + self
                .keyed_eddsa_public_keys
                .values()
                .filter(|key| key.is_active_at(now))
                .count()
    }

    fn configured_managed_eddsa_key_count(&self) -> usize {
        self.managed_eddsa_key_ids.len()
    }

    fn configured_active_managed_eddsa_key_count(&self, now: DateTime<Utc>) -> usize {
        self.managed_eddsa_key_ids
            .iter()
            .filter_map(|kid| self.keyed_eddsa_public_keys.get(kid))
            .filter(|key| key.is_active_at(now))
            .count()
    }

    fn configured_inactive_eddsa_key_count(&self, now: DateTime<Utc>) -> usize {
        self.configured_eddsa_key_count()
            .saturating_sub(self.configured_active_eddsa_key_count(now))
    }

    fn managed_eddsa_keyset_stale(&self, max_stale: StdDuration, now: DateTime<Utc>) -> bool {
        let Some(last_refreshed_at) = self.managed_eddsa_keyset_last_refreshed_at else {
            return true;
        };
        let Ok(max_stale) = Duration::from_std(max_stale) else {
            return false;
        };
        now.signed_duration_since(last_refreshed_at) > max_stale
    }
}

impl TraceCommonsSignedEddsaPublicKey {
    fn is_active_at(&self, now: DateTime<Utc>) -> bool {
        self.not_before
            .as_ref()
            .is_none_or(|not_before| now >= *not_before)
            && self
                .not_after
                .as_ref()
                .is_none_or(|not_after| now <= *not_after)
    }

    fn ensure_active(&self) -> ApiResult<()> {
        if !self.is_active_at(Utc::now()) {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "inactive signed tenant token key",
            ));
        }
        Ok(())
    }
}

fn replace_managed_eddsa_keyset_for_verifier(
    verifier: &mut TraceCommonsSignedTokenVerifier,
    managed_eddsa_public_keys: BTreeMap<String, TraceCommonsSignedEddsaPublicKey>,
    require_active_managed_key: bool,
) -> anyhow::Result<()> {
    if require_active_managed_key {
        let now = Utc::now();
        anyhow::ensure!(
            managed_eddsa_public_keys
                .values()
                .any(|key| key.is_active_at(now)),
            "refreshed keyset must include at least one active managed EdDSA key"
        );
    }
    for kid in managed_eddsa_public_keys.keys() {
        anyhow::ensure!(
            !verifier.keyed_secrets.contains_key(kid),
            "signed tenant token key id {kid} is configured for both HMAC and EdDSA"
        );
        anyhow::ensure!(
            !verifier.keyed_eddsa_public_keys.contains_key(kid)
                || verifier.managed_eddsa_key_ids.contains(kid),
            "refreshed managed EdDSA key id {kid} conflicts with an unmanaged EdDSA key"
        );
    }
    for retired_kid in &verifier.managed_eddsa_key_ids {
        verifier.keyed_eddsa_public_keys.remove(retired_kid);
    }
    verifier.managed_eddsa_key_ids = managed_eddsa_public_keys.keys().cloned().collect();
    for (kid, key) in managed_eddsa_public_keys {
        verifier.keyed_eddsa_public_keys.insert(kid, key);
    }
    verifier.managed_eddsa_keyset_last_refreshed_at = Some(Utc::now());
    verifier.managed_eddsa_keyset_last_refresh_failed_at = None;
    Ok(())
}

async fn refresh_signed_token_managed_eddsa_keyset(
    verifier: &SharedTraceCommonsSignedTokenVerifier,
    refresh: &TraceCommonsManagedEddsaKeysetRefreshConfig,
    require_active_managed_key: bool,
) -> anyhow::Result<()> {
    let configured = fetch_signed_token_eddsa_keyset_url_with_config(refresh).await?;
    let managed_eddsa_public_keys = parse_signed_token_eddsa_keyset_config(&configured)?;
    let mut verifier = verifier
        .write()
        .map_err(|_| anyhow::anyhow!("signed token verifier lock poisoned"))?;
    replace_managed_eddsa_keyset_for_verifier(
        &mut verifier,
        managed_eddsa_public_keys,
        require_active_managed_key,
    )
}

fn record_signed_token_managed_eddsa_keyset_refresh_failure(
    verifier: &SharedTraceCommonsSignedTokenVerifier,
) {
    if let Ok(mut verifier) = verifier.write() {
        verifier.managed_eddsa_keyset_last_refresh_failed_at = Some(Utc::now());
    }
}

fn spawn_managed_eddsa_keyset_refresh_task(state: &Arc<AppState>) {
    let Some(verifier) = state.signed_token_verifier.clone() else {
        return;
    };
    let Some(refresh) = state.managed_eddsa_keyset_refresh.clone() else {
        return;
    };
    let require_active_managed_key = state.require_managed_eddsa_signed_tokens;
    tokio::spawn(async move {
        loop {
            tokio::time::sleep(refresh.refresh_interval).await;
            match refresh_signed_token_managed_eddsa_keyset(
                &verifier,
                &refresh,
                require_active_managed_key,
            )
            .await
            {
                Ok(()) => tracing::info!("Trace Commons managed EdDSA keyset refreshed"),
                Err(error) => {
                    record_signed_token_managed_eddsa_keyset_refresh_failure(&verifier);
                    tracing::warn!(
                        error_hash = %safe_display_error_hash(&error),
                        "Trace Commons managed EdDSA keyset refresh failed; preserving last good keyset"
                    );
                }
            }
        }
    });
}

fn spawn_trace_export_job_scheduler_task(
    state: &Arc<AppState>,
    config: Option<TraceExportJobSchedulerConfig>,
) {
    let Some(config) = config else {
        return;
    };
    let state = state.clone();
    let dataset_kind = config.dataset_kind.as_deref().unwrap_or("all");
    tracing::info!(
        dataset_kind,
        interval_seconds = config.interval.as_secs(),
        run_queued_max_jobs = config.run_queued_max_jobs,
        retry_failed_max_jobs = config.retry_failed_max_jobs,
        retry_failed_max_retry_count = config.retry_failed_max_retry_count,
        "Trace Commons export job scheduler enabled"
    );
    tokio::spawn(async move {
        loop {
            tokio::time::sleep(config.interval).await;
            match run_trace_export_job_scheduler_tick(state.clone(), &config).await {
                Ok(summary) => {
                    tracing::info!(
                        tenant_storage_ref = %summary.run_queued.tenant_storage_ref,
                        dataset_kind = ?summary.run_queued.requested_dataset_kind,
                        retried_count = summary.retry_failed.retried_count,
                        claimed_count = summary.run_queued.claimed_count,
                        completed_count = summary.run_queued.completed_count,
                        failed_count = summary.run_queued.failed_count,
                        pending_after_count = summary.run_queued.pending_after_count,
                        "Trace Commons export job scheduler tick completed"
                    );
                }
                Err((status, Json(error))) => {
                    tracing::warn!(
                        status = %status,
                        error_hash = %safe_display_error_hash(&error.error),
                        "Trace Commons export job scheduler tick failed"
                    );
                }
            }
        }
    });
}

