fn validate_ranking_pairwise_threshold_config(
    ranking_min_pairwise_label_count: usize,
    ranking_min_pairwise_accuracy_micros: i64,
    ranking_min_pairwise_accuracy_configured: bool,
) -> anyhow::Result<()> {
    if ranking_min_pairwise_accuracy_configured
        && ranking_min_pairwise_accuracy_micros > 0
        && ranking_min_pairwise_label_count == 0
    {
        anyhow::bail!(
            "{TRACE_COMMONS_RANKING_MIN_PAIRWISE_ACCURACY_MICROS} requires {TRACE_COMMONS_RANKING_MIN_PAIRWISE_LABEL_COUNT} to be greater than zero when configured"
        );
    }
    Ok(())
}

fn validate_retention_policy_id(policy_id: &str) -> anyhow::Result<()> {
    let valid = policy_id.len() <= 128
        && policy_id.chars().all(|character| {
            character.is_ascii_alphanumeric() || matches!(character, '_' | '-' | '.' | ':')
        });
    if !valid {
        anyhow::bail!(
            "{TRACE_COMMONS_LEGAL_HOLD_RETENTION_POLICIES} contains an invalid retention policy id"
        );
    }
    Ok(())
}

#[cfg(test)]
fn insert_token(
    tokens: &mut BTreeMap<String, TenantAuth>,
    tenant_id: &str,
    token: &str,
    role: TokenRole,
) {
    insert_token_with_expiry(tokens, tenant_id, token, role, None)
        .expect("test tenant token inserts");
}

fn insert_token_with_expiry(
    tokens: &mut BTreeMap<String, TenantAuth>,
    tenant_id: &str,
    token: &str,
    role: TokenRole,
    expires_at: Option<DateTime<Utc>>,
) -> anyhow::Result<()> {
    let tenant_id = tenant_id.trim();
    let token = token.trim();
    if tenant_id.is_empty() || token.is_empty() {
        return Ok(());
    }
    if tokens.contains_key(token) {
        anyhow::bail!(
            "duplicate Trace Commons tenant token configured for multiple tenants or roles"
        );
    }
    tokens.insert(
        token.to_string(),
        TenantAuth {
            tenant_id: tenant_id.to_string(),
            role,
            principal_ref: principal_storage_ref(token),
            expires_at,
            auth_method: TraceAuthMethod::StaticToken,
            signed_claim_issuer: None,
            signed_claim_audiences: BTreeSet::new(),
            signed_claim_subject: None,
            allowed_consent_scopes: BTreeSet::new(),
            allowed_uses: BTreeSet::new(),
        },
    );
    Ok(())
}

