async fn put_tenant_policy_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<TraceTenantPolicyRequest>,
) -> ApiResult<Json<TraceTenantPolicyResponse>> {
    let tenant = authenticate(state.as_ref(), &headers)?;
    require_admin(&tenant)?;
    let target_scopes: BTreeSet<ConsentScope> =
        request.allowed_consent_scopes.iter().copied().collect();
    let target_uses: BTreeSet<TraceAllowedUse> = request.allowed_uses.iter().copied().collect();
    let privileged_policy = tenant_privileged_action_policy_for_request(
        state.as_ref(),
        &tenant,
        "tenant policy mutation",
    )
    .await?;
    ensure_action_target_matches_privileged_action_policy_abac(
        &target_scopes,
        &target_uses,
        &tenant,
        privileged_policy.as_ref(),
        "tenant policy mutation",
    )?;
    let db = trace_tenant_policy_db(state.as_ref())?;
    let policy_version = request.policy_version.trim();
    if policy_version.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "trace tenant contribution policy requires a policy_version",
        ));
    }
    let allowed_consent_scopes = request
        .allowed_consent_scopes
        .iter()
        .map(serde_storage_string)
        .collect::<anyhow::Result<Vec<_>>>()
        .map_err(internal_error)?;
    let allowed_uses = request
        .allowed_uses
        .iter()
        .map(serde_storage_string)
        .collect::<anyhow::Result<Vec<_>>>()
        .map_err(internal_error)?;
    let policy_projection_hash =
        trace_tenant_policy_projection_hash(policy_version, &allowed_consent_scopes, &allowed_uses)
            .map_err(internal_error)?;
    let policy = db
        .upsert_trace_tenant_policy(StorageTraceTenantPolicyWrite {
            tenant_id: tenant.tenant_id.clone(),
            policy_version: policy_version.to_string(),
            allowed_consent_scopes,
            allowed_uses,
            updated_by_principal_ref: tenant.principal_ref.clone(),
        })
        .await
        .map_err(internal_error)?;
    let response = trace_tenant_policy_response(policy);
    append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        TraceCommonsAuditEvent::tenant_policy_update(
            &tenant,
            &response.policy_version,
            response.allowed_consent_scopes.len(),
            response.allowed_uses.len(),
            &policy_projection_hash,
        ),
        StorageTraceAuditAction::PolicyUpdate,
        StorageTraceAuditSafeMetadata::TenantPolicy {
            policy_version: response.policy_version.clone(),
            allowed_consent_scope_count: response.allowed_consent_scopes.len() as u32,
            allowed_use_count: response.allowed_uses.len() as u32,
            policy_projection_hash,
        },
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(response))
}

async fn tenant_access_grants_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<TraceTenantAccessGrantsQuery>,
) -> ApiResult<Json<Vec<TraceTenantAccessGrantResponse>>> {
    let tenant = authenticate(state.as_ref(), &headers)?;
    require_admin(&tenant)?;
    let limit = validate_trace_read_limit(query.limit)?;
    let db = trace_tenant_access_grants_db(state.as_ref())?;
    let principal_ref = query
        .principal_ref
        .as_deref()
        .map(str::trim)
        .filter(|principal_ref| !principal_ref.is_empty());
    let grants = db
        .list_trace_tenant_access_grants(&tenant.tenant_id)
        .await
        .map_err(internal_error)?;
    let summaries = grants
        .into_iter()
        .rev()
        .filter(|grant| query.status.is_none_or(|status| grant.status == status))
        .filter(|grant| query.role.is_none_or(|role| grant.role == role))
        .filter(|grant| {
            principal_ref.is_none_or(|principal_ref| grant.principal_ref == principal_ref)
        })
        .take(limit)
        .map(trace_tenant_access_grant_response)
        .collect::<Vec<_>>();
    append_control_plane_read_audit(
        state.as_ref(),
        &tenant,
        "tenant_access_grants",
        summaries.len(),
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(summaries))
}

async fn create_tenant_access_grant_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(request): Json<TraceTenantAccessGrantRequest>,
) -> ApiResult<Json<TraceTenantAccessGrantResponse>> {
    let tenant = authenticate(state.as_ref(), &headers)?;
    require_admin(&tenant)?;
    let target_scopes: BTreeSet<ConsentScope> =
        request.allowed_consent_scopes.iter().copied().collect();
    let target_uses: BTreeSet<TraceAllowedUse> = request.allowed_uses.iter().copied().collect();
    let privileged_policy = tenant_privileged_action_policy_for_request(
        state.as_ref(),
        &tenant,
        "tenant access grant creation",
    )
    .await?;
    ensure_action_target_matches_privileged_action_policy_abac(
        &target_scopes,
        &target_uses,
        &tenant,
        privileged_policy.as_ref(),
        "tenant access grant creation",
    )?;
    let db = trace_tenant_access_grants_db(state.as_ref())?;
    let principal_ref = request.principal_ref.trim();
    if principal_ref.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "trace tenant access grant requires principal_ref",
        ));
    }
    let reason = request.reason.trim();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "trace tenant access grant requires reason",
        ));
    }
    let issued_at = request.issued_at.unwrap_or_else(Utc::now);
    if let Some(expires_at) = request.expires_at
        && expires_at <= issued_at
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "trace tenant access grant expires_at must be after issued_at",
        ));
    }
    let allowed_consent_scopes = request
        .allowed_consent_scopes
        .iter()
        .map(serde_storage_string)
        .collect::<anyhow::Result<Vec<_>>>()
        .map_err(internal_error)?;
    let allowed_uses = request
        .allowed_uses
        .iter()
        .map(serde_storage_string)
        .collect::<anyhow::Result<Vec<_>>>()
        .map_err(internal_error)?;
    let record = db
        .upsert_trace_tenant_access_grant(StorageTraceTenantAccessGrantWrite {
            tenant_id: tenant.tenant_id.clone(),
            grant_id: request.grant_id.unwrap_or_else(Uuid::new_v4),
            principal_ref: principal_ref.to_string(),
            role: request.role,
            status: StorageTraceTenantAccessGrantStatus::Active,
            allowed_consent_scopes,
            allowed_uses,
            issuer: trimmed_optional_string(request.issuer),
            audience: trimmed_optional_string(request.audience),
            subject: trimmed_optional_string(request.subject),
            issued_at,
            expires_at: request.expires_at,
            revoked_at: None,
            created_by_principal_ref: Some(tenant.principal_ref.clone()),
            revoked_by_principal_ref: None,
            reason: Some(reason.to_string()),
            metadata: request.metadata,
        })
        .await
        .map_err(internal_error)?;
    let response = trace_tenant_access_grant_response(record);
    append_tenant_access_grant_update_audit(state.as_ref(), &tenant, &response, "created")
        .await
        .map_err(internal_error)?;
    Ok(Json(response))
}

async fn revoke_tenant_access_grant_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    AxumPath(grant_id): AxumPath<Uuid>,
    Json(request): Json<TraceTenantAccessGrantRevokeRequest>,
) -> ApiResult<Json<TraceTenantAccessGrantResponse>> {
    let tenant = authenticate(state.as_ref(), &headers)?;
    require_admin(&tenant)?;
    let reason = request.reason.trim();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "trace tenant access grant revocation requires reason",
        ));
    }
    let db = trace_tenant_access_grants_db(state.as_ref())?;
    let existing = db
        .list_trace_tenant_access_grants(&tenant.tenant_id)
        .await
        .map_err(internal_error)?
        .into_iter()
        .find(|grant| grant.grant_id == grant_id)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "trace tenant access grant not found"))?;
    let target_scopes: BTreeSet<ConsentScope> = parse_storage_policy_values(
        &existing.allowed_consent_scopes,
        "grant.allowed_consent_scopes",
    )
    .map_err(internal_error)?;
    let target_uses: BTreeSet<TraceAllowedUse> =
        parse_storage_policy_values(&existing.allowed_uses, "grant.allowed_uses")
            .map_err(internal_error)?;
    let privileged_policy = tenant_privileged_action_policy_for_request(
        state.as_ref(),
        &tenant,
        "tenant access grant revocation",
    )
    .await?;
    ensure_action_target_matches_privileged_action_policy_abac(
        &target_scopes,
        &target_uses,
        &tenant,
        privileged_policy.as_ref(),
        "tenant access grant revocation",
    )?;
    let record = db
        .upsert_trace_tenant_access_grant(StorageTraceTenantAccessGrantWrite {
            tenant_id: existing.tenant_id,
            grant_id: existing.grant_id,
            principal_ref: existing.principal_ref,
            role: existing.role,
            status: StorageTraceTenantAccessGrantStatus::Revoked,
            allowed_consent_scopes: existing.allowed_consent_scopes,
            allowed_uses: existing.allowed_uses,
            issuer: existing.issuer,
            audience: existing.audience,
            subject: existing.subject,
            issued_at: existing.issued_at,
            expires_at: existing.expires_at,
            revoked_at: Some(Utc::now()),
            created_by_principal_ref: existing.created_by_principal_ref,
            revoked_by_principal_ref: Some(tenant.principal_ref.clone()),
            reason: Some(reason.to_string()),
            metadata: existing.metadata,
        })
        .await
        .map_err(internal_error)?;
    let response = trace_tenant_access_grant_response(record);
    append_tenant_access_grant_update_audit(state.as_ref(), &tenant, &response, "revoked")
        .await
        .map_err(internal_error)?;
    Ok(Json(response))
}

