async fn submission_status_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceSubmissionStatusRequest>,
) -> ApiResult<Json<Vec<TraceSubmissionStatusUpdate>>> {
    let tenant = authenticate_ctx_with_tenant_access_grant(state.as_ref(), &headers).await?;
    if body.submission_ids.len() > 500 {
        return Err(api_error(
            StatusCode::PAYLOAD_TOO_LARGE,
            "submission status requests are limited to 500 ids",
        ));
    }

    let credit_view = read_contributor_credit_view(state.as_ref(), tenant.auth())
        .await
        .map_err(internal_error)?;
    let visible_by_submission = credit_view
        .records
        .iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let status_credit_events =
        read_contributor_status_credit_events(state.as_ref(), tenant.auth(), &credit_view.records)
            .await
            .map_err(internal_error)?;
    let mut statuses = Vec::new();
    for submission_id in body.submission_ids {
        if let Some(record) = visible_by_submission.get(&submission_id) {
            statuses.push(submission_status_from_record(record, &status_credit_events));
        }
    }

    append_control_plane_read_audit(
        state.as_ref(),
        tenant.auth(),
        "submission_status",
        statuses.len(),
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(statuses))
}

async fn analytics_handler(
    State(state): State<Arc<AppState>>,
    Query(query): Query<TraceAnalyticsQuery>,
    headers: HeaderMap,
) -> ApiResult<Json<TraceCommonsAnalyticsResponse>> {
    let tenant = authenticate_ctx_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(tenant.auth())?;
    let TraceCommonsMetadataView { records, derived } =
        read_reviewer_metadata_view(state.as_ref(), tenant.auth())
            .await
            .map_err(internal_error)?;
    let mut response = TraceCommonsAnalyticsResponse::from_records(
        tenant.tenant_id().to_string(),
        records,
        derived,
    );
    response.apply_min_cell_count(state.analytics_min_cell_count);
    let requests_broad_release = query.requests_broad_release()?;
    if requests_broad_release && state.analytics_broad_release_noise.is_none() {
        response
            .privacy_budget
            .block_broad_release("noise_not_configured");
    }
    if requests_broad_release && let Some(config) = state.analytics_broad_release_noise.as_ref() {
        response.apply_broad_release_noise(config);
    }
    let privacy_ledger = if requests_broad_release {
        if let Some(config) = state.analytics_broad_release_privacy_accounting {
            let ledger =
                analytics_broad_release_privacy_ledger(state.as_ref(), tenant.tenant_id(), config)
                    .map_err(internal_error)?;
            if ledger.remaining_before_release < config.epsilon_micros_per_release {
                response
                    .privacy_budget
                    .block_broad_release("privacy_budget_exhausted");
            }
            Some((config, ledger))
        } else {
            None
        }
    } else {
        None
    };
    if requests_broad_release && !response.privacy_budget.broad_release_ready {
        return Err(api_error(
            StatusCode::CONFLICT,
            format!(
                "analytics broad release is blocked by privacy budget: {}",
                response
                    .privacy_budget
                    .broad_release_blocking_reasons
                    .join(",")
            ),
        ));
    }
    if let Some((config, ledger)) = privacy_ledger {
        response
            .privacy_budget
            .apply_privacy_accounting(config, ledger.spent_after_release);
    }
    let mut audit_event = tenant.read_audit_event("analytics_summary", response.submissions_total);
    if let Some((config, ledger)) = privacy_ledger {
        audit_event.reason = Some(trace_analytics_broad_release_audit_reason(
            response.submissions_total,
            config.epsilon_micros_per_release,
            ledger.spent_after_release,
            ledger.remaining_after_release,
        ));
    }
    append_audit_event_with_db_mirror(
        state.as_ref(),
        tenant.auth(),
        audit_event,
        StorageTraceAuditAction::Read,
        trace_read_audit_metadata("analytics_summary", response.submissions_total),
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(response))
}

#[derive(Debug, Clone, Copy)]
struct TraceAnalyticsPrivacyLedger {
    spent_before_release: u64,
    remaining_before_release: u64,
    spent_after_release: u64,
    remaining_after_release: u64,
}

fn analytics_broad_release_privacy_ledger(
    state: &AppState,
    tenant_id: &str,
    config: TraceAnalyticsPrivacyAccountingConfig,
) -> anyhow::Result<TraceAnalyticsPrivacyLedger> {
    let spent_before_release =
        analytics_broad_release_epsilon_spent_micros(&state.root, tenant_id)?;
    let remaining_before_release = config
        .max_epsilon_micros
        .saturating_sub(spent_before_release);
    let spent_after_release = spent_before_release
        .saturating_add(config.epsilon_micros_per_release)
        .min(config.max_epsilon_micros);
    let remaining_after_release = config
        .max_epsilon_micros
        .saturating_sub(spent_after_release);
    Ok(TraceAnalyticsPrivacyLedger {
        spent_before_release,
        remaining_before_release,
        spent_after_release,
        remaining_after_release,
    })
}

fn analytics_broad_release_epsilon_spent_micros(
    root: &Path,
    tenant_id: &str,
) -> anyhow::Result<u64> {
    read_all_audit_events(root, tenant_id)?
        .iter()
        .filter(|event| event.kind == "read")
        .filter(|event| {
            trace_audit_reason_value(event.reason.as_deref(), "surface")
                == Some("analytics_summary")
                && trace_audit_reason_value(event.reason.as_deref(), "release_scope")
                    == Some("broad")
        })
        .try_fold(0u64, |accumulator, event| {
            let epsilon = trace_audit_reason_u64(event.reason.as_deref(), "privacy_epsilon_micros")
                .ok_or_else(|| {
                    anyhow::anyhow!(
                        "analytics broad-release audit event {} is missing privacy_epsilon_micros",
                        event.event_id
                    )
                })?;
            accumulator
                .checked_add(epsilon)
                .ok_or_else(|| anyhow::anyhow!("analytics broad-release privacy ledger overflow"))
        })
}

#[derive(Debug, Default, Deserialize)]
struct TraceAnalyticsQuery {
    #[serde(default)]
    release_scope: Option<String>,
}

impl TraceAnalyticsQuery {
    fn requests_broad_release(&self) -> ApiResult<bool> {
        let Some(release_scope) = self.release_scope.as_deref() else {
            return Ok(false);
        };
        match release_scope.trim().to_ascii_lowercase().as_str() {
            "" | "operator" | "reviewer" | "admin" => Ok(false),
            "broad" | "public" => Ok(true),
            _ => Err(api_error(
                StatusCode::BAD_REQUEST,
                "analytics release_scope must be operator or broad",
            )),
        }
    }
}

#[derive(Debug, Deserialize)]
struct TraceListQuery {
    status: Option<TraceCorpusStatus>,
    limit: Option<usize>,
    purpose: Option<String>,
    coverage_tag: Option<String>,
    tool: Option<String>,
    privacy_risk: Option<ResidualPiiRisk>,
    consent_scope: Option<String>,
}

async fn list_traces_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<TraceListQuery>,
) -> ApiResult<Json<Vec<TraceCommonsTraceListItem>>> {
    let tenant = authenticate_ctx_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(tenant.auth())?;
    let TraceCommonsMetadataView { records, derived } =
        read_reviewer_metadata_view(state.as_ref(), tenant.auth())
            .await
            .map_err(internal_error)?;
    let derived_by_submission = derived
        .into_iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let limit = validate_trace_read_limit(query.limit)?;
    let consent_scope = parse_consent_scope_filter(query.consent_scope.as_deref())?;
    let purpose_submission_ids =
        trace_list_purpose_submission_ids(state.as_ref(), tenant.auth(), query.purpose.as_deref())
            .await
            .map_err(internal_error)?;

    let items: Vec<_> = records
        .into_iter()
        .rev()
        .filter(|record| query.status == Some(TraceCorpusStatus::Revoked) || !record.is_revoked())
        .filter(|record| query.status.is_none_or(|status| record.status == status))
        .filter(|record| {
            query
                .privacy_risk
                .is_none_or(|risk| record.privacy_risk == risk)
        })
        .filter(|record| consent_scope.is_none_or(|scope| record.consent_scopes.contains(&scope)))
        .filter(|record| {
            purpose_submission_ids
                .as_ref()
                .is_none_or(|submission_ids| submission_ids.contains(&record.submission_id))
        })
        .filter(|record| {
            trace_matches_derived_filters(
                derived_by_submission.get(&record.submission_id),
                query.coverage_tag.as_deref(),
                query.tool.as_deref(),
            )
        })
        .take(limit)
        .map(|record| TraceCommonsTraceListItem::from_record(record, &derived_by_submission))
        .collect();
    append_control_plane_read_audit(state.as_ref(), tenant.auth(), "trace_list", items.len())
        .await
        .map_err(internal_error)?;
    Ok(Json(items))
}

#[derive(Debug, Deserialize, Default)]
struct ReviewQueueQuery {
    #[serde(default)]
    lease_filter: TraceReviewLeaseFilter,
}

#[derive(Debug, Clone, Copy, Deserialize, PartialEq, Eq, Default)]
#[serde(rename_all = "snake_case")]
enum TraceReviewLeaseFilter {
    #[default]
    All,
    Mine,
    Available,
    Active,
    Expired,
}

fn trace_review_lease_filter_matches(
    record: &TraceCommonsSubmissionRecord,
    principal_ref: &str,
    now: DateTime<Utc>,
    filter: TraceReviewLeaseFilter,
) -> bool {
    let assigned_to = record.review_assigned_to_principal_ref.as_deref();
    let is_assigned = assigned_to.is_some();
    let is_mine = assigned_to == Some(principal_ref);
    let is_expired = record
        .review_lease_expires_at
        .is_some_and(|expires_at| expires_at <= now);
    let is_active = is_assigned && !is_expired;
    match filter {
        TraceReviewLeaseFilter::All => true,
        TraceReviewLeaseFilter::Mine => is_mine,
        TraceReviewLeaseFilter::Available => !is_assigned || is_expired,
        TraceReviewLeaseFilter::Active => is_active,
        TraceReviewLeaseFilter::Expired => is_assigned && is_expired,
    }
}

async fn review_quarantine_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Query(query): Query<ReviewQueueQuery>,
) -> ApiResult<Json<Vec<TraceReviewQueueItem>>> {
    let tenant = authenticate_ctx_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(tenant.auth())?;
    let TraceCommonsMetadataView { records, derived } =
        read_reviewer_metadata_view(state.as_ref(), tenant.auth())
            .await
            .map_err(internal_error)?;
    let derived_by_submission = derived
        .into_iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let now = Utc::now();
    let mut queue = records
        .into_iter()
        .filter(|record| record.status == TraceCorpusStatus::Quarantined)
        .filter(|record| {
            trace_review_lease_filter_matches(
                record,
                tenant.principal_ref(),
                now,
                query.lease_filter,
            )
        })
        .map(|record| TraceReviewQueueItem::from_record(record, &derived_by_submission, now))
        .collect::<Vec<_>>();
    queue.sort_by(|left, right| {
        right
            .review_escalation_state
            .rank()
            .cmp(&left.review_escalation_state.rank())
            .then_with(|| right.review_age_hours.cmp(&left.review_age_hours))
            .then_with(|| left.received_at.cmp(&right.received_at))
    });
    append_control_plane_read_audit(
        state.as_ref(),
        tenant.auth(),
        "review_quarantine",
        queue.len(),
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(queue))
}

async fn review_routing_summary_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> ApiResult<Json<TraceReviewRoutingSummary>> {
    let tenant = authenticate_ctx_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(tenant.auth())?;
    let TraceCommonsMetadataView { records, .. } =
        read_reviewer_metadata_view(state.as_ref(), tenant.auth())
            .await
            .map_err(internal_error)?;
    let now = Utc::now();
    let summary = TraceReviewRoutingSummary::from_records(tenant.auth(), &records, now);
    append_control_plane_read_audit(
        state.as_ref(),
        tenant.auth(),
        "review_routing_summary",
        summary.queue_count,
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(summary))
}

