async fn append_credit_event_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    AxumPath(submission_id): AxumPath<Uuid>,
    Json(body): Json<TraceCreditLedgerAppendRequest>,
) -> ApiResult<Json<TraceCommonsCreditLedgerRecord>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(&tenant)?;
    if !body.credit_points_delta.is_finite() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit_points_delta must be finite",
        ));
    }
    if body.credit_points_delta.abs() > MAX_DELAYED_CREDIT_POINTS_DELTA {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit_points_delta exceeds the delayed credit policy limit",
        ));
    }
    require_positive_credit_issuance_principal_if_configured(
        state.as_ref(),
        &tenant,
        body.credit_points_delta,
    )?;
    let submission = read_reviewer_submission_record(state.as_ref(), &tenant, submission_id)
        .await
        .map_err(internal_error)?
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "trace submission not found"))?;
    if submission.is_terminal() {
        return Err(api_error(
            StatusCode::CONFLICT,
            "terminal trace submissions are not eligible for delayed credit",
        ));
    }
    let reason = body
        .reason
        .as_deref()
        .map(str::trim)
        .filter(|reason| !reason.is_empty())
        .ok_or_else(|| {
            api_error(
                StatusCode::BAD_REQUEST,
                "delayed credit events require a non-empty reason",
            )
        })?
        .to_string();
    let external_ref = body
        .external_ref
        .as_deref()
        .map(str::trim)
        .filter(|external_ref| !external_ref.is_empty())
        .map(ToOwned::to_owned);
    if body.event_type.requires_external_ref() && external_ref.is_none() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "benchmark, regression, training, and ranking utility credit require external_ref",
        ));
    }
    let required_uses = delayed_credit_required_allowed_uses(body.event_type);
    let tenant_policy = if required_uses.is_empty() {
        None
    } else {
        tenant_utility_credit_policy_for_request(state.as_ref(), &tenant, required_uses).await?
    };
    if !required_uses.is_empty()
        && !record_matches_utility_credit_policy_abac(
            &submission,
            &tenant,
            tenant_policy.as_ref(),
            required_uses,
        )
    {
        tracing::warn!(
            tenant_id = %tenant.tenant_id,
            submission_id = %submission.submission_id,
            event_type = ?body.event_type,
            ?required_uses,
            "Trace Commons tenant policy rejected delayed credit source"
        );
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "trace delayed credit source is not allowed for this utility use",
        ));
    }
    let event = TraceCommonsCreditLedgerRecord {
        event_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        submission_id,
        trace_id: submission.trace_id,
        auth_principal_ref: submission.auth_principal_ref,
        event_type: body.event_type,
        credit_points_delta: body.credit_points_delta,
        reason: Some(reason),
        external_ref,
        actor_role: tenant.role,
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
    };
    if state.require_db_mirror_writes {
        let mirror_result = mirror_credit_event_to_db(&state, &event).await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_runtime_error_hash(error),
                submission_id = %event.submission_id,
                "Trace Commons DB dual-write credit mirror failed"
            );
        }
        enforce_db_mirror_write_result(state.as_ref(), "credit ledger event", mirror_result)
            .map_err(internal_error)?;
        append_credit_event(&state.root, &tenant.tenant_id, &event).map_err(internal_error)?;
    } else {
        append_credit_event(&state.root, &tenant.tenant_id, &event).map_err(internal_error)?;
        let mirror_result = mirror_credit_event_to_db(&state, &event).await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_runtime_error_hash(error),
                submission_id = %event.submission_id,
                "Trace Commons DB dual-write credit mirror failed"
            );
        }
        enforce_db_mirror_write_result(state.as_ref(), "credit ledger event", mirror_result)
            .map_err(internal_error)?;
    }
    let credit_audit_event = TraceCommonsAuditEvent::credit_mutation(
        &tenant,
        submission_id,
        body.credit_points_delta,
        event.reason.as_deref(),
    );
    if let Err(error) = append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        credit_audit_event.clone(),
        StorageTraceAuditAction::CreditMutate,
        StorageTraceAuditSafeMetadata::CreditMutation {
            event_type: storage_credit_event_type(body.event_type),
            credit_points_delta_micros: credit_delta_micros(body.credit_points_delta),
            reason_hash: sha256_prefixed(event.reason.as_deref().unwrap_or_default()),
            external_ref_hash: event.external_ref.as_deref().map(sha256_prefixed),
        },
    )
    .await
    {
        if state.require_db_mirror_writes {
            remove_credit_event_by_id(&state.root, &tenant.tenant_id, event.event_id)
                .map_err(internal_error)?;
            remove_audit_event_by_id(&state.root, &tenant.tenant_id, credit_audit_event.event_id)
                .map_err(internal_error)?;
        }
        return Err(internal_error(error));
    }
    Ok(Json(event))
}

async fn utility_credit_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceUtilityCreditJobRequest>,
) -> ApiResult<Json<TraceUtilityCreditJobResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    if !body.event_type.is_utility_job_type() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "utility credit jobs support regression_catch, training_utility, or ranking_utility",
        ));
    }
    if !body.credit_points_delta.is_finite() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit_points_delta must be finite",
        ));
    }
    if body.credit_points_delta.abs() > MAX_DELAYED_CREDIT_POINTS_DELTA {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit_points_delta exceeds the delayed credit policy limit",
        ));
    }
    require_positive_credit_issuance_principal_if_configured(
        state.as_ref(),
        &tenant,
        body.credit_points_delta,
    )?;
    let reason = body.reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "utility credit jobs require a non-empty reason",
        ));
    }
    let external_ref = body.external_ref.trim().to_string();
    if external_ref.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "utility credit jobs require a non-empty external_ref",
        ));
    }
    if body.submission_ids.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "utility credit jobs require at least one submission_id",
        ));
    }
    let required_uses = utility_credit_required_allowed_uses(body.event_type);
    let tenant_policy =
        tenant_utility_credit_policy_for_request(state.as_ref(), &tenant, required_uses).await?;
    let unique_submission_ids = body
        .submission_ids
        .iter()
        .copied()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let mut sources = Vec::with_capacity(unique_submission_ids.len());
    for submission_id in &unique_submission_ids {
        let submission = read_utility_submission_record(state.as_ref(), &tenant, *submission_id)
            .await
            .map_err(internal_error)?
            .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "trace submission not found"))?;
        if submission.status != TraceCorpusStatus::Accepted {
            return Err(api_error(
                StatusCode::CONFLICT,
                "utility credit jobs can only credit accepted trace submissions",
            ));
        }
        if !record_matches_utility_credit_policy_abac(
            &submission,
            &tenant,
            tenant_policy.as_ref(),
            required_uses,
        ) {
            tracing::warn!(
                tenant_id = %tenant.tenant_id,
                submission_id = %submission.submission_id,
                ?required_uses,
                "Trace Commons tenant policy rejected utility credit source"
            );
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "trace utility credit source is not allowed for this utility use",
            ));
        }
        sources.push(AutomaticUtilityCreditSource {
            submission_id: submission.submission_id,
            trace_id: submission.trace_id,
            auth_principal_ref: submission.auth_principal_ref,
        });
    }

    let counts = append_automatic_utility_credit_events_once_with_counts(
        state.as_ref(),
        &tenant,
        AutomaticUtilityCreditConfig {
            idempotency_label: body.event_type.utility_idempotency_label(),
            idempotency_ref: Some(external_ref.clone()),
            event_type: body.event_type,
            credit_points_delta: body.credit_points_delta,
            reason,
            external_ref: external_ref.clone(),
        },
        sources,
    )
    .await?;

    Ok(Json(TraceUtilityCreditJobResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        event_type: body.event_type,
        credit_points_delta: body.credit_points_delta,
        external_ref,
        requested_count: unique_submission_ids.len(),
        appended_count: counts.appended,
        skipped_existing_count: counts.skipped_existing,
    }))
}

async fn utility_attestation_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceUtilityAttestationRequest>,
) -> ApiResult<Json<TraceUtilityAttestationResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    if !body.event_type.is_utility_job_type() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "utility attestations support regression_catch, training_utility, or ranking_utility",
        ));
    }
    if !body.credit_points_delta.is_finite() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit_points_delta must be finite",
        ));
    }
    if body.credit_points_delta.abs() > MAX_DELAYED_CREDIT_POINTS_DELTA {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit_points_delta exceeds the delayed credit policy limit",
        ));
    }
    require_positive_credit_issuance_principal_if_configured(
        state.as_ref(),
        &tenant,
        body.credit_points_delta,
    )?;
    let use_category = validate_utility_attestation_use_category(&body.use_category)?;
    let policy_version =
        validate_credit_policy_version(&body.policy_version, "utility attestation")?;
    let evidence_hash = body.evidence_hash.trim().to_string();
    if !is_canonical_sha256_prefixed_hash(&evidence_hash) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "utility attestations require a canonical sha256-prefixed hex digest evidence_hash",
        ));
    }
    let reason = body.reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "utility attestations require a non-empty reason",
        ));
    }
    let external_ref = body.external_ref.trim().to_string();
    if external_ref.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "utility attestations require external_ref",
        ));
    }
    if body.source_submission_ids.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "utility attestations require at least one source submission",
        ));
    }

    let existing = read_utility_attestations_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    if let Some(attestation) = existing.iter().find(|attestation| {
        attestation.external_ref_hash == sha256_prefixed(&external_ref)
            && attestation.event_type == body.event_type
    }) {
        return Ok(Json(TraceUtilityAttestationResponse {
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            attestation_id: attestation.attestation_id,
            event_type: body.event_type,
            requested_count: body.source_submission_ids.len(),
            appended_count: 0,
            skipped_existing_count: body.source_submission_ids.len(),
        }));
    }

    let required_uses = utility_credit_required_allowed_uses(body.event_type);
    let tenant_policy =
        tenant_utility_credit_policy_for_request(state.as_ref(), &tenant, required_uses).await?;
    let unique_submission_ids = body
        .source_submission_ids
        .iter()
        .copied()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let mut sources = Vec::with_capacity(unique_submission_ids.len());
    for submission_id in &unique_submission_ids {
        let submission = read_utility_submission_record(state.as_ref(), &tenant, *submission_id)
            .await
            .map_err(internal_error)?
            .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "trace submission not found"))?;
        if submission.status != TraceCorpusStatus::Accepted {
            return Err(api_error(
                StatusCode::CONFLICT,
                "utility attestations can only reference accepted trace submissions",
            ));
        }
        if !record_matches_utility_credit_policy_abac(
            &submission,
            &tenant,
            tenant_policy.as_ref(),
            required_uses,
        ) {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "trace utility attestation source is not allowed for this utility use",
            ));
        }
        sources.push(AutomaticUtilityCreditSource {
            submission_id: submission.submission_id,
            trace_id: submission.trace_id,
            auth_principal_ref: submission.auth_principal_ref,
        });
    }

    let counts = append_automatic_utility_credit_events_once_with_counts(
        state.as_ref(),
        &tenant,
        AutomaticUtilityCreditConfig {
            idempotency_label: body.event_type.utility_idempotency_label(),
            idempotency_ref: Some(external_ref.clone()),
            event_type: body.event_type,
            credit_points_delta: body.credit_points_delta,
            reason,
            external_ref: external_ref.clone(),
        },
        sources,
    )
    .await?;

    let attestation = TraceUtilityAttestationRecord {
        attestation_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        event_type: body.event_type,
        use_category,
        policy_version,
        evidence_hash,
        external_ref_hash: sha256_prefixed(&external_ref),
        source_submission_ids: unique_submission_ids.clone(),
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
    };
    append_utility_attestation_with_db_mirror(state.as_ref(), &tenant, &attestation)
        .await
        .map_err(internal_error)?;

    Ok(Json(TraceUtilityAttestationResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        attestation_id: attestation.attestation_id,
        event_type: body.event_type,
        requested_count: unique_submission_ids.len(),
        appended_count: counts.appended,
        skipped_existing_count: counts.skipped_existing,
    }))
}

