fn validate_credit_settlement_issuer_approval_policy_version(value: &str) -> ApiResult<String> {
    validate_credit_policy_version(value, "issuer approval")
}

fn validate_credit_policy_version(value: &str, surface: &str) -> ApiResult<String> {
    let value = value.trim();
    if value.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("{surface} requires policy_version"),
        ));
    }
    if value.len() > 256 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("{surface} policy_version is too long"),
        ));
    }
    if !value
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.' | ':'))
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("{surface} policy_version contains unsupported characters"),
        ));
    }
    Ok(value.to_string())
}

fn validate_credit_settlement_issuer_approval_reason(reason: &str) -> ApiResult<String> {
    let reason = reason.trim();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "issuer approval requires a non-empty reason",
        ));
    }
    if reason.len() > 1024 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "issuer approval reason is too long",
        ));
    }
    Ok(sha256_prefixed(reason))
}

fn trace_credit_settlement_issuer_approval_audit_reason(
    approval: &TraceCreditSettlementIssuerApprovalResponse,
) -> String {
    trace_credit_settlement_issuer_approval_audit_reason_from_parts(
        &approval.policy_version,
        &approval.source_list_hash,
        &approval.evidence_hash,
        &approval.reason_hash,
        approval.evidence_ref_hash.as_deref(),
    )
}

fn trace_credit_settlement_issuer_approval_audit_reason_from_parts(
    policy_version: &str,
    source_list_hash: &str,
    evidence_hash: &str,
    reason_hash: &str,
    evidence_ref_hash: Option<&str>,
) -> String {
    let mut reason = format!(
        "surface=credit_settlement_issuer_approval;policy_version={};source_list_hash={};evidence_hash={};reason_hash={}",
        policy_version, source_list_hash, evidence_hash, reason_hash
    );
    if let Some(evidence_ref_hash) = evidence_ref_hash {
        reason.push_str(";evidence_ref_hash=");
        reason.push_str(evidence_ref_hash);
    }
    reason
}

fn trace_credit_settlement_issuer_approval_audit_metadata(
    approval: &TraceCreditSettlementIssuerApprovalResponse,
) -> StorageTraceAuditSafeMetadata {
    StorageTraceAuditSafeMetadata::CreditSettlementIssuerApproval {
        policy_version: approval.policy_version.clone(),
        source_list_hash: approval.source_list_hash.clone(),
        evidence_hash: approval.evidence_hash.clone(),
        reason_hash: approval.reason_hash.clone(),
        evidence_ref_hash: approval.evidence_ref_hash.clone(),
    }
}

fn trace_credit_settlement_issuer_approval_audit_metadata_from_reason(
    reason: Option<&str>,
) -> Option<StorageTraceAuditSafeMetadata> {
    if !trace_audit_reason_is_credit_settlement_issuer_approval(reason) {
        return None;
    }
    let policy_version = trace_audit_reason_value(reason, "policy_version")?.to_string();
    let source_list_hash = trace_audit_reason_value(reason, "source_list_hash")?.to_string();
    let evidence_hash = trace_audit_reason_value(reason, "evidence_hash")?.to_string();
    let reason_hash = trace_audit_reason_value(reason, "reason_hash")?.to_string();
    if !is_canonical_sha256_prefixed_hash(&source_list_hash)
        || !is_canonical_sha256_prefixed_hash(&evidence_hash)
        || !is_canonical_sha256_prefixed_hash(&reason_hash)
    {
        return None;
    }
    let evidence_ref_hash = match trace_audit_reason_value(reason, "evidence_ref_hash") {
        Some(hash) if is_canonical_sha256_prefixed_hash(hash) => Some(hash.to_string()),
        Some(_) => return None,
        None => None,
    };
    Some(
        StorageTraceAuditSafeMetadata::CreditSettlementIssuerApproval {
            policy_version,
            source_list_hash,
            evidence_hash,
            reason_hash,
            evidence_ref_hash,
        },
    )
}

fn trace_audit_reason_is_credit_settlement_issuer_approval(reason: Option<&str>) -> bool {
    trace_audit_reason_value(reason, "surface") == Some("credit_settlement_issuer_approval")
}

fn trace_credit_settlement_issuer_approval_from_audit_event(
    event: &TraceCommonsAuditEvent,
) -> Option<anyhow::Result<TraceCreditSettlementIssuerApprovalResponse>> {
    let reason = event.reason.as_deref();
    if event.kind != "credit_settlement_issuer_approval"
        && !trace_audit_reason_is_credit_settlement_issuer_approval(reason)
    {
        return None;
    }
    Some((|| {
        let policy_version = trace_audit_reason_value(reason, "policy_version")
            .context("credit settlement issuer approval audit missing policy_version")?
            .to_string();
        let source_list_hash = trace_audit_reason_value(reason, "source_list_hash")
            .context("credit settlement issuer approval audit missing source_list_hash")?
            .to_string();
        let evidence_hash = trace_audit_reason_value(reason, "evidence_hash")
            .context("credit settlement issuer approval audit missing evidence_hash")?
            .to_string();
        let reason_hash = trace_audit_reason_value(reason, "reason_hash")
            .context("credit settlement issuer approval audit missing reason_hash")?
            .to_string();
        anyhow::ensure!(
            is_canonical_sha256_prefixed_hash(&source_list_hash),
            "credit settlement issuer approval source_list_hash must be a canonical sha256-prefixed hex digest"
        );
        anyhow::ensure!(
            is_canonical_sha256_prefixed_hash(&evidence_hash),
            "credit settlement issuer approval evidence_hash must be a canonical sha256-prefixed hex digest"
        );
        anyhow::ensure!(
            is_canonical_sha256_prefixed_hash(&reason_hash),
            "credit settlement issuer approval reason_hash must be a canonical sha256-prefixed hex digest"
        );
        let evidence_ref_hash =
            trace_audit_reason_value(reason, "evidence_ref_hash").map(ToOwned::to_owned);
        if let Some(evidence_ref_hash) = evidence_ref_hash.as_deref() {
            anyhow::ensure!(
                is_canonical_sha256_prefixed_hash(evidence_ref_hash),
                "credit settlement issuer approval evidence_ref_hash must be a canonical sha256-prefixed hex digest"
            );
        }
        Ok(TraceCreditSettlementIssuerApprovalResponse {
            event_id: event.event_id,
            tenant_id: event.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&event.tenant_id),
            policy_version,
            source_list_hash,
            evidence_hash,
            reason_hash,
            evidence_ref_hash,
            actor_principal_ref: event.actor_principal_ref.clone().unwrap_or_default(),
            recorded_at: event.created_at,
        })
    })())
}

async fn read_credit_settlement_issuer_approvals_for_admin(
    state: &AppState,
    tenant: &TenantAuth,
) -> anyhow::Result<Vec<TraceCreditSettlementIssuerApprovalResponse>> {
    let events = if state.db_audit_reads_for_tenant(&tenant.tenant_id) {
        read_audit_events_from_db(state, tenant).await?
    } else {
        read_all_audit_events(&state.root, &tenant.tenant_id)?
    };
    events
        .iter()
        .filter_map(trace_credit_settlement_issuer_approval_from_audit_event)
        .collect()
}

#[derive(Debug, Default, Clone, Copy)]
struct TraceCreditSettlementIssuerApprovalCheck {
    recorded: bool,
    fresh: bool,
}

async fn credit_settlement_issuer_approval_check(
    state: &AppState,
    tenant: &TenantAuth,
    policy_version: &str,
    source_list_hash: &str,
    evidence_hash: &str,
) -> anyhow::Result<TraceCreditSettlementIssuerApprovalCheck> {
    let now = Utc::now();
    let mut check = TraceCreditSettlementIssuerApprovalCheck::default();
    for approval in read_credit_settlement_issuer_approvals_for_admin(state, tenant).await? {
        if approval.policy_version == policy_version
            && approval.source_list_hash == source_list_hash
            && approval.evidence_hash == evidence_hash
        {
            check.recorded = true;
            if credit_settlement_issuer_approval_is_fresh(state, &approval, now) {
                check.fresh = true;
                break;
            }
        }
    }
    Ok(check)
}

fn credit_settlement_issuer_approval_is_fresh(
    state: &AppState,
    approval: &TraceCreditSettlementIssuerApprovalResponse,
    now: DateTime<Utc>,
) -> bool {
    state
        .credit_settlement_issuer_approval_max_age
        .is_none_or(|max_age| now.signed_duration_since(approval.recorded_at) <= max_age)
}

