async fn build_credit_risk_summary(
    state: &AppState,
    tenant: &TenantAuth,
    account_limit: usize,
) -> ApiResult<TraceCreditRiskSummaryResponse> {
    let records = read_reviewer_metadata_view(state, tenant)
        .await
        .map_err(internal_error)?
        .records;
    let delayed_credit_eligible_submission_ids = records
        .iter()
        .filter(|record| {
            record.status == TraceCorpusStatus::Accepted && delayed_credit_applies_to_record(record)
        })
        .map(|record| record.submission_id)
        .collect::<BTreeSet<_>>();
    let settlement_batches = read_credit_settlement_batches_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let settled_credit_event_ids = settlement_batches
        .iter()
        .filter(|batch| batch.status == StorageTraceCreditSettlementBatchStatus::Finalized)
        .flat_map(|batch| batch.source_credit_event_ids.iter().copied())
        .collect::<BTreeSet<_>>();
    let held_credit_accounts = active_credit_hold_account_refs_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let credit_events = read_credit_events_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let mut account_summaries = BTreeMap::<String, TraceCreditRiskAccountAccumulator>::new();
    for event in credit_events {
        if !trace_credit_event_type_is_settlement_eligible(event.event_type)
            || event.credit_points_delta <= 0.0
            || settled_credit_event_ids.contains(&event.event_id)
            || !delayed_credit_eligible_submission_ids.contains(&event.submission_id)
        {
            continue;
        }
        let credit_delta_micros = credit_delta_micros(event.credit_points_delta);
        if credit_delta_micros <= 0 {
            continue;
        }
        let account = account_summaries
            .entry(event.auth_principal_ref.clone())
            .or_default();
        if held_credit_accounts.contains(&event.auth_principal_ref) {
            account.held_credit_micros += credit_delta_micros;
            account.held_source_event_count += 1;
        } else {
            account.pending_credit_micros += credit_delta_micros;
            account.pending_source_event_count += 1;
        }
    }
    Ok(TraceCreditRiskSummaryResponse::from_account_summaries(
        tenant,
        state.credit_settlement_max_micros_per_account,
        account_limit,
        account_summaries,
    ))
}

async fn credit_hold_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceCreditHoldRequest>,
) -> ApiResult<Json<TraceCreditHoldRecord>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    require_credit_hold_control_principal_if_configured(state.as_ref(), &tenant)?;
    let credit_account_ref = body.credit_account_ref.trim().to_string();
    if credit_account_ref.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit holds require credit_account_ref",
        ));
    }
    let reason_detail = body.reason_detail.trim().to_string();
    if reason_detail.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "credit holds require reason_detail",
        ));
    }
    if !credit_account_ref_exists_for_admin(state.as_ref(), &tenant, &credit_account_ref)
        .await
        .map_err(internal_error)?
    {
        return Err(api_error(StatusCode::NOT_FOUND, "credit account not found"));
    }
    let hold = TraceCreditHoldRecord {
        hold_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        credit_account_ref: credit_account_ref.clone(),
        credit_account_hash: sha256_prefixed(&credit_account_ref),
        reason: body.reason,
        reason_hash: sha256_prefixed(&reason_detail),
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
        released_at: None,
    };
    let should_enqueue_near_freeze = if state.credit_settlement_near_contract_id.is_some() {
        let existing_holds = read_credit_holds_for_admin(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?;
        !active_credit_hold_exists_for_account(&existing_holds, &hold.credit_account_hash, None)
    } else {
        false
    };
    if should_enqueue_near_freeze {
        require_near_credit_hold_account_transition_principal_if_configured(
            state.as_ref(),
            &tenant,
        )?;
    }
    append_credit_hold_with_db_mirror(state.as_ref(), &tenant, &hold)
        .await
        .map_err(internal_error)?;
    if should_enqueue_near_freeze {
        append_credit_hold_near_account_outbox_item(
            state.as_ref(),
            &tenant,
            &hold,
            true,
            &hold.reason_hash,
        )
        .await
        .map_err(internal_error)?;
    }
    append_credit_hold_audit_event(
        state.as_ref(),
        &tenant,
        &hold,
        "credit_hold",
        &hold.reason_hash,
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(hold))
}

