fn confirmed_near_transaction_hash_for_outbox_item(
    item: &TraceNearCreditOutboxItem,
    response: &TraceNearCreditConfirmationResponse,
) -> anyhow::Result<String> {
    let submitted_hash = item
        .near_transaction_hash
        .as_deref()
        .context("NEAR credit confirmation requires near_transaction_hash")
        .and_then(normalize_near_transaction_hash)?;
    let confirmed_hash = response
        .near_transaction_hash
        .as_deref()
        .context("confirmed NEAR credit response requires near_transaction_hash")
        .and_then(normalize_near_transaction_hash)?;
    anyhow::ensure!(
        confirmed_hash == submitted_hash,
        "confirmed NEAR credit transaction hash does not match submitted outbox transaction"
    );
    Ok(submitted_hash)
}

fn ensure_near_status_transaction_hash_matches_existing(
    item: &TraceNearCreditOutboxItem,
    status: StorageTraceCreditSettlementNearStatus,
    requested_hash: Option<&str>,
) -> ApiResult<()> {
    if !matches!(
        status,
        StorageTraceCreditSettlementNearStatus::Submitted
            | StorageTraceCreditSettlementNearStatus::Confirmed
    ) {
        return Ok(());
    }
    let Some(existing_hash) = item.near_transaction_hash.as_deref() else {
        return Ok(());
    };
    let requested_hash = requested_hash.ok_or_else(|| {
        api_error(
            StatusCode::BAD_REQUEST,
            "submitted or confirmed NEAR credit outbox status requires near_transaction_hash",
        )
    })?;
    let existing_hash = normalize_near_transaction_hash(existing_hash)
        .map_err(|error| api_error(StatusCode::CONFLICT, error.to_string()))?;
    let requested_hash = normalize_near_transaction_hash(requested_hash)
        .map_err(|error| api_error(StatusCode::BAD_REQUEST, error.to_string()))?;
    if existing_hash != requested_hash {
        return Err(api_error(
            StatusCode::CONFLICT,
            "confirmed NEAR credit transaction hash does not match submitted outbox transaction",
        ));
    }
    Ok(())
}

fn near_credit_outbox_item_is_submit_candidate(item: &TraceNearCreditOutboxItem) -> bool {
    matches!(
        item.status,
        StorageTraceCreditSettlementNearStatus::Pending
            | StorageTraceCreditSettlementNearStatus::Failed
    )
}

fn near_credit_outbox_item_is_confirm_candidate(item: &TraceNearCreditOutboxItem) -> bool {
    item.status == StorageTraceCreditSettlementNearStatus::Submitted
        && item.near_transaction_hash.is_some()
}

fn near_credit_submitter_request_from_outbox_item(
    item: &TraceNearCreditOutboxItem,
) -> anyhow::Result<TraceNearCreditSubmitterRequest> {
    item.near_call.validate().with_context(|| {
        format!(
            "NEAR credit outbox item {} has invalid method-call payload",
            item.near_outbox_id
        )
    })?;
    Ok(TraceNearCreditSubmitterRequest {
        tenant_storage_ref: item.tenant_storage_ref.clone(),
        near_outbox_id: item.near_outbox_id,
        settlement_batch_id: item.settlement_batch_id,
        credit_account_hash: item.credit_account_hash.clone(),
        near_call: item.near_call.clone(),
    })
}

fn near_credit_confirmation_request_from_outbox_item(
    item: &TraceNearCreditOutboxItem,
) -> anyhow::Result<TraceNearCreditConfirmationRequest> {
    item.near_call.validate().with_context(|| {
        format!(
            "NEAR credit outbox item {} has invalid method-call payload",
            item.near_outbox_id
        )
    })?;
    let near_transaction_hash = item
        .near_transaction_hash
        .as_deref()
        .context("NEAR credit confirmation requires near_transaction_hash")
        .and_then(normalize_near_transaction_hash)?;
    Ok(TraceNearCreditConfirmationRequest {
        tenant_storage_ref: item.tenant_storage_ref.clone(),
        near_outbox_id: item.near_outbox_id,
        settlement_batch_id: item.settlement_batch_id,
        credit_account_hash: item.credit_account_hash.clone(),
        near_transaction_hash,
        near_contract_id: item.near_call.contract_id.clone(),
        near_method_name: item.near_call.method_name.clone(),
        near_call_idempotency_key: item.near_call.idempotency_key.clone(),
        near_call_hash: near_credit_call_hash(&item.near_call)?,
    })
}

fn near_credit_call_hash(call: &NearCreditReceiptCall) -> anyhow::Result<String> {
    call.validate()?;
    let canonical_call =
        serde_json::to_string(call).context("failed to serialize NEAR credit call for hash")?;
    Ok(sha256_prefixed(&canonical_call))
}

fn normalize_near_transaction_hash(hash: &str) -> anyhow::Result<String> {
    let hash = hash.trim();
    anyhow::ensure!(!hash.is_empty(), "near_transaction_hash is required");
    anyhow::ensure!(
        (TRACE_NEAR_TRANSACTION_HASH_MIN_LEN..=TRACE_NEAR_TRANSACTION_HASH_MAX_LEN)
            .contains(&hash.len()),
        "near_transaction_hash must be a 43-44 character base58 NEAR transaction hash"
    );
    anyhow::ensure!(
        hash.chars().all(is_near_base58_character),
        "near_transaction_hash contains non-base58 characters"
    );
    Ok(hash.to_string())
}

fn normalize_outbox_error_detail(value: &str, surface: &str) -> anyhow::Result<String> {
    let value = value.trim();
    anyhow::ensure!(!value.is_empty(), "{surface} requires error_detail");
    anyhow::ensure!(
        value.len() <= TRACE_OUTBOX_ERROR_DETAIL_MAX_LEN,
        "{surface} error_detail is too long"
    );
    Ok(value.to_string())
}

fn outbox_error_detail_hash(value: &str, surface: &str) -> anyhow::Result<String> {
    let value = normalize_outbox_error_detail(value, surface)?;
    Ok(sha256_prefixed(&value))
}

fn is_near_base58_character(character: char) -> bool {
    matches!(
        character,
        '1'..='9' | 'A'..='H' | 'J'..='N' | 'P'..='Z' | 'a'..='k' | 'm'..='z'
    )
}

fn normalize_external_registry_receipt_ref(value: &str) -> anyhow::Result<String> {
    let value = value.trim();
    anyhow::ensure!(!value.is_empty(), "external_receipt_ref is required");
    anyhow::ensure!(value.len() <= 512, "external_receipt_ref is too long");
    anyhow::ensure!(
        value
            .chars()
            .all(|character| character.is_ascii_graphic() && character != '"' && character != '\\'),
        "external_receipt_ref contains invalid characters"
    );
    Ok(value.to_string())
}

