async fn ranking_calibration_dataset_conflict_quarantine_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingCalibrationDatasetConflictQuarantineRequest>,
) -> ApiResult<Json<TraceRankingCalibrationDatasetConflictQuarantineResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    let calibration_dataset_hash =
        validate_sha256_hash(&body.calibration_dataset_hash, "calibration_dataset_hash")?;
    let policy_version = validate_ranking_identifier(&body.policy_version, "policy_version")?;
    let reason = validate_ranking_calibration_dataset_conflict_quarantine_reason(&body.reason)?;
    let reason_hash = sha256_prefixed(&reason);
    let conflict_key = ranking_calibration_dataset_key(
        &calibration_dataset_hash,
        body.target_use,
        &policy_version,
    )
    .map_err(internal_error)?;
    let read = read_ranking_calibration_datasets_for_admin_reconciliation(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    if !read.manifest_conflict_keys.contains(&conflict_key) {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking calibration dataset conflict is not active for this key",
        ));
    }
    let latest = read
        .records
        .iter()
        .find(|record| {
            record.calibration_dataset_hash == calibration_dataset_hash
                && record.target_use == body.target_use
                && record.policy_version == policy_version
        })
        .ok_or_else(|| {
            api_error(
                StatusCode::NOT_FOUND,
                "ranking calibration dataset conflict key was not found",
            )
        })?;
    let archived_record = TraceRankingCalibrationDatasetRecord {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        calibration_dataset_hash,
        target_use: body.target_use,
        policy_version,
        source_manifest_hash: latest.source_manifest_hash.clone(),
        source_count: latest.source_count,
        label_source_count: latest.label_source_count,
        label_actor_count: latest.label_actor_count,
        status: StorageTraceRankingCalibrationDatasetStatus::Archived,
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
    };
    append_ranking_calibration_dataset_status_override_with_db_mirror(
        state.as_ref(),
        &tenant,
        &archived_record,
    )
    .await
    .map_err(internal_error)?;
    append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        TraceCommonsAuditEvent::ranking_calibration_dataset_quarantine(
            &tenant,
            &archived_record,
            &conflict_key,
            &reason_hash,
        ),
        StorageTraceAuditAction::RankingCalibrationDatasetQuarantine,
        ranking_calibration_dataset_quarantine_audit_metadata(
            &archived_record,
            &conflict_key,
            &reason_hash,
        )
        .map_err(internal_error)?,
    )
    .await
    .map_err(internal_error)?;
    let remaining_conflict_count =
        read_ranking_calibration_datasets_for_admin_reconciliation(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?
            .manifest_conflict_keys
            .len();
    Ok(Json(
        TraceRankingCalibrationDatasetConflictQuarantineResponse {
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            conflict_key,
            reason_hash,
            archived_record,
            remaining_conflict_count,
        },
    ))
}

fn validate_ranking_calibration_dataset_conflict_quarantine_reason(
    reason: &str,
) -> ApiResult<String> {
    let reason = reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking calibration dataset conflict quarantine requires a non-empty reason",
        ));
    }
    if reason.len() > 1024 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking calibration dataset conflict quarantine reason is too long",
        ));
    }
    Ok(reason)
}

fn ranking_calibration_dataset_quarantine_decision_hash(
    conflict_key: &str,
    reason_hash: &str,
    archived_source_manifest_hash: &str,
) -> String {
    sha256_prefixed(&format!(
        "{conflict_key}\n{reason_hash}\n{archived_source_manifest_hash}"
    ))
}

fn ranking_calibration_dataset_quarantine_audit_metadata(
    record: &TraceRankingCalibrationDatasetRecord,
    conflict_key: &str,
    reason_hash: &str,
) -> anyhow::Result<StorageTraceAuditSafeMetadata> {
    Ok(
        StorageTraceAuditSafeMetadata::RankingCalibrationDatasetQuarantine {
            calibration_dataset_hash: record.calibration_dataset_hash.clone(),
            target_use: serde_storage_string(&record.target_use)?,
            policy_version: record.policy_version.clone(),
            archived_source_manifest_hash: record.source_manifest_hash.clone(),
            conflict_key_hash: sha256_prefixed(conflict_key),
            reason_hash: reason_hash.to_string(),
        },
    )
}

fn ranking_calibration_dataset_conflict_report(
    tenant: &TenantAuth,
    read: RankingCalibrationDatasetReconciliationRead,
) -> TraceRankingCalibrationDatasetConflictReport {
    let records_by_key = read
        .records
        .iter()
        .filter_map(|record| {
            ranking_calibration_dataset_file_key(record)
                .ok()
                .map(|key| (key, record))
        })
        .collect::<BTreeMap<_, _>>();
    let mut conflicts = read
        .manifest_conflict_keys
        .iter()
        .filter_map(|conflict_key| {
            let latest = records_by_key.get(conflict_key)?;
            Some(TraceRankingCalibrationDatasetConflictRecord {
                conflict_key: conflict_key.clone(),
                calibration_dataset_hash: latest.calibration_dataset_hash.clone(),
                target_use: latest.target_use,
                policy_version: latest.policy_version.clone(),
                latest_source_manifest_hash: latest.source_manifest_hash.clone(),
                latest_source_count: latest.source_count,
                latest_label_source_count: latest.label_source_count,
                latest_label_actor_count: latest.label_actor_count,
                latest_status: latest.status,
                latest_created_at: latest.created_at,
                blocks_credit_issuance: !ranking_calibration_dataset_status_is_retired(
                    latest.status,
                ),
                recommended_action:
                    "register a new calibration_dataset_hash or policy_version after choosing the canonical source manifest; do not rewrite this conflicted key"
                        .to_string(),
            })
        })
        .collect::<Vec<_>>();
    conflicts.sort_by(|left, right| left.conflict_key.cmp(&right.conflict_key));
    let conflict_keys = conflicts
        .iter()
        .map(|conflict| conflict.conflict_key.clone())
        .collect::<Vec<_>>();
    TraceRankingCalibrationDatasetConflictReport {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        conflict_count: conflicts.len(),
        conflict_keys,
        conflicts,
    }
}

async fn ranking_model_promotion_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingModelPromotionRequest>,
) -> ApiResult<Json<TraceRankingModelPromotionResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    promote_ranking_model_version(state.as_ref(), &tenant, body)
        .await
        .map(Json)
}

async fn ranking_model_promotion_worker_run_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingModelPromotionRunRequest>,
) -> ApiResult<Json<TraceRankingModelPromotionRunResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let reason = validate_ranking_model_promotion_reason(&body.reason)?;
    let limit = body
        .limit
        .unwrap_or(TRACE_RANKING_MODEL_PROMOTION_RUN_DEFAULT_LIMIT);
    if !(1..=TRACE_RANKING_MODEL_PROMOTION_RUN_MAX_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking model promotion run limit must be between 1 and 100",
        ));
    }
    let model_version = optional_ranking_identifier(body.model_version, "model_version")?;
    let policy_version = optional_ranking_identifier(body.policy_version, "policy_version")?;
    ensure_no_overlapping_live_ranking_worker_run(
        state.as_ref(),
        &tenant,
        TraceRankingWorkerRunKind::ModelPromotion,
        body.dry_run,
        model_version.as_deref(),
        Some(body.target_use),
        policy_version.as_deref(),
    )
    .await?;
    let model_versions = read_ranking_model_versions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let mut candidates = latest_ranking_model_versions(&model_versions)
        .into_iter()
        .filter(|model| model.status == StorageTraceRankingModelStatus::Candidate)
        .filter(|model| {
            model_version
                .as_ref()
                .is_none_or(|model_version| &model.model_version == model_version)
                && policy_version
                    .as_ref()
                    .is_none_or(|policy_version| &model.policy_version == policy_version)
        })
        .collect::<Vec<_>>();
    candidates.sort_by(|left, right| {
        (left.created_at, &left.model_version).cmp(&(right.created_at, &right.model_version))
    });

    let mut response = TraceRankingModelPromotionRunResponse {
        ranking_worker_run_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run: body.dry_run,
        limit,
        target_use: body.target_use,
        reason_hash: sha256_prefixed(&reason),
        model_version: model_version.clone(),
        policy_version: policy_version.clone(),
        checked_count: 0,
        promoted_count: 0,
        skipped_ineligible_count: 0,
        skipped_reason_counts: BTreeMap::new(),
        pending_after_count: 0,
        promotions: Vec::new(),
    };
    let mut worker_run = TraceRankingWorkerRunRecord {
        ranking_worker_run_id: response.ranking_worker_run_id,
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        run_kind: TraceRankingWorkerRunKind::ModelPromotion,
        status: TraceRankingWorkerRunStatus::Running,
        dry_run: response.dry_run,
        reason_hash: response.reason_hash.clone(),
        model_version: response.model_version.clone(),
        target_use: Some(response.target_use),
        policy_version: response.policy_version.clone(),
        limit: response.limit,
        checked_count: 0,
        succeeded_count: 0,
        skipped_existing_count: 0,
        skipped_model_risk_count: 0,
        skipped_ineligible_count: 0,
        pending_after_count: 0,
        result_refs: Vec::new(),
        reason_counts: BTreeMap::new(),
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
        completed_at: None,
        last_error_hash: None,
    };
    append_ranking_worker_run_with_db_mirror(state.as_ref(), &tenant, &worker_run)
        .await
        .map_err(internal_error)?;

    for model in candidates.into_iter().take(limit) {
        response.checked_count += 1;
        match promote_ranking_model_version(
            state.as_ref(),
            &tenant,
            TraceRankingModelPromotionRequest {
                dry_run: body.dry_run,
                model_version: model.model_version.clone(),
                target_use: body.target_use,
                policy_version: model.policy_version.clone(),
                reason: reason.clone(),
            },
        )
        .await
        {
            Ok(promotion) => {
                if promotion.promoted {
                    response.promoted_count += 1;
                }
                response.promotions.push(promotion);
            }
            Err((status, Json(error))) if ranking_model_promotion_run_can_skip_status(status) => {
                response.skipped_ineligible_count += 1;
                for reason in ranking_model_promotion_skip_reason_codes(&error.error) {
                    increment_count(&mut response.skipped_reason_counts, &reason);
                }
            }
            Err(error) => {
                update_model_promotion_worker_run_from_response(&mut worker_run, &response);
                let public_error = error.1.0.error.clone();
                finalize_failed_ranking_worker_run_with_db_mirror(
                    state.as_ref(),
                    &tenant,
                    &mut worker_run,
                    error.0,
                    &public_error,
                )
                .await?;
                return Err(error);
            }
        }
    }
    response.pending_after_count = match count_pending_ranking_model_promotions(
        state.as_ref(),
        &tenant,
        model_version.as_deref(),
        policy_version.as_deref(),
    )
    .await
    {
        Ok(pending_after_count) => pending_after_count,
        Err(error) => {
            let api_error = internal_error(error);
            update_model_promotion_worker_run_from_response(&mut worker_run, &response);
            let public_error = api_error.1.0.error.clone();
            finalize_failed_ranking_worker_run_with_db_mirror(
                state.as_ref(),
                &tenant,
                &mut worker_run,
                api_error.0,
                &public_error,
            )
            .await?;
            return Err(api_error);
        }
    };

    update_model_promotion_worker_run_from_response(&mut worker_run, &response);
    worker_run.status = TraceRankingWorkerRunStatus::Completed;
    worker_run.completed_at = Some(Utc::now());
    append_ranking_worker_run_with_db_mirror(state.as_ref(), &tenant, &worker_run)
        .await
        .map_err(internal_error)?;

    Ok(Json(response))
}

fn ranking_model_promotion_run_can_skip_status(status: StatusCode) -> bool {
    matches!(status, StatusCode::NOT_FOUND | StatusCode::CONFLICT)
}

fn ranking_model_promotion_skip_reason_codes(error: &str) -> Vec<String> {
    let Some((_, reason_codes)) = error.split_once("reason_codes=") else {
        return vec![error.to_string()];
    };
    let parsed = reason_codes
        .split(',')
        .map(str::trim)
        .filter(|reason| !reason.is_empty())
        .map(ToString::to_string)
        .collect::<Vec<_>>();
    if parsed.is_empty() {
        vec![error.to_string()]
    } else {
        parsed
    }
}

async fn ensure_no_overlapping_live_ranking_worker_run(
    state: &AppState,
    tenant: &TenantAuth,
    run_kind: TraceRankingWorkerRunKind,
    dry_run: bool,
    model_version: Option<&str>,
    target_use: Option<TraceAllowedUse>,
    policy_version: Option<&str>,
) -> ApiResult<()> {
    if has_overlapping_live_ranking_worker_run(
        state,
        tenant,
        run_kind,
        dry_run,
        model_version,
        target_use,
        policy_version,
    )
    .await?
    {
        return Err(api_error(
            StatusCode::CONFLICT,
            ranking_worker_run_active_conflict_message(run_kind),
        ));
    }
    Ok(())
}

async fn has_overlapping_live_ranking_worker_run(
    state: &AppState,
    tenant: &TenantAuth,
    run_kind: TraceRankingWorkerRunKind,
    dry_run: bool,
    model_version: Option<&str>,
    target_use: Option<TraceAllowedUse>,
    policy_version: Option<&str>,
) -> ApiResult<bool> {
    if dry_run {
        return Ok(false);
    }
    let worker_runs = read_ranking_worker_runs_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let stale_cutoff = Utc::now() - Duration::hours(TRACE_RANKING_WORKER_RUN_STALE_AFTER_HOURS);
    Ok(worker_runs.iter().any(|record| {
        ranking_worker_run_overlaps_live_claim(
            record,
            run_kind,
            model_version,
            target_use,
            policy_version,
            stale_cutoff,
        )
    }))
}

fn ranking_worker_run_overlaps_live_claim(
    record: &TraceRankingWorkerRunRecord,
    run_kind: TraceRankingWorkerRunKind,
    model_version: Option<&str>,
    target_use: Option<TraceAllowedUse>,
    policy_version: Option<&str>,
    stale_cutoff: DateTime<Utc>,
) -> bool {
    record.run_kind == run_kind
        && record.status == TraceRankingWorkerRunStatus::Running
        && !record.dry_run
        && record.created_at > stale_cutoff
        && ranking_optional_filter_overlaps(record.model_version.as_deref(), model_version)
        && ranking_optional_filter_overlaps(record.policy_version.as_deref(), policy_version)
        && ranking_optional_filter_overlaps(record.target_use, target_use)
}

fn ranking_optional_filter_overlaps<T: PartialEq>(left: Option<T>, right: Option<T>) -> bool {
    left.is_none() || right.is_none() || left == right
}

fn ranking_worker_run_active_conflict_message(run_kind: TraceRankingWorkerRunKind) -> &'static str {
    match run_kind {
        TraceRankingWorkerRunKind::Calibration => {
            "ranking calibration worker run is already active for overlapping filters"
        }
        TraceRankingWorkerRunKind::PredictionCredit => {
            "ranking prediction credit worker run is already active for overlapping filters"
        }
        TraceRankingWorkerRunKind::ModelPromotion => {
            "ranking model promotion worker run is already active for overlapping filters"
        }
        TraceRankingWorkerRunKind::CreditCycle => {
            "credit cycle worker run is already active for overlapping filters"
        }
        TraceRankingWorkerRunKind::ProcessEvaluation => {
            "process evaluation worker run is already active for overlapping filters"
        }
    }
}

fn ranking_worker_run_kind_label(run_kind: TraceRankingWorkerRunKind) -> &'static str {
    match run_kind {
        TraceRankingWorkerRunKind::Calibration => "calibration",
        TraceRankingWorkerRunKind::PredictionCredit => "prediction_credit",
        TraceRankingWorkerRunKind::ModelPromotion => "model_promotion",
        TraceRankingWorkerRunKind::CreditCycle => "credit_cycle",
        TraceRankingWorkerRunKind::ProcessEvaluation => "process_evaluation",
    }
}

fn ranking_worker_run_status_label(status: TraceRankingWorkerRunStatus) -> &'static str {
    match status {
        TraceRankingWorkerRunStatus::Running => "running",
        TraceRankingWorkerRunStatus::Completed => "completed",
        TraceRankingWorkerRunStatus::Failed => "failed",
    }
}

fn update_calibration_worker_run_from_response(
    worker_run: &mut TraceRankingWorkerRunRecord,
    response: &TraceRankingCalibrationRunWorkerResponse,
) {
    worker_run.checked_count = response.checked_count;
    worker_run.succeeded_count = response.calibrated_count;
    worker_run.skipped_existing_count = response.skipped_existing_count;
    worker_run.skipped_ineligible_count = response.skipped_ineligible_count;
    worker_run.pending_after_count = response.pending_after_count;
    worker_run.result_refs = if response.dry_run {
        Vec::new()
    } else {
        response
            .calibration_runs
            .iter()
            .map(|run| format!("ranking_calibration:{}", run.calibration_run_id))
            .collect()
    };
    worker_run.reason_counts = response.skipped_reason_counts.clone();
}

fn update_model_promotion_worker_run_from_response(
    worker_run: &mut TraceRankingWorkerRunRecord,
    response: &TraceRankingModelPromotionRunResponse,
) {
    worker_run.checked_count = response.checked_count;
    worker_run.succeeded_count = response.promoted_count;
    worker_run.skipped_ineligible_count = response.skipped_ineligible_count;
    worker_run.pending_after_count = response.pending_after_count;
    worker_run.result_refs = response
        .promotions
        .iter()
        .filter(|promotion| promotion.promoted)
        .map(|promotion| format!("ranking_model:{}", promotion.model_version))
        .collect();
    worker_run.reason_counts = response.skipped_reason_counts.clone();
}

fn update_process_evaluation_worker_run_from_response(
    worker_run: &mut TraceRankingWorkerRunRecord,
    response: &ProcessEvaluationWorkerRunResponse,
    result_refs: &[String],
) {
    worker_run.checked_count = response.checked_count;
    worker_run.succeeded_count = response.evaluated_count;
    worker_run.skipped_existing_count = response.skipped_existing_count;
    worker_run.skipped_ineligible_count = response.skipped_ineligible_count;
    worker_run.pending_after_count = response.pending_after_count;
    worker_run.result_refs = result_refs.to_vec();
    worker_run.reason_counts = response.skipped_reason_counts.clone();
}

fn validate_ranking_calibration_run_reason(reason: &str) -> ApiResult<String> {
    let reason = reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking calibration run requires a non-empty reason",
        ));
    }
    if reason.len() > 1024 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking calibration run reason is too long",
        ));
    }
    Ok(reason)
}

fn validate_ranking_model_promotion_reason(reason: &str) -> ApiResult<String> {
    let reason = reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking model promotion requires a non-empty reason",
        ));
    }
    if reason.len() > 1024 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking model promotion reason is too long",
        ));
    }
    Ok(reason)
}

async fn count_pending_ranking_model_promotions(
    state: &AppState,
    tenant: &TenantAuth,
    model_version: Option<&str>,
    policy_version: Option<&str>,
) -> anyhow::Result<usize> {
    let model_versions = read_ranking_model_versions_for_admin(state, tenant).await?;
    Ok(latest_ranking_model_versions(&model_versions)
        .into_iter()
        .filter(|model| model.status == StorageTraceRankingModelStatus::Candidate)
        .filter(|model| {
            model_version.is_none_or(|model_version| model.model_version == model_version)
                && policy_version
                    .is_none_or(|policy_version| model.policy_version == policy_version)
        })
        .count())
}

async fn promote_ranking_model_version(
    state: &AppState,
    tenant: &TenantAuth,
    body: TraceRankingModelPromotionRequest,
) -> ApiResult<TraceRankingModelPromotionResponse> {
    let model_version = validate_ranking_identifier(&body.model_version, "model_version")?;
    let policy_version = validate_ranking_identifier(&body.policy_version, "policy_version")?;
    let reason = validate_ranking_model_promotion_reason(&body.reason)?;

    let model_versions = read_ranking_model_versions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let model = latest_ranking_model_version(&model_versions, &model_version)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "ranking model version not found"))?;
    if model.policy_version != policy_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking model promotion policy does not match the registered model",
        ));
    }
    match model.status {
        StorageTraceRankingModelStatus::Candidate | StorageTraceRankingModelStatus::Active => {}
        StorageTraceRankingModelStatus::Deprecated | StorageTraceRankingModelStatus::Archived => {
            return Err(api_error(
                StatusCode::CONFLICT,
                "ranking model promotion requires a candidate or active model",
            ));
        }
    }
    ensure_ranking_model_dataset_isolation(model, RankingModelDatasetIsolationContext::Promotion)?;
    let calibration_datasets = read_ranking_calibration_datasets_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    ensure_ranking_calibration_dataset_can_feed_run(
        &calibration_datasets,
        &model.calibration_dataset_hash,
        body.target_use,
        &policy_version,
        ranking_calibration_dataset_gate_config(state, state.ranking_min_label_count),
    )?;

    let calibration_run = latest_promotable_ranking_calibration_run(
        state,
        tenant,
        &model_version,
        body.target_use,
        &policy_version,
        &model.calibration_dataset_hash,
        RankingCalibrationGateContext::ModelPromotion,
    )
    .await?;
    ensure_ranking_calibration_dataset_can_feed_run(
        &calibration_datasets,
        &model.calibration_dataset_hash,
        body.target_use,
        &policy_version,
        ranking_calibration_dataset_gate_config(state, calibration_run.min_label_count),
    )?;
    let current_calibration = ensure_ranking_promotion_current_evidence_matches_calibration(
        state,
        tenant,
        model,
        body.target_use,
        &calibration_run,
    )
    .await?;
    ensure_ranking_model_backtest_passes(state, tenant, &model_versions, model, body.target_use)
        .await?;
    ensure_active_ranking_model_has_promotable_calibration(
        state,
        tenant,
        &model_version,
        &policy_version,
        &model.calibration_dataset_hash,
    )
    .await?;

    let promoted = !body.dry_run && model.status == StorageTraceRankingModelStatus::Candidate;
    if promoted {
        let active_record = TraceRankingModelVersionRecord {
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            model_version: model.model_version.clone(),
            feature_schema_version: model.feature_schema_version.clone(),
            policy_version: model.policy_version.clone(),
            status: StorageTraceRankingModelStatus::Active,
            training_dataset_hash: model.training_dataset_hash.clone(),
            calibration_dataset_hash: model.calibration_dataset_hash.clone(),
            model_artifact_hash: model.model_artifact_hash.clone(),
            actor_principal_ref: tenant.principal_ref.clone(),
            created_at: Utc::now(),
        };
        append_ranking_model_version_with_db_mirror(state, tenant, &active_record)
            .await
            .map_err(internal_error)?;
    }

    Ok(TraceRankingModelPromotionResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run: body.dry_run,
        promoted,
        model_version,
        target_use: body.target_use,
        policy_version,
        model_status: if body.dry_run {
            model.status
        } else {
            StorageTraceRankingModelStatus::Active
        },
        calibration_run_id: calibration_run.calibration_run_id,
        calibration_report_hash: calibration_run.report_hash.clone(),
        calibration_dataset_hash: model.calibration_dataset_hash.clone(),
        calibration_joined_evidence_hash: calibration_run.joined_evidence_hash.clone(),
        calibration_joined_label_prediction_count: calibration_run.joined_label_prediction_count,
        calibration_joined_label_source_count: calibration_run.joined_label_source_count,
        calibration_joined_label_actor_count: calibration_run.joined_label_actor_count,
        current_calibration_report_hash: current_calibration.report_hash,
        current_joined_evidence_hash: current_calibration.joined_evidence_hash,
        current_joined_label_prediction_count: current_calibration.joined_label_prediction_count,
        current_joined_label_source_count: current_calibration.joined_label_source_count,
        current_joined_label_actor_count: current_calibration.joined_label_actor_count,
        current_average_absolute_error_micros: current_calibration.average_absolute_error_micros,
        current_max_label_source_average_absolute_error_micros: current_calibration
            .max_label_source_average_absolute_error_micros,
        current_low_confidence_prediction_count: current_calibration
            .low_confidence_prediction_count,
        current_promotable: current_calibration.promotable,
        current_reason_codes: current_calibration.reason_codes,
        effective_min_label_count: current_calibration.min_label_count,
        effective_min_label_source_count: current_calibration.min_label_source_count,
        effective_confidence_threshold: current_calibration.confidence_threshold,
        effective_max_average_absolute_error_micros: current_calibration
            .max_average_absolute_error_micros,
        reason_hash: sha256_prefixed(&reason),
    })
}

async fn ensure_ranking_model_backtest_passes(
    state: &AppState,
    tenant: &TenantAuth,
    model_versions: &[TraceRankingModelVersionRecord],
    model: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
) -> ApiResult<()> {
    let predictions = read_ranking_predictions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let labels = read_ranking_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let preference_labels = read_ranking_preference_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let calibration_datasets = read_ranking_calibration_datasets_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let calibration_runs = read_ranking_calibration_runs_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let report = ranking_model_backtest_report(
        state,
        tenant,
        model_versions,
        RankingModelRiskEvidence {
            predictions: &predictions,
            labels: &labels,
            preference_labels: &preference_labels,
            calibration_datasets: &calibration_datasets,
            calibration_runs: &calibration_runs,
        },
    );
    let Some(backtest) = report.models.into_iter().find(|record| {
        record.model_version == model.model_version
            && record.target_use == target_use
            && record.policy_version == model.policy_version
            && record.feature_schema_version == model.feature_schema_version
    }) else {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking model promotion requires a current model backtest",
        ));
    };
    if !backtest.passed {
        return Err(api_error(
            StatusCode::CONFLICT,
            format!(
                "ranking model promotion requires a passing current model backtest; reason_codes={}",
                backtest.reason_codes.join(",")
            ),
        ));
    }
    Ok(())
}

async fn ensure_active_ranking_model_has_promotable_calibration(
    state: &AppState,
    tenant: &TenantAuth,
    model_version: &str,
    policy_version: &str,
    calibration_dataset_hash: &str,
) -> ApiResult<()> {
    let calibration_runs = read_ranking_calibration_runs_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let Some(latest_run) = calibration_runs
        .into_iter()
        .filter(|run| {
            run.model_version == model_version
                && run.policy_version == policy_version
                && run.evaluation_dataset_hash == calibration_dataset_hash
        })
        .max_by_key(|run| run.created_at)
    else {
        return Err(api_error(
            StatusCode::CONFLICT,
            "active ranking model requires a calibration run for the requested model, policy, and calibration dataset",
        ));
    };
    if !latest_run.promotable {
        return Err(api_error(
            StatusCode::CONFLICT,
            "active ranking model requires the latest calibration run to be promotable",
        ));
    }
    ensure_ranking_calibration_label_source_diversity(
        state,
        &latest_run,
        RankingCalibrationGateContext::ModelPromotion,
    )?;
    ensure_ranking_calibration_fresh(
        state,
        &latest_run,
        RankingCalibrationGateContext::ModelPromotion,
    )?;
    Ok(())
}

async fn latest_promotable_ranking_calibration_run(
    state: &AppState,
    tenant: &TenantAuth,
    model_version: &str,
    target_use: TraceAllowedUse,
    policy_version: &str,
    calibration_dataset_hash: &str,
    context: RankingCalibrationGateContext,
) -> ApiResult<TraceRankingCalibrationRunRecord> {
    let calibration_runs = read_ranking_calibration_runs_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let Some(run) = calibration_runs
        .into_iter()
        .filter(|run| {
            run.model_version == model_version
                && run.target_use == target_use
                && run.policy_version == policy_version
                && run.evaluation_dataset_hash == calibration_dataset_hash
        })
        .max_by_key(|run| run.created_at)
    else {
        return Err(api_error(StatusCode::CONFLICT, context.missing_message()));
    };
    if !run.promotable {
        let message = if run.reason_codes.is_empty() {
            context.nonpromotable_message().to_string()
        } else {
            format!(
                "{}; reason_codes={}",
                context.nonpromotable_message(),
                run.reason_codes.join(",")
            )
        };
        return Err(api_error(StatusCode::CONFLICT, message));
    }
    ensure_ranking_calibration_label_source_diversity(state, &run, context)?;
    ensure_ranking_calibration_fresh(state, &run, context)?;
    Ok(run)
}

async fn ensure_ranking_promotion_current_evidence_matches_calibration(
    state: &AppState,
    tenant: &TenantAuth,
    model: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
    run: &TraceRankingCalibrationRunRecord,
) -> ApiResult<TraceRankingCalibrationRunRecord> {
    let predictions = read_ranking_predictions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let labels = read_ranking_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let preference_labels = read_ranking_preference_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let thresholds = effective_ranking_calibration_thresholds(state, Some(run));
    let mut current = ranking_calibration_run_record(
        tenant,
        RankingCalibrationRunInputs {
            calibration_run_id: Uuid::new_v4(),
            model_version: model.model_version.clone(),
            target_use,
            policy_version: model.policy_version.clone(),
            feature_schema_version: model.feature_schema_version.clone(),
            evaluation_dataset_hash: model.calibration_dataset_hash.clone(),
            min_label_count: thresholds.min_label_count,
            min_label_source_count: thresholds.min_label_source_count,
            confidence_threshold: thresholds.confidence_threshold,
            max_average_absolute_error_micros: thresholds.max_average_absolute_error_micros,
            actor_principal_ref: tenant.principal_ref.clone(),
            created_at: Utc::now(),
        },
        &predictions,
        &labels,
        &preference_labels,
    );
    current.report_hash = ranking_calibration_run_report_hash(&current);
    if current.joined_evidence_hash != run.joined_evidence_hash {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking model promotion requires current joined evidence to match the latest calibration run",
        ));
    }
    if !current.promotable {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking model promotion requires current evidence to remain promotable",
        ));
    }
    Ok(current)
}

async fn ranking_feature_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingFeatureRequest>,
) -> ApiResult<Json<TraceRankingFeatureRecord>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let submission = read_ranking_source_submission(
        state.as_ref(),
        &tenant,
        body.submission_id,
        body.target_use,
    )
    .await?;
    let feature_schema_version =
        validate_ranking_identifier(&body.feature_schema_version, "feature_schema_version")?;
    let feature_vector_hash =
        validate_sha256_hash(&body.feature_vector_hash, "feature_vector_hash")?;
    let feature_names_hash = validate_sha256_hash(&body.feature_names_hash, "feature_names_hash")?;
    let source_feature_hash =
        validate_sha256_hash(&body.source_feature_hash, "source_feature_hash")?;
    validate_optional_unit_score(body.duplicate_score, "duplicate_score")?;
    validate_optional_unit_score(body.novelty_score, "novelty_score")?;
    validate_optional_unit_score(body.privacy_risk_score, "privacy_risk_score")?;
    validate_optional_unit_score(body.quality_score, "quality_score")?;
    validate_ranking_codes(&body.coverage_tags, "coverage_tags")?;
    if body.coverage_tags.iter().any(|tag| {
        tag == RANKING_FEATURE_SERVER_PROVENANCE_TAG
            || tag == RANKING_FEATURE_VECTOR_METADATA_TAG
            || tag == RANKING_FEATURE_DERIVED_METADATA_TAG
            || tag.starts_with("feature_input:")
    }) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking feature server provenance and input tags are reserved for the feature worker",
        ));
    }

    let record = TraceRankingFeatureRecord {
        ranking_feature_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        submission_id: submission.submission_id,
        trace_id: submission.trace_id,
        target_use: body.target_use,
        feature_schema_version,
        feature_vector_hash,
        feature_names_hash,
        source_feature_hash,
        duplicate_score: body.duplicate_score,
        novelty_score: body.novelty_score,
        privacy_risk_score: body.privacy_risk_score,
        quality_score: body.quality_score,
        coverage_tags: body.coverage_tags,
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
    };
    append_ranking_feature_with_db_mirror(state.as_ref(), &tenant, &record)
        .await
        .map_err(internal_error)?;
    Ok(Json(record))
}

async fn ranking_feature_run_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingFeatureRunRequest>,
) -> ApiResult<Json<TraceRankingFeatureRunResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let feature_schema_version =
        validate_ranking_identifier(&body.feature_schema_version, "feature_schema_version")?;
    let reason = validate_ranking_feature_run_reason(&body.reason)?;
    let limit = body.limit.unwrap_or(DEFAULT_RANKING_FEATURE_RUN_LIMIT);
    if !(1..=MAX_RANKING_FEATURE_RUN_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking feature run limit must be between 1 and 500",
        ));
    }
    let tenant_policy =
        tenant_utility_credit_policy_for_request(state.as_ref(), &tenant, &[body.target_use])
            .await?;
    let metadata = read_reviewer_metadata_view(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let existing_features = read_ranking_features_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let active_vector_entries =
        read_active_vector_entries_by_submission_source(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?;
    let mut existing_server_feature_keys = existing_features
        .iter()
        .filter(|feature| ranking_feature_is_server_provenanced(feature))
        .map(|feature| {
            (
                feature.submission_id,
                feature.target_use,
                feature.feature_schema_version.clone(),
                feature.source_feature_hash.clone(),
            )
        })
        .collect::<BTreeSet<_>>();
    let records_by_submission = metadata
        .records
        .iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let mut derived = metadata
        .derived
        .iter()
        .filter(|record| record.status == TraceCorpusStatus::Accepted)
        .filter(|record| !record.canonical_summary_hash.trim().is_empty())
        .collect::<Vec<_>>();
    derived.sort_by_key(|record| (record.created_at, record.submission_id));

    let mut response = TraceRankingFeatureRunResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run: body.dry_run,
        target_use: body.target_use,
        feature_schema_version: feature_schema_version.clone(),
        reason_hash: sha256_prefixed(&reason),
        limit,
        checked_count: 0,
        generated_count: 0,
        skipped_existing_count: 0,
        skipped_ineligible_count: 0,
        skipped_missing_vector_count: 0,
        vector_backed_count: 0,
        pending_after_count: 0,
        feature_refs: Vec::new(),
    };

    for derived in derived {
        if response.generated_count >= limit {
            break;
        }
        response.checked_count += 1;
        let Some(record) = records_by_submission.get(&derived.submission_id) else {
            response.skipped_ineligible_count += 1;
            continue;
        };
        if record.status != TraceCorpusStatus::Accepted
            || !record_matches_utility_credit_policy_abac(
                record,
                &tenant,
                tenant_policy.as_ref(),
                &[body.target_use],
            )
        {
            response.skipped_ineligible_count += 1;
            continue;
        }
        let vector_entry = active_vector_entries.get(&(
            derived.submission_id,
            derived.canonical_summary_hash.clone(),
        ));
        if body.require_vector_metadata && vector_entry.is_none() {
            response.skipped_missing_vector_count += 1;
            continue;
        }
        let feature_key = (
            derived.submission_id,
            body.target_use,
            feature_schema_version.clone(),
            derived.canonical_summary_hash.clone(),
        );
        if existing_server_feature_keys.contains(&feature_key) {
            response.skipped_existing_count += 1;
            continue;
        }
        let feature = server_derived_ranking_feature_record(
            &tenant,
            record,
            derived,
            vector_entry,
            body.target_use,
            &feature_schema_version,
        );
        response
            .feature_refs
            .push(ranking_feature_external_ref(feature.ranking_feature_id));
        response.generated_count += 1;
        if vector_entry.is_some() {
            response.vector_backed_count += 1;
        }
        existing_server_feature_keys.insert(feature_key);
        if !body.dry_run {
            append_ranking_feature_with_db_mirror(state.as_ref(), &tenant, &feature)
                .await
                .map_err(internal_error)?;
        }
    }

    let pending_before_current_run =
        count_pending_server_ranking_features(PendingServerRankingFeatureInputs {
            metadata: &metadata,
            features: &existing_features,
            records_by_submission: &records_by_submission,
            tenant: &tenant,
            tenant_policy: tenant_policy.as_ref(),
            target_use: body.target_use,
            feature_schema_version: &feature_schema_version,
            active_vector_entries: &active_vector_entries,
            require_vector_metadata: body.require_vector_metadata,
        });
    response.pending_after_count = if body.dry_run {
        pending_before_current_run
    } else {
        pending_before_current_run.saturating_sub(response.generated_count)
    };
    Ok(Json(response))
}

fn validate_ranking_feature_run_reason(reason: &str) -> ApiResult<String> {
    let reason = reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking feature runs require a non-empty reason",
        ));
    }
    if reason.len() > 1024 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking feature run reason is too long",
        ));
    }
    Ok(reason)
}

fn ranking_feature_external_ref(ranking_feature_id: Uuid) -> String {
    format!("ranking_feature:{ranking_feature_id}")
}

async fn read_active_vector_entries_by_submission_source(
    state: &AppState,
    tenant: &TenantAuth,
) -> anyhow::Result<BTreeMap<(Uuid, String), StorageTraceVectorEntryRecord>> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(BTreeMap::new());
    };
    let mut entries = db
        .list_trace_vector_entries(&tenant.tenant_id)
        .await
        .context("failed to read active vector metadata for ranking features")?;
    entries.sort_by_key(|entry| {
        (
            entry.indexed_at.unwrap_or(entry.updated_at),
            entry.updated_at,
            entry.vector_entry_id,
        )
    });
    let mut by_submission_source = BTreeMap::new();
    for entry in entries {
        if entry.status == StorageTraceVectorEntryStatus::Active
            && entry.source_projection == StorageTraceVectorEntrySourceProjection::CanonicalSummary
            && !entry.source_hash.trim().is_empty()
        {
            by_submission_source.insert((entry.submission_id, entry.source_hash.clone()), entry);
        }
    }
    Ok(by_submission_source)
}

fn ranking_feature_is_server_provenanced(feature: &TraceRankingFeatureRecord) -> bool {
    feature
        .coverage_tags
        .iter()
        .any(|tag| tag == RANKING_FEATURE_SERVER_PROVENANCE_TAG)
}

fn ranking_prediction_has_server_feature_provenance(
    features: &[TraceRankingFeatureRecord],
    prediction: &TraceRankingPredictionRecord,
) -> bool {
    features.iter().any(|feature| {
        feature.submission_id == prediction.submission_id
            && feature.target_use == prediction.target_use
            && feature.feature_schema_version == prediction.feature_schema_version
            && feature.feature_vector_hash == prediction.feature_vector_hash
            && ranking_feature_is_server_provenanced(feature)
    })
}

fn server_derived_ranking_feature_record(
    tenant: &TenantAuth,
    submission: &TraceCommonsSubmissionRecord,
    derived: &TraceCommonsDerivedRecord,
    vector_entry: Option<&StorageTraceVectorEntryRecord>,
    target_use: TraceAllowedUse,
    feature_schema_version: &str,
) -> TraceRankingFeatureRecord {
    let source_feature_hash = vector_entry
        .map(|entry| entry.source_hash.clone())
        .unwrap_or_else(|| derived.canonical_summary_hash.clone());
    let feature_vector_hash = server_derived_ranking_feature_vector_hash(
        tenant,
        submission,
        derived,
        vector_entry,
        target_use,
        feature_schema_version,
    );
    let ranking_feature_id = deterministic_trace_uuid_for_external_ref(
        "ranking_feature_server_derived",
        &tenant.tenant_id,
        submission.submission_id,
        &format!("{feature_schema_version}:{target_use:?}:{source_feature_hash}"),
    );
    let coverage_tags = server_derived_ranking_feature_coverage_tags(derived, vector_entry);
    TraceRankingFeatureRecord {
        ranking_feature_id,
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        submission_id: submission.submission_id,
        trace_id: submission.trace_id,
        target_use,
        feature_schema_version: feature_schema_version.to_string(),
        feature_vector_hash,
        feature_names_hash: server_derived_ranking_feature_names_hash(feature_schema_version),
        source_feature_hash,
        duplicate_score: Some(
            vector_entry
                .and_then(|entry| entry.duplicate_score)
                .unwrap_or(derived.duplicate_score),
        ),
        novelty_score: Some(
            vector_entry
                .and_then(|entry| entry.novelty_score)
                .unwrap_or(derived.novelty_score),
        ),
        privacy_risk_score: Some(privacy_risk_feature_score(submission.privacy_risk)),
        quality_score: Some(submission.submission_score.clamp(0.0, 1.0)),
        coverage_tags,
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
    }
}

fn server_derived_ranking_feature_names_hash(feature_schema_version: &str) -> String {
    sha256_prefixed(&format!(
        "ranking_feature_names:server_derived:v1\n{feature_schema_version}\nduplicate_score\nnovelty_score\nprivacy_risk_score\nquality_score\ncoverage_tags"
    ))
}

fn server_derived_ranking_feature_coverage_tags(
    derived: &TraceCommonsDerivedRecord,
    vector_entry: Option<&StorageTraceVectorEntryRecord>,
) -> Vec<String> {
    let mut coverage_tags = derived.coverage_tags.clone();
    coverage_tags.push(RANKING_FEATURE_SERVER_PROVENANCE_TAG.to_string());
    coverage_tags.push(
        if vector_entry.is_some() {
            RANKING_FEATURE_VECTOR_METADATA_TAG
        } else {
            RANKING_FEATURE_DERIVED_METADATA_TAG
        }
        .to_string(),
    );
    coverage_tags.sort();
    coverage_tags.dedup();
    coverage_tags
}

fn optional_score_feature_bits(score: Option<f32>) -> String {
    score
        .map(|score| score.to_bits().to_string())
        .unwrap_or_else(|| "none".to_string())
}

fn server_derived_ranking_feature_vector_hash(
    tenant: &TenantAuth,
    submission: &TraceCommonsSubmissionRecord,
    derived: &TraceCommonsDerivedRecord,
    vector_entry: Option<&StorageTraceVectorEntryRecord>,
    target_use: TraceAllowedUse,
    feature_schema_version: &str,
) -> String {
    let coverage_tags =
        server_derived_ranking_feature_coverage_tags(derived, vector_entry).join(",");
    let vector_metadata = vector_entry
        .map(|entry| {
            format!(
                "{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}",
                entry.vector_entry_id,
                entry.vector_store,
                entry.embedding_model,
                entry.embedding_dimension,
                entry.embedding_version,
                serde_enum_tag(&entry.source_projection),
                entry.source_hash,
                entry.nearest_trace_ids.join(","),
                entry.cluster_id.as_deref().unwrap_or("none"),
                [
                    optional_score_feature_bits(entry.duplicate_score),
                    optional_score_feature_bits(entry.novelty_score),
                ]
                .join(",")
            )
        })
        .unwrap_or_else(|| "none".to_string());
    sha256_prefixed(&format!(
        "ranking_feature_vector:server_derived:v1\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}",
        tenant_storage_ref(&tenant.tenant_id),
        submission.submission_id,
        submission.trace_id,
        serde_enum_tag(&target_use),
        feature_schema_version,
        derived.canonical_summary_hash,
        derived.duplicate_score.to_bits(),
        derived.novelty_score.to_bits(),
        serde_enum_tag(&submission.privacy_risk),
        submission.submission_score.to_bits(),
        coverage_tags,
        vector_metadata
    ))
}

fn privacy_risk_feature_score(privacy_risk: ResidualPiiRisk) -> f32 {
    match privacy_risk {
        ResidualPiiRisk::Low => 0.05,
        ResidualPiiRisk::Medium => 0.5,
        ResidualPiiRisk::High => 0.95,
    }
}

struct PendingServerRankingFeatureInputs<'a> {
    metadata: &'a TraceCommonsMetadataView,
    features: &'a [TraceRankingFeatureRecord],
    records_by_submission: &'a BTreeMap<Uuid, &'a TraceCommonsSubmissionRecord>,
    tenant: &'a TenantAuth,
    tenant_policy: Option<&'a TenantSubmissionPolicy>,
    target_use: TraceAllowedUse,
    feature_schema_version: &'a str,
    active_vector_entries: &'a BTreeMap<(Uuid, String), StorageTraceVectorEntryRecord>,
    require_vector_metadata: bool,
}

fn count_pending_server_ranking_features(inputs: PendingServerRankingFeatureInputs<'_>) -> usize {
    let existing_server_feature_keys = inputs
        .features
        .iter()
        .filter(|feature| ranking_feature_is_server_provenanced(feature))
        .map(|feature| {
            (
                feature.submission_id,
                feature.target_use,
                feature.feature_schema_version.clone(),
                feature.source_feature_hash.clone(),
            )
        })
        .collect::<BTreeSet<_>>();
    inputs
        .metadata
        .derived
        .iter()
        .filter(|derived| derived.status == TraceCorpusStatus::Accepted)
        .filter(|derived| !derived.canonical_summary_hash.trim().is_empty())
        .filter(|derived| {
            !inputs.require_vector_metadata
                || inputs.active_vector_entries.contains_key(&(
                    derived.submission_id,
                    derived.canonical_summary_hash.clone(),
                ))
        })
        .filter_map(|derived| {
            let record = inputs.records_by_submission.get(&derived.submission_id)?;
            (record.status == TraceCorpusStatus::Accepted
                && record_matches_utility_credit_policy_abac(
                    record,
                    inputs.tenant,
                    inputs.tenant_policy,
                    &[inputs.target_use],
                ))
            .then_some(derived)
        })
        .filter(|derived| {
            !existing_server_feature_keys.contains(&(
                derived.submission_id,
                inputs.target_use,
                inputs.feature_schema_version.to_string(),
                derived.canonical_summary_hash.clone(),
            ))
        })
        .count()
}

async fn ranking_features_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
) -> ApiResult<Json<Vec<TraceRankingFeatureRecord>>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    let records = read_ranking_features_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    append_control_plane_read_audit(state.as_ref(), &tenant, "ranking_features", records.len())
        .await
        .map_err(internal_error)?;
    Ok(Json(records))
}

async fn ranking_prediction_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingPredictionRequest>,
) -> ApiResult<Json<TraceRankingPredictionRecord>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let submission = read_ranking_source_submission(
        state.as_ref(),
        &tenant,
        body.submission_id,
        body.target_use,
    )
    .await?;
    let model_version = validate_ranking_identifier(&body.model_version, "model_version")?;
    let feature_schema_version =
        validate_ranking_identifier(&body.feature_schema_version, "feature_schema_version")?;
    let prediction_policy_version =
        validate_ranking_identifier(&body.prediction_policy_version, "prediction_policy_version")?;
    let feature_vector_hash =
        validate_sha256_hash(&body.feature_vector_hash, "feature_vector_hash")?;
    validate_nonnegative_micros(body.predicted_utility_micros, "predicted_utility_micros")?;
    validate_nonnegative_micros(body.uncertainty_micros, "uncertainty_micros")?;
    validate_unit_score(body.confidence, "confidence")?;
    validate_nonnegative_micros(body.risk_penalty_micros, "risk_penalty_micros")?;
    validate_nonnegative_micros(body.novelty_bonus_micros, "novelty_bonus_micros")?;
    validate_ranking_codes(&body.explanation_codes, "explanation_codes")?;
    let model_versions = read_ranking_model_versions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let model = latest_ranking_model_version(&model_versions, &model_version).ok_or_else(|| {
        api_error(
            StatusCode::NOT_FOUND,
            "ranking prediction model version not found",
        )
    })?;
    ensure_ranking_model_accepts_evidence(model)?;
    if model.feature_schema_version != feature_schema_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction feature schema does not match the registered model",
        ));
    }
    if model.policy_version != prediction_policy_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction policy does not match the registered model",
        ));
    }
    let features = read_ranking_features_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    if !features.iter().any(|feature| {
        feature.submission_id == submission.submission_id
            && feature.target_use == body.target_use
            && feature.feature_schema_version == feature_schema_version
            && feature.feature_vector_hash == feature_vector_hash
    }) {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction must reference an existing feature vector for the source and model schema",
        ));
    }

    let settlement_score_micros =
        body.predicted_utility_micros + body.novelty_bonus_micros - body.risk_penalty_micros;
    let record = TraceRankingPredictionRecord {
        ranking_prediction_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        submission_id: submission.submission_id,
        trace_id: submission.trace_id,
        target_use: body.target_use,
        model_version,
        feature_schema_version,
        prediction_policy_version,
        feature_vector_hash,
        predicted_utility_micros: body.predicted_utility_micros,
        uncertainty_micros: body.uncertainty_micros,
        confidence: body.confidence,
        risk_penalty_micros: body.risk_penalty_micros,
        novelty_bonus_micros: body.novelty_bonus_micros,
        settlement_score_micros,
        explanation_codes: body.explanation_codes,
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
    };
    append_ranking_prediction_with_db_mirror(state.as_ref(), &tenant, &record)
        .await
        .map_err(internal_error)?;
    Ok(Json(record))
}

async fn ranking_prediction_credit_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingPredictionCreditRequest>,
) -> ApiResult<Json<TraceRankingPredictionCreditResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let reason = validate_ranking_prediction_credit_reason(&body.reason)?;
    require_positive_credit_issuance_principal_if_configured(state.as_ref(), &tenant, 1.0)?;

    let predictions = read_ranking_predictions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    let prediction = predictions
        .into_iter()
        .find(|prediction| prediction.ranking_prediction_id == body.ranking_prediction_id)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "ranking prediction not found"))?;
    append_ranking_prediction_credit_for_record(
        state.as_ref(),
        &tenant,
        prediction,
        &reason,
        false,
        false,
    )
    .await
    .map(Json)
}

async fn ranking_prediction_credit_run_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceRankingPredictionCreditRunRequest>,
) -> ApiResult<Json<TraceRankingPredictionCreditRunResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_utility_operator(&tenant)?;
    let reason = validate_ranking_prediction_credit_reason(&body.reason)?;
    let limit = body
        .limit
        .unwrap_or(DEFAULT_RANKING_PREDICTION_CREDIT_RUN_LIMIT);
    if !(1..=MAX_RANKING_PREDICTION_CREDIT_RUN_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking prediction credit run limit must be between 1 and 500",
        ));
    }
    if !body.dry_run {
        require_positive_credit_issuance_principal_if_configured(state.as_ref(), &tenant, 1.0)?;
    }
    let model_version = optional_ranking_identifier(body.model_version, "model_version")?;
    let policy_version = optional_ranking_identifier(body.policy_version, "policy_version")?;
    ensure_no_overlapping_live_ranking_worker_run(
        state.as_ref(),
        &tenant,
        TraceRankingWorkerRunKind::PredictionCredit,
        body.dry_run,
        model_version.as_deref(),
        body.target_use,
        policy_version.as_deref(),
    )
    .await?;
    let mut predictions = read_ranking_predictions_for_admin(state.as_ref(), &tenant)
        .await
        .map_err(internal_error)?;
    predictions.sort_by_key(|prediction| {
        (
            prediction.created_at,
            prediction.submission_id,
            prediction.ranking_prediction_id,
        )
    });
    let blocked_model_risk_codes_by_key = if body.allow_at_risk_models {
        BTreeMap::new()
    } else {
        let model_versions = read_ranking_model_versions_for_admin(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?;
        let labels = read_ranking_labels_for_admin(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?;
        let preference_labels = read_ranking_preference_labels_for_admin(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?;
        let calibration_datasets =
            read_ranking_calibration_datasets_for_admin(state.as_ref(), &tenant)
                .await
                .map_err(internal_error)?;
        let calibration_runs = read_ranking_calibration_runs_for_admin(state.as_ref(), &tenant)
            .await
            .map_err(internal_error)?;
        blocking_ranking_model_risk_codes_by_key(ranking_model_risk_report(
            state.as_ref(),
            &tenant,
            &model_versions,
            RankingModelRiskEvidence {
                predictions: &predictions,
                labels: &labels,
                preference_labels: &preference_labels,
                calibration_datasets: &calibration_datasets,
                calibration_runs: &calibration_runs,
            },
        ))
    };
    let mut response = TraceRankingPredictionCreditRunResponse {
        ranking_worker_run_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run: body.dry_run,
        allow_at_risk_models: body.allow_at_risk_models,
        limit,
        reason_hash: sha256_prefixed(&reason),
        model_version: model_version.clone(),
        target_use: body.target_use,
        policy_version: policy_version.clone(),
        checked_count: 0,
        credited_count: 0,
        skipped_existing_count: 0,
        skipped_model_risk_count: 0,
        skipped_ineligible_count: 0,
        blocked_model_risk_reason_counts: BTreeMap::new(),
        pending_after_count: 0,
    };
    let mut worker_run = TraceRankingWorkerRunRecord {
        ranking_worker_run_id: response.ranking_worker_run_id,
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        run_kind: TraceRankingWorkerRunKind::PredictionCredit,
        status: TraceRankingWorkerRunStatus::Running,
        dry_run: response.dry_run,
        reason_hash: response.reason_hash.clone(),
        model_version: response.model_version.clone(),
        target_use: response.target_use,
        policy_version: response.policy_version.clone(),
        limit: response.limit,
        checked_count: 0,
        succeeded_count: 0,
        skipped_existing_count: 0,
        skipped_model_risk_count: 0,
        skipped_ineligible_count: 0,
        pending_after_count: 0,
        result_refs: Vec::new(),
        reason_counts: BTreeMap::new(),
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
        completed_at: None,
        last_error_hash: None,
    };
    append_ranking_worker_run_with_db_mirror(state.as_ref(), &tenant, &worker_run)
        .await
        .map_err(internal_error)?;

    let mut attempted_uncredited = 0;
    let mut result_refs = Vec::new();
    for prediction in predictions.into_iter().filter(|prediction| {
        model_version
            .as_ref()
            .is_none_or(|model_version| &prediction.model_version == model_version)
            && body
                .target_use
                .is_none_or(|target_use| prediction.target_use == target_use)
            && policy_version.as_ref().is_none_or(|policy_version| {
                &prediction.prediction_policy_version == policy_version
            })
    }) {
        let already_credited =
            match ranking_prediction_credit_already_exists(state.as_ref(), &tenant, &prediction)
                .await
            {
                Ok(already_credited) => already_credited,
                Err(error) => {
                    let api_error = internal_error(error);
                    update_prediction_credit_worker_run_from_response(
                        &mut worker_run,
                        &response,
                        &result_refs,
                    );
                    let public_error = api_error.1.0.error.clone();
                    finalize_failed_ranking_worker_run_with_db_mirror(
                        state.as_ref(),
                        &tenant,
                        &mut worker_run,
                        api_error.0,
                        &public_error,
                    )
                    .await?;
                    return Err(api_error);
                }
            };
        if already_credited {
            response.checked_count += 1;
            response.skipped_existing_count += 1;
            continue;
        }
        if attempted_uncredited >= limit {
            break;
        }
        response.checked_count += 1;
        attempted_uncredited += 1;
        if let Some(risk_codes) =
            blocked_model_risk_codes_by_key.get(&ranking_prediction_risk_lookup_key(&prediction))
        {
            response.skipped_model_risk_count += 1;
            for code in risk_codes {
                *response
                    .blocked_model_risk_reason_counts
                    .entry(code.clone())
                    .or_insert(0) += 1;
            }
            continue;
        }
        let result_ref = ranking_prediction_external_ref(prediction.ranking_prediction_id);
        match append_ranking_prediction_credit_for_record(
            state.as_ref(),
            &tenant,
            prediction,
            &reason,
            body.dry_run,
            true,
        )
        .await
        {
            Ok(credit) => {
                if credit.appended_count > 0 {
                    result_refs.push(result_ref);
                }
                response.credited_count += credit.appended_count;
                response.skipped_existing_count += credit.skipped_existing_count;
            }
            Err((status, _)) if ranking_prediction_credit_run_can_skip_status(status) => {
                response.skipped_ineligible_count += 1;
            }
            Err(error) => {
                update_prediction_credit_worker_run_from_response(
                    &mut worker_run,
                    &response,
                    &result_refs,
                );
                let public_error = error.1.0.error.clone();
                finalize_failed_ranking_worker_run_with_db_mirror(
                    state.as_ref(),
                    &tenant,
                    &mut worker_run,
                    error.0,
                    &public_error,
                )
                .await?;
                return Err(error);
            }
        }
    }
    response.pending_after_count = match count_pending_ranking_prediction_credits(
        state.as_ref(),
        &tenant,
        model_version.as_deref(),
        body.target_use,
        policy_version.as_deref(),
    )
    .await
    {
        Ok(pending_after_count) => pending_after_count,
        Err(error) => {
            let api_error = internal_error(error);
            update_prediction_credit_worker_run_from_response(
                &mut worker_run,
                &response,
                &result_refs,
            );
            let public_error = api_error.1.0.error.clone();
            finalize_failed_ranking_worker_run_with_db_mirror(
                state.as_ref(),
                &tenant,
                &mut worker_run,
                api_error.0,
                &public_error,
            )
            .await?;
            return Err(api_error);
        }
    };
    update_prediction_credit_worker_run_from_response(&mut worker_run, &response, &result_refs);
    worker_run.status = TraceRankingWorkerRunStatus::Completed;
    worker_run.completed_at = Some(Utc::now());
    append_ranking_worker_run_with_db_mirror(state.as_ref(), &tenant, &worker_run)
        .await
        .map_err(internal_error)?;
    Ok(Json(response))
}

fn validate_ranking_prediction_credit_reason(reason: &str) -> ApiResult<String> {
    let reason = reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking prediction credit jobs require a non-empty reason",
        ));
    }
    if reason.len() > 1024 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking prediction credit reason is too long",
        ));
    }
    Ok(reason)
}

fn optional_ranking_identifier(value: Option<String>, label: &str) -> ApiResult<Option<String>> {
    value
        .map(|value| validate_ranking_identifier(&value, label))
        .transpose()
}

fn ranking_prediction_credit_run_can_skip_status(status: StatusCode) -> bool {
    matches!(
        status,
        StatusCode::BAD_REQUEST | StatusCode::NOT_FOUND | StatusCode::CONFLICT
    )
}

fn update_prediction_credit_worker_run_from_response(
    worker_run: &mut TraceRankingWorkerRunRecord,
    response: &TraceRankingPredictionCreditRunResponse,
    result_refs: &[String],
) {
    worker_run.checked_count = response.checked_count;
    worker_run.succeeded_count = response.credited_count;
    worker_run.skipped_existing_count = response.skipped_existing_count;
    worker_run.skipped_model_risk_count = response.skipped_model_risk_count;
    worker_run.skipped_ineligible_count = response.skipped_ineligible_count;
    worker_run.pending_after_count = response.pending_after_count;
    worker_run.result_refs = result_refs.to_vec();
    worker_run.reason_counts = response.blocked_model_risk_reason_counts.clone();
}

fn ranking_worker_run_error_hash(http_status: StatusCode, public_error: &str) -> String {
    sha256_prefixed(&format!(
        "status={};error={public_error}",
        http_status.as_u16()
    ))
}

fn ranking_worker_run_recovery_error_hash(reason: &str) -> String {
    sha256_prefixed(&format!(
        "status=409;error=stale_ranking_worker_run_recovered;reason_hash={}",
        sha256_prefixed(reason)
    ))
}

fn export_job_recovery_last_error(reason_hash: &str) -> String {
    format!("stale_export_job_expired;reason_hash={reason_hash}")
}

fn next_export_job_retry_count(metadata: &BTreeMap<String, String>) -> u32 {
    metadata
        .get("retry_count")
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or(0)
        .saturating_add(1)
}

fn current_export_job_retry_count(metadata: &BTreeMap<String, String>) -> u32 {
    metadata
        .get("retry_count")
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or(0)
}

fn export_job_retry_delay(
    retry_count: u32,
    base_delay_seconds: i64,
    max_delay_seconds: i64,
) -> Duration {
    let exponent = retry_count.min(10);
    let multiplier = 1_i64.checked_shl(exponent).unwrap_or(i64::MAX);
    let delay_seconds = base_delay_seconds
        .saturating_mul(multiplier)
        .min(max_delay_seconds);
    Duration::seconds(delay_seconds)
}

fn export_job_retry_due_at(
    record: &StorageTraceExportJobRecord,
    base_delay_seconds: i64,
    max_delay_seconds: i64,
) -> DateTime<Utc> {
    let retry_count = current_export_job_retry_count(&record.metadata);
    let failed_at = record.finished_at.unwrap_or(record.updated_at);
    failed_at + export_job_retry_delay(retry_count, base_delay_seconds, max_delay_seconds)
}

fn export_job_recovery_audit_reason(
    export_job_id: Uuid,
    status: StorageTraceExportJobStatus,
    reason_hash: &str,
) -> String {
    format!(
        "export_job_id={export_job_id};status={};reason_hash={reason_hash}",
        serde_enum_tag(&status)
    )
}

fn export_job_recovery_audit_metadata(
    record: &StorageTraceExportJobRecord,
    reason_hash: &str,
) -> StorageTraceAuditSafeMetadata {
    StorageTraceAuditSafeMetadata::ExportJobRecovery {
        export_job_id: record.export_job_id,
        recovered_status: record.status,
        reason_hash: reason_hash.to_string(),
    }
}

fn ranking_worker_run_recovery_audit_reason(
    ranking_worker_run_id: Uuid,
    run_kind: StorageTraceRankingWorkerRunKind,
    status: StorageTraceRankingWorkerRunStatus,
    reason_hash: &str,
) -> String {
    format!(
        "ranking_worker_run_id={ranking_worker_run_id};run_kind={};status={};reason_hash={reason_hash}",
        serde_enum_tag(&run_kind),
        serde_enum_tag(&status)
    )
}

fn ranking_worker_run_recovery_audit_metadata(
    record: &TraceRankingWorkerRunRecord,
    reason_hash: &str,
) -> StorageTraceAuditSafeMetadata {
    StorageTraceAuditSafeMetadata::RankingWorkerRunRecovery {
        ranking_worker_run_id: record.ranking_worker_run_id,
        run_kind: record.run_kind,
        recovered_status: record.status,
        reason_hash: reason_hash.to_string(),
    }
}

async fn finalize_failed_ranking_worker_run_with_db_mirror(
    state: &AppState,
    tenant: &TenantAuth,
    worker_run: &mut TraceRankingWorkerRunRecord,
    http_status: StatusCode,
    public_error: &str,
) -> ApiResult<()> {
    worker_run.status = TraceRankingWorkerRunStatus::Failed;
    worker_run.completed_at = Some(Utc::now());
    worker_run.last_error_hash = Some(ranking_worker_run_error_hash(http_status, public_error));
    append_ranking_worker_run_with_db_mirror(state, tenant, worker_run)
        .await
        .map_err(internal_error)
}

fn ranking_prediction_credit_event_id(
    tenant: &TenantAuth,
    prediction: &TraceRankingPredictionRecord,
) -> Uuid {
    deterministic_trace_uuid_for_external_ref(
        TraceCreditLedgerEventType::RankingUtility.utility_idempotency_label(),
        &tenant.tenant_id,
        prediction.submission_id,
        &ranking_prediction_external_ref(prediction.ranking_prediction_id),
    )
}

async fn ranking_prediction_credit_already_exists(
    state: &AppState,
    tenant: &TenantAuth,
    prediction: &TraceRankingPredictionRecord,
) -> anyhow::Result<bool> {
    let event_id = ranking_prediction_credit_event_id(tenant, prediction);
    Ok(read_credit_events_for_admin(state, tenant)
        .await?
        .into_iter()
        .any(|event| event.event_id == event_id))
}

async fn count_pending_ranking_prediction_credits(
    state: &AppState,
    tenant: &TenantAuth,
    model_version: Option<&str>,
    target_use: Option<TraceAllowedUse>,
    policy_version: Option<&str>,
) -> anyhow::Result<usize> {
    let predictions = read_ranking_predictions_for_admin(state, tenant).await?;
    let existing_event_ids = read_credit_events_for_admin(state, tenant)
        .await?
        .into_iter()
        .map(|event| event.event_id)
        .collect::<BTreeSet<_>>();
    let mut pending_count = 0usize;
    for prediction in predictions.iter().filter(|prediction| {
        prediction.settlement_score_micros > 0
            && model_version.is_none_or(|model_version| prediction.model_version == model_version)
            && target_use.is_none_or(|target_use| prediction.target_use == target_use)
            && policy_version
                .is_none_or(|policy_version| prediction.prediction_policy_version == policy_version)
            && !existing_event_ids.contains(&ranking_prediction_credit_event_id(tenant, prediction))
    }) {
        match read_ranking_source_submission(
            state,
            tenant,
            prediction.submission_id,
            prediction.target_use,
        )
        .await
        {
            Ok(_) => pending_count += 1,
            Err((status, _)) if ranking_prediction_credit_run_can_skip_status(status) => {}
            Err((status, error)) => {
                anyhow::bail!(
                    "failed to count pending ranking prediction credit: status={}, error={}",
                    status.as_u16(),
                    error.0.error
                );
            }
        }
    }
    Ok(pending_count)
}

async fn ranking_prediction_model_risk_codes(
    state: &AppState,
    tenant: &TenantAuth,
    prediction: &TraceRankingPredictionRecord,
) -> ApiResult<Vec<String>> {
    let model_versions = read_ranking_model_versions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let predictions = read_ranking_predictions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let labels = read_ranking_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let preference_labels = read_ranking_preference_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let calibration_datasets = read_ranking_calibration_datasets_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let calibration_runs = read_ranking_calibration_runs_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let risk_key = ranking_prediction_risk_lookup_key(prediction);
    Ok(ranking_model_risk_report(
        state,
        tenant,
        &model_versions,
        RankingModelRiskEvidence {
            predictions: &predictions,
            labels: &labels,
            preference_labels: &preference_labels,
            calibration_datasets: &calibration_datasets,
            calibration_runs: &calibration_runs,
        },
    )
    .models
    .into_iter()
    .find(|model| {
        ranking_model_risk_lookup_key(
            &model.model_version,
            model.target_use,
            &model.policy_version,
        ) == risk_key
    })
    .map(|model| model.risk_codes)
    .unwrap_or_default())
}

async fn append_ranking_prediction_credit_for_record(
    state: &AppState,
    tenant: &TenantAuth,
    prediction: TraceRankingPredictionRecord,
    reason: &str,
    dry_run: bool,
    allow_at_risk_model: bool,
) -> ApiResult<TraceRankingPredictionCreditResponse> {
    if prediction.settlement_score_micros <= 0 {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit requires a positive settlement score",
        ));
    }
    if !dry_run {
        require_positive_credit_issuance_principal_if_configured(state, tenant, 1.0)?;
    }

    let submission = read_ranking_source_submission(
        state,
        tenant,
        prediction.submission_id,
        prediction.target_use,
    )
    .await?;
    if submission.trace_id != prediction.trace_id {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit source does not match the referenced trace",
        ));
    }

    let model_versions = read_ranking_model_versions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let model = latest_ranking_model_version(&model_versions, &prediction.model_version)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "ranking prediction model not found"))?;
    if model.status != StorageTraceRankingModelStatus::Active {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit requires an active model version",
        ));
    }
    ensure_ranking_model_dataset_isolation(
        model,
        RankingModelDatasetIsolationContext::PredictionCredit,
    )?;
    if model.feature_schema_version != prediction.feature_schema_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit feature schema does not match the active model",
        ));
    }
    if model.policy_version != prediction.prediction_policy_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit policy does not match the active model",
        ));
    }
    if state.ranking_require_server_feature_provenance {
        let features = read_ranking_features_for_admin(state, tenant)
            .await
            .map_err(internal_error)?;
        if !ranking_prediction_has_server_feature_provenance(&features, &prediction) {
            return Err(api_error(
                StatusCode::CONFLICT,
                "ranking prediction credit requires server-provenanced ranking feature evidence",
            ));
        }
    }
    let calibration_run = latest_promotable_ranking_calibration_run(
        state,
        tenant,
        &prediction.model_version,
        prediction.target_use,
        &prediction.prediction_policy_version,
        &model.calibration_dataset_hash,
        RankingCalibrationGateContext::PredictionCredit,
    )
    .await?;
    let calibration_thresholds =
        effective_ranking_calibration_thresholds(state, Some(&calibration_run));
    if state.ranking_max_labeler_issue_rate_micros.is_some()
        || state.ranking_min_labeler_reliability_label_count.is_some()
    {
        let predictions = read_ranking_predictions_for_admin(state, tenant)
            .await
            .map_err(internal_error)?;
        let labels = read_ranking_labels_for_admin(state, tenant)
            .await
            .map_err(internal_error)?;
        let preference_labels = read_ranking_preference_labels_for_admin(state, tenant)
            .await
            .map_err(internal_error)?;
        let reason_codes = ranking_calibration_labeler_reliability_reason_codes(
            state,
            &tenant.tenant_id,
            model,
            prediction.target_use,
            &predictions,
            &labels,
            &preference_labels,
        );
        if !reason_codes.is_empty() {
            return Err(api_error(
                StatusCode::CONFLICT,
                format!(
                    "ranking prediction credit requires calibration labeler reliability: reason_codes={}",
                    reason_codes.join(",")
                ),
            ));
        }
    }
    if prediction.confidence < calibration_thresholds.confidence_threshold {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit requires prediction confidence to meet the calibration threshold",
        ));
    }
    if !allow_at_risk_model {
        let risk_codes = ranking_prediction_model_risk_codes(state, tenant, &prediction).await?;
        if !risk_codes.is_empty() {
            return Err(api_error(
                StatusCode::CONFLICT,
                format!(
                    "ranking prediction credit requires model risk to be clear: {}",
                    risk_codes.join(",")
                ),
            ));
        }
    }

    let credit_points_delta = prediction.settlement_score_micros as f32 / 1_000_000.0;
    if !credit_points_delta.is_finite() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "ranking prediction credit delta must be finite",
        ));
    }
    if credit_points_delta.abs() > MAX_DELAYED_CREDIT_POINTS_DELTA {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking prediction credit exceeds the delayed credit policy limit",
        ));
    }

    let external_ref = ranking_prediction_external_ref(prediction.ranking_prediction_id);
    let counts = if dry_run {
        AutomaticUtilityCreditAppendCounts::default()
    } else {
        append_automatic_utility_credit_events_once_with_counts(
            state,
            tenant,
            AutomaticUtilityCreditConfig {
                idempotency_label: TraceCreditLedgerEventType::RankingUtility
                    .utility_idempotency_label(),
                idempotency_ref: Some(external_ref.clone()),
                event_type: TraceCreditLedgerEventType::RankingUtility,
                credit_points_delta,
                reason: format!("ranking prediction credit: {reason}"),
                external_ref: external_ref.clone(),
            },
            [AutomaticUtilityCreditSource {
                submission_id: submission.submission_id,
                trace_id: submission.trace_id,
                auth_principal_ref: submission.auth_principal_ref,
            }],
        )
        .await?
    };

    Ok(TraceRankingPredictionCreditResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        ranking_prediction_id: prediction.ranking_prediction_id,
        submission_id: prediction.submission_id,
        model_version: prediction.model_version,
        target_use: prediction.target_use,
        policy_version: prediction.prediction_policy_version,
        credit_points_delta,
        external_ref,
        appended_count: counts.appended,
        skipped_existing_count: counts.skipped_existing,
    })
}

