fn latest_ranking_model_version<'a>(
    records: &'a [TraceRankingModelVersionRecord],
    model_version: &str,
) -> Option<&'a TraceRankingModelVersionRecord> {
    records
        .iter()
        .filter(|record| record.model_version == model_version)
        .max_by_key(|record| record.created_at)
}

fn ensure_ranking_model_accepts_evidence(model: &TraceRankingModelVersionRecord) -> ApiResult<()> {
    if matches!(
        model.status,
        StorageTraceRankingModelStatus::Candidate | StorageTraceRankingModelStatus::Active
    ) {
        return Ok(());
    }
    Err(api_error(
        StatusCode::CONFLICT,
        "ranking evidence requires an active or candidate model version",
    ))
}

async fn read_ranking_source_submission(
    state: &AppState,
    tenant: &TenantAuth,
    submission_id: Uuid,
    target_use: TraceAllowedUse,
) -> ApiResult<TraceCommonsSubmissionRecord> {
    let required_uses = [target_use];
    let tenant_policy =
        tenant_utility_credit_policy_for_request(state, tenant, &required_uses).await?;
    let submission = read_utility_submission_record(state, tenant, submission_id)
        .await
        .map_err(internal_error)?
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "trace submission not found"))?;
    if submission.status != TraceCorpusStatus::Accepted {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking evidence can only reference accepted trace submissions",
        ));
    }
    if !record_matches_utility_credit_policy_abac(
        &submission,
        tenant,
        tenant_policy.as_ref(),
        &required_uses,
    ) {
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "ranking evidence source is not allowed for this target use",
        ));
    }
    Ok(submission)
}

fn validate_ranking_identifier(value: &str, label: &str) -> ApiResult<String> {
    let value = value.trim();
    if value.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("ranking {label} is required"),
        ));
    }
    if value.len() > 128 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("ranking {label} is too long"),
        ));
    }
    if !value
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.' | ':'))
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("ranking {label} contains unsupported characters"),
        ));
    }
    Ok(value.to_string())
}

fn validate_sha256_hash(value: &str, label: &str) -> ApiResult<String> {
    let value = value.trim();
    if is_canonical_sha256_prefixed_hash(value) {
        Ok(value.to_string())
    } else {
        Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("ranking {label} must be a canonical sha256-prefixed hex digest"),
        ))
    }
}

fn validate_trace_sha256_hash(value: &str, label: &str) -> ApiResult<String> {
    let value = value.trim();
    if is_canonical_sha256_prefixed_hash(value) {
        Ok(value.to_string())
    } else {
        Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("{label} must be a canonical sha256-prefixed hex digest"),
        ))
    }
}

fn is_canonical_sha256_prefixed_hash(value: &str) -> bool {
    value.strip_prefix("sha256:").is_some_and(|digest| {
        digest.len() == 64
            && digest
                .chars()
                .all(|ch| ch.is_ascii_digit() || matches!(ch, 'a'..='f'))
    })
}

fn validate_positive_ranking_count(value: u32, label: &str) -> ApiResult<()> {
    if value > 0 {
        return Ok(());
    }
    Err(api_error(
        StatusCode::BAD_REQUEST,
        format!("ranking {label} must be greater than zero"),
    ))
}

fn validate_unit_score(value: f32, label: &str) -> ApiResult<()> {
    if value.is_finite() && (0.0..=1.0).contains(&value) {
        Ok(())
    } else {
        Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("ranking {label} must be between 0 and 1"),
        ))
    }
}

fn validate_optional_unit_score(value: Option<f32>, label: &str) -> ApiResult<()> {
    if let Some(value) = value {
        validate_unit_score(value, label)?;
    }
    Ok(())
}

fn validate_nonnegative_micros(value: i64, label: &str) -> ApiResult<()> {
    if (0..=1_000_000_000_000).contains(&value) {
        Ok(())
    } else {
        Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("ranking {label} must be non-negative and within policy bounds"),
        ))
    }
}

fn validate_ranking_codes(values: &[String], label: &str) -> ApiResult<()> {
    if values.len() > 64 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("ranking {label} has too many entries"),
        ));
    }
    for value in values {
        validate_ranking_identifier(value, label)?;
    }
    Ok(())
}

fn max_label_source_average_error(
    source_abs_error_sums: &BTreeMap<StorageTraceRankingLabelSource, (i128, usize)>,
) -> (Option<i64>, Option<StorageTraceRankingLabelSource>) {
    let mut max_average = None;
    let mut max_source = None;
    for (source, (sum, count)) in source_abs_error_sums {
        let Some(average) = average_i128(*sum, *count) else {
            continue;
        };
        if max_average.is_none_or(|current| average > current) {
            max_average = Some(average);
            max_source = Some(*source);
        }
    }
    (max_average, max_source)
}

fn ranking_adjudication_report(
    tenant_id: &str,
    labels: &[TraceRankingLabelRecord],
    preference_labels: &[TraceRankingPreferenceLabelRecord],
) -> TraceRankingAdjudicationReport {
    let mut latest_label_by_source = BTreeMap::new();
    for label in labels {
        let key = (label.submission_id, label.target_use, label.label_source);
        let should_replace =
            latest_label_by_source
                .get(&key)
                .is_none_or(|current: &&TraceRankingLabelRecord| {
                    (label.created_at, label.ranking_label_id)
                        > (current.created_at, current.ranking_label_id)
                });
        if should_replace {
            latest_label_by_source.insert(key, label);
        }
    }

    let mut label_groups: BTreeMap<(Uuid, TraceAllowedUse), Vec<&TraceRankingLabelRecord>> =
        BTreeMap::new();
    for label in latest_label_by_source.into_values() {
        label_groups
            .entry((label.submission_id, label.target_use))
            .or_default()
            .push(label);
    }

    let mut reason_code_counts = BTreeMap::new();
    let mut unresolved_disputed_label_group_count = 0usize;
    let mut conflicting_absolute_label_group_count = 0usize;
    let mut absolute_label_issues = Vec::new();
    for ((submission_id, target_use), mut group_labels) in
        label_groups.iter().map(|(key, labels)| {
            ((*key).to_owned(), {
                let mut labels = labels.clone();
                labels.sort_by_key(|label| {
                    (label.label_source, label.created_at, label.ranking_label_id)
                });
                labels
            })
        })
    {
        let mut label_sources = BTreeSet::new();
        let mut label_actors = BTreeSet::new();
        let mut non_disputed_outcomes = BTreeSet::new();
        let mut has_disputed_label = false;
        for label in group_labels.drain(..) {
            label_sources.insert(label.label_source);
            label_actors.insert(label.actor_principal_ref.as_str());
            if label.label_outcome == StorageTraceRankingLabelOutcome::Disputed {
                has_disputed_label = true;
            } else {
                non_disputed_outcomes.insert(serde_enum_tag(&label.label_outcome));
            }
        }

        let mut reason_codes = Vec::new();
        if has_disputed_label {
            unresolved_disputed_label_group_count += 1;
            reason_codes.push("absolute_label_disputed".to_string());
        }
        if non_disputed_outcomes.len() > 1 {
            conflicting_absolute_label_group_count += 1;
            reason_codes.push("absolute_label_outcome_conflict".to_string());
        }
        if reason_codes.is_empty() {
            continue;
        }
        reason_codes.sort();
        reason_codes.dedup();
        for reason in &reason_codes {
            increment_count(&mut reason_code_counts, reason);
        }
        absolute_label_issues.push(TraceRankingAbsoluteLabelAdjudicationIssue {
            submission_id,
            target_use,
            latest_label_count: label_sources.len(),
            label_source_count: label_sources.len(),
            label_actor_count: label_actors.len(),
            non_disputed_outcome_count: non_disputed_outcomes.len(),
            has_disputed_label,
            reason_codes,
        });
    }

    let mut preference_pairs: BTreeMap<
        TraceRankingPreferencePairKey,
        TraceRankingPreferencePairEntries<'_>,
    > = BTreeMap::new();
    for label in preference_labels {
        let (left_submission_id, right_submission_id, forward) =
            if label.preferred_submission_id <= label.rejected_submission_id {
                (
                    label.preferred_submission_id,
                    label.rejected_submission_id,
                    true,
                )
            } else {
                (
                    label.rejected_submission_id,
                    label.preferred_submission_id,
                    false,
                )
            };
        preference_pairs
            .entry((left_submission_id, right_submission_id, label.target_use))
            .or_default()
            .push((forward, label));
    }

    let mut conflicting_preference_pair_count = 0usize;
    let mut preference_pair_issues = Vec::new();
    for ((left_submission_id, right_submission_id, target_use), pair_labels) in &preference_pairs {
        let mut label_sources = BTreeSet::new();
        let mut label_actors = BTreeSet::new();
        let mut forward_preference_count = 0usize;
        let mut reverse_preference_count = 0usize;
        for (forward, label) in pair_labels {
            label_sources.insert(label.label_source);
            label_actors.insert(label.actor_principal_ref.as_str());
            if *forward {
                forward_preference_count += 1;
            } else {
                reverse_preference_count += 1;
            }
        }
        if forward_preference_count == 0 || reverse_preference_count == 0 {
            continue;
        }
        conflicting_preference_pair_count += 1;
        let reason_codes = vec!["pairwise_preference_conflict".to_string()];
        increment_count(&mut reason_code_counts, "pairwise_preference_conflict");
        preference_pair_issues.push(TraceRankingPreferencePairAdjudicationIssue {
            left_submission_id: *left_submission_id,
            right_submission_id: *right_submission_id,
            target_use: *target_use,
            preference_label_count: pair_labels.len(),
            label_source_count: label_sources.len(),
            label_actor_count: label_actors.len(),
            forward_preference_count,
            reverse_preference_count,
            reason_codes,
        });
    }

    absolute_label_issues.sort_by_key(|issue| (issue.submission_id, issue.target_use));
    preference_pair_issues.sort_by_key(|issue| {
        (
            issue.left_submission_id,
            issue.right_submission_id,
            issue.target_use,
        )
    });
    let issue_group_count = absolute_label_issues.len() + preference_pair_issues.len();

    TraceRankingAdjudicationReport {
        tenant_id: tenant_id.to_string(),
        tenant_storage_ref: tenant_storage_ref(tenant_id),
        absolute_label_count: labels.len(),
        preference_label_count: preference_labels.len(),
        absolute_label_group_count: label_groups.len(),
        unresolved_disputed_label_group_count,
        conflicting_absolute_label_group_count,
        preference_pair_count: preference_pairs.len(),
        conflicting_preference_pair_count,
        issue_group_count,
        reason_code_counts,
        absolute_label_issues,
        preference_pair_issues,
    }
}

fn ranking_adjudication_issue_count_for_target(
    report: &TraceRankingAdjudicationReport,
    target_use: TraceAllowedUse,
) -> usize {
    report
        .absolute_label_issues
        .iter()
        .filter(|issue| issue.target_use == target_use)
        .count()
        + report
            .preference_pair_issues
            .iter()
            .filter(|issue| issue.target_use == target_use)
            .count()
}

fn ranking_labeler_reliability_report(
    tenant_id: &str,
    labels: &[TraceRankingLabelRecord],
    preference_labels: &[TraceRankingPreferenceLabelRecord],
) -> TraceRankingLabelerReliabilityReport {
    let mut source_stats =
        BTreeMap::<StorageTraceRankingLabelSource, TraceRankingLabelerReliabilityStats>::new();
    let mut actor_stats = BTreeMap::<String, TraceRankingLabelerReliabilityStats>::new();

    for label in labels {
        record_labeler_reliability_absolute_label(
            source_stats.entry(label.label_source).or_default(),
            label,
        );
        record_labeler_reliability_absolute_label(
            actor_stats
                .entry(sha256_prefixed(&label.actor_principal_ref))
                .or_default(),
            label,
        );
    }
    for label in preference_labels {
        record_labeler_reliability_preference_label(
            source_stats.entry(label.label_source).or_default(),
            label,
        );
        record_labeler_reliability_preference_label(
            actor_stats
                .entry(sha256_prefixed(&label.actor_principal_ref))
                .or_default(),
            label,
        );
    }

    let mut latest_label_by_source = BTreeMap::new();
    for label in labels {
        let key = (label.submission_id, label.target_use, label.label_source);
        let should_replace =
            latest_label_by_source
                .get(&key)
                .is_none_or(|current: &&TraceRankingLabelRecord| {
                    (label.created_at, label.ranking_label_id)
                        > (current.created_at, current.ranking_label_id)
                });
        if should_replace {
            latest_label_by_source.insert(key, label);
        }
    }

    let adjudication = ranking_adjudication_report(tenant_id, labels, preference_labels);
    for issue in &adjudication.absolute_label_issues {
        for label in latest_label_by_source.values().filter(|label| {
            label.submission_id == issue.submission_id && label.target_use == issue.target_use
        }) {
            if issue
                .reason_codes
                .iter()
                .any(|reason| reason == "absolute_label_outcome_conflict")
            {
                source_stats
                    .entry(label.label_source)
                    .or_default()
                    .absolute_conflict_count += 1;
                actor_stats
                    .entry(sha256_prefixed(&label.actor_principal_ref))
                    .or_default()
                    .absolute_conflict_count += 1;
            }
            source_stats
                .entry(label.label_source)
                .or_default()
                .issue_count += 1;
            actor_stats
                .entry(sha256_prefixed(&label.actor_principal_ref))
                .or_default()
                .issue_count += 1;
        }
    }
    for issue in &adjudication.preference_pair_issues {
        for label in preference_labels.iter().filter(|label| {
            label.target_use == issue.target_use
                && preference_label_matches_adjudication_pair(
                    label,
                    issue.left_submission_id,
                    issue.right_submission_id,
                )
        }) {
            source_stats
                .entry(label.label_source)
                .or_default()
                .pairwise_conflict_count += 1;
            source_stats
                .entry(label.label_source)
                .or_default()
                .issue_count += 1;
            actor_stats
                .entry(sha256_prefixed(&label.actor_principal_ref))
                .or_default()
                .pairwise_conflict_count += 1;
            actor_stats
                .entry(sha256_prefixed(&label.actor_principal_ref))
                .or_default()
                .issue_count += 1;
        }
    }

    let sources = source_stats
        .into_iter()
        .map(|(label_source, stats)| {
            let label_count = stats.label_count();
            let issue_rate_micros = reliability_issue_rate_micros(&stats);
            TraceRankingLabelSourceReliabilityRecord {
                label_count,
                label_source,
                absolute_label_count: stats.absolute_label_count,
                preference_label_count: stats.preference_label_count,
                disputed_label_count: stats.disputed_label_count,
                absolute_conflict_count: stats.absolute_conflict_count,
                pairwise_conflict_count: stats.pairwise_conflict_count,
                issue_count: stats.issue_count,
                issue_rate_micros,
            }
        })
        .collect::<Vec<_>>();
    let actors = actor_stats
        .into_iter()
        .map(|(actor_principal_hash, stats)| {
            let label_count = stats.label_count();
            let issue_rate_micros = reliability_issue_rate_micros(&stats);
            TraceRankingLabelActorReliabilityRecord {
                actor_principal_hash,
                label_source_counts: stats.label_source_counts,
                label_count,
                absolute_label_count: stats.absolute_label_count,
                preference_label_count: stats.preference_label_count,
                disputed_label_count: stats.disputed_label_count,
                absolute_conflict_count: stats.absolute_conflict_count,
                pairwise_conflict_count: stats.pairwise_conflict_count,
                issue_count: stats.issue_count,
                issue_rate_micros,
            }
        })
        .collect::<Vec<_>>();

    TraceRankingLabelerReliabilityReport {
        tenant_id: tenant_id.to_string(),
        tenant_storage_ref: tenant_storage_ref(tenant_id),
        absolute_label_count: labels.len(),
        preference_label_count: preference_labels.len(),
        source_count: sources.len(),
        actor_count: actors.len(),
        sources,
        actors,
    }
}

fn record_labeler_reliability_absolute_label(
    stats: &mut TraceRankingLabelerReliabilityStats,
    label: &TraceRankingLabelRecord,
) {
    stats.absolute_label_count += 1;
    increment_labeler_reliability_source(stats, label.label_source);
    if label.label_outcome == StorageTraceRankingLabelOutcome::Disputed {
        stats.disputed_label_count += 1;
    }
}

fn record_labeler_reliability_preference_label(
    stats: &mut TraceRankingLabelerReliabilityStats,
    label: &TraceRankingPreferenceLabelRecord,
) {
    stats.preference_label_count += 1;
    increment_labeler_reliability_source(stats, label.label_source);
}

fn increment_labeler_reliability_source(
    stats: &mut TraceRankingLabelerReliabilityStats,
    label_source: StorageTraceRankingLabelSource,
) {
    increment_count(
        &mut stats.label_source_counts,
        &serde_enum_tag(&label_source),
    );
}

fn reliability_issue_rate_micros(stats: &TraceRankingLabelerReliabilityStats) -> Option<i64> {
    let label_count = stats.label_count();
    if label_count == 0 {
        return None;
    }
    Some(((stats.issue_count as i128 * 1_000_000i128) / label_count as i128) as i64)
}

fn ranking_calibration_joined_labelers(
    model: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
    predictions: &[TraceRankingPredictionRecord],
    labels: &[TraceRankingLabelRecord],
) -> (BTreeSet<StorageTraceRankingLabelSource>, BTreeSet<String>) {
    let matching_predictions = predictions
        .iter()
        .filter(|prediction| ranking_prediction_matches_model_target(prediction, model, target_use))
        .collect::<Vec<_>>();
    let matching_labels = ranking_calibration_effective_labels(
        labels.iter().filter(|label| label.target_use == target_use),
    );
    let mut latest_prediction_by_submission = BTreeMap::new();
    for prediction in &matching_predictions {
        latest_prediction_by_submission.insert(prediction.submission_id, *prediction);
    }

    let mut label_sources = BTreeSet::new();
    let mut label_actor_hashes = BTreeSet::new();
    for label in matching_labels {
        if latest_prediction_by_submission.contains_key(&label.submission_id) {
            label_sources.insert(label.label_source);
            label_actor_hashes.insert(sha256_prefixed(&label.actor_principal_ref));
        }
    }
    (label_sources, label_actor_hashes)
}

fn ranking_calibration_labeler_reliability_reason_codes(
    state: &AppState,
    tenant_id: &str,
    model: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
    predictions: &[TraceRankingPredictionRecord],
    labels: &[TraceRankingLabelRecord],
    preference_labels: &[TraceRankingPreferenceLabelRecord],
) -> Vec<String> {
    if state.ranking_max_labeler_issue_rate_micros.is_none()
        && state.ranking_min_labeler_reliability_label_count.is_none()
    {
        return Vec::new();
    }
    let (calibration_label_sources, calibration_label_actor_hashes) =
        ranking_calibration_joined_labelers(model, target_use, predictions, labels);
    if calibration_label_sources.is_empty() && calibration_label_actor_hashes.is_empty() {
        return Vec::new();
    }

    let reliability = ranking_labeler_reliability_report(tenant_id, labels, preference_labels);
    let mut reason_codes = Vec::new();
    if let Some(max_issue_rate_micros) = state.ranking_max_labeler_issue_rate_micros {
        if reliability.sources.iter().any(|record| {
            calibration_label_sources.contains(&record.label_source)
                && record
                    .issue_rate_micros
                    .is_some_and(|rate| rate > max_issue_rate_micros)
        }) {
            reason_codes.push(RANKING_CALIBRATION_LABEL_SOURCE_ISSUE_RATE_REASON.to_string());
        }
        if reliability.actors.iter().any(|record| {
            calibration_label_actor_hashes.contains(&record.actor_principal_hash)
                && record
                    .issue_rate_micros
                    .is_some_and(|rate| rate > max_issue_rate_micros)
        }) {
            reason_codes.push(RANKING_CALIBRATION_LABEL_ACTOR_ISSUE_RATE_REASON.to_string());
        }
    }
    if let Some(min_label_count) = state.ranking_min_labeler_reliability_label_count {
        if reliability.sources.iter().any(|record| {
            calibration_label_sources.contains(&record.label_source)
                && record.label_count < min_label_count
        }) {
            reason_codes
                .push(RANKING_CALIBRATION_LABEL_SOURCE_RELIABILITY_SUPPORT_REASON.to_string());
        }
        if reliability.actors.iter().any(|record| {
            calibration_label_actor_hashes.contains(&record.actor_principal_hash)
                && record.label_count < min_label_count
        }) {
            reason_codes
                .push(RANKING_CALIBRATION_LABEL_ACTOR_RELIABILITY_SUPPORT_REASON.to_string());
        }
    }
    reason_codes
}

fn preference_label_matches_adjudication_pair(
    label: &TraceRankingPreferenceLabelRecord,
    left_submission_id: Uuid,
    right_submission_id: Uuid,
) -> bool {
    (label.preferred_submission_id == left_submission_id
        && label.rejected_submission_id == right_submission_id)
        || (label.preferred_submission_id == right_submission_id
            && label.rejected_submission_id == left_submission_id)
}

fn ranking_calibration_report(
    tenant_id: &str,
    model_version_count: usize,
    feature_count: usize,
    predictions: &[TraceRankingPredictionRecord],
    labels: &[TraceRankingLabelRecord],
) -> TraceRankingCalibrationReport {
    let mut latest_prediction_by_submission_use = BTreeMap::new();
    for prediction in predictions {
        latest_prediction_by_submission_use.insert(
            (prediction.submission_id, prediction.target_use),
            prediction.predicted_utility_micros,
        );
    }

    let effective_labels = ranking_calibration_effective_labels(labels.iter());
    let mut joined_count = 0usize;
    let mut predicted_sum = 0i128;
    let mut label_sum = 0i128;
    let mut abs_error_sum = 0i128;
    let mut joined_label_sources = BTreeSet::new();
    let mut joined_label_actors = BTreeSet::new();
    let mut label_source_abs_error_sums = BTreeMap::new();
    for label in &effective_labels {
        let Some(predicted) =
            latest_prediction_by_submission_use.get(&(label.submission_id, label.target_use))
        else {
            continue;
        };
        joined_count += 1;
        joined_label_sources.insert(label.label_source);
        joined_label_actors.insert(label.actor_principal_ref.as_str());
        let abs_error = (label.utility_delta_micros - *predicted).abs();
        let (source_error_sum, source_count) = label_source_abs_error_sums
            .entry(label.label_source)
            .or_insert((0i128, 0usize));
        *source_error_sum += i128::from(abs_error);
        *source_count += 1;
        predicted_sum += i128::from(*predicted);
        label_sum += i128::from(label.utility_delta_micros);
        abs_error_sum += i128::from(abs_error);
    }
    let (max_label_source_average_absolute_error_micros, max_error_label_source) =
        max_label_source_average_error(&label_source_abs_error_sums);

    TraceRankingCalibrationReport {
        tenant_id: tenant_id.to_string(),
        tenant_storage_ref: tenant_storage_ref(tenant_id),
        model_version_count,
        feature_count,
        prediction_count: predictions.len(),
        label_count: effective_labels.len(),
        joined_label_prediction_count: joined_count,
        joined_label_source_count: joined_label_sources.len(),
        joined_label_actor_count: joined_label_actors.len(),
        average_predicted_utility_micros: average_i128(predicted_sum, joined_count),
        average_label_utility_delta_micros: average_i128(label_sum, joined_count),
        average_absolute_error_micros: average_i128(abs_error_sum, joined_count),
        max_label_source_average_absolute_error_micros,
        max_error_label_source,
        low_confidence_prediction_count: predictions
            .iter()
            .filter(|prediction| prediction.confidence < 0.5)
            .count(),
    }
}

fn ranking_pairwise_evaluation_report(
    tenant_id: &str,
    model_versions: &[TraceRankingModelVersionRecord],
    predictions: &[TraceRankingPredictionRecord],
    preference_labels: &[TraceRankingPreferenceLabelRecord],
) -> TraceRankingPairwiseEvaluationReport {
    let latest_models = latest_ranking_model_versions(model_versions)
        .into_iter()
        .filter(|model| {
            matches!(
                model.status,
                StorageTraceRankingModelStatus::Candidate | StorageTraceRankingModelStatus::Active
            )
        })
        .collect::<Vec<_>>();
    let mut models = Vec::new();
    for model in &latest_models {
        let mut target_uses = BTreeSet::new();
        for prediction in predictions {
            if prediction.model_version == model.model_version
                && prediction.prediction_policy_version == model.policy_version
                && prediction.feature_schema_version == model.feature_schema_version
            {
                target_uses.insert(prediction.target_use);
            }
        }
        for label in preference_labels {
            target_uses.insert(label.target_use);
        }
        for target_use in target_uses {
            let model_report = ranking_pairwise_evaluation_model_report(
                model,
                target_use,
                predictions,
                preference_labels,
            );
            if model_report.prediction_count > 0 || model_report.preference_label_count > 0 {
                models.push(model_report);
            }
        }
    }
    models.sort_by(|left, right| {
        (
            &left.model_version,
            serde_enum_tag(&left.target_use),
            &left.policy_version,
        )
            .cmp(&(
                &right.model_version,
                serde_enum_tag(&right.target_use),
                &right.policy_version,
            ))
    });

    let joined_pair_prediction_count = models
        .iter()
        .map(|model| model.joined_pair_prediction_count)
        .sum::<usize>();
    let correct_pair_count = models
        .iter()
        .map(|model| model.correct_pair_count)
        .sum::<usize>();
    let reversed_pair_count = models
        .iter()
        .map(|model| model.reversed_pair_count)
        .sum::<usize>();
    let tied_pair_count = models
        .iter()
        .map(|model| model.tied_pair_count)
        .sum::<usize>();
    let mut margin_sum = 0i128;
    let mut margin_count = 0usize;
    let mut min_preferred_margin_micros: Option<i64> = None;
    let mut max_preferred_margin_micros: Option<i64> = None;
    for model in &models {
        if let Some(average) = model.average_preferred_margin_micros {
            margin_sum += i128::from(average) * model.joined_pair_prediction_count as i128;
            margin_count += model.joined_pair_prediction_count;
        }
        if let Some(min_margin) = model.min_preferred_margin_micros {
            min_preferred_margin_micros = Some(
                min_preferred_margin_micros.map_or(min_margin, |current| current.min(min_margin)),
            );
        }
        if let Some(max_margin) = model.max_preferred_margin_micros {
            max_preferred_margin_micros = Some(
                max_preferred_margin_micros.map_or(max_margin, |current| current.max(max_margin)),
            );
        }
    }

    TraceRankingPairwiseEvaluationReport {
        tenant_id: tenant_id.to_string(),
        tenant_storage_ref: tenant_storage_ref(tenant_id),
        model_version_count: latest_models.len(),
        prediction_count: predictions.len(),
        preference_label_count: preference_labels.len(),
        joined_pair_prediction_count,
        correct_pair_count,
        reversed_pair_count,
        tied_pair_count,
        pairwise_accuracy_micros: ratio_micros(correct_pair_count, joined_pair_prediction_count),
        average_preferred_margin_micros: average_i128(margin_sum, margin_count),
        min_preferred_margin_micros,
        max_preferred_margin_micros,
        models,
    }
}

fn ranking_pairwise_evaluation_model_report(
    model: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
    predictions: &[TraceRankingPredictionRecord],
    preference_labels: &[TraceRankingPreferenceLabelRecord],
) -> TraceRankingPairwiseEvaluationModelReport {
    let matching_predictions = predictions
        .iter()
        .filter(|prediction| ranking_prediction_matches_model_target(prediction, model, target_use))
        .collect::<Vec<_>>();
    let matching_preferences = preference_labels
        .iter()
        .filter(|label| label.target_use == target_use)
        .collect::<Vec<_>>();
    let mut latest_prediction_by_submission = BTreeMap::new();
    for prediction in &matching_predictions {
        let should_replace = latest_prediction_by_submission
            .get(&prediction.submission_id)
            .is_none_or(|current: &&TraceRankingPredictionRecord| {
                prediction.created_at > current.created_at
            });
        if should_replace {
            latest_prediction_by_submission.insert(prediction.submission_id, *prediction);
        }
    }

    let mut joined_pair_prediction_count = 0usize;
    let mut correct_pair_count = 0usize;
    let mut reversed_pair_count = 0usize;
    let mut tied_pair_count = 0usize;
    let mut margin_sum = 0i128;
    let mut min_preferred_margin_micros: Option<i64> = None;
    let mut max_preferred_margin_micros: Option<i64> = None;
    let mut joined_label_source_counts = BTreeMap::new();
    let mut joined_label_sources = BTreeSet::new();
    let mut joined_label_actors = BTreeSet::new();
    for label in &matching_preferences {
        let Some(preferred_prediction) =
            latest_prediction_by_submission.get(&label.preferred_submission_id)
        else {
            continue;
        };
        let Some(rejected_prediction) =
            latest_prediction_by_submission.get(&label.rejected_submission_id)
        else {
            continue;
        };
        let margin = preferred_prediction.settlement_score_micros
            - rejected_prediction.settlement_score_micros;
        joined_pair_prediction_count += 1;
        margin_sum += i128::from(margin);
        min_preferred_margin_micros =
            Some(min_preferred_margin_micros.map_or(margin, |current| current.min(margin)));
        max_preferred_margin_micros =
            Some(max_preferred_margin_micros.map_or(margin, |current| current.max(margin)));
        *joined_label_source_counts
            .entry(label.label_source)
            .or_insert(0usize) += 1;
        joined_label_sources.insert(label.label_source);
        joined_label_actors.insert(label.actor_principal_ref.as_str());
        match margin.cmp(&0) {
            std::cmp::Ordering::Greater => correct_pair_count += 1,
            std::cmp::Ordering::Less => reversed_pair_count += 1,
            std::cmp::Ordering::Equal => tied_pair_count += 1,
        }
    }

    TraceRankingPairwiseEvaluationModelReport {
        model_version: model.model_version.clone(),
        model_status: model.status,
        target_use,
        policy_version: model.policy_version.clone(),
        feature_schema_version: model.feature_schema_version.clone(),
        prediction_count: matching_predictions.len(),
        preference_label_count: matching_preferences.len(),
        joined_pair_prediction_count,
        joined_label_source_count: joined_label_sources.len(),
        joined_label_actor_count: joined_label_actors.len(),
        correct_pair_count,
        reversed_pair_count,
        tied_pair_count,
        pairwise_accuracy_micros: ratio_micros(correct_pair_count, joined_pair_prediction_count),
        average_preferred_margin_micros: average_i128(margin_sum, joined_pair_prediction_count),
        min_preferred_margin_micros,
        max_preferred_margin_micros,
        joined_label_source_counts,
    }
}

fn ratio_micros(numerator: usize, denominator: usize) -> Option<i64> {
    if denominator == 0 {
        return None;
    }
    Some(((numerator as i128 * 1_000_000i128) / denominator as i128) as i64)
}

fn latest_ranking_model_versions(
    records: &[TraceRankingModelVersionRecord],
) -> Vec<&TraceRankingModelVersionRecord> {
    let mut latest_by_version = BTreeMap::new();
    for record in records {
        let should_replace = latest_by_version.get(&record.model_version).is_none_or(
            |current: &&TraceRankingModelVersionRecord| record.created_at > current.created_at,
        );
        if should_replace {
            latest_by_version.insert(record.model_version.clone(), record);
        }
    }
    latest_by_version.into_values().collect()
}

#[derive(Debug, Clone, Copy)]
enum RankingModelDatasetIsolationContext {
    Registration,
    Promotion,
    PredictionCredit,
    Settlement,
}

impl RankingModelDatasetIsolationContext {
    fn status(self) -> StatusCode {
        match self {
            Self::Registration => StatusCode::BAD_REQUEST,
            Self::Promotion | Self::PredictionCredit | Self::Settlement => StatusCode::CONFLICT,
        }
    }

    fn message(self) -> &'static str {
        match self {
            Self::Registration => {
                "ranking model training_dataset_hash and calibration_dataset_hash must be disjoint"
            }
            Self::Promotion => {
                "ranking model promotion requires disjoint training and calibration datasets"
            }
            Self::PredictionCredit => {
                "ranking prediction credit requires disjoint training and calibration datasets"
            }
            Self::Settlement => {
                "ranking utility settlement requires disjoint training and calibration datasets"
            }
        }
    }
}

fn ranking_model_training_calibration_datasets_overlap(
    model: &TraceRankingModelVersionRecord,
) -> bool {
    model.training_dataset_hash == model.calibration_dataset_hash
}

fn ensure_ranking_model_dataset_hashes_are_disjoint(
    training_dataset_hash: &str,
    calibration_dataset_hash: &str,
    context: RankingModelDatasetIsolationContext,
) -> ApiResult<()> {
    if training_dataset_hash == calibration_dataset_hash {
        return Err(api_error(context.status(), context.message()));
    }
    Ok(())
}

fn ensure_ranking_model_dataset_isolation(
    model: &TraceRankingModelVersionRecord,
    context: RankingModelDatasetIsolationContext,
) -> ApiResult<()> {
    ensure_ranking_model_dataset_hashes_are_disjoint(
        &model.training_dataset_hash,
        &model.calibration_dataset_hash,
        context,
    )
}

fn ranking_prediction_matches_model_target(
    prediction: &TraceRankingPredictionRecord,
    model: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
) -> bool {
    prediction.model_version == model.model_version
        && prediction.target_use == target_use
        && prediction.prediction_policy_version == model.policy_version
        && prediction.feature_schema_version == model.feature_schema_version
}

fn ranking_model_target_uses(
    model: &TraceRankingModelVersionRecord,
    predictions: &[TraceRankingPredictionRecord],
    calibration_runs: &[TraceRankingCalibrationRunRecord],
) -> BTreeSet<TraceAllowedUse> {
    let mut target_uses = BTreeSet::new();
    for run in calibration_runs {
        if run.model_version == model.model_version
            && run.policy_version == model.policy_version
            && run.evaluation_dataset_hash == model.calibration_dataset_hash
        {
            target_uses.insert(run.target_use);
        }
    }
    for prediction in predictions {
        if prediction.model_version == model.model_version
            && prediction.prediction_policy_version == model.policy_version
            && prediction.feature_schema_version == model.feature_schema_version
        {
            target_uses.insert(prediction.target_use);
        }
    }
    target_uses
}

fn latest_calibration_run_for_model_target<'a>(
    model: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
    calibration_runs: &'a [TraceRankingCalibrationRunRecord],
) -> Option<&'a TraceRankingCalibrationRunRecord> {
    calibration_runs
        .iter()
        .filter(|run| {
            run.model_version == model.model_version
                && run.target_use == target_use
                && run.policy_version == model.policy_version
                && run.evaluation_dataset_hash == model.calibration_dataset_hash
        })
        .max_by_key(|run| run.created_at)
}

fn ranking_calibration_is_stale(state: &AppState, run: &TraceRankingCalibrationRunRecord) -> bool {
    state
        .ranking_calibration_max_age
        .is_some_and(|max_age| Utc::now().signed_duration_since(run.created_at) > max_age)
}

fn ranking_model_risk_report(
    state: &AppState,
    tenant: &TenantAuth,
    model_versions: &[TraceRankingModelVersionRecord],
    evidence: RankingModelRiskEvidence<'_>,
) -> TraceRankingModelRiskReport {
    let active_models = latest_ranking_model_versions(model_versions)
        .into_iter()
        .filter(|model| model.status == StorageTraceRankingModelStatus::Active)
        .collect::<Vec<_>>();
    let active_model_count = active_models.len();
    let mut models = Vec::new();
    for model in active_models {
        for target_use in
            ranking_model_target_uses(model, evidence.predictions, evidence.calibration_runs)
        {
            models.push(ranking_model_risk_record(
                state, tenant, model, target_use, evidence,
            ));
        }
    }
    models.sort_by(|left, right| {
        (
            &left.model_version,
            serde_enum_tag(&left.target_use),
            &left.policy_version,
        )
            .cmp(&(
                &right.model_version,
                serde_enum_tag(&right.target_use),
                &right.policy_version,
            ))
    });
    let at_risk_model_count = models
        .iter()
        .filter(|model| !model.risk_codes.is_empty())
        .count();
    let mut risk_code_counts = BTreeMap::new();
    for model in &models {
        for code in &model.risk_codes {
            *risk_code_counts.entry(code.clone()).or_insert(0) += 1;
        }
    }
    TraceRankingModelRiskReport {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        active_model_count,
        monitored_model_count: models.len(),
        at_risk_model_count,
        risk_code_counts,
        models,
    }
}

fn ranking_model_backtest_report(
    state: &AppState,
    tenant: &TenantAuth,
    model_versions: &[TraceRankingModelVersionRecord],
    evidence: RankingModelRiskEvidence<'_>,
) -> TraceRankingModelBacktestReport {
    let deployable_models = latest_ranking_model_versions(model_versions)
        .into_iter()
        .filter(|model| {
            matches!(
                model.status,
                StorageTraceRankingModelStatus::Candidate | StorageTraceRankingModelStatus::Active
            )
        })
        .collect::<Vec<_>>();
    let model_version_count = deployable_models.len();
    let mut models = Vec::new();
    for model in deployable_models {
        for target_use in
            ranking_model_target_uses(model, evidence.predictions, evidence.calibration_runs)
        {
            let risk = ranking_model_risk_record(state, tenant, model, target_use, evidence);
            let passed = risk.risk_codes.is_empty();
            models.push(TraceRankingModelBacktestRecord {
                model_version: risk.model_version,
                model_status: model.status,
                target_use: risk.target_use,
                policy_version: risk.policy_version,
                feature_schema_version: risk.feature_schema_version,
                latest_calibration_run_id: risk.latest_calibration_run_id,
                latest_calibration_report_hash: risk.latest_calibration_report_hash,
                latest_joined_evidence_hash: risk.latest_joined_evidence_hash,
                latest_calibration_created_at: risk.latest_calibration_created_at,
                latest_calibration_promotable: risk.latest_calibration_promotable,
                latest_calibration_reason_codes: risk.latest_calibration_reason_codes,
                current_joined_evidence_hash: risk.current_joined_evidence_hash,
                current_promotable: risk.current_promotable,
                current_reason_codes: risk.current_reason_codes,
                joined_evidence_changed: risk.joined_evidence_changed,
                prediction_count: risk.prediction_count,
                label_count: risk.label_count,
                joined_label_prediction_count: risk.joined_label_prediction_count,
                joined_label_source_count: risk.joined_label_source_count,
                current_average_absolute_error_micros: risk.current_average_absolute_error_micros,
                current_max_label_source_average_absolute_error_micros: risk
                    .current_max_label_source_average_absolute_error_micros,
                current_max_error_label_source: risk.current_max_error_label_source,
                current_min_label_count: risk.current_min_label_count,
                current_min_label_source_count: risk.current_min_label_source_count,
                current_confidence_threshold: risk.current_confidence_threshold,
                current_max_average_absolute_error_micros: risk
                    .current_max_average_absolute_error_micros,
                predictions_since_calibration_count: risk.predictions_since_calibration_count,
                labels_since_calibration_count: risk.labels_since_calibration_count,
                low_confidence_predictions_since_calibration_count: risk
                    .low_confidence_predictions_since_calibration_count,
                pairwise_min_label_count: risk.pairwise_min_label_count,
                pairwise_min_accuracy_micros: risk.pairwise_min_accuracy_micros,
                pairwise_preference_label_count: risk.pairwise_preference_label_count,
                pairwise_joined_pair_prediction_count: risk.pairwise_joined_pair_prediction_count,
                pairwise_joined_label_source_count: risk.pairwise_joined_label_source_count,
                pairwise_joined_label_actor_count: risk.pairwise_joined_label_actor_count,
                pairwise_correct_pair_count: risk.pairwise_correct_pair_count,
                pairwise_reversed_pair_count: risk.pairwise_reversed_pair_count,
                pairwise_tied_pair_count: risk.pairwise_tied_pair_count,
                pairwise_accuracy_micros: risk.pairwise_accuracy_micros,
                pairwise_average_preferred_margin_micros: risk
                    .pairwise_average_preferred_margin_micros,
                passed,
                reason_codes: risk.risk_codes,
            });
        }
    }
    models.sort_by(|left, right| {
        (
            &left.model_version,
            serde_enum_tag(&left.target_use),
            &left.policy_version,
        )
            .cmp(&(
                &right.model_version,
                serde_enum_tag(&right.target_use),
                &right.policy_version,
            ))
    });
    let passing_model_target_count = models.iter().filter(|model| model.passed).count();
    let failing_model_target_count = models.len().saturating_sub(passing_model_target_count);
    let mut reason_code_counts = BTreeMap::new();
    for model in &models {
        for reason in &model.reason_codes {
            increment_count(&mut reason_code_counts, reason);
        }
    }

    TraceRankingModelBacktestReport {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        model_version_count,
        evaluated_model_target_count: models.len(),
        passing_model_target_count,
        failing_model_target_count,
        reason_code_counts,
        models,
    }
}

#[derive(Clone, Copy)]
struct RankingModelRiskEvidence<'a> {
    predictions: &'a [TraceRankingPredictionRecord],
    labels: &'a [TraceRankingLabelRecord],
    preference_labels: &'a [TraceRankingPreferenceLabelRecord],
    calibration_datasets: &'a [TraceRankingCalibrationDatasetRecord],
    calibration_runs: &'a [TraceRankingCalibrationRunRecord],
}

#[derive(Clone, Copy)]
struct RankingDatasetReadinessEvidence<'a> {
    predictions: &'a [TraceRankingPredictionRecord],
    labels: &'a [TraceRankingLabelRecord],
    preference_labels: &'a [TraceRankingPreferenceLabelRecord],
    calibration_datasets: &'a [TraceRankingCalibrationDatasetRecord],
    calibration_runs: &'a [TraceRankingCalibrationRunRecord],
}

fn ranking_model_risk_record(
    state: &AppState,
    tenant: &TenantAuth,
    model: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
    evidence: RankingModelRiskEvidence<'_>,
) -> TraceRankingModelRiskRecord {
    let latest_calibration =
        latest_calibration_run_for_model_target(model, target_use, evidence.calibration_runs);
    let calibration_thresholds =
        effective_ranking_calibration_thresholds(state, latest_calibration);
    let current = ranking_calibration_run_record(
        tenant,
        RankingCalibrationRunInputs {
            calibration_run_id: Uuid::new_v4(),
            model_version: model.model_version.clone(),
            target_use,
            policy_version: model.policy_version.clone(),
            feature_schema_version: model.feature_schema_version.clone(),
            evaluation_dataset_hash: model.calibration_dataset_hash.clone(),
            min_label_count: calibration_thresholds.min_label_count,
            min_label_source_count: calibration_thresholds.min_label_source_count,
            confidence_threshold: calibration_thresholds.confidence_threshold,
            max_average_absolute_error_micros: calibration_thresholds
                .max_average_absolute_error_micros,
            actor_principal_ref: tenant.principal_ref.clone(),
            created_at: Utc::now(),
        },
        evidence.predictions,
        evidence.labels,
        evidence.preference_labels,
    );

    let predictions_since_calibration_count = latest_calibration.map_or(0, |run| {
        evidence
            .predictions
            .iter()
            .filter(|prediction| {
                prediction.created_at > run.created_at
                    && ranking_prediction_matches_model_target(prediction, model, target_use)
            })
            .count()
    });
    let labels_since_calibration_count = latest_calibration.map_or(0, |run| {
        evidence
            .labels
            .iter()
            .filter(|label| label.created_at > run.created_at && label.target_use == target_use)
            .count()
    });
    let low_confidence_predictions_since_calibration_count = latest_calibration.map_or(0, |run| {
        evidence
            .predictions
            .iter()
            .filter(|prediction| {
                prediction.created_at > run.created_at
                    && ranking_prediction_matches_model_target(prediction, model, target_use)
                    && prediction.confidence < calibration_thresholds.confidence_threshold
            })
            .count()
    });
    let pairwise = ranking_pairwise_evaluation_model_report(
        model,
        target_use,
        evidence.predictions,
        evidence.preference_labels,
    );
    let adjudication = ranking_adjudication_report(
        &tenant.tenant_id,
        evidence.labels,
        evidence.preference_labels,
    );

    let joined_evidence_changed = latest_calibration
        .is_some_and(|run| run.joined_evidence_hash != current.joined_evidence_hash);
    let mut risk_codes = Vec::new();
    match latest_calibration {
        Some(run) => {
            if !run.promotable {
                risk_codes.push("calibration_not_promotable".to_string());
            }
            if ranking_calibration_is_stale(state, run) {
                risk_codes.push("calibration_stale".to_string());
            }
            if run.joined_label_source_count < state.ranking_min_label_source_count {
                risk_codes.push("calibration_label_source_underdiverse".to_string());
            }
            if ranking_calibration_run_label_actor_underdiverse(
                run,
                state.ranking_min_label_source_count,
            ) {
                risk_codes.push("calibration_label_actor_underdiverse".to_string());
            }
            if joined_evidence_changed {
                risk_codes.push("joined_evidence_changed_since_calibration".to_string());
            }
        }
        None => risk_codes.push("missing_calibration".to_string()),
    }
    if !current.promotable {
        risk_codes.push("current_evidence_not_promotable".to_string());
    }
    if low_confidence_predictions_since_calibration_count > 0 {
        risk_codes.push("low_confidence_predictions_since_calibration".to_string());
    }
    if pairwise.joined_pair_prediction_count < state.ranking_min_pairwise_label_count {
        risk_codes.push("pairwise_evidence_below_threshold".to_string());
    }
    let pairwise_diversity_required = state.ranking_min_pairwise_label_count > 0
        && state.ranking_min_label_source_count > 1
        && pairwise.joined_pair_prediction_count >= state.ranking_min_pairwise_label_count;
    if pairwise_diversity_required
        && pairwise.joined_label_source_count < state.ranking_min_label_source_count
    {
        risk_codes.push("pairwise_label_source_underdiverse".to_string());
    }
    if pairwise_diversity_required
        && pairwise.joined_label_actor_count < state.ranking_min_label_source_count
    {
        risk_codes.push("pairwise_label_actor_underdiverse".to_string());
    }
    if pairwise.joined_pair_prediction_count > 0
        && pairwise
            .pairwise_accuracy_micros
            .is_some_and(|accuracy| accuracy < state.ranking_min_pairwise_accuracy_micros)
    {
        risk_codes.push("pairwise_accuracy_below_threshold".to_string());
    }
    if ranking_model_training_calibration_datasets_overlap(model) {
        risk_codes.push("training_calibration_dataset_overlap".to_string());
    }
    if ranking_adjudication_issue_count_for_target(&adjudication, target_use) > 0 {
        risk_codes.push(RANKING_ADJUDICATION_ISSUES_REASON.to_string());
    }
    risk_codes.extend(ranking_calibration_labeler_reliability_reason_codes(
        state,
        &tenant.tenant_id,
        model,
        target_use,
        evidence.predictions,
        evidence.labels,
        evidence.preference_labels,
    ));
    if let Some(reason) = ranking_calibration_dataset_gate_reason(
        evidence.calibration_datasets,
        &model.calibration_dataset_hash,
        target_use,
        &model.policy_version,
        ranking_calibration_dataset_gate_config(state, current.min_label_count),
    ) {
        risk_codes.push(reason.to_string());
    }
    risk_codes.sort();
    risk_codes.dedup();

    TraceRankingModelRiskRecord {
        model_version: model.model_version.clone(),
        target_use,
        policy_version: model.policy_version.clone(),
        feature_schema_version: model.feature_schema_version.clone(),
        latest_calibration_run_id: latest_calibration.map(|run| run.calibration_run_id),
        latest_calibration_report_hash: latest_calibration.map(|run| run.report_hash.clone()),
        latest_joined_evidence_hash: latest_calibration.map(|run| run.joined_evidence_hash.clone()),
        latest_calibration_created_at: latest_calibration.map(|run| run.created_at),
        latest_calibration_promotable: latest_calibration.map(|run| run.promotable),
        latest_calibration_reason_codes: latest_calibration
            .map(|run| run.reason_codes.clone())
            .unwrap_or_default(),
        current_joined_evidence_hash: current.joined_evidence_hash,
        current_promotable: current.promotable,
        current_reason_codes: current.reason_codes,
        joined_evidence_changed,
        prediction_count: current.prediction_count,
        label_count: current.label_count,
        joined_label_prediction_count: current.joined_label_prediction_count,
        joined_label_source_count: current.joined_label_source_count,
        current_average_absolute_error_micros: current.average_absolute_error_micros,
        current_max_label_source_average_absolute_error_micros: current
            .max_label_source_average_absolute_error_micros,
        current_max_error_label_source: current.max_error_label_source,
        current_min_label_count: current.min_label_count,
        current_min_label_source_count: current.min_label_source_count,
        current_confidence_threshold: current.confidence_threshold,
        current_max_average_absolute_error_micros: current.max_average_absolute_error_micros,
        predictions_since_calibration_count,
        labels_since_calibration_count,
        low_confidence_predictions_since_calibration_count,
        pairwise_min_label_count: state.ranking_min_pairwise_label_count,
        pairwise_min_accuracy_micros: state.ranking_min_pairwise_accuracy_micros,
        pairwise_preference_label_count: pairwise.preference_label_count,
        pairwise_joined_pair_prediction_count: pairwise.joined_pair_prediction_count,
        pairwise_joined_label_source_count: pairwise.joined_label_source_count,
        pairwise_joined_label_actor_count: pairwise.joined_label_actor_count,
        pairwise_correct_pair_count: pairwise.correct_pair_count,
        pairwise_reversed_pair_count: pairwise.reversed_pair_count,
        pairwise_tied_pair_count: pairwise.tied_pair_count,
        pairwise_accuracy_micros: pairwise.pairwise_accuracy_micros,
        pairwise_average_preferred_margin_micros: pairwise.average_preferred_margin_micros,
        risk_codes,
    }
}

struct RankingDatasetReadinessReportInputs<'a> {
    state: &'a AppState,
    tenant: &'a TenantAuth,
    model_versions: &'a [TraceRankingModelVersionRecord],
    predictions: &'a [TraceRankingPredictionRecord],
    labels: &'a [TraceRankingLabelRecord],
    preference_labels: &'a [TraceRankingPreferenceLabelRecord],
    calibration_datasets: &'a [TraceRankingCalibrationDatasetRecord],
    calibration_dataset_manifest_conflict_count: usize,
    calibration_runs: &'a [TraceRankingCalibrationRunRecord],
}

fn ranking_dataset_readiness_report(
    inputs: RankingDatasetReadinessReportInputs<'_>,
) -> TraceRankingDatasetReadinessReport {
    let RankingDatasetReadinessReportInputs {
        state,
        tenant,
        model_versions,
        predictions,
        labels,
        preference_labels,
        calibration_datasets,
        calibration_dataset_manifest_conflict_count,
        calibration_runs,
    } = inputs;
    let latest_models = latest_ranking_model_versions(model_versions);
    let mut models_by_dataset = BTreeMap::new();
    for model in latest_models {
        models_by_dataset
            .entry(model.calibration_dataset_hash.clone())
            .or_insert_with(Vec::new)
            .push(model);
    }

    let mut datasets = Vec::new();
    let mut model_version_count = 0usize;
    let mut candidate_model_count = 0usize;
    let mut active_model_count = 0usize;
    let mut no_target_evidence_model_count = 0usize;
    let mut ready_model_target_count = 0usize;
    let mut blocked_model_target_count = 0usize;
    let mut reason_code_counts = BTreeMap::new();
    let evidence = RankingDatasetReadinessEvidence {
        predictions,
        labels,
        preference_labels,
        calibration_datasets,
        calibration_runs,
    };
    if calibration_dataset_manifest_conflict_count > 0 {
        reason_code_counts.insert(
            RANKING_CALIBRATION_DATASET_MANIFEST_CONFLICT_REASON.to_string(),
            calibration_dataset_manifest_conflict_count,
        );
    }

    for (calibration_dataset_hash, mut models) in models_by_dataset {
        models.sort_by(|left, right| left.model_version.cmp(&right.model_version));
        let mut dataset_candidate_count = 0usize;
        let mut dataset_active_count = 0usize;
        let mut dataset_deprecated_count = 0usize;
        let mut dataset_archived_count = 0usize;
        let mut dataset_no_target_count = 0usize;
        let mut dataset_ready_count = 0usize;
        let mut dataset_blocked_count = 0usize;
        let mut dataset_reason_counts = BTreeMap::new();
        let mut dataset_model_versions = Vec::new();
        let mut training_dataset_hashes = BTreeSet::new();
        let mut model_targets = Vec::new();

        for model in &models {
            model_version_count += 1;
            dataset_model_versions.push(model.model_version.clone());
            training_dataset_hashes.insert(model.training_dataset_hash.clone());
            match model.status {
                StorageTraceRankingModelStatus::Candidate => {
                    candidate_model_count += 1;
                    dataset_candidate_count += 1;
                }
                StorageTraceRankingModelStatus::Active => {
                    active_model_count += 1;
                    dataset_active_count += 1;
                }
                StorageTraceRankingModelStatus::Deprecated => {
                    dataset_deprecated_count += 1;
                }
                StorageTraceRankingModelStatus::Archived => {
                    dataset_archived_count += 1;
                }
            }

            let target_uses = ranking_model_target_uses(model, predictions, calibration_runs);
            if target_uses.is_empty() {
                dataset_no_target_count += 1;
                no_target_evidence_model_count += 1;
                increment_count(&mut dataset_reason_counts, "missing_target_use_evidence");
                increment_count(&mut reason_code_counts, "missing_target_use_evidence");
                continue;
            }
            for target_use in target_uses {
                let target = ranking_dataset_target_readiness_record(
                    state, tenant, model, target_use, evidence,
                );
                if target.ready {
                    dataset_ready_count += 1;
                    ready_model_target_count += 1;
                } else {
                    dataset_blocked_count += 1;
                    blocked_model_target_count += 1;
                }
                for reason in &target.reason_codes {
                    increment_count(&mut dataset_reason_counts, reason);
                    increment_count(&mut reason_code_counts, reason);
                }
                model_targets.push(target);
            }
        }

        model_targets.sort_by(|left, right| {
            (
                &left.model_version,
                serde_enum_tag(&left.target_use),
                &left.policy_version,
            )
                .cmp(&(
                    &right.model_version,
                    serde_enum_tag(&right.target_use),
                    &right.policy_version,
                ))
        });

        datasets.push(TraceRankingDatasetReadinessRecord {
            calibration_dataset_hash,
            model_version_count: models.len(),
            candidate_model_count: dataset_candidate_count,
            active_model_count: dataset_active_count,
            deprecated_model_count: dataset_deprecated_count,
            archived_model_count: dataset_archived_count,
            no_target_evidence_model_count: dataset_no_target_count,
            ready_model_target_count: dataset_ready_count,
            blocked_model_target_count: dataset_blocked_count,
            reason_code_counts: dataset_reason_counts,
            model_versions: dataset_model_versions,
            training_dataset_hashes: training_dataset_hashes.into_iter().collect(),
            model_targets,
        });
    }

    TraceRankingDatasetReadinessReport {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        calibration_dataset_count: datasets.len(),
        calibration_dataset_manifest_conflict_count,
        model_version_count,
        candidate_model_count,
        active_model_count,
        no_target_evidence_model_count,
        ready_model_target_count,
        blocked_model_target_count,
        reason_code_counts,
        datasets,
    }
}

fn ranking_dataset_target_readiness_record(
    state: &AppState,
    tenant: &TenantAuth,
    model: &TraceRankingModelVersionRecord,
    target_use: TraceAllowedUse,
    evidence: RankingDatasetReadinessEvidence<'_>,
) -> TraceRankingDatasetTargetReadinessRecord {
    let latest_calibration =
        latest_calibration_run_for_model_target(model, target_use, evidence.calibration_runs);
    let thresholds = effective_ranking_calibration_thresholds(state, latest_calibration);
    let mut current = ranking_calibration_run_record(
        tenant,
        RankingCalibrationRunInputs {
            calibration_run_id: Uuid::new_v4(),
            model_version: model.model_version.clone(),
            target_use,
            policy_version: model.policy_version.clone(),
            feature_schema_version: model.feature_schema_version.clone(),
            evaluation_dataset_hash: model.calibration_dataset_hash.clone(),
            min_label_count: thresholds.min_label_count,
            min_label_source_count: thresholds.min_label_source_count,
            confidence_threshold: thresholds.confidence_threshold,
            max_average_absolute_error_micros: thresholds.max_average_absolute_error_micros,
            actor_principal_ref: tenant.principal_ref.clone(),
            created_at: Utc::now(),
        },
        evidence.predictions,
        evidence.labels,
        evidence.preference_labels,
    );
    current.report_hash = ranking_calibration_run_report_hash(&current);

    let joined_evidence_changed = latest_calibration
        .is_some_and(|run| run.joined_evidence_hash != current.joined_evidence_hash);
    let mut reason_codes = Vec::new();
    match model.status {
        StorageTraceRankingModelStatus::Candidate | StorageTraceRankingModelStatus::Active => {}
        StorageTraceRankingModelStatus::Deprecated | StorageTraceRankingModelStatus::Archived => {
            reason_codes.push("model_status_not_deployable".to_string());
        }
    }
    match latest_calibration {
        Some(run) => {
            if !run.promotable {
                reason_codes.push("calibration_not_promotable".to_string());
            }
            if ranking_calibration_is_stale(state, run) {
                reason_codes.push("calibration_stale".to_string());
            }
            if run.joined_label_source_count < state.ranking_min_label_source_count {
                reason_codes.push("calibration_label_source_underdiverse".to_string());
            }
            if ranking_calibration_run_label_actor_underdiverse(
                run,
                state.ranking_min_label_source_count,
            ) {
                reason_codes.push("calibration_label_actor_underdiverse".to_string());
            }
            if joined_evidence_changed {
                reason_codes.push("joined_evidence_changed_since_calibration".to_string());
            }
        }
        None => reason_codes.push("missing_calibration".to_string()),
    }
    if !current.promotable {
        reason_codes.push("current_evidence_not_promotable".to_string());
    }
    if ranking_model_training_calibration_datasets_overlap(model) {
        reason_codes.push("training_calibration_dataset_overlap".to_string());
    }
    reason_codes.extend(ranking_calibration_labeler_reliability_reason_codes(
        state,
        &tenant.tenant_id,
        model,
        target_use,
        evidence.predictions,
        evidence.labels,
        evidence.preference_labels,
    ));
    if let Some(reason) = ranking_calibration_dataset_gate_reason(
        evidence.calibration_datasets,
        &model.calibration_dataset_hash,
        target_use,
        &model.policy_version,
        ranking_calibration_dataset_gate_config(state, current.min_label_count),
    ) {
        reason_codes.push(reason.to_string());
    }
    reason_codes.sort();
    reason_codes.dedup();
    let ready = reason_codes.is_empty();

    TraceRankingDatasetTargetReadinessRecord {
        model_version: model.model_version.clone(),
        model_status: model.status,
        target_use,
        policy_version: model.policy_version.clone(),
        feature_schema_version: model.feature_schema_version.clone(),
        latest_calibration_run_id: latest_calibration.map(|run| run.calibration_run_id),
        latest_calibration_report_hash: latest_calibration.map(|run| run.report_hash.clone()),
        latest_joined_evidence_hash: latest_calibration.map(|run| run.joined_evidence_hash.clone()),
        latest_calibration_created_at: latest_calibration.map(|run| run.created_at),
        latest_calibration_promotable: latest_calibration.map(|run| run.promotable),
        latest_calibration_reason_codes: latest_calibration
            .map(|run| run.reason_codes.clone())
            .unwrap_or_default(),
        current_calibration_report_hash: current.report_hash,
        current_joined_evidence_hash: current.joined_evidence_hash,
        current_promotable: current.promotable,
        current_reason_codes: current.reason_codes,
        joined_evidence_changed,
        current_prediction_count: current.prediction_count,
        current_label_count: current.label_count,
        current_joined_label_prediction_count: current.joined_label_prediction_count,
        current_joined_label_source_count: current.joined_label_source_count,
        current_average_absolute_error_micros: current.average_absolute_error_micros,
        current_max_label_source_average_absolute_error_micros: current
            .max_label_source_average_absolute_error_micros,
        current_min_label_count: current.min_label_count,
        current_min_label_source_count: current.min_label_source_count,
        current_confidence_threshold: current.confidence_threshold,
        current_max_average_absolute_error_micros: current.max_average_absolute_error_micros,
        ready,
        reason_codes,
    }
}

fn ranking_model_risk_lookup_key(
    model_version: &str,
    target_use: TraceAllowedUse,
    policy_version: &str,
) -> String {
    format!(
        "{model_version}\n{}\n{policy_version}",
        serde_enum_tag(&target_use)
    )
}

fn ranking_prediction_risk_lookup_key(prediction: &TraceRankingPredictionRecord) -> String {
    ranking_model_risk_lookup_key(
        &prediction.model_version,
        prediction.target_use,
        &prediction.prediction_policy_version,
    )
}

fn blocking_ranking_model_risk_codes_by_key(
    report: TraceRankingModelRiskReport,
) -> BTreeMap<String, Vec<String>> {
    report
        .models
        .into_iter()
        .filter(|model| !model.risk_codes.is_empty())
        .map(|model| {
            (
                ranking_model_risk_lookup_key(
                    &model.model_version,
                    model.target_use,
                    &model.policy_version,
                ),
                model.risk_codes,
            )
        })
        .collect()
}

struct RankingCreditReadinessInputs<'a> {
    state: &'a AppState,
    tenant: &'a TenantAuth,
    credit_events: &'a [TraceCommonsCreditLedgerRecord],
    settlement_batches: &'a [TraceCreditSettlementBatchRecord],
    held_credit_accounts: &'a BTreeSet<String>,
    features: &'a [TraceRankingFeatureRecord],
    predictions: &'a [TraceRankingPredictionRecord],
    model_versions: &'a [TraceRankingModelVersionRecord],
    labels: &'a [TraceRankingLabelRecord],
    preference_labels: &'a [TraceRankingPreferenceLabelRecord],
    calibration_datasets: &'a [TraceRankingCalibrationDatasetRecord],
    calibration_dataset_manifest_conflict_count: usize,
    calibration_runs: &'a [TraceRankingCalibrationRunRecord],
}

fn ranking_credit_readiness_report(
    inputs: RankingCreditReadinessInputs<'_>,
) -> TraceRankingCreditReadinessReport {
    let already_settled_event_ids = inputs
        .settlement_batches
        .iter()
        .filter(|batch| batch.status == StorageTraceCreditSettlementBatchStatus::Finalized)
        .flat_map(|batch| batch.source_credit_event_ids.iter().copied())
        .collect::<BTreeSet<_>>();
    let model_risk_codes_by_key =
        blocking_ranking_model_risk_codes_by_key(ranking_model_risk_report(
            inputs.state,
            inputs.tenant,
            inputs.model_versions,
            RankingModelRiskEvidence {
                predictions: inputs.predictions,
                labels: inputs.labels,
                preference_labels: inputs.preference_labels,
                calibration_datasets: inputs.calibration_datasets,
                calibration_runs: inputs.calibration_runs,
            },
        ));
    let mut events = inputs
        .credit_events
        .iter()
        .filter(|event| event.event_type == TraceCreditLedgerEventType::RankingUtility)
        .filter(|event| event.credit_points_delta > 0.0)
        .filter(|event| !already_settled_event_ids.contains(&event.event_id))
        .map(|event| {
            ranking_credit_readiness_event(RankingCreditReadinessEventInputs {
                state: inputs.state,
                event,
                held_credit_accounts: inputs.held_credit_accounts,
                features: inputs.features,
                predictions: inputs.predictions,
                model_versions: inputs.model_versions,
                calibration_runs: inputs.calibration_runs,
                calibration_dataset_manifest_conflict_count: inputs
                    .calibration_dataset_manifest_conflict_count,
                model_risk_codes_by_key: &model_risk_codes_by_key,
            })
        })
        .collect::<Vec<_>>();
    events.sort_by_key(|event| (event.ready, event.event_id));
    let ready_count = events.iter().filter(|event| event.ready).count();
    let blocked_count = events.len().saturating_sub(ready_count);
    let mut blocked_reason_counts = BTreeMap::new();
    for event in events.iter().filter(|event| !event.ready) {
        for reason in &event.reason_codes {
            *blocked_reason_counts.entry(reason.clone()).or_insert(0) += 1;
        }
    }
    TraceRankingCreditReadinessReport {
        tenant_id: inputs.tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&inputs.tenant.tenant_id),
        pending_ranking_credit_event_count: events.len(),
        calibration_dataset_manifest_conflict_count: inputs
            .calibration_dataset_manifest_conflict_count,
        ready_count,
        blocked_count,
        blocked_reason_counts,
        events,
    }
}

struct RankingCreditReadinessEventInputs<'a> {
    state: &'a AppState,
    event: &'a TraceCommonsCreditLedgerRecord,
    held_credit_accounts: &'a BTreeSet<String>,
    features: &'a [TraceRankingFeatureRecord],
    predictions: &'a [TraceRankingPredictionRecord],
    model_versions: &'a [TraceRankingModelVersionRecord],
    calibration_runs: &'a [TraceRankingCalibrationRunRecord],
    calibration_dataset_manifest_conflict_count: usize,
    model_risk_codes_by_key: &'a BTreeMap<String, Vec<String>>,
}

fn ranking_credit_readiness_event(
    inputs: RankingCreditReadinessEventInputs<'_>,
) -> TraceRankingCreditReadinessEvent {
    let RankingCreditReadinessEventInputs {
        state,
        event,
        held_credit_accounts,
        features,
        predictions,
        model_versions,
        calibration_runs,
        calibration_dataset_manifest_conflict_count,
        model_risk_codes_by_key,
    } = inputs;
    let mut reason_codes = Vec::new();
    if calibration_dataset_manifest_conflict_count > 0 {
        reason_codes.push(RANKING_CALIBRATION_DATASET_MANIFEST_CONFLICT_REASON.to_string());
    }
    if held_credit_accounts.contains(&event.auth_principal_ref) {
        reason_codes.push("held_credit_account".to_string());
    }

    let ranking_prediction_id =
        parse_ranking_prediction_external_ref(event.external_ref.as_deref());
    let mut model_version = None;
    let mut target_use = None;
    let mut policy_version = None;
    let mut ranking_calibration_run_id = None;
    let mut ranking_calibration_report_hash = None;
    let mut ranking_calibration_joined_evidence_hash = None;

    let Some(parsed_prediction_id) = ranking_prediction_id else {
        reason_codes.push("missing_prediction_ref".to_string());
        reason_codes.sort();
        reason_codes.dedup();
        return TraceRankingCreditReadinessEvent {
            event_id: event.event_id,
            submission_id: event.submission_id,
            credit_points_delta: event.credit_points_delta,
            ranking_prediction_id: None,
            model_version,
            target_use,
            policy_version,
            ranking_calibration_run_id,
            ranking_calibration_report_hash,
            ranking_calibration_joined_evidence_hash,
            ready: false,
            reason_codes,
        };
    };

    let prediction = predictions
        .iter()
        .find(|prediction| prediction.ranking_prediction_id == parsed_prediction_id);
    let Some(prediction) = prediction else {
        reason_codes.push("missing_prediction".to_string());
        reason_codes.sort();
        reason_codes.dedup();
        return TraceRankingCreditReadinessEvent {
            event_id: event.event_id,
            submission_id: event.submission_id,
            credit_points_delta: event.credit_points_delta,
            ranking_prediction_id,
            model_version,
            target_use,
            policy_version,
            ranking_calibration_run_id,
            ranking_calibration_report_hash,
            ranking_calibration_joined_evidence_hash,
            ready: false,
            reason_codes,
        };
    };

    model_version = Some(prediction.model_version.clone());
    target_use = Some(prediction.target_use);
    policy_version = Some(prediction.prediction_policy_version.clone());
    if let Some(risk_codes) =
        model_risk_codes_by_key.get(&ranking_prediction_risk_lookup_key(prediction))
    {
        reason_codes.extend(risk_codes.iter().cloned());
    }
    if prediction.submission_id != event.submission_id {
        reason_codes.push("prediction_submission_mismatch".to_string());
    }
    if prediction.settlement_score_micros != credit_delta_micros(event.credit_points_delta) {
        reason_codes.push("settlement_score_mismatch".to_string());
    }
    if state.ranking_require_server_feature_provenance
        && !ranking_prediction_has_server_feature_provenance(features, prediction)
    {
        reason_codes.push("unprovenanced_ranking_feature".to_string());
    }

    match latest_ranking_model_version(model_versions, &prediction.model_version) {
        Some(model) => {
            if model.status != StorageTraceRankingModelStatus::Active {
                reason_codes.push("inactive_model".to_string());
            }
            if model.feature_schema_version != prediction.feature_schema_version {
                reason_codes.push("feature_schema_mismatch".to_string());
            }
            if model.policy_version != prediction.prediction_policy_version {
                reason_codes.push("policy_mismatch".to_string());
            }
            match latest_calibration_run_for_model_target(
                model,
                prediction.target_use,
                calibration_runs,
            ) {
                Some(run) => {
                    ranking_calibration_run_id = Some(run.calibration_run_id);
                    ranking_calibration_report_hash = Some(run.report_hash.clone());
                    ranking_calibration_joined_evidence_hash =
                        Some(run.joined_evidence_hash.clone());
                    if !run.promotable {
                        reason_codes.push("calibration_not_promotable".to_string());
                    }
                    if ranking_calibration_is_stale(state, run) {
                        reason_codes.push("calibration_stale".to_string());
                    }
                    if run.joined_label_source_count < state.ranking_min_label_source_count {
                        reason_codes.push("calibration_label_source_underdiverse".to_string());
                    }
                    if ranking_calibration_run_label_actor_underdiverse(
                        run,
                        state.ranking_min_label_source_count,
                    ) {
                        reason_codes.push("calibration_label_actor_underdiverse".to_string());
                    }
                    if prediction.confidence < run.confidence_threshold {
                        reason_codes.push("low_confidence_prediction".to_string());
                    }
                }
                None => reason_codes.push("missing_calibration".to_string()),
            }
        }
        None => reason_codes.push("missing_model".to_string()),
    }

    reason_codes.sort();
    reason_codes.dedup();
    TraceRankingCreditReadinessEvent {
        event_id: event.event_id,
        submission_id: event.submission_id,
        credit_points_delta: event.credit_points_delta,
        ranking_prediction_id,
        model_version,
        target_use,
        policy_version,
        ranking_calibration_run_id,
        ranking_calibration_report_hash,
        ranking_calibration_joined_evidence_hash,
        ready: reason_codes.is_empty(),
        reason_codes,
    }
}

struct RankingCalibrationRunInputs {
    calibration_run_id: Uuid,
    model_version: String,
    target_use: TraceAllowedUse,
    policy_version: String,
    feature_schema_version: String,
    evaluation_dataset_hash: String,
    min_label_count: usize,
    min_label_source_count: usize,
    confidence_threshold: f32,
    max_average_absolute_error_micros: i64,
    actor_principal_ref: String,
    created_at: DateTime<Utc>,
}

fn ranking_calibration_joined_evidence_hash(
    inputs: &RankingCalibrationRunInputs,
    joined_evidence_lines: &[String],
) -> String {
    let mut lines = joined_evidence_lines.to_vec();
    lines.sort();
    let mut payload = format!(
        "ranking_calibration_joined_evidence:v1\n{}\n{}\n{}\n{}\n{}",
        inputs.model_version,
        serde_enum_tag(&inputs.target_use),
        inputs.policy_version,
        inputs.feature_schema_version,
        inputs.evaluation_dataset_hash
    );
    for line in lines {
        payload.push('\n');
        payload.push_str(&line);
    }
    sha256_prefixed(&payload)
}

fn ranking_calibration_run_record(
    tenant: &TenantAuth,
    inputs: RankingCalibrationRunInputs,
    predictions: &[TraceRankingPredictionRecord],
    labels: &[TraceRankingLabelRecord],
    preference_labels: &[TraceRankingPreferenceLabelRecord],
) -> TraceRankingCalibrationRunRecord {
    let matching_predictions = predictions
        .iter()
        .filter(|prediction| {
            prediction.model_version == inputs.model_version
                && prediction.target_use == inputs.target_use
                && prediction.prediction_policy_version == inputs.policy_version
                && prediction.feature_schema_version == inputs.feature_schema_version
        })
        .collect::<Vec<_>>();
    let matching_labels = ranking_calibration_effective_labels(
        labels
            .iter()
            .filter(|label| label.target_use == inputs.target_use),
    );
    let mut latest_prediction_by_submission = BTreeMap::new();
    for prediction in &matching_predictions {
        latest_prediction_by_submission.insert(prediction.submission_id, *prediction);
    }

    let mut joined_count = 0usize;
    let mut predicted_sum = 0i128;
    let mut label_sum = 0i128;
    let mut signed_error_sum = 0i128;
    let mut abs_error_sum = 0i128;
    let mut joined_label_sources = BTreeSet::new();
    let mut joined_label_actors = BTreeSet::new();
    let mut label_source_abs_error_sums = BTreeMap::new();
    let mut joined_evidence_lines = Vec::new();
    for label in &matching_labels {
        let Some(prediction) = latest_prediction_by_submission.get(&label.submission_id) else {
            continue;
        };
        joined_count += 1;
        joined_label_sources.insert(label.label_source);
        joined_label_actors.insert(label.actor_principal_ref.as_str());
        let predicted = prediction.predicted_utility_micros;
        let abs_error = (label.utility_delta_micros - predicted).abs();
        let (source_error_sum, source_count) = label_source_abs_error_sums
            .entry(label.label_source)
            .or_insert((0i128, 0usize));
        *source_error_sum += i128::from(abs_error);
        *source_count += 1;
        predicted_sum += i128::from(predicted);
        label_sum += i128::from(label.utility_delta_micros);
        signed_error_sum += i128::from(predicted - label.utility_delta_micros);
        abs_error_sum += i128::from(abs_error);
        joined_evidence_lines.push(format!(
            "{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",
            label.submission_id,
            prediction.ranking_prediction_id,
            label.ranking_label_id,
            serde_enum_tag(&label.label_source),
            prediction.feature_vector_hash,
            predicted,
            prediction.confidence.to_bits(),
            label.utility_delta_micros,
            label.evidence_hash
        ));
    }
    let joined_label_source_count = joined_label_sources.len();
    let joined_label_actor_count = joined_label_actors.len();
    let joined_evidence_hash =
        ranking_calibration_joined_evidence_hash(&inputs, &joined_evidence_lines);
    let (max_label_source_average_absolute_error_micros, max_error_label_source) =
        max_label_source_average_error(&label_source_abs_error_sums);
    let average_absolute_error_micros = average_i128(abs_error_sum, joined_count);
    let mut reason_codes = Vec::new();
    if joined_count < inputs.min_label_count {
        reason_codes.push("insufficient_labels".to_string());
    }
    if joined_label_source_count < inputs.min_label_source_count {
        reason_codes.push("insufficient_label_source_diversity".to_string());
    }
    if joined_label_source_count >= inputs.min_label_source_count
        && joined_label_actor_count < inputs.min_label_source_count
    {
        reason_codes.push("insufficient_label_actor_diversity".to_string());
    }
    if average_absolute_error_micros
        .is_none_or(|error| error > inputs.max_average_absolute_error_micros)
    {
        reason_codes.push("average_error_above_threshold".to_string());
    }
    if max_label_source_average_absolute_error_micros
        .is_some_and(|error| error > inputs.max_average_absolute_error_micros)
    {
        reason_codes.push("label_source_error_above_threshold".to_string());
    }
    if matching_predictions
        .iter()
        .any(|prediction| prediction.confidence < inputs.confidence_threshold)
    {
        reason_codes.push("low_confidence_predictions_present".to_string());
    }
    let adjudication = ranking_adjudication_report(&tenant.tenant_id, labels, preference_labels);
    if ranking_adjudication_issue_count_for_target(&adjudication, inputs.target_use) > 0 {
        reason_codes.push(RANKING_ADJUDICATION_ISSUES_REASON.to_string());
    }
    reason_codes.sort();
    reason_codes.dedup();
    let promotable = reason_codes.is_empty();

    TraceRankingCalibrationRunRecord {
        calibration_run_id: inputs.calibration_run_id,
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        model_version: inputs.model_version,
        target_use: inputs.target_use,
        policy_version: inputs.policy_version,
        evaluation_dataset_hash: inputs.evaluation_dataset_hash,
        prediction_count: matching_predictions.len(),
        label_count: matching_labels.len(),
        joined_label_prediction_count: joined_count,
        joined_label_source_count,
        joined_label_actor_count,
        joined_evidence_hash,
        average_predicted_utility_micros: average_i128(predicted_sum, joined_count),
        average_label_utility_delta_micros: average_i128(label_sum, joined_count),
        average_absolute_error_micros,
        max_label_source_average_absolute_error_micros,
        max_error_label_source,
        mean_signed_error_micros: average_i128(signed_error_sum, joined_count),
        low_confidence_prediction_count: matching_predictions
            .iter()
            .filter(|prediction| prediction.confidence < inputs.confidence_threshold)
            .count(),
        confidence_threshold: inputs.confidence_threshold,
        min_label_count: inputs.min_label_count,
        min_label_source_count: inputs.min_label_source_count,
        max_average_absolute_error_micros: inputs.max_average_absolute_error_micros,
        promotable,
        reason_codes,
        report_hash: String::new(),
        actor_principal_ref: inputs.actor_principal_ref,
        created_at: inputs.created_at,
    }
}

fn ranking_calibration_effective_labels<'a>(
    labels: impl Iterator<Item = &'a TraceRankingLabelRecord>,
) -> Vec<&'a TraceRankingLabelRecord> {
    let mut latest_by_submission_source = BTreeMap::new();
    for label in labels {
        let key = (label.submission_id, label.target_use, label.label_source);
        let should_replace = latest_by_submission_source.get(&key).is_none_or(
            |current: &&TraceRankingLabelRecord| {
                (label.created_at, label.ranking_label_id)
                    > (current.created_at, current.ranking_label_id)
            },
        );
        if should_replace {
            latest_by_submission_source.insert(key, label);
        }
    }
    let mut labels = latest_by_submission_source
        .into_values()
        .collect::<Vec<_>>();
    labels.sort_by_key(|label| {
        (
            label.submission_id,
            label.label_source,
            label.created_at,
            label.ranking_label_id,
        )
    });
    labels.retain(|label| label.label_outcome != StorageTraceRankingLabelOutcome::Disputed);
    labels
}

fn ranking_calibration_run_report_hash(record: &TraceRankingCalibrationRunRecord) -> String {
    let max_error_label_source = record
        .max_error_label_source
        .as_ref()
        .and_then(|source| serde_storage_string(source).ok());
    let mut payload = format!(
        "ranking_calibration_run:v5\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{:?}\n{:?}\n{:?}\n{:?}\n{:?}\n{:?}\n{}\n{}\n{}\n{}\n{}\n{}",
        record.tenant_storage_ref,
        record.model_version,
        serde_storage_string(&record.target_use).unwrap_or_else(|_| "invalid".to_string()),
        record.policy_version,
        record.evaluation_dataset_hash,
        record.prediction_count,
        record.label_count,
        record.joined_label_prediction_count,
        record.joined_label_source_count,
        record.joined_label_actor_count,
        record.joined_evidence_hash,
        record.average_predicted_utility_micros,
        record.average_label_utility_delta_micros,
        record.average_absolute_error_micros,
        record.max_label_source_average_absolute_error_micros,
        max_error_label_source,
        record.mean_signed_error_micros,
        record.low_confidence_prediction_count,
        record.confidence_threshold,
        record.min_label_count,
        record.min_label_source_count,
        record.max_average_absolute_error_micros,
        record.promotable
    );
    for reason in &record.reason_codes {
        payload.push('\n');
        payload.push_str(reason);
    }
    sha256_prefixed(&payload)
}

#[derive(Debug, Clone)]
struct RankingSettlementCalibrationGate {
    model_version: String,
    target_use: TraceAllowedUse,
    calibration_run_id: Uuid,
    report_hash: String,
    joined_evidence_hash: String,
    confidence_threshold: f32,
    model_risk_codes: Vec<String>,
}

#[derive(Debug, Clone, Copy)]
enum RankingCalibrationGateContext {
    ModelPromotion,
    PredictionCredit,
    Settlement,
}

impl RankingCalibrationGateContext {
    fn missing_message(self) -> &'static str {
        match self {
            Self::ModelPromotion => {
                "ranking model promotion requires a calibration run for the requested model, target use, and policy"
            }
            Self::PredictionCredit => {
                "ranking prediction credit requires a calibration run for the requested model, target use, and policy"
            }
            Self::Settlement => {
                "ranking utility settlement requires a calibration run for the requested model, target use, and policy"
            }
        }
    }

    fn nonpromotable_message(self) -> &'static str {
        match self {
            Self::ModelPromotion => {
                "ranking model promotion requires the latest calibration run to be promotable"
            }
            Self::PredictionCredit => {
                "ranking prediction credit requires the latest calibration run to be promotable"
            }
            Self::Settlement => "ranking utility settlement requires a promotable calibration run",
        }
    }

    fn stale_message(self) -> &'static str {
        match self {
            Self::ModelPromotion => "ranking model promotion requires a fresh calibration run",
            Self::PredictionCredit => "ranking prediction credit requires a fresh calibration run",
            Self::Settlement => "ranking utility settlement requires a fresh calibration run",
        }
    }

    fn underdiverse_message(self) -> &'static str {
        match self {
            Self::ModelPromotion => {
                "ranking model promotion requires calibration label-source diversity"
            }
            Self::PredictionCredit => {
                "ranking prediction credit requires calibration label-source diversity"
            }
            Self::Settlement => {
                "ranking utility settlement requires calibration label-source diversity"
            }
        }
    }

    fn actor_underdiverse_message(self) -> &'static str {
        match self {
            Self::ModelPromotion => {
                "ranking model promotion requires calibration label-actor diversity"
            }
            Self::PredictionCredit => {
                "ranking prediction credit requires calibration label-actor diversity"
            }
            Self::Settlement => {
                "ranking utility settlement requires calibration label-actor diversity"
            }
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct EffectiveRankingCalibrationThresholds {
    min_label_count: usize,
    min_label_source_count: usize,
    confidence_threshold: f32,
    max_average_absolute_error_micros: i64,
}

fn effective_ranking_calibration_thresholds(
    state: &AppState,
    run: Option<&TraceRankingCalibrationRunRecord>,
) -> EffectiveRankingCalibrationThresholds {
    EffectiveRankingCalibrationThresholds {
        min_label_count: run.map_or(state.ranking_min_label_count, |run| {
            run.min_label_count.max(state.ranking_min_label_count)
        }),
        min_label_source_count: run.map_or(state.ranking_min_label_source_count, |run| {
            run.min_label_source_count
                .max(state.ranking_min_label_source_count)
        }),
        confidence_threshold: run
            .map_or(state.ranking_min_confidence_threshold, |run| {
                run.confidence_threshold
            })
            .max(state.ranking_min_confidence_threshold),
        max_average_absolute_error_micros: run.map_or(
            state.ranking_max_average_absolute_error_micros,
            |run| {
                run.max_average_absolute_error_micros
                    .min(state.ranking_max_average_absolute_error_micros)
            },
        ),
    }
}

const RANKING_PREDICTION_EXTERNAL_REF_PREFIX: &str = "ranking_prediction:";

fn ranking_prediction_external_ref(ranking_prediction_id: Uuid) -> String {
    format!("{RANKING_PREDICTION_EXTERNAL_REF_PREFIX}{ranking_prediction_id}")
}

fn parse_ranking_prediction_external_ref(external_ref: Option<&str>) -> Option<Uuid> {
    let external_ref = external_ref?.trim();
    let prediction_id = external_ref.strip_prefix(RANKING_PREDICTION_EXTERNAL_REF_PREFIX)?;
    Uuid::parse_str(prediction_id).ok()
}

fn parse_revocation_credit_reversal_external_ref(external_ref: Option<&str>) -> Option<Uuid> {
    let external_ref = external_ref?.trim();
    let credit_event_id =
        external_ref.strip_prefix(REVOCATION_CREDIT_REVERSAL_EXTERNAL_REF_PREFIX)?;
    Uuid::parse_str(credit_event_id).ok()
}

fn ranking_credit_event_exclusion_reason_codes(
    state: &AppState,
    event: &TraceCommonsCreditLedgerRecord,
    features: &[TraceRankingFeatureRecord],
    predictions: &[TraceRankingPredictionRecord],
    gate: Option<&RankingSettlementCalibrationGate>,
    policy_version: &str,
) -> Vec<String> {
    let mut reason_codes = Vec::new();
    let Some(gate) = gate else {
        return vec!["missing_ranking_model_gate".to_string()];
    };
    reason_codes.extend(gate.model_risk_codes.iter().cloned());

    let Some(prediction_id) = parse_ranking_prediction_external_ref(event.external_ref.as_deref())
    else {
        reason_codes.push("missing_prediction_ref".to_string());
        reason_codes.sort();
        reason_codes.dedup();
        return reason_codes;
    };
    let Some(prediction) = predictions
        .iter()
        .find(|prediction| prediction.ranking_prediction_id == prediction_id)
    else {
        reason_codes.push("missing_prediction".to_string());
        reason_codes.sort();
        reason_codes.dedup();
        return reason_codes;
    };

    if prediction.submission_id != event.submission_id {
        reason_codes.push("prediction_submission_mismatch".to_string());
    }
    let settlement_score_micros = credit_delta_micros(event.credit_points_delta);
    if prediction.model_version != gate.model_version {
        reason_codes.push("model_mismatch".to_string());
    }
    if prediction.target_use != gate.target_use {
        reason_codes.push("target_use_mismatch".to_string());
    }
    if prediction.prediction_policy_version != policy_version {
        reason_codes.push("policy_mismatch".to_string());
    }
    if prediction.settlement_score_micros != settlement_score_micros {
        reason_codes.push("settlement_score_mismatch".to_string());
    }
    if state.ranking_require_server_feature_provenance
        && !ranking_prediction_has_server_feature_provenance(features, prediction)
    {
        reason_codes.push("unprovenanced_ranking_feature".to_string());
    }
    if prediction.confidence < gate.confidence_threshold {
        reason_codes.push("low_confidence_prediction".to_string());
    }
    reason_codes.sort();
    reason_codes.dedup();
    reason_codes
}

fn ensure_ranking_calibration_fresh(
    state: &AppState,
    run: &TraceRankingCalibrationRunRecord,
    context: RankingCalibrationGateContext,
) -> ApiResult<()> {
    let Some(max_age) = state.ranking_calibration_max_age else {
        return Ok(());
    };
    let age = Utc::now().signed_duration_since(run.created_at);
    if age > max_age {
        return Err(api_error(StatusCode::CONFLICT, context.stale_message()));
    }
    Ok(())
}

fn ensure_ranking_calibration_label_source_diversity(
    state: &AppState,
    run: &TraceRankingCalibrationRunRecord,
    context: RankingCalibrationGateContext,
) -> ApiResult<()> {
    if run.joined_label_source_count < state.ranking_min_label_source_count {
        return Err(api_error(
            StatusCode::CONFLICT,
            context.underdiverse_message(),
        ));
    }
    if ranking_calibration_run_label_actor_underdiverse(run, state.ranking_min_label_source_count) {
        return Err(api_error(
            StatusCode::CONFLICT,
            context.actor_underdiverse_message(),
        ));
    }
    Ok(())
}

fn ranking_calibration_run_label_actor_underdiverse(
    run: &TraceRankingCalibrationRunRecord,
    min_label_source_count: usize,
) -> bool {
    run.joined_label_source_count >= min_label_source_count
        && run.joined_label_actor_count < min_label_source_count
}

async fn ranking_settlement_calibration_gate(
    state: &AppState,
    tenant: &TenantAuth,
    policy_version: &str,
    model_version: Option<&str>,
    target_use: TraceAllowedUse,
) -> ApiResult<Option<RankingSettlementCalibrationGate>> {
    let Some(model_version) = model_version else {
        return Ok(None);
    };
    let model_versions = read_ranking_model_versions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let model = latest_ranking_model_version(&model_versions, model_version).ok_or_else(|| {
        api_error(
            StatusCode::CONFLICT,
            RankingCalibrationGateContext::Settlement.missing_message(),
        )
    })?;
    if model.status != StorageTraceRankingModelStatus::Active {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking utility settlement requires an active ranking model",
        ));
    }
    ensure_ranking_model_dataset_isolation(model, RankingModelDatasetIsolationContext::Settlement)?;
    if model.policy_version != policy_version {
        return Err(api_error(
            StatusCode::CONFLICT,
            "ranking utility settlement policy does not match the active model",
        ));
    }
    let run = latest_promotable_ranking_calibration_run(
        state,
        tenant,
        model_version,
        target_use,
        policy_version,
        &model.calibration_dataset_hash,
        RankingCalibrationGateContext::Settlement,
    )
    .await?;
    let predictions = read_ranking_predictions_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let labels = read_ranking_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let preference_labels = read_ranking_preference_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let calibration_datasets = read_ranking_calibration_datasets_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let calibration_runs = read_ranking_calibration_runs_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    let model_risk_codes = blocking_ranking_model_risk_codes_by_key(ranking_model_risk_report(
        state,
        tenant,
        &model_versions,
        RankingModelRiskEvidence {
            predictions: &predictions,
            labels: &labels,
            preference_labels: &preference_labels,
            calibration_datasets: &calibration_datasets,
            calibration_runs: &calibration_runs,
        },
    ))
    .remove(&ranking_model_risk_lookup_key(
        &run.model_version,
        run.target_use,
        policy_version,
    ))
    .unwrap_or_default();
    let calibration_thresholds = effective_ranking_calibration_thresholds(state, Some(&run));
    Ok(Some(RankingSettlementCalibrationGate {
        model_version: run.model_version,
        target_use: run.target_use,
        calibration_run_id: run.calibration_run_id,
        report_hash: run.report_hash,
        joined_evidence_hash: run.joined_evidence_hash,
        confidence_threshold: calibration_thresholds.confidence_threshold,
        model_risk_codes,
    }))
}

fn average_i128(sum: i128, count: usize) -> Option<i64> {
    if count == 0 {
        return None;
    }
    Some((sum / count as i128) as i64)
}

fn trace_credit_event_type_is_settlement_eligible(event_type: TraceCreditLedgerEventType) -> bool {
    matches!(
        event_type,
        TraceCreditLedgerEventType::BenchmarkConversion
            | TraceCreditLedgerEventType::RegressionCatch
            | TraceCreditLedgerEventType::TrainingUtility
            | TraceCreditLedgerEventType::RankingUtility
            | TraceCreditLedgerEventType::NoveltyUtility
    )
}

fn delayed_credit_required_allowed_uses(
    event_type: TraceCreditLedgerEventType,
) -> &'static [TraceAllowedUse] {
    match event_type {
        TraceCreditLedgerEventType::BenchmarkConversion => &[TraceAllowedUse::BenchmarkGeneration],
        TraceCreditLedgerEventType::RegressionCatch
        | TraceCreditLedgerEventType::TrainingUtility
        | TraceCreditLedgerEventType::RankingUtility
        | TraceCreditLedgerEventType::NoveltyUtility => {
            utility_credit_required_allowed_uses(event_type)
        }
        TraceCreditLedgerEventType::ReviewerBonus | TraceCreditLedgerEventType::AbusePenalty => &[],
    }
}

fn utility_credit_required_allowed_uses(
    event_type: TraceCreditLedgerEventType,
) -> &'static [TraceAllowedUse] {
    match event_type {
        TraceCreditLedgerEventType::RegressionCatch => &[TraceAllowedUse::Evaluation],
        TraceCreditLedgerEventType::TrainingUtility => &[TraceAllowedUse::ModelTraining],
        TraceCreditLedgerEventType::RankingUtility => &[TraceAllowedUse::RankingModelTraining],
        // Phase A5: a trace that's novel for the corpus is most directly
        // useful as training data. The spec calls this `TrainingDataset`, but
        // the canonical `TraceAllowedUse` enum exposes the equivalent through
        // `ModelTraining`. Operators wanting a different use can refine this
        // through a tenant-policy extension in a future slice.
        TraceCreditLedgerEventType::NoveltyUtility => &[TraceAllowedUse::ModelTraining],
        TraceCreditLedgerEventType::BenchmarkConversion
        | TraceCreditLedgerEventType::ReviewerBonus
        | TraceCreditLedgerEventType::AbusePenalty => &[],
    }
}

const VECTOR_INDEX_ALLOWED_USES: &[TraceAllowedUse] = &[
    TraceAllowedUse::Debugging,
    TraceAllowedUse::Evaluation,
    TraceAllowedUse::BenchmarkGeneration,
    TraceAllowedUse::RankingModelTraining,
    TraceAllowedUse::ModelTraining,
];

async fn process_evaluation_worker_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceProcessEvaluationJobRequest>,
) -> ApiResult<Json<TraceProcessEvaluationJobResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_process_evaluation_operator(&tenant)?;
    run_process_evaluation_job(state.as_ref(), &tenant, body)
        .await
        .map(Json)
}

async fn run_process_evaluation_job(
    state: &AppState,
    tenant: &TenantAuth,
    body: TraceProcessEvaluationJobRequest,
) -> ApiResult<TraceProcessEvaluationJobResponse> {
    let reason = body.reason.trim().to_string();
    if reason.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "process evaluation jobs require a non-empty reason",
        ));
    }
    if body.process_evaluation.evaluator_version.trim().is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "process evaluation jobs require a non-empty evaluator_version",
        ));
    }
    if let Some(score) = body.process_evaluation.overall_score
        && (!score.is_finite() || !(0.0..=1.0).contains(&score))
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "process evaluation overall_score must be finite and between 0.0 and 1.0",
        ));
    }
    let utility_external_ref = body
        .utility_external_ref
        .as_deref()
        .map(str::trim)
        .filter(|external_ref| !external_ref.is_empty())
        .map(ToOwned::to_owned);
    match (
        body.utility_credit_points_delta,
        utility_external_ref.as_ref(),
    ) {
        (Some(points), None) => {
            if !points.is_finite() {
                return Err(api_error(
                    StatusCode::BAD_REQUEST,
                    "utility_credit_points_delta must be finite",
                ));
            }
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "process evaluation utility credit requires a non-empty utility_external_ref",
            ));
        }
        (Some(points), Some(_)) if !points.is_finite() => {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "utility_credit_points_delta must be finite",
            ));
        }
        (Some(points), Some(_)) if points.abs() > MAX_DELAYED_CREDIT_POINTS_DELTA => {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "utility_credit_points_delta exceeds the delayed credit policy limit",
            ));
        }
        (None, Some(_)) => {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "utility_external_ref requires utility_credit_points_delta",
            ));
        }
        _ => {}
    }
    let utility_credit_request = body
        .utility_credit_points_delta
        .zip(utility_external_ref.clone());
    if let Some((credit_points_delta, _)) = utility_credit_request.as_ref() {
        require_positive_credit_issuance_principal_if_configured(
            state,
            tenant,
            *credit_points_delta,
        )?;
    }

    let mut record = read_utility_submission_record(state, tenant, body.submission_id)
        .await
        .map_err(internal_error)?
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "trace submission not found"))?;
    if record.status != TraceCorpusStatus::Accepted {
        return Err(api_error(
            StatusCode::CONFLICT,
            "process evaluation jobs can only label accepted trace submissions",
        ));
    }
    let tenant_policy = tenant_process_evaluation_policy_for_request(state, tenant).await?;
    if !record_matches_export_policy_abac(
        &record,
        tenant,
        tenant_policy.as_ref(),
        TraceAllowedUse::Evaluation,
    ) {
        tracing::warn!(
            tenant_id = %tenant.tenant_id,
            submission_id = %record.submission_id,
            "Trace Commons tenant policy rejected process evaluation source"
        );
        return Err(api_error(
            StatusCode::FORBIDDEN,
            "trace process evaluation source is not allowed by tenant policy",
        ));
    }
    let ranking_label_request = body.ranking_label.clone();
    let ranking_label_plan = if let Some(ranking_label) = ranking_label_request.as_ref() {
        if ranking_label.label_source != StorageTraceRankingLabelSource::System {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "process evaluation ranking labels must use system label_source",
            ));
        }
        if !record_matches_export_policy_abac(
            &record,
            tenant,
            tenant_policy.as_ref(),
            ranking_label.target_use,
        ) {
            return Err(api_error(
                StatusCode::FORBIDDEN,
                "trace process evaluation ranking label source is not allowed for this target use",
            ));
        }
        let external_ref =
            validate_process_evaluation_ranking_label_external_ref(&ranking_label.external_ref)?;
        Some(
            prepare_process_evaluation_ranking_label(
                state,
                tenant,
                &record,
                &body.process_evaluation,
                ranking_label,
                &external_ref,
            )
            .await?,
        )
    } else {
        None
    };

    let TraceEnvelopeBodyRead {
        envelope: mut envelope_before,
        object_ref_id: input_object_ref_id,
    } = read_envelope_for_process_evaluation(state, tenant, &record, Some(&reason))
        .await
        .map_err(internal_error)?;
    let input_hash = envelope_plaintext_hash(&envelope_before).map_err(internal_error)?;
    envelope_before.process_evaluation = Some(body.process_evaluation);
    apply_credit_estimate_to_envelope(&mut envelope_before);
    let process_eval_value = envelope_before.value_card.scorecard.process_eval_value;
    let stored = store_envelope(
        state,
        &tenant.tenant_id,
        record.status,
        "process-evaluated-envelope",
        &envelope_before,
    )
    .map_err(internal_error)?;
    record.object_key = stored.object_key;
    record.artifact_receipt = stored.artifact_receipt;
    record.artifact_object_store = stored.artifact_object_store;
    if submission_metadata_path(&state.root, &tenant.tenant_id, record.submission_id).exists() {
        write_submission_record(&state.root, &record).map_err(internal_error)?;
    }

    if let Some(mut derived) =
        read_derived_record(&state.root, &tenant.tenant_id, record.submission_id)
            .map_err(internal_error)?
    {
        derived.coverage_tags = coverage_tags_for_envelope(&envelope_before);
        write_derived_record(&state.root, &derived).map_err(internal_error)?;
    }

    let output_object_ref_id = mirror_process_evaluation_to_db(
        state,
        tenant,
        &record,
        &envelope_before,
        input_object_ref_id,
        &input_hash,
    )
    .await
    .map_err(internal_error)?;

    append_audit_event_with_db_mirror(
        state,
        tenant,
        TraceCommonsAuditEvent::process_evaluation(
            tenant,
            record.submission_id,
            envelope_before.value_card.scorecard.process_eval_value,
            Some(&reason),
        ),
        StorageTraceAuditAction::ProcessEvaluate,
        process_evaluation_audit_metadata(
            envelope_before.process_evaluation.as_ref(),
            utility_credit_request.as_ref(),
        ),
    )
    .await
    .map_err(internal_error)?;

    let utility_credit_counts =
        if let Some((credit_points_delta, external_ref)) = utility_credit_request {
            append_automatic_utility_credit_events_once_with_counts(
                state,
                tenant,
                AutomaticUtilityCreditConfig {
                    idempotency_label: "process-evaluation-training-credit",
                    idempotency_ref: Some(external_ref.clone()),
                    event_type: TraceCreditLedgerEventType::TrainingUtility,
                    credit_points_delta,
                    reason: format!("process evaluation utility: {reason}"),
                    external_ref,
                },
                [AutomaticUtilityCreditSource {
                    submission_id: record.submission_id,
                    trace_id: record.trace_id,
                    auth_principal_ref: record.auth_principal_ref.clone(),
                }],
            )
            .await?
        } else {
            AutomaticUtilityCreditAppendCounts::default()
        };
    let ranking_label_counts = if let (Some(ranking_label), Some(plan)) =
        (ranking_label_request.as_ref(), ranking_label_plan.as_ref())
    {
        append_process_evaluation_ranking_label_once(state, tenant, &record, ranking_label, plan)
            .await?
    } else {
        ProcessEvaluationRankingLabelAppendCounts::default()
    };

    Ok(TraceProcessEvaluationJobResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        submission_id: record.submission_id,
        trace_id: record.trace_id,
        status: record.status,
        process_eval_value,
        review_scorecard: envelope_before.value_card.scorecard,
        output_object_ref_id,
        utility_credit_appended_count: utility_credit_counts.appended,
        utility_credit_skipped_existing_count: utility_credit_counts.skipped_existing,
        ranking_label_appended_count: ranking_label_counts.appended,
        ranking_label_skipped_existing_count: ranking_label_counts.skipped_existing,
    })
}

async fn process_evaluation_worker_run_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<ProcessEvaluationWorkerRunRequest>,
) -> ApiResult<Json<ProcessEvaluationWorkerRunResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_process_evaluation_operator(&tenant)?;
    run_process_evaluation_worker(state.as_ref(), &tenant, body)
        .await
        .map(Json)
}

async fn run_process_evaluation_worker(
    state: &AppState,
    tenant: &TenantAuth,
    body: ProcessEvaluationWorkerRunRequest,
) -> ApiResult<ProcessEvaluationWorkerRunResponse> {
    let limit = validate_process_evaluation_worker_run_limit(body.limit)?;
    let dry_run = body.dry_run.unwrap_or(false);
    let evaluator_ref = normalize_process_evaluation_worker_evaluator_ref(body.evaluator_ref)?;
    let reason = normalize_process_evaluation_worker_reason(body.reason)?;
    let require_external_evaluator = body.require_external_evaluator.unwrap_or(false);
    if require_external_evaluator && state.process_evaluator.is_none() {
        return Err(api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "process evaluation worker requires TRACE_COMMONS_PROCESS_EVALUATOR_URL",
        ));
    }
    let target_use = body.target_use;
    let utility_category = target_use.map(|_| {
        body.utility_category
            .unwrap_or(StorageTraceRankingUtilityCategory::RankingTraining)
    });
    let external_ref_prefix = if target_use.is_some() {
        Some(normalize_process_evaluation_external_ref_prefix(
            body.external_ref_prefix,
        )?)
    } else {
        None
    };
    ensure_no_overlapping_live_ranking_worker_run(
        state,
        tenant,
        TraceRankingWorkerRunKind::ProcessEvaluation,
        dry_run,
        None,
        target_use,
        None,
    )
    .await?;
    let tenant_policy = tenant_process_evaluation_policy_for_request(state, tenant).await?;
    let view = read_reviewer_metadata_view(state, tenant)
        .await
        .map_err(internal_error)?;
    let derived_by_submission = view
        .derived
        .iter()
        .map(|derived| (derived.submission_id, derived))
        .collect::<BTreeMap<_, _>>();
    let existing_labels = if target_use.is_some() {
        read_ranking_labels_for_admin(state, tenant)
            .await
            .map_err(internal_error)?
    } else {
        Vec::new()
    };
    let external_evaluator = state.process_evaluator.clone();
    let initial_pending_count = view
        .records
        .iter()
        .filter(|record| {
            process_evaluation_worker_source_is_pending(
                record,
                derived_by_submission.get(&record.submission_id).copied(),
                &ProcessEvaluationWorkerPendingContext {
                    tenant,
                    tenant_policy: tenant_policy.as_ref(),
                    target_use,
                    utility_category,
                    external_ref_prefix: external_ref_prefix.as_deref(),
                    existing_labels: &existing_labels,
                },
            )
        })
        .count();
    let ranking_worker_run_id = Uuid::new_v4();
    let mut response = ProcessEvaluationWorkerRunResponse {
        ranking_worker_run_id,
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        dry_run,
        limit,
        evaluator_ref: evaluator_ref.clone(),
        target_use,
        utility_category,
        reason_hash: sha256_prefixed(&reason),
        checked_count: 0,
        evaluated_count: 0,
        ranking_label_appended_count: 0,
        ranking_label_skipped_existing_count: 0,
        skipped_existing_count: 0,
        skipped_ineligible_count: 0,
        pending_after_count: initial_pending_count,
        evaluated_submission_ids: Vec::new(),
        skipped_reason_counts: BTreeMap::new(),
    };
    let mut worker_run = TraceRankingWorkerRunRecord {
        ranking_worker_run_id,
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        run_kind: TraceRankingWorkerRunKind::ProcessEvaluation,
        status: TraceRankingWorkerRunStatus::Running,
        dry_run: response.dry_run,
        reason_hash: response.reason_hash.clone(),
        model_version: None,
        target_use: response.target_use,
        policy_version: None,
        limit: response.limit,
        checked_count: 0,
        succeeded_count: 0,
        skipped_existing_count: 0,
        skipped_model_risk_count: 0,
        skipped_ineligible_count: 0,
        pending_after_count: 0,
        result_refs: Vec::new(),
        reason_counts: BTreeMap::new(),
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
        completed_at: None,
        last_error_hash: None,
    };
    append_ranking_worker_run_with_db_mirror(state, tenant, &worker_run)
        .await
        .map_err(internal_error)?;
    let mut result_refs = Vec::new();

    for record in view.records.iter().take(limit) {
        response.checked_count += 1;
        let Some(derived) = derived_by_submission.get(&record.submission_id).copied() else {
            response.skipped_ineligible_count += 1;
            increment_count(
                &mut response.skipped_reason_counts,
                "missing_derived_summary",
            );
            continue;
        };
        if record.status != TraceCorpusStatus::Accepted {
            response.skipped_ineligible_count += 1;
            increment_count(&mut response.skipped_reason_counts, "source_not_accepted");
            continue;
        }
        if !record_matches_export_policy_abac(
            record,
            tenant,
            tenant_policy.as_ref(),
            TraceAllowedUse::Evaluation,
        ) {
            response.skipped_ineligible_count += 1;
            increment_count(
                &mut response.skipped_reason_counts,
                "evaluation_use_not_allowed",
            );
            continue;
        }
        if let Some(target_use) = target_use {
            if !record_matches_export_policy_abac(
                record,
                tenant,
                tenant_policy.as_ref(),
                target_use,
            ) {
                response.skipped_ineligible_count += 1;
                increment_count(
                    &mut response.skipped_reason_counts,
                    "ranking_target_use_not_allowed",
                );
                continue;
            }
            if process_evaluation_worker_existing_ranking_label(
                record,
                target_use,
                utility_category.ok_or_else(|| {
                    internal_error(anyhow::anyhow!(
                        "process evaluation worker target use missing utility category"
                    ))
                })?,
                external_ref_prefix.as_deref().ok_or_else(|| {
                    internal_error(anyhow::anyhow!(
                        "process evaluation worker target use missing external ref prefix"
                    ))
                })?,
                &existing_labels,
            ) {
                response.skipped_existing_count += 1;
                increment_count(&mut response.skipped_reason_counts, "ranking_label_exists");
                continue;
            }
        }
        if dry_run && external_evaluator.is_some() {
            response.skipped_ineligible_count += 1;
            increment_count(
                &mut response.skipped_reason_counts,
                "external_evaluator_dry_run",
            );
            continue;
        }

        let candidate = process_evaluator_candidate_from_records(0, record, derived);
        let decision = if let Some(evaluator) = external_evaluator.as_ref() {
            let evaluator_request = TraceProcessEvaluatorRequest {
                tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
                evaluator_ref: evaluator_ref.clone(),
                target_use,
                purpose_hash: sha256_prefixed(&reason),
                candidate_count: 1,
                candidate,
            };
            match evaluator.evaluate(evaluator_request).await {
                Ok(evaluator_response) => {
                    match process_evaluation_worker_decision_from_external_response(
                        evaluator_response,
                        &evaluator_ref,
                        target_use,
                    ) {
                        Ok(decision) => decision,
                        Err(error) => {
                            tracing::warn!(
                                error_hash = %safe_display_error_hash(&error),
                                submission_id = %record.submission_id,
                                "Trace Commons process evaluator response was rejected"
                            );
                            response.skipped_ineligible_count += 1;
                            increment_count(
                                &mut response.skipped_reason_counts,
                                "evaluator_adapter_error",
                            );
                            continue;
                        }
                    }
                }
                Err(error) => {
                    tracing::warn!(
                        error_hash = %safe_display_error_hash(&error),
                        submission_id = %record.submission_id,
                        "Trace Commons process evaluator call failed"
                    );
                    response.skipped_ineligible_count += 1;
                    increment_count(
                        &mut response.skipped_reason_counts,
                        "evaluator_adapter_error",
                    );
                    continue;
                }
            }
        } else {
            evaluate_process_candidate_structurally(&evaluator_ref, target_use, derived, record)
        };

        if !dry_run {
            let ranking_label = if let Some(target_use) = target_use {
                let ranking_decision = decision.ranking_label.ok_or_else(|| {
                    internal_error(anyhow::anyhow!(
                        "process evaluation worker target use decision missing ranking label"
                    ))
                })?;
                let utility_category = utility_category.ok_or_else(|| {
                    internal_error(anyhow::anyhow!(
                        "process evaluation worker target use missing utility category"
                    ))
                })?;
                let external_ref_prefix = external_ref_prefix.as_deref().ok_or_else(|| {
                    internal_error(anyhow::anyhow!(
                        "process evaluation worker target use missing external ref prefix"
                    ))
                })?;
                Some(TraceProcessEvaluationRankingLabelRequest {
                    target_use,
                    label_source: StorageTraceRankingLabelSource::System,
                    utility_category,
                    label_outcome: ranking_decision.label_outcome,
                    utility_delta_micros: ranking_decision.utility_delta_micros,
                    external_ref: process_evaluation_worker_external_ref(
                        external_ref_prefix,
                        record.submission_id,
                    ),
                })
            } else {
                None
            };
            let job_response = run_process_evaluation_job(
                state,
                tenant,
                TraceProcessEvaluationJobRequest {
                    submission_id: record.submission_id,
                    process_evaluation: decision.process_evaluation,
                    reason: reason.clone(),
                    utility_credit_points_delta: None,
                    utility_external_ref: None,
                    ranking_label,
                },
            )
            .await
            .inspect_err(|_| {
                update_process_evaluation_worker_run_from_response(
                    &mut worker_run,
                    &response,
                    &result_refs,
                );
            });
            let job_response = match job_response {
                Ok(job_response) => job_response,
                Err(error) => {
                    let public_error = error.1.0.error.clone();
                    finalize_failed_ranking_worker_run_with_db_mirror(
                        state,
                        tenant,
                        &mut worker_run,
                        error.0,
                        &public_error,
                    )
                    .await?;
                    return Err(error);
                }
            };
            response.ranking_label_appended_count += job_response.ranking_label_appended_count;
            response.ranking_label_skipped_existing_count +=
                job_response.ranking_label_skipped_existing_count;
            result_refs.push(process_evaluation_worker_result_ref(record.submission_id));
        }
        response.evaluated_count += 1;
        response.evaluated_submission_ids.push(record.submission_id);
    }
    if !dry_run {
        response.pending_after_count =
            initial_pending_count.saturating_sub(response.evaluated_count);
    }
    update_process_evaluation_worker_run_from_response(&mut worker_run, &response, &result_refs);
    worker_run.status = TraceRankingWorkerRunStatus::Completed;
    worker_run.completed_at = Some(Utc::now());
    append_ranking_worker_run_with_db_mirror(state, tenant, &worker_run)
        .await
        .map_err(internal_error)?;
    Ok(response)
}

fn process_evaluation_worker_result_ref(submission_id: Uuid) -> String {
    format!(
        "trace_submission_hash:{}",
        sha256_prefixed(&submission_id.to_string())
    )
}

fn validate_process_evaluation_worker_run_limit(limit: Option<usize>) -> ApiResult<usize> {
    let limit = limit.unwrap_or(TRACE_PROCESS_EVALUATION_WORKER_RUN_DEFAULT_LIMIT);
    if !(1..=TRACE_PROCESS_EVALUATION_WORKER_RUN_MAX_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "process evaluation worker run limit must be between 1 and 100",
        ));
    }
    Ok(limit)
}

fn normalize_process_evaluation_worker_evaluator_ref(value: Option<String>) -> ApiResult<String> {
    let Some(value) = value
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
    else {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "process evaluation worker run requires evaluator_ref",
        ));
    };
    if value.len() > 512 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "process evaluation worker run evaluator_ref is too long",
        ));
    }
    Ok(value)
}

fn normalize_process_evaluation_worker_reason(value: Option<String>) -> ApiResult<String> {
    let Some(value) = value
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
    else {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "process evaluation worker run requires reason",
        ));
    };
    if value.len() > 1024 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "process evaluation worker run reason is too long",
        ));
    }
    Ok(value)
}

fn normalize_process_evaluation_external_ref_prefix(value: Option<String>) -> ApiResult<String> {
    let Some(value) = value
        .map(|value| value.trim().trim_end_matches(':').to_string())
        .filter(|value| !value.is_empty())
    else {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "process evaluation worker run requires external_ref_prefix for ranking labels",
        ));
    };
    if value.len() > 512 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "process evaluation worker run external_ref_prefix is too long",
        ));
    }
    Ok(value)
}

fn process_evaluation_worker_external_ref(prefix: &str, submission_id: Uuid) -> String {
    format!("{prefix}:{submission_id}")
}

fn process_evaluation_worker_existing_ranking_label(
    record: &TraceCommonsSubmissionRecord,
    target_use: TraceAllowedUse,
    utility_category: StorageTraceRankingUtilityCategory,
    external_ref_prefix: &str,
    existing_labels: &[TraceRankingLabelRecord],
) -> bool {
    let external_ref_hash = sha256_prefixed(&process_evaluation_worker_external_ref(
        external_ref_prefix,
        record.submission_id,
    ));
    existing_labels.iter().any(|label| {
        label.submission_id == record.submission_id
            && label.target_use == target_use
            && label.label_source == StorageTraceRankingLabelSource::System
            && label.utility_category == utility_category
            && label.external_ref_hash == external_ref_hash
    })
}

struct ProcessEvaluationWorkerPendingContext<'a> {
    tenant: &'a TenantAuth,
    tenant_policy: Option<&'a TenantSubmissionPolicy>,
    target_use: Option<TraceAllowedUse>,
    utility_category: Option<StorageTraceRankingUtilityCategory>,
    external_ref_prefix: Option<&'a str>,
    existing_labels: &'a [TraceRankingLabelRecord],
}

fn process_evaluation_worker_source_is_pending(
    record: &TraceCommonsSubmissionRecord,
    derived: Option<&TraceCommonsDerivedRecord>,
    context: &ProcessEvaluationWorkerPendingContext<'_>,
) -> bool {
    if record.status != TraceCorpusStatus::Accepted || derived.is_none() {
        return false;
    }
    if !record_matches_export_policy_abac(
        record,
        context.tenant,
        context.tenant_policy,
        TraceAllowedUse::Evaluation,
    ) {
        return false;
    }
    let Some(target_use) = context.target_use else {
        return true;
    };
    if !record_matches_export_policy_abac(record, context.tenant, context.tenant_policy, target_use)
    {
        return false;
    }
    let (Some(utility_category), Some(external_ref_prefix)) =
        (context.utility_category, context.external_ref_prefix)
    else {
        return false;
    };
    !process_evaluation_worker_existing_ranking_label(
        record,
        target_use,
        utility_category,
        external_ref_prefix,
        context.existing_labels,
    )
}

fn process_evaluator_candidate_from_records(
    candidate_index: usize,
    record: &TraceCommonsSubmissionRecord,
    derived: &TraceCommonsDerivedRecord,
) -> TraceProcessEvaluatorCandidate {
    TraceProcessEvaluatorCandidate {
        candidate_index,
        submission_id_hash: sha256_prefixed(&record.submission_id.to_string()),
        trace_id_hash: sha256_prefixed(&record.trace_id.to_string()),
        canonical_summary_hash: derived.canonical_summary_hash.clone(),
        canonical_summary: derived.canonical_summary.clone(),
        summary_model: derived.summary_model.clone(),
        task_success: derived.task_success.clone(),
        event_count: derived.event_count,
        tool_sequence: derived.tool_sequence.clone(),
        tool_categories: derived.tool_categories.clone(),
        coverage_tags: derived.coverage_tags.clone(),
        novelty_score: derived.novelty_score,
        duplicate_score: derived.duplicate_score,
        submission_score: record.submission_score,
        consent_scopes: record.consent_scopes.clone(),
    }
}

struct ProcessEvaluationWorkerDecision {
    process_evaluation: ProcessEvaluationLabels,
    ranking_label: Option<TraceProcessEvaluatorRankingLabelDecision>,
}

fn process_evaluation_worker_decision_from_external_response(
    response: TraceProcessEvaluatorResponse,
    evaluator_ref: &str,
    target_use: Option<TraceAllowedUse>,
) -> anyhow::Result<ProcessEvaluationWorkerDecision> {
    let mut process_evaluation = response.process_evaluation;
    if process_evaluation.evaluator_version.trim().is_empty() {
        process_evaluation.evaluator_version = evaluator_ref.to_string();
    }
    if let Some(score) = process_evaluation.overall_score {
        anyhow::ensure!(
            score.is_finite() && (0.0..=1.0).contains(&score),
            "process evaluator overall_score must be between 0 and 1"
        );
    }
    if target_use.is_some() {
        anyhow::ensure!(
            response.ranking_label.is_some(),
            "process evaluator response requires ranking_label for ranking target runs"
        );
    }
    Ok(ProcessEvaluationWorkerDecision {
        process_evaluation,
        ranking_label: response.ranking_label,
    })
}

fn evaluate_process_candidate_structurally(
    evaluator_ref: &str,
    target_use: Option<TraceAllowedUse>,
    derived: &TraceCommonsDerivedRecord,
    record: &TraceCommonsSubmissionRecord,
) -> ProcessEvaluationWorkerDecision {
    let score = if record.submission_score.is_finite() {
        record.submission_score.clamp(0.0, 1.0)
    } else {
        0.0
    };
    ProcessEvaluationWorkerDecision {
        process_evaluation: ProcessEvaluationLabels {
            evaluator_name: Some("structural-process-evaluator".to_string()),
            evaluator_version: evaluator_ref.to_string(),
            verification: Some(if derived.event_count > 0 {
                ProcessEvalRating::Pass
            } else {
                ProcessEvalRating::Fail
            }),
            overall_score: Some(score),
            ..ProcessEvaluationLabels::default()
        },
        ranking_label: target_use.map(|_| TraceProcessEvaluatorRankingLabelDecision {
            label_outcome: if score >= 0.5 {
                StorageTraceRankingLabelOutcome::Useful
            } else {
                StorageTraceRankingLabelOutcome::Neutral
            },
            utility_delta_micros: (score * 1_000_000.0).round() as i64,
        }),
    }
}

#[derive(Default)]
struct ProcessEvaluationRankingLabelAppendCounts {
    appended: usize,
    skipped_existing: usize,
}

struct ProcessEvaluationRankingLabelPlan {
    evidence_hash: String,
    external_ref_hash: String,
    skipped_existing: bool,
}

fn validate_process_evaluation_ranking_label_external_ref(value: &str) -> ApiResult<String> {
    let value = value.trim();
    if value.is_empty() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "process evaluation ranking label requires a non-empty external_ref",
        ));
    }
    if value.len() > 1024 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "process evaluation ranking label external_ref is too long",
        ));
    }
    Ok(value.to_string())
}

async fn prepare_process_evaluation_ranking_label(
    state: &AppState,
    tenant: &TenantAuth,
    record: &TraceCommonsSubmissionRecord,
    process_evaluation: &ProcessEvaluationLabels,
    request: &TraceProcessEvaluationRankingLabelRequest,
    external_ref: &str,
) -> ApiResult<ProcessEvaluationRankingLabelPlan> {
    let evidence_hash = process_evaluation_ranking_label_evidence_hash(process_evaluation, request);
    let external_ref_hash = sha256_prefixed(external_ref);
    let existing_labels = read_ranking_labels_for_admin(state, tenant)
        .await
        .map_err(internal_error)?;
    if let Some(existing) = existing_labels.iter().find(|label| {
        label.submission_id == record.submission_id
            && label.target_use == request.target_use
            && label.label_source == request.label_source
            && label.utility_category == request.utility_category
            && label.external_ref_hash == external_ref_hash
    }) {
        if existing.label_outcome == request.label_outcome
            && existing.utility_delta_micros == request.utility_delta_micros
            && existing.evidence_hash == evidence_hash
        {
            return Ok(ProcessEvaluationRankingLabelPlan {
                evidence_hash,
                external_ref_hash,
                skipped_existing: true,
            });
        }
        return Err(api_error(
            StatusCode::CONFLICT,
            "process evaluation ranking label external_ref already exists with different evidence",
        ));
    }
    Ok(ProcessEvaluationRankingLabelPlan {
        evidence_hash,
        external_ref_hash,
        skipped_existing: false,
    })
}

async fn append_process_evaluation_ranking_label_once(
    state: &AppState,
    tenant: &TenantAuth,
    record: &TraceCommonsSubmissionRecord,
    request: &TraceProcessEvaluationRankingLabelRequest,
    plan: &ProcessEvaluationRankingLabelPlan,
) -> ApiResult<ProcessEvaluationRankingLabelAppendCounts> {
    if plan.skipped_existing {
        return Ok(ProcessEvaluationRankingLabelAppendCounts {
            appended: 0,
            skipped_existing: 1,
        });
    }

    append_ranking_label_with_db_mirror(
        state,
        tenant,
        &TraceRankingLabelRecord {
            ranking_label_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            submission_id: record.submission_id,
            trace_id: record.trace_id,
            target_use: request.target_use,
            label_source: request.label_source,
            utility_category: request.utility_category,
            label_outcome: request.label_outcome,
            utility_delta_micros: request.utility_delta_micros,
            evidence_hash: plan.evidence_hash.clone(),
            external_ref_hash: plan.external_ref_hash.clone(),
            actor_principal_ref: tenant.principal_ref.clone(),
            created_at: Utc::now(),
        },
    )
    .await
    .map_err(internal_error)?;

    Ok(ProcessEvaluationRankingLabelAppendCounts {
        appended: 1,
        skipped_existing: 0,
    })
}

fn process_evaluation_ranking_label_evidence_hash(
    process_evaluation: &ProcessEvaluationLabels,
    request: &TraceProcessEvaluationRankingLabelRequest,
) -> String {
    let mut labels = process_evaluation
        .labels
        .iter()
        .map(serde_enum_tag)
        .collect::<Vec<_>>();
    labels.sort();
    let payload = format!(
        "process_evaluation_ranking_label:v1\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{:?}\n{:?}\n{:?}\n{:?}\n{:?}",
        process_evaluation
            .evaluator_name
            .as_deref()
            .map(str::trim)
            .unwrap_or_default(),
        process_evaluation.evaluator_version.trim(),
        labels.join(","),
        serde_enum_tag(&request.target_use),
        serde_enum_tag(&request.label_source),
        serde_enum_tag(&request.utility_category),
        serde_enum_tag(&request.label_outcome),
        request.utility_delta_micros,
        process_evaluation
            .overall_score
            .map(|score| format!("{score:.6}"))
            .unwrap_or_default(),
        process_evaluation.tool_selection,
        process_evaluation.tool_argument_quality,
        process_evaluation.tool_ordering,
        process_evaluation.verification,
        process_evaluation.side_effect_safety,
    );
    sha256_prefixed(&payload)
}

fn process_evaluation_audit_metadata(
    process_evaluation: Option<&ProcessEvaluationLabels>,
    utility_credit_request: Option<&(f32, String)>,
) -> StorageTraceAuditSafeMetadata {
    let Some(process_evaluation) = process_evaluation else {
        return StorageTraceAuditSafeMetadata::Empty;
    };
    let mut rating_counts = BTreeMap::<String, u32>::new();
    for rating in [
        process_evaluation.tool_selection,
        process_evaluation.tool_argument_quality,
        process_evaluation.tool_ordering,
        process_evaluation.verification,
        process_evaluation.side_effect_safety,
    ]
    .into_iter()
    .flatten()
    {
        *rating_counts.entry(serde_enum_tag(&rating)).or_insert(0) += 1;
    }
    StorageTraceAuditSafeMetadata::ProcessEvaluation {
        evaluator_version_hash: sha256_prefixed(process_evaluation.evaluator_version.trim()),
        label_count: process_evaluation.labels.len().min(u32::MAX as usize) as u32,
        rating_counts,
        score_band: process_evaluation
            .overall_score
            .map(process_eval_score_band)
            .map(ToOwned::to_owned),
        utility_credit_delta_micros: utility_credit_request
            .map(|(points_delta, _)| credit_delta_micros(*points_delta)),
        utility_external_ref_hash: utility_credit_request
            .map(|(_, external_ref)| sha256_prefixed(external_ref)),
    }
}

