struct AutomaticUtilityCreditConfig {
    idempotency_label: &'static str,
    idempotency_ref: Option<String>,
    event_type: TraceCreditLedgerEventType,
    credit_points_delta: f32,
    reason: String,
    external_ref: String,
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
struct AutomaticUtilityCreditAppendCounts {
    appended: usize,
    skipped_existing: usize,
}

async fn append_automatic_utility_credit_events_once(
    state: &AppState,
    tenant: &TenantAuth,
    config: AutomaticUtilityCreditConfig,
    sources: impl IntoIterator<Item = AutomaticUtilityCreditSource>,
) -> ApiResult<usize> {
    Ok(
        append_automatic_utility_credit_events_once_with_counts(state, tenant, config, sources)
            .await?
            .appended,
    )
}

async fn append_automatic_utility_credit_events_once_with_counts(
    state: &AppState,
    tenant: &TenantAuth,
    config: AutomaticUtilityCreditConfig,
    sources: impl IntoIterator<Item = AutomaticUtilityCreditSource>,
) -> ApiResult<AutomaticUtilityCreditAppendCounts> {
    require_positive_credit_issuance_principal_if_configured(
        state,
        tenant,
        config.credit_points_delta,
    )?;
    let mut existing_event_ids = read_all_credit_events(&state.root, &tenant.tenant_id)
        .map_err(internal_error)?
        .into_iter()
        .map(|event| event.event_id)
        .collect::<BTreeSet<_>>();
    let mut counts = AutomaticUtilityCreditAppendCounts::default();
    for source in sources {
        let event_id = if let Some(idempotency_ref) = config.idempotency_ref.as_ref() {
            deterministic_trace_uuid_for_external_ref(
                config.idempotency_label,
                &tenant.tenant_id,
                source.submission_id,
                idempotency_ref,
            )
        } else {
            deterministic_trace_uuid_for(
                config.idempotency_label,
                &tenant.tenant_id,
                source.submission_id,
            )
        };
        if existing_event_ids.contains(&event_id) {
            counts.skipped_existing += 1;
            continue;
        }
        let event = TraceCommonsCreditLedgerRecord {
            event_id,
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            submission_id: source.submission_id,
            trace_id: source.trace_id,
            auth_principal_ref: source.auth_principal_ref,
            event_type: config.event_type,
            credit_points_delta: config.credit_points_delta,
            reason: Some(config.reason.clone()),
            external_ref: Some(config.external_ref.clone()),
            actor_role: tenant.role,
            actor_principal_ref: tenant.principal_ref.clone(),
            created_at: Utc::now(),
        };
        append_credit_event(&state.root, &tenant.tenant_id, &event).map_err(internal_error)?;
        let mirror_result = mirror_credit_event_to_db(state, &event).await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_runtime_error_hash(error),
                submission_id = %event.submission_id,
                "Trace Commons DB dual-write automatic credit mirror failed"
            );
        }
        enforce_db_mirror_write_result(state, "automatic credit ledger event", mirror_result)
            .map_err(internal_error)?;
        append_audit_event_with_db_mirror(
            state,
            tenant,
            TraceCommonsAuditEvent::credit_mutation(
                tenant,
                event.submission_id,
                config.credit_points_delta,
                event.reason.as_deref(),
            ),
            StorageTraceAuditAction::CreditMutate,
            StorageTraceAuditSafeMetadata::CreditMutation {
                event_type: storage_credit_event_type(config.event_type),
                credit_points_delta_micros: credit_delta_micros(config.credit_points_delta),
                reason_hash: sha256_prefixed(event.reason.as_deref().unwrap_or_default()),
                external_ref_hash: event.external_ref.as_deref().map(sha256_prefixed),
            },
        )
        .await
        .map_err(internal_error)?;
        existing_event_ids.insert(event_id);
        counts.appended += 1;
    }
    Ok(counts)
}

async fn review_decision_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    AxumPath(submission_id): AxumPath<Uuid>,
    Json(body): Json<TraceReviewDecisionRequest>,
) -> ApiResult<Json<TraceSubmissionReceipt>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(&tenant)?;
    let reason = validate_review_decision_reason(body.reason.as_deref())?;
    let receipt =
        apply_review_decision(state.as_ref(), &tenant, submission_id, &body, &reason).await?;
    Ok(Json(receipt))
}

async fn review_batch_decision_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceReviewBatchDecisionRequest>,
) -> ApiResult<Json<TraceReviewBatchDecisionResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(&tenant)?;
    validate_review_batch_decision_submission_ids(&body.submission_ids)?;
    let reason = validate_review_decision_reason(body.reason.as_deref())?;
    let decision = TraceReviewDecisionRequest {
        decision: body.decision,
        reason: Some(reason.clone()),
        credit_points_pending: body.credit_points_pending,
    };
    let mut decisions = Vec::with_capacity(body.submission_ids.len());
    for submission_id in body.submission_ids {
        match apply_review_decision(state.as_ref(), &tenant, submission_id, &decision, &reason)
            .await
        {
            Ok(receipt) => decisions.push(TraceReviewBatchDecisionItem::decided(
                submission_id,
                receipt,
            )),
            Err((status, Json(error))) => {
                decisions.push(TraceReviewBatchDecisionItem::failed(
                    submission_id,
                    status,
                    error.error,
                ));
            }
        }
    }
    Ok(Json(TraceReviewBatchDecisionResponse::new(decisions)))
}

fn validate_review_decision_reason(reason: Option<&str>) -> ApiResult<String> {
    let reason = reason
        .map(str::trim)
        .filter(|reason| !reason.is_empty())
        .ok_or_else(|| {
            api_error(
                StatusCode::BAD_REQUEST,
                "review decisions require a non-empty reason",
            )
        })?
        .to_string();
    Ok(reason)
}

fn validate_review_batch_decision_submission_ids(submission_ids: &[Uuid]) -> ApiResult<()> {
    if submission_ids.is_empty() || submission_ids.len() > 50 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "review batch decisions require between 1 and 50 submission ids",
        ));
    }
    let mut seen = BTreeSet::new();
    if submission_ids
        .iter()
        .any(|submission_id| !seen.insert(*submission_id))
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "review batch decisions require unique submission ids",
        ));
    }
    Ok(())
}

async fn apply_review_decision(
    state: &AppState,
    tenant: &TenantAuth,
    submission_id: Uuid,
    body: &TraceReviewDecisionRequest,
    reason: &str,
) -> ApiResult<TraceSubmissionReceipt> {
    let ReviewDecisionRecord {
        mut record,
        mut canonical_summary_hash,
        file_record_available,
        allow_file_body_fallback,
    } = read_review_decision_record(state, tenant, submission_id)
        .await
        .map_err(internal_error)?
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "trace submission not found"))?;
    let now = Utc::now();
    ensure_review_decision_eligible(state, &record, body.decision, now)?;
    if review_lease_held_by_other(&record, tenant, now) {
        return Err(api_error(
            StatusCode::CONFLICT,
            "trace review lease is held by another reviewer",
        ));
    }
    let privileged_policy =
        tenant_privileged_action_policy_for_request(state, tenant, "review decision").await?;
    ensure_record_matches_privileged_action_policy_abac(
        &record,
        tenant,
        privileged_policy.as_ref(),
        "review decision",
    )?;
    if state.require_db_mirror_writes {
        enforce_db_mirror_write_result(state, "review decision", Ok(())).map_err(internal_error)?;
    }
    let mut envelope = read_envelope_for_review_decision(
        state,
        tenant,
        &record,
        allow_file_body_fallback,
        Some(reason),
    )
    .await
    .map_err(internal_error)?
    .envelope;

    match body.decision {
        TraceReviewDecision::Approve => {
            record.status = TraceCorpusStatus::Accepted;
            let pending_credit = body
                .credit_points_pending
                .unwrap_or_else(|| reviewer_credit_for_record(&record));
            record.credit_points_pending = pending_credit;
            record.credit_points_final = None;
            envelope.value.credit_points_pending = pending_credit;
            envelope.value.explanation =
                vec!["Approved after privacy review for the private redacted corpus.".to_string()];
            envelope.value_card.user_visible_explanation = envelope.value.explanation.clone();
            let stored = store_envelope(
                state,
                &tenant.tenant_id,
                TraceCorpusStatus::Accepted,
                "reviewed-envelope",
                &envelope,
            )
            .map_err(internal_error)?;
            record.object_key = stored.object_key;
            record.artifact_receipt = stored.artifact_receipt;
            record.artifact_object_store = stored.artifact_object_store;
        }
        TraceReviewDecision::Reject => {
            record.status = TraceCorpusStatus::Rejected;
            record.credit_points_pending = 0.0;
            record.credit_points_final = Some(0.0);
            envelope.value.credit_points_pending = 0.0;
            envelope.value.credit_points_final = Some(0.0);
            envelope.value.explanation =
                vec!["Rejected during privacy or quality review; no credit awarded.".to_string()];
            envelope.value_card.user_visible_explanation = envelope.value.explanation.clone();
            let stored = store_envelope(
                state,
                &tenant.tenant_id,
                TraceCorpusStatus::Rejected,
                "reviewed-envelope",
                &envelope,
            )
            .map_err(internal_error)?;
            record.object_key = stored.object_key;
            record.artifact_receipt = stored.artifact_receipt;
            record.artifact_object_store = stored.artifact_object_store;
        }
    }
    clear_review_lease_metadata(&mut record);

    let reviewed_derived = if let Some(mut derived) =
        read_derived_record(&state.root, &tenant.tenant_id, submission_id)
            .map_err(internal_error)?
    {
        derived.status = record.status;
        canonical_summary_hash = Some(derived.canonical_summary_hash.clone());
        Some(derived)
    } else {
        None
    };
    let audit_event =
        TraceCommonsAuditEvent::review_decision(tenant, submission_id, record.status, Some(reason));

    if state.require_db_mirror_writes {
        let mirror_result = mirror_review_decision_to_db(
            state,
            tenant,
            &record,
            &envelope,
            canonical_summary_hash.clone(),
        )
        .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_runtime_error_hash(error),
                %submission_id,
                "Trace Commons DB dual-write review mirror failed"
            );
            if let Err(cleanup_error) = delete_trace_objects_for_record(state, &record) {
                tracing::warn!(
                    error_hash = %safe_runtime_error_hash(&cleanup_error),
                    %submission_id,
                    "Trace Commons reviewed envelope cleanup failed after DB mirror failure"
                );
            }
        }
        enforce_db_mirror_write_result(state, "review decision", mirror_result)
            .map_err(internal_error)?;
    }

    if file_record_available {
        write_submission_record(&state.root, &record).map_err(internal_error)?;
    }
    if let Some(derived) = reviewed_derived.as_ref() {
        write_derived_record(&state.root, derived).map_err(internal_error)?;
    }
    append_audit_event(&state.root, &tenant.tenant_id, audit_event).map_err(internal_error)?;

    if !state.require_db_mirror_writes {
        let mirror_result =
            mirror_review_decision_to_db(state, tenant, &record, &envelope, canonical_summary_hash)
                .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_runtime_error_hash(error),
                %submission_id,
                "Trace Commons DB dual-write review mirror failed"
            );
        }
        enforce_db_mirror_write_result(state, "review decision", mirror_result)
            .map_err(internal_error)?;
    }

    Ok(receipt_from_record(&record))
}

fn ensure_review_decision_eligible(
    state: &AppState,
    record: &TraceCommonsSubmissionRecord,
    decision: TraceReviewDecision,
    now: DateTime<Utc>,
) -> ApiResult<()> {
    ensure_retention_metadata_within_server_policy(record).map_err(internal_error)?;
    if record.is_terminal() {
        return Err(api_error(
            StatusCode::CONFLICT,
            "terminal trace submissions are not eligible for review decisions",
        ));
    }
    if record.status != TraceCorpusStatus::Quarantined {
        return Err(api_error(
            StatusCode::CONFLICT,
            "only quarantined trace submissions are eligible for review decisions",
        ));
    }
    if record.is_expired_at(now)
        && !retention_policy_is_on_legal_hold(state, record).map_err(internal_error)?
    {
        return Err(api_error(
            StatusCode::CONFLICT,
            "expired trace submissions are not eligible for review decisions",
        ));
    }
    if matches!(decision, TraceReviewDecision::Approve)
        && !record.allowed_uses.iter().any(|allowed_use| {
            retention_policy_for_allowed_use(*allowed_use).allows_derived_artifacts
        })
    {
        return Err(api_error(
            StatusCode::CONFLICT,
            "trace retention policy does not permit review approval",
        ));
    }
    Ok(())
}

async fn claim_review_lease_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    AxumPath(submission_id): AxumPath<Uuid>,
    Json(body): Json<TraceReviewLeaseRequest>,
) -> ApiResult<Json<TraceReviewLeaseResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(&tenant)?;
    let db = require_db_reviewer_lease_store(state.as_ref(), &tenant)?;
    let ttl_seconds = validate_review_lease_ttl_seconds(body.lease_ttl_seconds)?;
    let now = Utc::now();
    let lease_expires_at = now + Duration::seconds(ttl_seconds);
    let claimed = db
        .claim_trace_review_lease(
            &tenant.tenant_id,
            submission_id,
            &tenant.principal_ref,
            lease_expires_at,
            body.review_due_at,
            now,
        )
        .await
        .map_err(internal_error)?;
    let Some(record) = claimed else {
        return review_lease_claim_conflict(state.as_ref(), &tenant, submission_id).await;
    };
    let record = trace_commons_record_from_storage_submission(record)
        .ok_or_else(|| {
            internal_error(anyhow::anyhow!(
                "review lease record has unsupported status"
            ))
        })?
        .map_err(internal_error)?;
    append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        TraceCommonsAuditEvent::review_lease(
            &tenant,
            submission_id,
            StorageTraceReviewLeaseAuditAction::Claim,
            record.review_lease_expires_at,
            record.review_due_at,
        ),
        StorageTraceAuditAction::Review,
        StorageTraceAuditSafeMetadata::ReviewLease {
            action: StorageTraceReviewLeaseAuditAction::Claim,
            lease_expires_at: record.review_lease_expires_at,
            review_due_at: record.review_due_at,
        },
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(TraceReviewLeaseResponse::from_record(&record)))
}

async fn claim_next_review_lease_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceReviewLeaseClaimNextRequest>,
) -> ApiResult<Json<TraceReviewLeaseResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(&tenant)?;
    let db = require_db_reviewer_lease_store(state.as_ref(), &tenant)?;
    let ttl_seconds = validate_review_lease_ttl_seconds(body.lease_ttl_seconds)?;
    let now = Utc::now();
    let lease_expires_at = now + Duration::seconds(ttl_seconds);
    let candidate_ids = prioritized_available_review_lease_candidates(
        state.as_ref(),
        &tenant,
        body.privacy_risk,
        now,
    )
    .await
    .map_err(internal_error)?;

    for submission_id in candidate_ids {
        let claimed = db
            .claim_trace_review_lease(
                &tenant.tenant_id,
                submission_id,
                &tenant.principal_ref,
                lease_expires_at,
                body.review_due_at,
                now,
            )
            .await
            .map_err(internal_error)?;
        let Some(record) = claimed else {
            continue;
        };
        let record = trace_commons_record_from_storage_submission(record)
            .ok_or_else(|| {
                internal_error(anyhow::anyhow!(
                    "review lease record has unsupported status"
                ))
            })?
            .map_err(internal_error)?;
        append_audit_event_with_db_mirror(
            state.as_ref(),
            &tenant,
            TraceCommonsAuditEvent::review_lease(
                &tenant,
                submission_id,
                StorageTraceReviewLeaseAuditAction::Claim,
                record.review_lease_expires_at,
                record.review_due_at,
            ),
            StorageTraceAuditAction::Review,
            StorageTraceAuditSafeMetadata::ReviewLease {
                action: StorageTraceReviewLeaseAuditAction::Claim,
                lease_expires_at: record.review_lease_expires_at,
                review_due_at: record.review_due_at,
            },
        )
        .await
        .map_err(internal_error)?;
        return Ok(Json(TraceReviewLeaseResponse::from_record(&record)));
    }

    Err(api_error(
        StatusCode::NOT_FOUND,
        "no available review lease to claim",
    ))
}

async fn claim_batch_review_lease_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Json(body): Json<TraceReviewLeaseClaimBatchRequest>,
) -> ApiResult<Json<TraceReviewLeaseBatchResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(&tenant)?;
    let db = require_db_reviewer_lease_store(state.as_ref(), &tenant)?;
    let limit = validate_review_lease_batch_limit(body.limit)?;
    let ttl_seconds = validate_review_lease_ttl_seconds(body.lease_ttl_seconds)?;
    let now = Utc::now();
    let lease_expires_at = now + Duration::seconds(ttl_seconds);
    let candidate_ids = prioritized_available_review_lease_candidates(
        state.as_ref(),
        &tenant,
        body.privacy_risk,
        now,
    )
    .await
    .map_err(internal_error)?;

    let mut claimed = Vec::new();
    for submission_id in candidate_ids {
        if claimed.len() >= limit {
            break;
        }
        let claimed_record = db
            .claim_trace_review_lease(
                &tenant.tenant_id,
                submission_id,
                &tenant.principal_ref,
                lease_expires_at,
                body.review_due_at,
                now,
            )
            .await
            .map_err(internal_error)?;
        let Some(record) = claimed_record else {
            continue;
        };
        let record = trace_commons_record_from_storage_submission(record)
            .ok_or_else(|| {
                internal_error(anyhow::anyhow!(
                    "review lease record has unsupported status"
                ))
            })?
            .map_err(internal_error)?;
        append_audit_event_with_db_mirror(
            state.as_ref(),
            &tenant,
            TraceCommonsAuditEvent::review_lease(
                &tenant,
                submission_id,
                StorageTraceReviewLeaseAuditAction::Claim,
                record.review_lease_expires_at,
                record.review_due_at,
            ),
            StorageTraceAuditAction::Review,
            StorageTraceAuditSafeMetadata::ReviewLease {
                action: StorageTraceReviewLeaseAuditAction::Claim,
                lease_expires_at: record.review_lease_expires_at,
                review_due_at: record.review_due_at,
            },
        )
        .await
        .map_err(internal_error)?;
        claimed.push(TraceReviewLeaseResponse::from_record(&record));
    }

    Ok(Json(TraceReviewLeaseBatchResponse::new(limit, claimed)))
}

async fn release_review_lease_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    AxumPath(submission_id): AxumPath<Uuid>,
) -> ApiResult<Json<TraceReviewLeaseResponse>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_reviewer(&tenant)?;
    let db = require_db_reviewer_lease_store(state.as_ref(), &tenant)?;
    let released = db
        .release_trace_review_lease(&tenant.tenant_id, submission_id, &tenant.principal_ref)
        .await
        .map_err(internal_error)?;
    let Some(record) = released else {
        return review_lease_release_conflict(state.as_ref(), &tenant, submission_id).await;
    };
    let record = trace_commons_record_from_storage_submission(record)
        .ok_or_else(|| {
            internal_error(anyhow::anyhow!(
                "review lease record has unsupported status"
            ))
        })?
        .map_err(internal_error)?;
    append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        TraceCommonsAuditEvent::review_lease(
            &tenant,
            submission_id,
            StorageTraceReviewLeaseAuditAction::Release,
            None,
            None,
        ),
        StorageTraceAuditAction::Review,
        StorageTraceAuditSafeMetadata::ReviewLease {
            action: StorageTraceReviewLeaseAuditAction::Release,
            lease_expires_at: None,
            review_due_at: None,
        },
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(TraceReviewLeaseResponse::from_record(&record)))
}

fn validate_review_lease_ttl_seconds(ttl_seconds: Option<i64>) -> ApiResult<i64> {
    let ttl_seconds = ttl_seconds.unwrap_or(DEFAULT_REVIEW_LEASE_TTL_SECONDS);
    if !(1..=MAX_REVIEW_LEASE_TTL_SECONDS).contains(&ttl_seconds) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "review lease ttl must be between 1 second and 24 hours",
        ));
    }
    Ok(ttl_seconds)
}

fn validate_review_lease_batch_limit(limit: Option<usize>) -> ApiResult<usize> {
    let limit = limit.unwrap_or(DEFAULT_REVIEW_LEASE_BATCH_LIMIT);
    if !(1..=MAX_REVIEW_LEASE_BATCH_LIMIT).contains(&limit) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "review lease batch limit must be between 1 and 50",
        ));
    }
    Ok(limit)
}

async fn prioritized_available_review_lease_candidates(
    state: &AppState,
    tenant: &TenantAuth,
    privacy_risk: Option<ResidualPiiRisk>,
    now: DateTime<Utc>,
) -> anyhow::Result<Vec<Uuid>> {
    let TraceCommonsMetadataView { records, .. } =
        read_reviewer_metadata_view(state, tenant).await?;
    let mut records = records
        .into_iter()
        .filter(|record| record.status == TraceCorpusStatus::Quarantined)
        .filter(|record| !record.is_revoked())
        .filter(|record| privacy_risk.is_none_or(|risk| record.privacy_risk == risk))
        .filter(|record| {
            trace_review_lease_filter_matches(
                record,
                &tenant.principal_ref,
                now,
                TraceReviewLeaseFilter::Available,
            )
        })
        .collect::<Vec<_>>();
    records.sort_by(|left, right| {
        let left_escalation = trace_review_escalation(left, now);
        let right_escalation = trace_review_escalation(right, now);
        right_escalation
            .state
            .rank()
            .cmp(&left_escalation.state.rank())
            .then_with(|| right_escalation.age_hours.cmp(&left_escalation.age_hours))
            .then_with(|| left.received_at.cmp(&right.received_at))
    });
    Ok(records
        .into_iter()
        .map(|record| record.submission_id)
        .collect())
}

fn require_db_reviewer_lease_store<'a>(
    state: &'a AppState,
    tenant: &TenantAuth,
) -> ApiResult<&'a dyn Database> {
    if !state.db_reviewer_reads_for_tenant(&tenant.tenant_id) {
        return Err(api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "review leases require TRACE_COMMONS_DB_REVIEWER_READS=true",
        ));
    }
    state.db_mirror.as_deref().ok_or_else(|| {
        api_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "review leases require a configured Trace Commons DB mirror",
        )
    })
}

async fn review_lease_claim_conflict(
    state: &AppState,
    tenant: &TenantAuth,
    submission_id: Uuid,
) -> ApiResult<Json<TraceReviewLeaseResponse>> {
    let record = read_reviewer_submission_record(state, tenant, submission_id)
        .await
        .map_err(internal_error)?
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "trace submission not found"))?;
    if record.status != TraceCorpusStatus::Quarantined {
        return Err(api_error(
            StatusCode::CONFLICT,
            "review leases can only be claimed for quarantined traces",
        ));
    }
    if review_lease_held_by_other(&record, tenant, Utc::now()) {
        return Err(api_error(
            StatusCode::CONFLICT,
            "trace review lease is held by another reviewer",
        ));
    }
    Err(api_error(
        StatusCode::CONFLICT,
        "trace review lease could not be claimed",
    ))
}

async fn review_lease_release_conflict(
    state: &AppState,
    tenant: &TenantAuth,
    submission_id: Uuid,
) -> ApiResult<Json<TraceReviewLeaseResponse>> {
    let record = read_reviewer_submission_record(state, tenant, submission_id)
        .await
        .map_err(internal_error)?
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "trace submission not found"))?;
    if record.status != TraceCorpusStatus::Quarantined {
        return Err(api_error(
            StatusCode::CONFLICT,
            "review leases can only be released for quarantined traces",
        ));
    }
    if review_lease_held_by_other(&record, tenant, Utc::now()) {
        return Err(api_error(
            StatusCode::CONFLICT,
            "trace review lease is held by another reviewer",
        ));
    }
    Err(api_error(
        StatusCode::CONFLICT,
        "no active review lease is owned by this reviewer",
    ))
}

fn review_lease_held_by_other(
    record: &TraceCommonsSubmissionRecord,
    tenant: &TenantAuth,
    now: DateTime<Utc>,
) -> bool {
    record
        .review_assigned_to_principal_ref
        .as_deref()
        .is_some_and(|assigned| {
            assigned != tenant.principal_ref
                && record
                    .review_lease_expires_at
                    .is_some_and(|expires_at| expires_at > now)
        })
}

fn clear_review_lease_metadata(record: &mut TraceCommonsSubmissionRecord) {
    record.review_assigned_to_principal_ref = None;
    record.review_assigned_at = None;
    record.review_lease_expires_at = None;
    record.review_due_at = None;
}

