async fn current_trace_export_job_or_claimed(
    db: &Arc<dyn Database>,
    claimed: StorageTraceExportJobRecord,
) -> ApiResult<StorageTraceExportJobRecord> {
    let tenant_id = claimed.tenant_id.clone();
    let export_job_id = claimed.export_job_id;
    let current = db
        .list_trace_export_jobs(&tenant_id)
        .await
        .map_err(internal_error)?
        .into_iter()
        .find(|job| job.export_job_id == export_job_id);
    Ok(match current {
        Some(record) => record,
        None => claimed,
    })
}

async fn count_pending_export_jobs(
    db: &Arc<dyn Database>,
    tenant_id: &str,
    requested_dataset_kind: Option<&str>,
    now: DateTime<Utc>,
) -> ApiResult<usize> {
    let jobs = db
        .list_trace_export_jobs(tenant_id)
        .await
        .map_err(internal_error)?;
    Ok(jobs
        .into_iter()
        .filter(|job| job.status == StorageTraceExportJobStatus::Queued && job.expires_at > now)
        .filter(|job| {
            requested_dataset_kind
                .is_none_or(|dataset_kind| job.requested_dataset_kind == dataset_kind)
        })
        .count())
}

async fn count_failed_export_jobs(
    db: &Arc<dyn Database>,
    tenant_id: &str,
    requested_dataset_kind: Option<&str>,
    now: DateTime<Utc>,
) -> ApiResult<usize> {
    let jobs = db
        .list_trace_export_jobs(tenant_id)
        .await
        .map_err(internal_error)?;
    Ok(jobs
        .into_iter()
        .filter(|job| job.status == StorageTraceExportJobStatus::Failed && job.expires_at > now)
        .filter(|job| {
            requested_dataset_kind
                .is_none_or(|dataset_kind| job.requested_dataset_kind == dataset_kind)
        })
        .count())
}

struct ClaimedExportJobExecution {
    replay_export: Option<TraceReplayDatasetExport>,
    benchmark_artifact: Option<TraceBenchmarkConversionArtifact>,
    ranker_candidate_export: Option<TraceRankerTrainingCandidateExport>,
    ranker_pair_export: Option<TraceRankerTrainingPairExport>,
}

async fn execute_claimed_export_job(
    state: &AppState,
    tenant: &TenantAuth,
    claimed: StorageTraceExportJobRecord,
) -> ApiResult<ClaimedExportJobExecution> {
    let job = export_job_slice_from_storage_record(claimed)?;
    match job.requested_dataset_kind {
        TraceExportDatasetKind::ReplayDataset => {
            let query = replay_export_query_from_claimed_job(&job)?;
            let (consent_scope, tenant_policy, purpose) =
                prepare_replay_export_execution(state, tenant, &query).await?;
            let Json(export) = run_dataset_replay_export_job(
                state,
                tenant,
                query,
                job,
                consent_scope,
                tenant_policy,
                purpose,
            )
            .await?;
            Ok(ClaimedExportJobExecution {
                replay_export: Some(export),
                benchmark_artifact: None,
                ranker_candidate_export: None,
                ranker_pair_export: None,
            })
        }
        TraceExportDatasetKind::BenchmarkConversion => {
            require_positive_credit_issuance_principal_if_configured(state, tenant, 1.0)?;
            let body = benchmark_conversion_request_from_claimed_job(&job)?;
            let (consent_scope, tenant_policy, purpose) =
                prepare_benchmark_conversion_execution(state, tenant, &body).await?;
            let Json(artifact) = run_benchmark_conversion_job(
                state,
                tenant,
                body,
                job,
                consent_scope,
                tenant_policy,
                purpose,
            )
            .await?;
            Ok(ClaimedExportJobExecution {
                replay_export: None,
                benchmark_artifact: Some(artifact),
                ranker_candidate_export: None,
                ranker_pair_export: None,
            })
        }
        TraceExportDatasetKind::RankerTrainingCandidates => {
            require_positive_credit_issuance_principal_if_configured(state, tenant, 1.0)?;
            let query = ranker_training_export_query_from_claimed_job(&job)?;
            let (consent_scope, tenant_policy, purpose) = prepare_ranker_training_export_execution(
                state,
                tenant,
                &query,
                "ranker training candidates",
                "ranker_training_candidates_export",
            )
            .await?;
            let Json(export) = run_ranker_training_candidates_export_job(
                state,
                tenant,
                query,
                job,
                consent_scope,
                tenant_policy,
                purpose,
            )
            .await?;
            Ok(ClaimedExportJobExecution {
                replay_export: None,
                benchmark_artifact: None,
                ranker_candidate_export: Some(export),
                ranker_pair_export: None,
            })
        }
        TraceExportDatasetKind::RankerTrainingPairs => {
            require_positive_credit_issuance_principal_if_configured(state, tenant, 1.0)?;
            let query = ranker_training_export_query_from_claimed_job(&job)?;
            let (consent_scope, tenant_policy, purpose) = prepare_ranker_training_export_execution(
                state,
                tenant,
                &query,
                "ranker training pairs",
                "ranker_training_pairs_export",
            )
            .await?;
            let Json(export) = run_ranker_training_pairs_export_job(
                state,
                tenant,
                query,
                job,
                consent_scope,
                tenant_policy,
                purpose,
            )
            .await?;
            Ok(ClaimedExportJobExecution {
                replay_export: None,
                benchmark_artifact: None,
                ranker_candidate_export: None,
                ranker_pair_export: Some(export),
            })
        }
    }
}

fn export_job_slice_from_storage_record(
    record: StorageTraceExportJobRecord,
) -> ApiResult<TraceExportJobSlice> {
    let requested_dataset_kind =
        trace_export_dataset_kind_from_storage_name(&record.requested_dataset_kind)?;
    let status = match record.status {
        StorageTraceExportJobStatus::Queued => TraceExportJobStatus::Pending,
        StorageTraceExportJobStatus::Running => TraceExportJobStatus::InProgress,
        StorageTraceExportJobStatus::Complete => TraceExportJobStatus::Completed,
        StorageTraceExportJobStatus::Failed => TraceExportJobStatus::Failed,
        StorageTraceExportJobStatus::Cancelled | StorageTraceExportJobStatus::Expired => {
            TraceExportJobStatus::Rejected
        }
    };
    if status != TraceExportJobStatus::InProgress {
        return Err(api_error(
            StatusCode::CONFLICT,
            "claimed export job must be running before execution",
        ));
    }
    let max_item_cap = record.max_item_cap.ok_or_else(|| {
        api_error(
            StatusCode::CONFLICT,
            "claimed export job is missing max_item_cap",
        )
    })?;
    Ok(TraceExportJobSlice {
        job_id: record.export_job_id,
        grant_id: record.grant_id,
        tenant_id: record.tenant_id,
        caller_principal_ref: record.caller_principal_ref,
        requested_dataset_kind,
        purpose: record.purpose,
        expires_at: record.expires_at,
        max_item_cap: max_item_cap as usize,
        status,
        requested_at: record.requested_at,
        started_at: record.started_at,
        finished_at: record.finished_at,
        metadata: record.metadata,
    })
}

fn trace_export_dataset_kind_from_storage_name(value: &str) -> ApiResult<TraceExportDatasetKind> {
    match normalized_export_dataset_kind_filter(value).as_str() {
        "replay_dataset" => Ok(TraceExportDatasetKind::ReplayDataset),
        "benchmark_conversion" => Ok(TraceExportDatasetKind::BenchmarkConversion),
        "ranker_training_candidates" => Ok(TraceExportDatasetKind::RankerTrainingCandidates),
        "ranker_training_pairs" => Ok(TraceExportDatasetKind::RankerTrainingPairs),
        _ => Err(api_error(
            StatusCode::BAD_REQUEST,
            format!("unsupported export dataset kind: {value}"),
        )),
    }
}

fn trace_export_dataset_kind_creates_positive_credit(kind: TraceExportDatasetKind) -> bool {
    matches!(
        kind,
        TraceExportDatasetKind::BenchmarkConversion
            | TraceExportDatasetKind::RankerTrainingCandidates
            | TraceExportDatasetKind::RankerTrainingPairs
    )
}

fn require_export_job_claim_central_issuer_if_configured(
    state: &AppState,
    tenant: &TenantAuth,
    dataset_kind: Option<TraceExportDatasetKind>,
) -> ApiResult<()> {
    if dataset_kind.is_none_or(trace_export_dataset_kind_creates_positive_credit) {
        require_positive_credit_issuance_principal_if_configured(state, tenant, 1.0)?;
    }
    Ok(())
}

fn replay_export_query_from_claimed_job(
    job: &TraceExportJobSlice,
) -> ApiResult<DatasetExportQuery> {
    if job
        .metadata
        .get("request_schema_version")
        .map(String::as_str)
        != Some("trace_export_job_request.v1")
    {
        return Err(api_error(
            StatusCode::CONFLICT,
            "claimed export job is missing replayable request metadata",
        ));
    }
    Ok(DatasetExportQuery {
        limit: Some(job.max_item_cap),
        purpose: Some(job.purpose.clone()),
        status: trace_export_job_metadata_filter(&job.metadata, "filter_status")?,
        privacy_risk: trace_export_job_metadata_filter(&job.metadata, "filter_privacy_risk")?,
        consent_scope: trace_export_job_metadata_string_filter(
            &job.metadata,
            "filter_consent_scope",
        ),
    })
}

