fn trace_export_job_metadata_filter<T>(
    metadata: &BTreeMap<String, String>,
    key: &str,
) -> ApiResult<Option<T>>
where
    T: for<'de> Deserialize<'de>,
{
    let Some(value) = trace_export_job_metadata_string_filter(metadata, key) else {
        return Ok(None);
    };
    serde_json::from_value(serde_json::Value::String(value.clone()))
        .map(Some)
        .map_err(|error| {
            api_error(
                StatusCode::CONFLICT,
                format!("claimed export job has invalid {key}: {error}"),
            )
        })
}

fn trace_export_job_metadata_string_filter(
    metadata: &BTreeMap<String, String>,
    key: &str,
) -> Option<String> {
    metadata
        .get(key)
        .map(String::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty() && *value != "any")
        .map(ToOwned::to_owned)
}

async fn mark_claimed_export_job_failed(
    state: &AppState,
    claimed: &StorageTraceExportJobRecord,
    error_message: &str,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    let mut metadata = claimed.metadata.clone();
    metadata.insert("state".to_string(), "failed".to_string());
    metadata.insert(
        "failure_reason_hash".to_string(),
        sha256_prefixed(error_message),
    );
    let last_error = anyhow::anyhow!(
        "queued_export_job_execution_failed;reason_hash={}",
        sha256_prefixed(error_message)
    );
    db.update_trace_export_job_status(
        &claimed.tenant_id,
        claimed.export_job_id,
        StorageTraceExportJobStatusUpdate {
            status: StorageTraceExportJobStatus::Failed,
            started_at: claimed.started_at,
            finished_at: Some(Utc::now()),
            result_manifest_id: None,
            item_count: None,
            last_error: Some(safe_worker_error(&last_error)),
            metadata,
        },
    )
    .await
    .context("failed to terminalize claimed export job after execution failure")?;
    Ok(())
}

async fn recover_stale_export_job_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    AxumPath(export_job_id): AxumPath<Uuid>,
    Json(body): Json<TraceExportJobRecoveryRequest>,
) -> ApiResult<Json<TraceExportJobSummary>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    let reason = validate_export_job_recovery_reason(&body.reason)?;
    let db = trace_export_control_db(state.as_ref())?;
    let jobs = db
        .list_trace_export_jobs(&tenant.tenant_id)
        .await
        .map_err(internal_error)?;
    let record = jobs
        .into_iter()
        .find(|job| job.export_job_id == export_job_id)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "export job not found"))?;
    if record.status != StorageTraceExportJobStatus::Running {
        return Err(api_error(StatusCode::CONFLICT, "export job is not running"));
    }
    let now = Utc::now();
    if record.expires_at > now {
        return Err(api_error(StatusCode::CONFLICT, "export job is not stale"));
    }

    let recovery_reason_hash = sha256_prefixed(&reason);
    let mut metadata = record.metadata.clone();
    metadata.insert("state".to_string(), "expired".to_string());
    metadata.insert(
        "recovery".to_string(),
        "stale_running_export_job".to_string(),
    );
    metadata.insert("reason_hash".to_string(), recovery_reason_hash.clone());
    let recovered = db
        .recover_stale_trace_export_job(
            &tenant.tenant_id,
            export_job_id,
            now,
            StorageTraceExportJobStatusUpdate {
                status: StorageTraceExportJobStatus::Expired,
                started_at: record.started_at,
                finished_at: Some(now),
                result_manifest_id: record.result_manifest_id,
                item_count: record.item_count,
                last_error: Some(export_job_recovery_last_error(&recovery_reason_hash)),
                metadata,
            },
        )
        .await
        .map_err(internal_error)?
        .ok_or_else(|| api_error(StatusCode::CONFLICT, "export job changed before recovery"))?;
    append_audit_event_with_db_mirror(
        state.as_ref(),
        &tenant,
        TraceCommonsAuditEvent::export_job_recovery(&tenant, &recovered, &recovery_reason_hash),
        StorageTraceAuditAction::ExportJobRecovery,
        export_job_recovery_audit_metadata(&recovered, &recovery_reason_hash),
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(TraceExportJobSummary::from_storage_record(recovered)))
}

async fn retry_export_job_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    AxumPath(export_job_id): AxumPath<Uuid>,
    Json(body): Json<TraceExportJobRetryRequest>,
) -> ApiResult<Json<TraceExportJobSummary>> {
    let tenant = authenticate_with_tenant_access_grant(state.as_ref(), &headers).await?;
    require_admin(&tenant)?;
    let reason = validate_export_job_retry_reason(&body.reason)?;
    let db = trace_export_control_db(state.as_ref())?;
    let jobs = db
        .list_trace_export_jobs(&tenant.tenant_id)
        .await
        .map_err(internal_error)?;
    let record = jobs
        .into_iter()
        .find(|job| job.export_job_id == export_job_id)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "export job not found"))?;
    let retried =
        retry_failed_export_job_record(state.as_ref(), &tenant, &db, record, &reason, Utc::now())
            .await?;
    Ok(Json(TraceExportJobSummary::from_storage_record(retried)))
}

async fn retry_failed_export_job_record(
    state: &AppState,
    tenant: &TenantAuth,
    db: &Arc<dyn Database>,
    record: StorageTraceExportJobRecord,
    reason: &str,
    now: DateTime<Utc>,
) -> ApiResult<StorageTraceExportJobRecord> {
    if record.status != StorageTraceExportJobStatus::Failed {
        return Err(api_error(StatusCode::CONFLICT, "export job is not failed"));
    }
    if record.expires_at <= now {
        return Err(api_error(
            StatusCode::CONFLICT,
            "export job grant has expired",
        ));
    }
    if !export_job_has_replayable_request_metadata(&record) {
        return Err(api_error(
            StatusCode::CONFLICT,
            "export job is missing replayable request metadata",
        ));
    }

    let retry_reason_hash = sha256_prefixed(reason);
    let retry_count = next_export_job_retry_count(&record.metadata);
    let mut metadata = record.metadata.clone();
    metadata.insert("state".to_string(), "queued".to_string());
    metadata.insert("retry_count".to_string(), retry_count.to_string());
    metadata.insert("retry_reason_hash".to_string(), retry_reason_hash.clone());
    metadata.insert("last_retried_at".to_string(), now.to_rfc3339());
    metadata.insert(
        "last_retried_by_principal_ref".to_string(),
        tenant.principal_ref.clone(),
    );
    metadata.remove("claimed_by_principal_ref");
    let retried = db
        .retry_failed_trace_export_job(
            &tenant.tenant_id,
            record.export_job_id,
            now,
            StorageTraceExportJobStatusUpdate {
                status: StorageTraceExportJobStatus::Queued,
                started_at: None,
                finished_at: None,
                result_manifest_id: None,
                item_count: None,
                last_error: None,
                metadata,
            },
        )
        .await
        .map_err(internal_error)?
        .ok_or_else(|| api_error(StatusCode::CONFLICT, "export job changed before retry"))?;
    append_audit_event_with_db_mirror(
        state,
        tenant,
        TraceCommonsAuditEvent::export_job_recovery(tenant, &retried, &retry_reason_hash),
        StorageTraceAuditAction::ExportJobRecovery,
        export_job_recovery_audit_metadata(&retried, &retry_reason_hash),
    )
    .await
    .map_err(internal_error)?;
    Ok(retried)
}

fn export_job_has_replayable_request_metadata(record: &StorageTraceExportJobRecord) -> bool {
    record
        .metadata
        .get("request_schema_version")
        .map(String::as_str)
        == Some("trace_export_job_request.v1")
}

