async fn read_trace_operational_summary(
    state: &AppState,
    tenant: &TenantCtx,
    generated_at: DateTime<Utc>,
) -> anyhow::Result<TraceOperationalSummaryResponse> {
    let TraceCommonsMetadataView { records, derived } =
        read_reviewer_metadata_view(state, tenant.auth()).await?;
    let credit_events = read_operational_credit_events(state, tenant.auth(), &records).await?;
    let credit_risk = build_credit_risk_summary(
        state,
        tenant.auth(),
        TRACE_CREDIT_RISK_SUMMARY_DEFAULT_ACCOUNT_LIMIT,
    )
    .await
    .map_err(|(status, Json(error))| {
        anyhow::anyhow!(
            "failed to build operational credit risk summary: status={}, error={}",
            status,
            error.error
        )
    })?;
    let credit_risk = TraceOperationalCreditRiskSummary::from_response(&credit_risk);
    let db_summary = read_operational_db_summary(state, tenant.auth()).await?;
    let ranking =
        read_operational_ranking_summary(state, tenant.auth(), &credit_events, generated_at)
            .await?;
    let benchmark_artifacts =
        list_benchmark_conversion_artifacts_for_worker(state, tenant.auth()).await?;
    let benchmark_registry_outbox =
        read_benchmark_registry_outbox_items_for_admin(state, tenant.auth()).await?;
    let near_credit_outbox = read_near_credit_outbox_items_for_admin(state, tenant.auth()).await?;
    let rollout_smoke_evidence =
        read_rollout_smoke_evidence_for_admin(state, tenant.auth()).await?;
    let revocation_propagation =
        read_revocation_propagation_summary_for_admin(state, tenant.auth()).await?;
    Ok(TraceOperationalSummaryResponse::from_parts(
        TraceOperationalSummaryInputs {
            state,
            tenant_id: tenant.tenant_id().to_string(),
            records,
            derived,
            credit_events,
            credit_risk,
            db_summary,
            benchmark_artifacts,
            benchmark_registry_outbox,
            near_credit_outbox,
            ranking,
            rollout_smoke_evidence,
            revocation_propagation,
            generated_at,
        },
    ))
}

