async fn run_canary_read_drill(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceCanaryReadDrillRequest,
) -> anyhow::Result<TraceCanaryReadDrillResponse> {
    let generated_at = Utc::now();
    let purpose = request
        .purpose
        .as_deref()
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .unwrap_or("trace_commons_canary_read_drill")
        .to_string();
    let submission_ref_hash = sha256_prefixed(&request.submission_id.to_string());
    let isolation_tenant_id = request
        .isolation_tenant_id
        .as_deref()
        .map(str::trim)
        .filter(|tenant_id| !tenant_id.is_empty());
    let isolation_tenant_storage_ref = isolation_tenant_id.map(tenant_storage_ref);
    let record = read_submission_record(&state.root, &tenant.tenant_id, request.submission_id)
        .with_context(|| {
            format!(
                "failed to read Trace Commons canary submission {}",
                request.submission_id
            )
        })?;

    let mut submit_status_visible = false;
    let mut contributor_credit_visible = false;
    let mut reviewer_metadata_visible = false;
    let mut replay_export_selection_visible = false;
    let mut tenant_canary_isolated = false;
    let mut audit_read_count = 0usize;

    if let Some(record) = record.as_ref() {
        ensure_retention_metadata_within_server_policy(record)?;
        let contributor_auth = canary_contributor_auth_from_record(record);
        let credit_view = read_contributor_credit_view(state, &contributor_auth).await?;
        let visible_status_record = credit_view
            .records
            .iter()
            .find(|candidate| candidate.submission_id == request.submission_id);
        if let Some(status_record) = visible_status_record {
            let status_credit_events = read_contributor_status_credit_events(
                state,
                &contributor_auth,
                &credit_view.records,
            )
            .await?;
            let status = submission_status_from_record(status_record, &status_credit_events);
            submit_status_visible = status.submission_id == request.submission_id
                && status.status == record.status.as_str();
        }
        contributor_credit_visible = visible_status_record.is_some();

        let TraceCommonsMetadataView { records, derived } =
            read_reviewer_metadata_view(state, tenant).await?;
        reviewer_metadata_visible = records
            .iter()
            .any(|candidate| candidate.submission_id == request.submission_id)
            && derived
                .iter()
                .any(|candidate| candidate.submission_id == request.submission_id);
        replay_export_selection_visible =
            canary_replay_export_selection_visible(state, tenant, request.submission_id).await?;
        audit_read_count = read_recent_audit_events(state, tenant, 100).await?.len();

        tenant_canary_isolated = canary_submission_is_isolated_from_tenant(
            state,
            request.submission_id,
            isolation_tenant_id,
        )
        .await?;
    }

    let mut response = TraceCanaryReadDrillResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        generated_at,
        purpose: purpose.clone(),
        ready: false,
        evidence_hash: String::new(),
        submission_ref_hash,
        isolation_tenant_storage_ref,
        canary_submission_found: record.is_some(),
        submit_status_visible,
        tenant_canary_isolated,
        contributor_credit_visible,
        reviewer_metadata_visible,
        replay_export_selection_visible,
        audit_read_count,
        blocking_gaps: Vec::new(),
        recorded_evidence: Vec::new(),
    };
    response.blocking_gaps = canary_read_drill_blocking_gaps(&response);
    response.ready = response.blocking_gaps.is_empty();
    response.evidence_hash = canary_read_drill_evidence_hash(tenant, &response);

    if request.record_evidence {
        for (check_name, passed) in canary_read_drill_check_statuses(&response) {
            let evidence = TraceRolloutSmokeEvidenceResponse {
                event_id: Uuid::new_v4(),
                tenant_id: tenant.tenant_id.clone(),
                tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
                check_name: check_name.to_string(),
                status: if passed {
                    TraceRolloutSmokeEvidenceStatus::Passed
                } else {
                    TraceRolloutSmokeEvidenceStatus::Failed
                },
                evidence_hash: canary_read_drill_check_evidence_hash(
                    tenant,
                    &response.evidence_hash,
                    check_name,
                    passed,
                ),
                evidence_ref_hash: Some(sha256_prefixed(&purpose)),
                actor_principal_ref: tenant.principal_ref.clone(),
                recorded_at: Utc::now(),
            };
            append_audit_event_with_db_mirror(
                state,
                tenant,
                TraceCommonsAuditEvent::rollout_smoke_evidence(&evidence),
                StorageTraceAuditAction::Read,
                StorageTraceAuditSafeMetadata::Empty,
            )
            .await?;
            response.recorded_evidence.push(evidence);
        }
    }

    Ok(response)
}

async fn run_object_primary_read_drill(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceObjectPrimaryReadDrillRequest,
) -> anyhow::Result<TraceObjectPrimaryReadDrillResponse> {
    let generated_at = Utc::now();
    let purpose = request
        .purpose
        .as_deref()
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .unwrap_or("trace_commons_object_primary_read_drill")
        .to_string();
    let submission_ref_hash = sha256_prefixed(&request.submission_id.to_string());
    let fallback_tenant_id = request
        .fallback_tenant_id
        .as_deref()
        .map(str::trim)
        .filter(|tenant_id| !tenant_id.is_empty());
    let fallback_tenant_storage_ref = fallback_tenant_id.map(tenant_storage_ref);
    let record = read_submission_record(&state.root, &tenant.tenant_id, request.submission_id)
        .with_context(|| {
            format!(
                "failed to read Trace Commons object-primary drill submission {}",
                request.submission_id
            )
        })?;

    let object_store_eligible = state
        .artifact_store
        .as_ref()
        .is_some_and(|store| store.object_primary_eligible());
    let object_primary_submit_review_enabled =
        state.object_primary_submit_review_for_tenant(&tenant.tenant_id);
    let object_primary_replay_export_enabled =
        state.object_primary_replay_export_for_tenant(&tenant.tenant_id);
    let fallback_tenant_object_primary_disabled = fallback_tenant_id.is_some_and(|tenant_id| {
        !state.object_primary_submit_review_for_tenant(tenant_id)
            && !state.object_primary_replay_export_for_tenant(tenant_id)
            && !state.object_primary_derived_exports_for_tenant(tenant_id)
    });

    let mut submitted_object_ref_present = false;
    let mut submitted_object_ref_service_owned = false;
    let mut submitted_object_ref_readable = false;
    let mut review_body_object_ref_readable = false;
    let mut replay_body_object_ref_readable = false;
    let mut plaintext_submitted_body_absent = false;

    if let Some(record) = record.as_ref() {
        ensure_retention_metadata_within_server_policy(record)?;
        let db = state
            .db_mirror
            .as_ref()
            .context("trace object-primary read drill requires configured DB mirror")?;
        let active_object_ref = db
            .get_latest_active_trace_object_ref(
                &tenant.tenant_id,
                request.submission_id,
                StorageTraceObjectArtifactKind::SubmittedEnvelope,
            )
            .await
            .with_context(|| {
                format!(
                    "failed to read active submitted-envelope object ref for object-primary drill {}",
                    request.submission_id
                )
            })?;
        submitted_object_ref_present = active_object_ref.is_some();
        if let Some(object_ref) = active_object_ref.as_ref() {
            submitted_object_ref_service_owned =
                is_service_owned_trace_object_store(&object_ref.object_store);
            submitted_object_ref_readable =
                read_envelope_from_object_ref(state, &tenant.tenant_id, object_ref)
                    .is_ok_and(|envelope| envelope.submission_id == request.submission_id);
        }
        if object_primary_submit_review_enabled {
            review_body_object_ref_readable =
                read_envelope_body_for_review_decision(state, tenant, record, false)
                    .await
                    .is_ok_and(|body| {
                        body.object_ref_id.is_some()
                            && body.envelope.submission_id == request.submission_id
                    });
            plaintext_submitted_body_absent = !state.root.join(&record.object_key).exists();
        }
        if object_primary_replay_export_enabled && record.is_export_eligible() {
            replay_body_object_ref_readable =
                read_envelope_body_for_replay_export(state, tenant, record)
                    .await
                    .is_ok_and(|body| {
                        body.object_ref_id.is_some()
                            && body.envelope.submission_id == request.submission_id
                    });
        }
    }

    let mut response = TraceObjectPrimaryReadDrillResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        generated_at,
        purpose: purpose.clone(),
        ready: false,
        evidence_hash: String::new(),
        submission_ref_hash,
        fallback_tenant_storage_ref,
        canary_submission_found: record.is_some(),
        object_store_eligible,
        object_primary_submit_review_enabled,
        object_primary_replay_export_enabled,
        submitted_object_ref_present,
        submitted_object_ref_service_owned,
        submitted_object_ref_readable,
        review_body_object_ref_readable,
        replay_body_object_ref_readable,
        plaintext_submitted_body_absent,
        fallback_tenant_object_primary_disabled,
        blocking_gaps: Vec::new(),
        recorded_evidence: None,
    };
    response.blocking_gaps = object_primary_read_drill_blocking_gaps(&response);
    response.ready = response.blocking_gaps.is_empty();
    response.evidence_hash = object_primary_read_drill_evidence_hash(tenant, &response);

    if request.record_evidence {
        let evidence = TraceRolloutSmokeEvidenceResponse {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            check_name: "object_primary_reads".to_string(),
            status: if response.ready {
                TraceRolloutSmokeEvidenceStatus::Passed
            } else {
                TraceRolloutSmokeEvidenceStatus::Failed
            },
            evidence_hash: object_primary_read_drill_evidence_hash(tenant, &response),
            evidence_ref_hash: Some(sha256_prefixed(&purpose)),
            actor_principal_ref: tenant.principal_ref.clone(),
            recorded_at: Utc::now(),
        };
        append_audit_event_with_db_mirror(
            state,
            tenant,
            TraceCommonsAuditEvent::rollout_smoke_evidence(&evidence),
            StorageTraceAuditAction::Read,
            StorageTraceAuditSafeMetadata::Empty,
        )
        .await?;
        response.recorded_evidence = Some(evidence);
    }

    Ok(response)
}

async fn run_object_store_migration_drill(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceObjectStoreMigrationDrillRequest,
) -> anyhow::Result<TraceObjectStoreMigrationDrillResponse> {
    let generated_at = Utc::now();
    let purpose = request
        .purpose
        .as_deref()
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .unwrap_or("trace_commons_object_store_migration_drill")
        .to_string();
    let tenant_ref = tenant_storage_ref(&tenant.tenant_id);
    let object_store_configured = state.artifact_store.is_some();
    let object_store_name = state
        .artifact_store
        .as_ref()
        .map(|store| store.object_store_name().to_string());
    let object_store_eligible = state
        .artifact_store
        .as_ref()
        .is_some_and(|store| store.object_primary_eligible());
    let object_io_enabled = state
        .artifact_store
        .as_ref()
        .is_some_and(|store| store.object_io_enabled());
    let plaintext_compatibility_allowed = state
        .artifact_store
        .as_ref()
        .is_some_and(|store| store.plaintext_compatibility_allowed());
    let object_versioning_supported = state
        .artifact_store
        .as_ref()
        .is_some_and(|store| store.object_versioning_supported());
    let restore_after_delete_supported = state
        .artifact_store
        .as_ref()
        .is_some_and(|store| store.restore_after_delete_supported());
    let mut write_succeeded = false;
    let mut read_succeeded = false;
    let mut delete_succeeded = false;
    let mut restore_after_delete_succeeded = false;
    let mut probe_object_ref_hash = None;
    let mut io_error_hashes = Vec::new();

    if let Some(store) = state.artifact_store.as_ref()
        && store.object_io_enabled()
    {
        let probe_object_id = format!("object-store-migration-drill-{}", Uuid::new_v4());
        let probe_payload = serde_json::json!({
            "schema": "trace_commons_object_store_migration_drill_probe.v1",
            "tenant_storage_ref": &tenant_ref,
            "purpose_hash": sha256_prefixed(&purpose),
            "probe_nonce_hash": sha256_prefixed(&probe_object_id),
            "secret_probe": "object-store-migration-drill-secret",
        });
        match store.put_json(
            &tenant_ref,
            TraceArtifactKind::AuditSnapshot,
            &probe_object_id,
            &probe_payload,
        ) {
            Ok(receipt) => {
                write_succeeded = true;
                probe_object_ref_hash = Some(object_store_migration_probe_ref_hash(
                    store.object_store_name(),
                    &receipt,
                ));
                match store.get_json::<serde_json::Value>(&tenant_ref, &receipt) {
                    Ok(read_back) => {
                        read_succeeded = read_back == probe_payload;
                        if !read_succeeded {
                            io_error_hashes.push(sha256_prefixed(
                                "object store migration drill probe read mismatch",
                            ));
                        }
                    }
                    Err(error) => {
                        io_error_hashes.push(sha256_prefixed(&error.to_string()));
                    }
                }
                match store.delete_artifact(&tenant_ref, &receipt) {
                    Ok(deleted) => {
                        delete_succeeded = deleted;
                    }
                    Err(error) => {
                        io_error_hashes.push(sha256_prefixed(&error.to_string()));
                    }
                }
                if request.require_versioning && restore_after_delete_supported {
                    match store.restore_deleted_artifact(&tenant_ref, &receipt) {
                        Ok(restored) => {
                            if restored {
                                match store.get_json::<serde_json::Value>(&tenant_ref, &receipt) {
                                    Ok(read_back) => {
                                        restore_after_delete_succeeded = read_back == probe_payload;
                                        if !restore_after_delete_succeeded {
                                            io_error_hashes.push(sha256_prefixed(
                                                "object store migration drill restored probe read mismatch",
                                            ));
                                        }
                                    }
                                    Err(error) => {
                                        io_error_hashes.push(sha256_prefixed(&error.to_string()));
                                    }
                                }
                                match store.delete_artifact(&tenant_ref, &receipt) {
                                    Ok(deleted) => {
                                        delete_succeeded = delete_succeeded && deleted;
                                    }
                                    Err(error) => {
                                        delete_succeeded = false;
                                        io_error_hashes.push(sha256_prefixed(&error.to_string()));
                                    }
                                }
                            } else {
                                io_error_hashes.push(sha256_prefixed(
                                    "object store migration drill deleted probe did not restore",
                                ));
                            }
                        }
                        Err(error) => {
                            io_error_hashes.push(sha256_prefixed(&error.to_string()));
                        }
                    }
                }
            }
            Err(error) => {
                io_error_hashes.push(sha256_prefixed(&error.to_string()));
            }
        }
    }

    let mut response = TraceObjectStoreMigrationDrillResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_ref,
        generated_at,
        purpose: purpose.clone(),
        ready: false,
        migration_manifest_hash: String::new(),
        evidence_hash: String::new(),
        object_store_configured,
        object_store_name,
        object_store_eligible,
        object_io_enabled,
        plaintext_compatibility_allowed,
        require_delete: request.require_delete,
        require_versioning: request.require_versioning,
        object_versioning_supported,
        restore_after_delete_supported,
        write_succeeded,
        read_succeeded,
        delete_succeeded,
        restore_after_delete_succeeded,
        probe_object_ref_hash,
        io_error_hashes,
        blocking_gaps: Vec::new(),
        recorded_evidence: None,
    };
    response.blocking_gaps = object_store_migration_drill_blocking_gaps(&response);
    response.ready = response.blocking_gaps.is_empty();
    response.migration_manifest_hash = object_store_migration_manifest_hash(tenant, &response);
    response.evidence_hash = object_store_migration_drill_evidence_hash(tenant, &response);

    if request.record_evidence {
        let evidence = TraceRolloutSmokeEvidenceResponse {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            check_name: "object_store_migration".to_string(),
            status: if response.ready {
                TraceRolloutSmokeEvidenceStatus::Passed
            } else {
                TraceRolloutSmokeEvidenceStatus::Failed
            },
            evidence_hash: response.evidence_hash.clone(),
            evidence_ref_hash: Some(response.migration_manifest_hash.clone()),
            actor_principal_ref: tenant.principal_ref.clone(),
            recorded_at: Utc::now(),
        };
        append_audit_event_with_db_mirror(
            state,
            tenant,
            TraceCommonsAuditEvent::rollout_smoke_evidence(&evidence),
            StorageTraceAuditAction::Read,
            StorageTraceAuditSafeMetadata::Empty,
        )
        .await?;
        response.recorded_evidence = Some(evidence);
    }

    Ok(response)
}

