async fn run_vector_index_drill(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceVectorIndexDrillRequest,
    limit: usize,
    tenant_policy: Option<&TenantSubmissionPolicy>,
) -> anyhow::Result<TraceVectorIndexDrillResponse> {
    let generated_at = Utc::now();
    let purpose = request
        .purpose
        .as_deref()
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .unwrap_or("trace_commons_vector_index_drill")
        .to_string();
    let worker = run_vector_index_worker(
        state,
        tenant,
        TraceVectorIndexRequest {
            purpose: Some(purpose.clone()),
            dry_run: true,
            limit: Some(limit),
        },
        limit,
        tenant_policy,
    )
    .await?;
    let candidate_count = worker
        .checked_count
        .saturating_add(worker.skipped_existing_count)
        .saturating_add(worker.pending_after_count);
    let nearest_neighbor_policy_gap_count =
        trace_vector_nearest_neighbor_policy_gap_count_for_tenant(state, tenant).await?;
    let blocking_gaps = vector_index_drill_blocking_gaps(
        state,
        candidate_count,
        worker.pending_after_count,
        nearest_neighbor_policy_gap_count,
        &request,
    );
    let mut response = TraceVectorIndexDrillResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        generated_at,
        purpose: worker.purpose,
        ready: blocking_gaps.is_empty(),
        evidence_hash: String::new(),
        dry_run: worker.dry_run,
        audit_event_id: worker.audit_event_id,
        limit,
        require_candidates: request.require_candidates,
        private_embedder_configured: state.vector_embedder.is_some(),
        private_embedder_required: state.require_external_vector_embedder,
        private_searcher_configured: state.vector_searcher.is_some(),
        private_searcher_required: state.require_external_vector_searcher,
        scheduler_enabled: state.vector_index_scheduler.is_some(),
        checked_count: worker.checked_count,
        vector_entries_indexed: worker.vector_entries_indexed,
        skipped_existing_count: worker.skipped_existing_count,
        pending_after_count: worker.pending_after_count,
        candidate_count,
        nearest_neighbor_policy_gap_count,
        blocking_gaps,
        recorded_evidence: None,
    };
    response.evidence_hash = vector_index_drill_evidence_hash(tenant, &response, state);

    if request.record_evidence {
        let evidence = TraceRolloutSmokeEvidenceResponse {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            check_name: "vector_index".to_string(),
            status: if response.ready {
                TraceRolloutSmokeEvidenceStatus::Passed
            } else {
                TraceRolloutSmokeEvidenceStatus::Failed
            },
            evidence_hash: response.evidence_hash.clone(),
            evidence_ref_hash: Some(sha256_prefixed(&purpose)),
            actor_principal_ref: tenant.principal_ref.clone(),
            recorded_at: Utc::now(),
        };
        append_audit_event_with_db_mirror(
            state,
            tenant,
            TraceCommonsAuditEvent::rollout_smoke_evidence(&evidence),
            StorageTraceAuditAction::Read,
            StorageTraceAuditSafeMetadata::Empty,
        )
        .await?;
        response.recorded_evidence = Some(evidence);
    }

    Ok(response)
}

async fn trace_vector_nearest_neighbor_policy_gap_count_for_tenant(
    state: &AppState,
    tenant: &TenantAuth,
) -> anyhow::Result<usize> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(0);
    };
    let metadata = read_reviewer_metadata_view(state, tenant)
        .await
        .context("failed to read metadata for vector neighbor policy diagnostics")?;
    let vector_entries = db
        .list_trace_vector_entries(&tenant.tenant_id)
        .await
        .context("failed to read vector entries for vector neighbor policy diagnostics")?;
    Ok(trace_vector_nearest_neighbor_policy_gap_count(
        &metadata.derived,
        &vector_entries,
    ))
}

async fn run_analytics_release_drill(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceAnalyticsReleaseDrillRequest,
) -> anyhow::Result<TraceAnalyticsReleaseDrillResponse> {
    let generated_at = Utc::now();
    let purpose = request
        .purpose
        .as_deref()
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .unwrap_or("trace_commons_analytics_release_drill")
        .to_string();
    let TraceCommonsMetadataView { records, derived } =
        read_reviewer_metadata_view(state, tenant).await?;
    let mut analytics =
        TraceCommonsAnalyticsResponse::from_records(tenant.tenant_id.clone(), records, derived);
    analytics.apply_min_cell_count(state.analytics_min_cell_count);
    if state.analytics_broad_release_noise.is_none() {
        analytics
            .privacy_budget
            .block_broad_release("noise_not_configured");
    }
    if let Some(config) = state.analytics_broad_release_noise.as_ref() {
        analytics.apply_broad_release_noise(config);
    }
    let privacy_ledger = if let Some(config) = state.analytics_broad_release_privacy_accounting {
        let ledger = analytics_broad_release_privacy_ledger(state, &tenant.tenant_id, config)?;
        if ledger.remaining_before_release < config.epsilon_micros_per_release {
            analytics
                .privacy_budget
                .block_broad_release("privacy_budget_exhausted");
        }
        analytics
            .privacy_budget
            .apply_privacy_accounting(config, ledger.spent_before_release);
        Some((config, ledger))
    } else {
        None
    };

    let budget = analytics.privacy_budget.clone();
    let blocking_gaps = budget.broad_release_blocking_reasons.clone();
    let evidence_hash = analytics_release_drill_evidence_hash(
        tenant,
        state,
        &budget,
        analytics.min_cell_count,
        &blocking_gaps,
    );
    let mut response = TraceAnalyticsReleaseDrillResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        generated_at,
        purpose: purpose.clone(),
        ready: blocking_gaps.is_empty(),
        evidence_hash,
        min_cell_count: state.analytics_min_cell_count,
        min_cell_count_configured: analytics.min_cell_count.is_some(),
        broad_release_noise_configured: state.analytics_broad_release_noise.is_some(),
        broad_release_noise_max_delta: state
            .analytics_broad_release_noise
            .as_ref()
            .map(|config| config.max_delta),
        privacy_accounting_configured: privacy_ledger.is_some(),
        epsilon_micros_per_release: privacy_ledger
            .map(|(config, _)| config.epsilon_micros_per_release),
        max_epsilon_micros: privacy_ledger.map(|(config, _)| config.max_epsilon_micros),
        epsilon_spent_micros: privacy_ledger.map(|(_, ledger)| ledger.spent_before_release),
        epsilon_remaining_micros: privacy_ledger.map(|(_, ledger)| ledger.remaining_before_release),
        released_cell_count: budget.released_cell_count,
        suppressed_cell_count: budget.suppressed_cell_count,
        suppression_applied: budget.suppression_applied,
        noise_applied: budget.noise_applied,
        noise_max_delta: budget.noise_max_delta,
        noisy_cell_count: budget.noisy_cell_count,
        blocking_gaps,
        recorded_evidence: None,
    };

    if request.record_evidence {
        let evidence = TraceRolloutSmokeEvidenceResponse {
            event_id: Uuid::new_v4(),
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            check_name: "analytics_release".to_string(),
            status: if response.ready {
                TraceRolloutSmokeEvidenceStatus::Passed
            } else {
                TraceRolloutSmokeEvidenceStatus::Failed
            },
            evidence_hash: response.evidence_hash.clone(),
            evidence_ref_hash: Some(sha256_prefixed(&purpose)),
            actor_principal_ref: tenant.principal_ref.clone(),
            recorded_at: Utc::now(),
        };
        append_audit_event_with_db_mirror(
            state,
            tenant,
            TraceCommonsAuditEvent::rollout_smoke_evidence(&evidence),
            StorageTraceAuditAction::Read,
            StorageTraceAuditSafeMetadata::Empty,
        )
        .await?;
        response.recorded_evidence = Some(evidence);
    }

    Ok(response)
}

