async fn run_ranker_training_candidates_export_with_grant(
    state: &AppState,
    tenant: &TenantAuth,
    query: RankerTrainingExportQuery,
    grant: TraceExportAccessGrant,
    now: DateTime<Utc>,
) -> ApiResult<Json<TraceRankerTrainingCandidateExport>> {
    require_positive_credit_issuance_principal_if_configured(state, tenant, 1.0)?;
    let (consent_scope, tenant_policy, purpose) = prepare_ranker_training_export_execution(
        state,
        tenant,
        &query,
        "ranker training candidates",
        "ranker_training_candidates_export",
    )
    .await?;
    let job = create_validated_export_job_slice(
        state,
        tenant,
        TraceExportJobRequest {
            requested_dataset_kind: TraceExportDatasetKind::RankerTrainingCandidates,
            purpose: purpose.clone(),
            requested_limit: query.limit,
            grant: grant.clone(),
            metadata: export_job_request_metadata(
                query.limit,
                query.status,
                query.privacy_risk,
                consent_scope,
                None,
            ),
        },
        now,
    )?;
    enforce_export_job_mirror_result(
        state,
        "ranker candidate export job start",
        mirror_export_job_started_to_db(state, tenant, &grant, &job).await,
    )
    .await
    .map_err(internal_error)?;
    run_ranker_training_candidates_export_job(
        state,
        tenant,
        query,
        job,
        consent_scope,
        tenant_policy,
        purpose,
    )
    .await
}

async fn prepare_ranker_training_export_execution(
    state: &AppState,
    tenant: &TenantAuth,
    query: &RankerTrainingExportQuery,
    surface: &str,
    default_purpose: &str,
) -> ApiResult<(Option<ConsentScope>, Option<TenantSubmissionPolicy>, String)> {
    let consent_scope = parse_ranker_consent_scope_filter(query.consent_scope.as_deref())?;
    let purpose = normalized_export_purpose(query.purpose.as_deref(), default_purpose);
    enforce_ranker_export_guardrails(
        state,
        query.purpose.as_deref(),
        query.status,
        query.privacy_risk,
        consent_scope,
    )?;
    let tenant_policy = tenant_export_policy_for_request(
        state,
        tenant,
        surface,
        consent_scope,
        TraceAllowedUse::RankingModelTraining,
    )
    .await?;
    Ok((consent_scope, tenant_policy, purpose))
}

async fn run_ranker_training_candidates_export_job(
    state: &AppState,
    tenant: &TenantAuth,
    query: RankerTrainingExportQuery,
    job: TraceExportJobSlice,
    consent_scope: Option<ConsentScope>,
    tenant_policy: Option<TenantSubmissionPolicy>,
    purpose: String,
) -> ApiResult<Json<TraceRankerTrainingCandidateExport>> {
    let mut candidate_query = query;
    candidate_query.limit = Some(job.max_item_cap);
    let candidates = fail_export_job_on_error(
        state,
        &job,
        "ranker candidate export job failure",
        collect_ranker_training_candidates(
            state,
            tenant,
            &candidate_query,
            consent_scope,
            tenant_policy.as_ref(),
        )
        .await,
    )
    .await?;
    let export_id = Uuid::new_v4();
    let source_submission_ids = candidates
        .iter()
        .map(|candidate| candidate.submission_id)
        .collect::<Vec<_>>();
    let source_object_refs = fail_export_job_on_error(
        state,
        &job,
        "ranker candidate export job failure",
        revalidate_db_export_sources(
            state,
            tenant,
            &source_submission_ids,
            state.require_derived_export_object_refs_for_tenant(&tenant.tenant_id),
        )
        .await,
    )
    .await?;
    fail_export_job_on_error(
        state,
        &job,
        "ranker candidate export job failure",
        append_derived_source_read_audits(
            state,
            tenant,
            &source_submission_ids,
            &source_object_refs,
            "ranker_training_candidates",
            Some(&purpose),
        )
        .await,
    )
    .await?;
    let source_item_list_hash =
        source_submission_ids_hash("ranker_training_candidates_export", &source_submission_ids);
    let audit_event = TraceCommonsAuditEvent::ranker_training_export(
        tenant,
        export_id,
        purpose.as_str(),
        candidates.len(),
        source_item_list_hash.clone(),
    );
    let audit_event_id = audit_event.event_id;
    let provenance = TraceExportProvenanceManifest::new(
        &tenant.tenant_id,
        export_id,
        audit_event_id,
        TraceExportProvenanceKind::RankerTrainingCandidates,
        purpose.clone(),
        source_submission_ids,
        source_item_list_hash.clone(),
    );
    let provenance_path = ranker_provenance_path(&state.root, &tenant.tenant_id, export_id);
    let mut required_artifact_object_ref_material = None;
    let object_primary_derived_exports =
        state.object_primary_derived_exports_for_tenant(&tenant.tenant_id);
    if state.require_db_mirror_writes {
        let artifact_object_ref_material = if state.db_mirror.is_some() {
            Some(
                trace_export_artifact_object_ref_material(
                    state,
                    &tenant.tenant_id,
                    TraceArtifactKind::RankerTrainingExport,
                    export_id,
                    &provenance_path,
                    &provenance,
                )
                .map_err(internal_error)?,
            )
        } else {
            None
        };
        let mirror_result = mirror_ranker_candidate_export_provenance_to_db(
            state,
            &provenance,
            &candidates,
            artifact_object_ref_material.as_ref(),
        )
        .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_display_error_hash(error),
                export_id = %export_id,
                "Trace Commons DB dual-write ranker candidate provenance mirror failed"
            );
            cleanup_export_artifact_publication(
                state,
                &tenant.tenant_id,
                TraceArtifactKind::RankerTrainingExport,
                artifact_object_ref_material.as_ref(),
                std::slice::from_ref(&provenance_path),
            )
            .map_err(internal_error)?;
        }
        enforce_db_mirror_write_result(state, "ranker candidate provenance", mirror_result)
            .map_err(internal_error)?;
        required_artifact_object_ref_material = artifact_object_ref_material;
        if !object_primary_derived_exports {
            write_export_provenance(&provenance_path, &tenant.tenant_id, &provenance)
                .map_err(internal_error)?;
        }
    } else {
        if !object_primary_derived_exports {
            write_export_provenance(&provenance_path, &tenant.tenant_id, &provenance)
                .map_err(internal_error)?;
        }
        let artifact_object_ref_material = if state.db_mirror.is_some() {
            Some(
                trace_export_artifact_object_ref_material(
                    state,
                    &tenant.tenant_id,
                    TraceArtifactKind::RankerTrainingExport,
                    export_id,
                    &provenance_path,
                    &provenance,
                )
                .map_err(internal_error)?,
            )
        } else {
            None
        };
        let mirror_result = mirror_ranker_candidate_export_provenance_to_db(
            state,
            &provenance,
            &candidates,
            artifact_object_ref_material.as_ref(),
        )
        .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_display_error_hash(error),
                export_id = %export_id,
                "Trace Commons DB dual-write ranker candidate provenance mirror failed"
            );
        }
        enforce_db_mirror_write_result(state, "ranker candidate provenance", mirror_result)
            .map_err(internal_error)?;
    }
    let audit_result = append_audit_event_with_db_mirror(
        state,
        tenant,
        audit_event.clone(),
        StorageTraceAuditAction::Export,
        StorageTraceAuditSafeMetadata::Export {
            artifact_kind: StorageTraceObjectArtifactKind::ExportArtifact,
            purpose_code: Some(purpose.clone()),
            item_count: candidates.len().min(u32::MAX as usize) as u32,
        },
    )
    .await;
    if let Err(error) = audit_result {
        if state.require_db_mirror_writes {
            cleanup_export_artifact_publication(
                state,
                &tenant.tenant_id,
                TraceArtifactKind::RankerTrainingExport,
                required_artifact_object_ref_material.as_ref(),
                std::slice::from_ref(&provenance_path),
            )
            .map_err(internal_error)?;
            rollback_db_export_manifest_publication(state, &tenant.tenant_id, export_id)
                .await
                .map_err(internal_error)?;
            remove_audit_event_by_id(&state.root, &tenant.tenant_id, audit_event.event_id)
                .map_err(internal_error)?;
        }
        return Err(internal_error(error));
    }
    append_automatic_utility_credit_events_once(
        state,
        tenant,
        AutomaticUtilityCreditConfig {
            idempotency_label: "ranker-training-candidate-credit",
            idempotency_ref: None,
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: RANKER_TRAINING_CANDIDATE_CREDIT_POINTS_DELTA,
            reason: format!("Exported as ranker training candidate {}.", export_id),
            external_ref: format!("ranker_training_candidates_export:{export_id}"),
        },
        candidates
            .iter()
            .map(AutomaticUtilityCreditSource::from_ranker_candidate),
    )
    .await?;
    enforce_export_job_mirror_result(
        state,
        "ranker candidate export job completion",
        mirror_export_job_finished_to_db(state, &job, export_id, candidates.len()).await,
    )
    .await
    .map_err(internal_error)?;
    Ok(Json(TraceRankerTrainingCandidateExport {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        export_id,
        audit_event_id,
        purpose,
        generated_at: Utc::now(),
        item_count: candidates.len(),
        source_item_list_hash,
        candidates,
    }))
}

