fn require_ranking_label_source_operator(
    auth: &TenantAuth,
    label_source: StorageTraceRankingLabelSource,
) -> ApiResult<()> {
    if auth.role.can_admin()
        || matches!(
            (auth.role, label_source),
            (
                TokenRole::UtilityWorker,
                StorageTraceRankingLabelSource::FrontierLab
            ) | (
                TokenRole::Reviewer,
                StorageTraceRankingLabelSource::Reviewer
            ) | (
                TokenRole::BenchmarkWorker,
                StorageTraceRankingLabelSource::Benchmark
            ) | (
                TokenRole::ProcessEvalWorker,
                StorageTraceRankingLabelSource::System
            )
        )
    {
        Ok(())
    } else {
        Err(api_error(
            StatusCode::FORBIDDEN,
            "ranking label_source is not allowed for this token role",
        ))
    }
}

fn require_process_evaluation_operator(auth: &TenantAuth) -> ApiResult<()> {
    if auth.role.can_admin() || auth.role == TokenRole::ProcessEvalWorker {
        Ok(())
    } else {
        Err(api_error(
            StatusCode::FORBIDDEN,
            "admin or process evaluation worker token required",
        ))
    }
}

fn require_maintenance_operator(
    auth: &TenantAuth,
    request: &TraceMaintenanceRequest,
) -> ApiResult<()> {
    if auth.role.can_admin() {
        return Ok(());
    }
    if auth.role == TokenRole::RetentionWorker && request.is_retention_worker_request() {
        return Ok(());
    }
    if auth.role == TokenRole::VectorWorker && request.is_vector_worker_request() {
        return Ok(());
    }
    Err(api_error(
        StatusCode::FORBIDDEN,
        "admin token or matching maintenance worker token required",
    ))
}

fn require_admin(auth: &TenantAuth) -> ApiResult<()> {
    if auth.role.can_admin() {
        Ok(())
    } else {
        Err(api_error(StatusCode::FORBIDDEN, "admin token required"))
    }
}

fn can_access_submission(auth: &TenantAuth, record: &TraceCommonsSubmissionRecord) -> bool {
    auth.role.can_review() || principal_owns_submission(&auth.principal_ref, record)
}

fn can_access_storage_submission(auth: &TenantAuth, record: &StorageTraceSubmissionRecord) -> bool {
    auth.role.can_review() || principal_owns_storage_submission(&auth.principal_ref, record)
}

fn principal_owns_submission(principal_ref: &str, record: &TraceCommonsSubmissionRecord) -> bool {
    record.auth_principal_ref == legacy_principal_ref()
        || record.auth_principal_ref == principal_ref
}

fn principal_owns_storage_submission(
    principal_ref: &str,
    record: &StorageTraceSubmissionRecord,
) -> bool {
    record.auth_principal_ref == legacy_principal_ref()
        || record.auth_principal_ref == principal_ref
}

fn principal_can_self_revoke_submission(
    auth: &TenantAuth,
    record: &TraceCommonsSubmissionRecord,
) -> bool {
    record.auth_principal_ref == auth.principal_ref
        || (record.auth_principal_ref == legacy_principal_ref() && !auth.role.can_review())
}

fn principal_can_self_revoke_storage_submission(
    auth: &TenantAuth,
    record: &StorageTraceSubmissionRecord,
) -> bool {
    record.auth_principal_ref == auth.principal_ref
        || (record.auth_principal_ref == legacy_principal_ref() && !auth.role.can_review())
}

fn visible_submission_records(
    auth: &TenantAuth,
    records: Vec<TraceCommonsSubmissionRecord>,
) -> Vec<TraceCommonsSubmissionRecord> {
    records
        .into_iter()
        .filter(|record| can_access_submission(auth, record))
        .collect()
}

fn can_access_credit_event(auth: &TenantAuth, event: &TraceCommonsCreditLedgerRecord) -> bool {
    auth.role.can_review()
        || event.auth_principal_ref == legacy_principal_ref()
        || event.auth_principal_ref == auth.principal_ref
}

fn visible_credit_events(
    auth: &TenantAuth,
    events: Vec<TraceCommonsCreditLedgerRecord>,
) -> Vec<TraceCommonsCreditLedgerRecord> {
    events
        .into_iter()
        .filter(|event| can_access_credit_event(auth, event))
        .collect()
}

fn eligible_credit_events_for_records(
    records: &[TraceCommonsSubmissionRecord],
    events: Vec<TraceCommonsCreditLedgerRecord>,
) -> Vec<TraceCommonsCreditLedgerRecord> {
    let eligible_submissions = records
        .iter()
        .filter(|record| !record.is_terminal())
        .map(|record| record.submission_id)
        .collect::<BTreeSet<_>>();
    events
        .into_iter()
        .filter(|event| eligible_submissions.contains(&event.submission_id))
        .collect()
}

fn credit_events_for_records(
    records: &[TraceCommonsSubmissionRecord],
    events: Vec<TraceCommonsCreditLedgerRecord>,
) -> Vec<TraceCommonsCreditLedgerRecord> {
    let visible_submissions = records
        .iter()
        .map(|record| record.submission_id)
        .collect::<BTreeSet<_>>();
    events
        .into_iter()
        .filter(|event| visible_submissions.contains(&event.submission_id))
        .collect()
}

