async fn mirror_ranker_pair_export_provenance_to_db(
    state: &AppState,
    provenance: &TraceExportProvenanceManifest,
    pairs: &[TraceRankerTrainingPair],
    artifact_object_ref_material: Option<&TraceExportArtifactObjectRefMaterial>,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    let vector_entry_ids =
        active_vector_entry_lookup_for_export(db.as_ref(), &provenance.tenant_id)
            .await
            .context("failed to read active vector entries for ranker pair provenance")?;
    let mut object_refs = Vec::new();
    let mut items = Vec::new();
    for pair in pairs {
        for candidate in [&pair.preferred, &pair.rejected] {
            let object_ref_id = if let Some(material) = artifact_object_ref_material {
                let object_ref = trace_export_artifact_object_ref_write(
                    &provenance.tenant_id,
                    candidate.submission_id,
                    StorageTraceObjectArtifactKind::ExportArtifact,
                    provenance.export_id,
                    material,
                );
                let object_ref_id = object_ref.object_ref_id;
                object_refs.push(object_ref);
                Some(object_ref_id)
            } else {
                None
            };
            items.push(StorageTraceExportManifestItemWrite {
                tenant_id: provenance.tenant_id.clone(),
                export_manifest_id: provenance.export_id,
                submission_id: candidate.submission_id,
                trace_id: candidate.trace_id,
                derived_id: Some(candidate.derived_id),
                object_ref_id,
                vector_entry_id: vector_entry_ids
                    .get(&(
                        candidate.submission_id,
                        candidate.derived_id,
                        candidate.canonical_summary_hash.clone(),
                    ))
                    .copied(),
                source_status_at_export: storage_corpus_status(candidate.status),
                source_hash_at_export: candidate.canonical_summary_hash.clone(),
            });
        }
    }
    db.upsert_trace_export_manifest_mirror(StorageTraceExportManifestMirrorWrite {
        manifest: provenance_manifest_write(
            provenance,
            StorageTraceObjectArtifactKind::ExportArtifact,
            provenance.source_submission_ids.len(),
        ),
        object_refs,
        items,
    })
    .await
    .context("failed to atomically mirror ranker pair provenance metadata")?;
    Ok(())
}

async fn active_vector_entry_lookup_for_export(
    db: &dyn Database,
    tenant_id: &str,
) -> anyhow::Result<BTreeMap<(Uuid, Uuid, String), Uuid>> {
    let entries = db
        .list_trace_vector_entries(tenant_id)
        .await
        .context("failed to list trace vector entries")?;
    Ok(entries
        .into_iter()
        .filter(|entry| entry.status == StorageTraceVectorEntryStatus::Active)
        .filter(|entry| {
            entry.source_projection == StorageTraceVectorEntrySourceProjection::CanonicalSummary
        })
        .map(|entry| {
            (
                (entry.submission_id, entry.derived_id, entry.source_hash),
                entry.vector_entry_id,
            )
        })
        .collect())
}

fn provenance_manifest_write(
    provenance: &TraceExportProvenanceManifest,
    artifact_kind: StorageTraceObjectArtifactKind,
    item_count: usize,
) -> StorageTraceExportManifestWrite {
    StorageTraceExportManifestWrite {
        tenant_id: provenance.tenant_id.clone(),
        export_manifest_id: provenance.export_id,
        artifact_kind,
        purpose_code: Some(provenance_storage_purpose_code(provenance)),
        audit_event_id: Some(provenance.audit_event_id),
        source_submission_ids: provenance.source_submission_ids.clone(),
        source_submission_ids_hash: provenance.source_submission_ids_hash.clone(),
        item_count: item_count.min(u32::MAX as usize) as u32,
        generated_at: provenance.generated_at,
    }
}

fn provenance_storage_purpose_code(provenance: &TraceExportProvenanceManifest) -> String {
    match provenance.export_kind {
        TraceExportProvenanceKind::BenchmarkConversion => provenance.purpose.clone(),
        TraceExportProvenanceKind::RankerTrainingCandidates => ranker_storage_purpose_code(
            RANKER_TRAINING_CANDIDATES_EXPORT_PURPOSE_CODE,
            &provenance.purpose,
        ),
        TraceExportProvenanceKind::RankerTrainingPairs => ranker_storage_purpose_code(
            RANKER_TRAINING_PAIRS_EXPORT_PURPOSE_CODE,
            &provenance.purpose,
        ),
    }
}

fn ranker_storage_purpose_code(export_kind_code: &str, purpose: &str) -> String {
    let purpose = purpose.trim();
    if purpose == export_kind_code {
        export_kind_code.to_string()
    } else {
        format!("{export_kind_code}:{purpose}")
    }
}

fn is_ranker_training_purpose_code(purpose_code: &str) -> bool {
    purpose_code == RANKER_TRAINING_CANDIDATES_EXPORT_PURPOSE_CODE
        || purpose_code == RANKER_TRAINING_PAIRS_EXPORT_PURPOSE_CODE
        || purpose_code
            .strip_prefix(RANKER_TRAINING_CANDIDATES_EXPORT_PURPOSE_CODE)
            .is_some_and(|suffix| suffix.starts_with(':'))
        || purpose_code
            .strip_prefix(RANKER_TRAINING_PAIRS_EXPORT_PURPOSE_CODE)
            .is_some_and(|suffix| suffix.starts_with(':'))
}

fn storage_manifest_purpose_matches(purpose_code: Option<&str>, requested_purpose: &str) -> bool {
    let Some(purpose_code) = purpose_code else {
        return false;
    };
    purpose_code == requested_purpose
        || purpose_code
            .strip_prefix(RANKER_TRAINING_CANDIDATES_EXPORT_PURPOSE_CODE)
            .and_then(|suffix| suffix.strip_prefix(':'))
            .is_some_and(|purpose| purpose == requested_purpose)
        || purpose_code
            .strip_prefix(RANKER_TRAINING_PAIRS_EXPORT_PURPOSE_CODE)
            .and_then(|suffix| suffix.strip_prefix(':'))
            .is_some_and(|purpose| purpose == requested_purpose)
}

fn storage_submission_write_from_record(
    record: &TraceCommonsSubmissionRecord,
    envelope: &TraceContributionEnvelope,
    canonical_summary_hash: Option<String>,
) -> anyhow::Result<StorageTraceSubmissionWrite> {
    let consent_scopes = consent_scope_storage_strings(&record.consent_scopes)?;
    let allowed_uses = trace_allowed_use_storage_strings(&envelope.trace_card.allowed_uses)?;
    Ok(StorageTraceSubmissionWrite {
        tenant_id: record.tenant_id.clone(),
        submission_id: record.submission_id,
        trace_id: record.trace_id,
        auth_principal_ref: record.auth_principal_ref.clone(),
        contributor_pseudonym: record.contributor_pseudonym.clone(),
        submitted_tenant_scope_ref: record.submitted_tenant_scope_ref.clone(),
        schema_version: envelope.schema_version.clone(),
        consent_policy_version: envelope.consent.policy_version.clone(),
        consent_scopes: consent_scopes.clone(),
        allowed_uses,
        retention_policy_id: record.retention_policy_id.clone(),
        status: storage_corpus_status(record.status),
        privacy_risk: serde_storage_string(&record.privacy_risk)?,
        redaction_pipeline_version: envelope.privacy.redaction_pipeline_version.clone(),
        redaction_counts: record.redaction_counts.clone(),
        redaction_hash: envelope.privacy.redaction_hash.clone(),
        canonical_summary_hash,
        submission_score: Some(record.submission_score),
        credit_points_pending: Some(record.credit_points_pending),
        credit_points_final: record.credit_points_final,
        expires_at: record.expires_at,
    })
}

fn deterministic_trace_uuid(label: &str, record: &TraceCommonsSubmissionRecord) -> Uuid {
    deterministic_trace_uuid_for(label, &record.tenant_id, record.submission_id)
}

fn deterministic_trace_uuid_for(label: &str, tenant_id: &str, submission_id: Uuid) -> Uuid {
    let input = format!(
        "ironclaw.trace_commons.{label}:{}:{}",
        tenant_id, submission_id
    );
    Uuid::new_v5(&Uuid::NAMESPACE_URL, input.as_bytes())
}

fn deterministic_trace_uuid_for_external_ref(
    label: &str,
    tenant_id: &str,
    submission_id: Uuid,
    external_ref: &str,
) -> Uuid {
    let input = format!(
        "ironclaw.trace_commons.{label}:{}:{}:{}",
        tenant_id, submission_id, external_ref
    );
    Uuid::new_v5(&Uuid::NAMESPACE_URL, input.as_bytes())
}

fn storage_corpus_status(status: TraceCorpusStatus) -> StorageTraceCorpusStatus {
    match status {
        TraceCorpusStatus::Accepted => StorageTraceCorpusStatus::Accepted,
        TraceCorpusStatus::Quarantined => StorageTraceCorpusStatus::Quarantined,
        TraceCorpusStatus::Rejected => StorageTraceCorpusStatus::Rejected,
        TraceCorpusStatus::Revoked => StorageTraceCorpusStatus::Revoked,
        TraceCorpusStatus::Expired => StorageTraceCorpusStatus::Expired,
        TraceCorpusStatus::Purged => StorageTraceCorpusStatus::Purged,
    }
}

fn storage_derived_status(status: TraceCorpusStatus) -> StorageTraceDerivedStatus {
    match status {
        TraceCorpusStatus::Revoked => StorageTraceDerivedStatus::Revoked,
        TraceCorpusStatus::Expired | TraceCorpusStatus::Purged => {
            StorageTraceDerivedStatus::Expired
        }
        TraceCorpusStatus::Rejected => StorageTraceDerivedStatus::Invalidated,
        TraceCorpusStatus::Accepted | TraceCorpusStatus::Quarantined => {
            StorageTraceDerivedStatus::Current
        }
    }
}

fn storage_credit_event_type(
    event_type: TraceCreditLedgerEventType,
) -> StorageTraceCreditEventType {
    match event_type {
        TraceCreditLedgerEventType::BenchmarkConversion => {
            StorageTraceCreditEventType::BenchmarkConversion
        }
        TraceCreditLedgerEventType::RegressionCatch => StorageTraceCreditEventType::RegressionCatch,
        TraceCreditLedgerEventType::TrainingUtility => StorageTraceCreditEventType::TrainingUtility,
        TraceCreditLedgerEventType::RankingUtility => StorageTraceCreditEventType::RankingUtility,
        TraceCreditLedgerEventType::ReviewerBonus => StorageTraceCreditEventType::ReviewerBonus,
        TraceCreditLedgerEventType::AbusePenalty => StorageTraceCreditEventType::AbusePenalty,
        TraceCreditLedgerEventType::NoveltyUtility => StorageTraceCreditEventType::NoveltyUtility,
    }
}

fn credit_delta_micros(delta: f32) -> i64 {
    (delta * 1_000_000.0).round() as i64
}

fn consent_scope_storage_strings(scopes: &[ConsentScope]) -> anyhow::Result<Vec<String>> {
    scopes.iter().map(serde_storage_string).collect()
}

fn trace_allowed_use_storage_strings(
    allowed_uses: &[TraceAllowedUse],
) -> anyhow::Result<Vec<String>> {
    allowed_uses.iter().map(serde_storage_string).collect()
}

fn serde_storage_string<T: Serialize>(value: &T) -> anyhow::Result<String> {
    let value = serde_json::to_value(value).context("failed to serialize storage enum")?;
    value
        .as_str()
        .map(str::to_string)
        .ok_or_else(|| anyhow::anyhow!("storage enum did not serialize to a string"))
}

fn write_submission_record(
    root: &Path,
    record: &TraceCommonsSubmissionRecord,
) -> anyhow::Result<()> {
    ensure_submission_record_tenant(record, &record.tenant_id)?;
    let path = submission_metadata_path(root, &record.tenant_id, record.submission_id);
    write_json_file(&path, record, "trace contribution metadata")
}

fn submission_metadata_path(root: &Path, tenant_id: &str, submission_id: Uuid) -> PathBuf {
    let tenant_key = tenant_storage_key(tenant_id);
    root.join("tenants")
        .join(tenant_key)
        .join("metadata")
        .join(format!("{submission_id}.json"))
}

fn read_submission_record(
    root: &Path,
    tenant_id: &str,
    submission_id: Uuid,
) -> anyhow::Result<Option<TraceCommonsSubmissionRecord>> {
    let path = submission_metadata_path(root, tenant_id, submission_id);
    if !path.exists() {
        return Ok(None);
    }
    let body = std::fs::read_to_string(&path)
        .with_context(|| format!("failed to read trace metadata {}", path.display()))?;
    let record = serde_json::from_str(&body)
        .with_context(|| format!("failed to parse trace metadata {}", path.display()))?;
    ensure_submission_record_tenant(&record, tenant_id)?;
    Ok(Some(record))
}

fn ensure_submission_record_tenant(
    record: &TraceCommonsSubmissionRecord,
    tenant_id: &str,
) -> anyhow::Result<()> {
    let expected_tenant_ref = tenant_storage_ref(tenant_id);
    anyhow::ensure!(
        record.tenant_id == tenant_id,
        "trace metadata tenant mismatch"
    );
    anyhow::ensure!(
        record.tenant_storage_ref == expected_tenant_ref,
        "trace metadata tenant storage ref mismatch"
    );
    if let Some(scope_ref) = record.submitted_tenant_scope_ref.as_deref() {
        anyhow::ensure!(
            scope_ref == expected_tenant_ref,
            "trace metadata submitted tenant scope mismatch"
        );
    }
    Ok(())
}

fn read_envelope_by_record(
    state: &AppState,
    record: &TraceCommonsSubmissionRecord,
) -> anyhow::Result<TraceContributionEnvelope> {
    let envelope = if let (Some(store), Some(receipt)) = (
        state.artifact_store.as_ref(),
        record.artifact_receipt.as_ref(),
    ) && trace_record_artifact_receipt_matches_store(
        record,
        receipt,
        store.object_store_name(),
    )? {
        store.get_json(&record.tenant_storage_ref, receipt)?
    } else {
        let path = state.root.join(&record.object_key);
        let body = std::fs::read_to_string(&path)
            .with_context(|| format!("failed to read trace object {}", path.display()))?;
        serde_json::from_str(&body)
            .with_context(|| format!("failed to parse trace object {}", path.display()))?
    };
    ensure_envelope_tenant_scope(&envelope, &record.tenant_id)?;
    verify_envelope_tenant_drift(&envelope, &record.tenant_id)?;
    Ok(envelope)
}

fn trace_record_artifact_receipt_matches_store(
    record: &TraceCommonsSubmissionRecord,
    receipt: &EncryptedTraceArtifactReceipt,
    configured_object_store: &str,
) -> anyhow::Result<bool> {
    if let Some(object_store) = trace_record_explicit_artifact_object_store(record, receipt) {
        anyhow::ensure!(
            object_store == configured_object_store,
            "configured trace artifact store does not match submission artifact store"
        );
        return Ok(true);
    }
    Ok(matches!(
        configured_object_store,
        TRACE_COMMONS_LEGACY_ENCRYPTED_OBJECT_STORE
            | TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE
    ))
}

fn ensure_envelope_tenant_scope(
    envelope: &TraceContributionEnvelope,
    tenant_id: &str,
) -> anyhow::Result<()> {
    if let Some(scope_ref) = envelope.contributor.tenant_scope_ref.as_deref()
        && looks_like_server_tenant_storage_ref(scope_ref)
    {
        anyhow::ensure!(
            scope_ref == tenant_storage_ref(tenant_id),
            "trace envelope tenant scope mismatch"
        );
    }
    Ok(())
}

/// Cross-check every server-owned tenant-bearing field on a fully-deserialized
/// envelope against the auth-derived tenant.
///
/// Server-owned refs look like `tenant_sha256:<32 hex>` (see
/// [`looks_like_server_tenant_storage_ref`]); client-supplied refs are left
/// untouched because they are attribution only. The KEK context binding stops
/// a tenant from lifting another tenant's ciphertext across the boundary, but
/// it does not catch a deserialized envelope whose embedded server-owned
/// tenant fields disagree with the authenticated tenant. This helper closes
/// that gap.
///
/// Error class string is stable and part of the contract:
/// `TenantDriftRejected: <field-class>`. Never include raw refs, contributor
/// identity, or other operator-secret material in the message.
fn verify_envelope_tenant_drift(
    envelope: &TraceContributionEnvelope,
    tenant_id: &str,
) -> anyhow::Result<()> {
    let expected = tenant_storage_ref(tenant_id);
    if let Some(scope_ref) = envelope.contributor.tenant_scope_ref.as_deref()
        && looks_like_server_tenant_storage_ref(scope_ref)
        && scope_ref != expected
    {
        anyhow::bail!(
            "TenantDriftRejected: contributor.tenant_scope_ref server tenant ref disagrees with authenticated tenant"
        );
    }
    Ok(())
}

#[cfg(test)]
mod envelope_tenant_drift_tests {
    use super::*;
    use trace_commons_protocol::llm::recording::TraceFile;
    use trace_commons_protocol::trace_contribution::{
        DeterministicTraceRedactor, RawTraceContribution, RecordedTraceContributionOptions,
        TraceContributionEnvelope, TraceRedactor,
    };

    async fn fixture_envelope(scope_ref: Option<String>) -> TraceContributionEnvelope {
        let trace = TraceFile {
            model_name: "test-model".to_string(),
            memory_snapshot: Vec::new(),
            http_exchanges: Vec::new(),
            steps: Vec::new(),
        };
        let raw = RawTraceContribution::from_recorded_trace(
            &trace,
            RecordedTraceContributionOptions {
                tenant_scope_ref: scope_ref,
                ..Default::default()
            },
        );
        DeterministicTraceRedactor::default()
            .redact_trace(raw)
            .await
            .expect("redaction succeeds for empty fixture")
    }

    #[tokio::test]
    async fn drift_rejected_when_server_scope_disagrees_with_auth_tenant() {
        let other_tenant_ref = tenant_storage_ref("other-tenant-id");
        let envelope = fixture_envelope(Some(other_tenant_ref)).await;
        let err = verify_envelope_tenant_drift(&envelope, "auth-tenant-id")
            .expect_err("must reject mismatched server tenant scope ref");
        let msg = err.to_string();
        assert!(
            msg.starts_with("TenantDriftRejected:"),
            "unexpected error class: {msg}"
        );
        assert!(
            msg.contains("contributor.tenant_scope_ref"),
            "error must name the field class: {msg}"
        );
        // Stability of error contract: no raw refs leak into the message.
        assert!(
            !msg.contains("tenant_sha256:"),
            "error must not leak raw refs: {msg}"
        );
    }

    #[tokio::test]
    async fn client_supplied_scope_is_attribution_only_and_accepted() {
        // A ref that does not match the server-owned format must be ignored.
        let envelope = fixture_envelope(Some("client-attribution://acme".to_string())).await;
        verify_envelope_tenant_drift(&envelope, "auth-tenant-id")
            .expect("client-supplied attribution refs must be accepted");
    }

    #[tokio::test]
    async fn missing_scope_ref_is_accepted() {
        let envelope = fixture_envelope(None).await;
        verify_envelope_tenant_drift(&envelope, "auth-tenant-id")
            .expect("envelopes without scope refs must be accepted");
    }

    #[tokio::test]
    async fn matching_server_scope_ref_is_accepted() {
        let matching = tenant_storage_ref("auth-tenant-id");
        let envelope = fixture_envelope(Some(matching)).await;
        verify_envelope_tenant_drift(&envelope, "auth-tenant-id")
            .expect("matching server tenant scope must be accepted");
    }
}

fn bind_envelope_server_tenant_scope_for_storage(
    envelope: &mut TraceContributionEnvelope,
    tenant_id: &str,
) {
    if envelope
        .contributor
        .tenant_scope_ref
        .as_deref()
        .is_some_and(looks_like_server_tenant_storage_ref)
    {
        envelope.contributor.tenant_scope_ref = Some(tenant_storage_ref(tenant_id));
    }
}

fn looks_like_server_tenant_storage_ref(value: &str) -> bool {
    let Some(hex_ref) = value.strip_prefix("tenant_sha256:") else {
        return false;
    };
    hex_ref.len() == 32 && hex_ref.chars().all(|ch| ch.is_ascii_hexdigit())
}

struct TraceEnvelopeBodyRead {
    envelope: TraceContributionEnvelope,
    object_ref_id: Option<Uuid>,
}

async fn read_envelope_for_replay_export(
    state: &AppState,
    tenant: &TenantAuth,
    record: &TraceCommonsSubmissionRecord,
    surface: &str,
    purpose: Option<&str>,
) -> anyhow::Result<TraceEnvelopeBodyRead> {
    anyhow::ensure!(
        tenant.role.can_export(),
        "trace body read requires reviewer, admin, or export worker role"
    );
    anyhow::ensure!(
        record.tenant_id == tenant.tenant_id,
        "trace body read tenant mismatch"
    );
    anyhow::ensure!(
        record.is_export_eligible(),
        "trace body read source is not export eligible"
    );
    let body_read = read_envelope_body_for_replay_export(state, tenant, record).await?;
    let refs: &[Uuid] = match body_read.object_ref_id.as_ref() {
        Some(id) => std::slice::from_ref(id),
        None => &[],
    };
    append_trace_content_read_audit_per_source(
        state,
        tenant,
        record.submission_id,
        refs,
        surface,
        purpose,
    )
    .await?;
    Ok(body_read)
}

async fn read_envelope_for_review_decision(
    state: &AppState,
    tenant: &TenantAuth,
    record: &TraceCommonsSubmissionRecord,
    allow_file_body_fallback: bool,
    purpose: Option<&str>,
) -> anyhow::Result<TraceEnvelopeBodyRead> {
    anyhow::ensure!(
        tenant.role.can_review(),
        "trace review body read requires reviewer or admin role"
    );
    anyhow::ensure!(
        record.tenant_id == tenant.tenant_id,
        "trace review body read tenant mismatch"
    );
    let body_read =
        read_envelope_body_for_review_decision(state, tenant, record, allow_file_body_fallback)
            .await?;
    let refs: &[Uuid] = match body_read.object_ref_id.as_ref() {
        Some(id) => std::slice::from_ref(id),
        None => &[],
    };
    append_trace_content_read_audit_per_source(
        state,
        tenant,
        record.submission_id,
        refs,
        "review_decision",
        purpose,
    )
    .await?;
    Ok(body_read)
}

async fn read_envelope_for_process_evaluation(
    state: &AppState,
    tenant: &TenantAuth,
    record: &TraceCommonsSubmissionRecord,
    purpose: Option<&str>,
) -> anyhow::Result<TraceEnvelopeBodyRead> {
    anyhow::ensure!(
        tenant.role.can_review() || tenant.role == TokenRole::ProcessEvalWorker,
        "trace process evaluation body read requires reviewer, admin, or process evaluation worker role"
    );
    anyhow::ensure!(
        record.tenant_id == tenant.tenant_id,
        "trace process evaluation body read tenant mismatch"
    );
    anyhow::ensure!(
        record.status == TraceCorpusStatus::Accepted,
        "trace process evaluation source is not accepted"
    );
    let body_read = if state.db_reviewer_reads_for_tenant(&tenant.tenant_id) {
        if let Some(envelope) =
            read_envelope_from_active_db_object_ref(state, &tenant.tenant_id, record.submission_id)
                .await?
        {
            envelope
        } else {
            anyhow::ensure!(
                !state.db_reviewer_require_object_refs_for_tenant(&tenant.tenant_id),
                "missing active submitted envelope object ref for process evaluation"
            );
            TraceEnvelopeBodyRead {
                envelope: read_envelope_by_record(state, record)?,
                object_ref_id: None,
            }
        }
    } else {
        TraceEnvelopeBodyRead {
            envelope: read_envelope_by_record(state, record)?,
            object_ref_id: None,
        }
    };
    let refs: &[Uuid] = match body_read.object_ref_id.as_ref() {
        Some(id) => std::slice::from_ref(id),
        None => &[],
    };
    append_trace_content_read_audit_per_source(
        state,
        tenant,
        record.submission_id,
        refs,
        "process_evaluation_worker",
        purpose,
    )
    .await?;
    Ok(body_read)
}

async fn read_envelope_body_for_review_decision(
    state: &AppState,
    tenant: &TenantAuth,
    record: &TraceCommonsSubmissionRecord,
    allow_file_body_fallback: bool,
) -> anyhow::Result<TraceEnvelopeBodyRead> {
    if state.db_reviewer_reads_for_tenant(&tenant.tenant_id)
        && let Some(envelope) =
            read_envelope_from_active_db_object_ref(state, &tenant.tenant_id, record.submission_id)
                .await?
    {
        return Ok(envelope);
    }
    anyhow::ensure!(
        !state.db_reviewer_require_object_refs_for_tenant(&tenant.tenant_id)
            && allow_file_body_fallback,
        "missing active submitted envelope object ref for review decision"
    );
    Ok(TraceEnvelopeBodyRead {
        envelope: read_envelope_by_record(state, record)?,
        object_ref_id: None,
    })
}

async fn read_envelope_body_for_replay_export(
    state: &AppState,
    tenant: &TenantAuth,
    record: &TraceCommonsSubmissionRecord,
) -> anyhow::Result<TraceEnvelopeBodyRead> {
    if state.db_replay_export_reads_for_tenant(&tenant.tenant_id) {
        if let Some(envelope) =
            read_envelope_from_active_db_object_ref(state, &tenant.tenant_id, record.submission_id)
                .await?
        {
            return Ok(envelope);
        }
        anyhow::ensure!(
            !state.db_replay_export_require_object_refs_for_tenant(&tenant.tenant_id),
            "missing active submitted envelope object ref for replay export"
        );
    }
    Ok(TraceEnvelopeBodyRead {
        envelope: read_envelope_by_record(state, record)?,
        object_ref_id: None,
    })
}

async fn read_envelope_from_active_db_object_ref(
    state: &AppState,
    tenant_id: &str,
    submission_id: Uuid,
) -> anyhow::Result<Option<TraceEnvelopeBodyRead>> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(None);
    };
    let Some(object_ref) = db
        .get_latest_active_trace_object_ref(
            tenant_id,
            submission_id,
            StorageTraceObjectArtifactKind::SubmittedEnvelope,
        )
        .await
        .with_context(|| {
            format!(
                "failed to read active submitted envelope object ref for submission {submission_id}"
            )
        })?
    else {
        return Ok(None);
    };
    let envelope = read_envelope_from_object_ref(state, tenant_id, &object_ref)?;
    Ok(Some(TraceEnvelopeBodyRead {
        envelope,
        object_ref_id: Some(object_ref.object_ref_id),
    }))
}

fn read_envelope_from_object_ref(
    state: &AppState,
    tenant_id: &str,
    object_ref: &StorageTraceObjectRefRecord,
) -> anyhow::Result<TraceContributionEnvelope> {
    anyhow::ensure!(
        object_ref.tenant_id == tenant_id,
        "trace object ref tenant mismatch"
    );
    anyhow::ensure!(
        matches!(
            object_ref.artifact_kind,
            StorageTraceObjectArtifactKind::SubmittedEnvelope
                | StorageTraceObjectArtifactKind::ReviewSnapshot
        ),
        "trace object ref artifact kind mismatch"
    );
    anyhow::ensure!(
        object_ref.compression.is_none(),
        "compressed trace object refs are not supported"
    );
    ensure_local_trace_object_ref_key_ref(object_ref, tenant_id)?;

    let envelope = match object_ref.object_store.as_str() {
        object_store if is_encrypted_trace_object_store(object_store) => {
            let store = state
                .artifact_store
                .as_ref()
                .context("encrypted trace artifact store is not configured")?;
            anyhow::ensure!(
                store.object_store_name() == object_ref.object_store,
                TRACE_OBJECT_REF_STORE_MISMATCH
            );
            store.get_json_by_object_key(
                &tenant_storage_ref(tenant_id),
                TraceArtifactKind::ContributionEnvelope,
                &object_ref.object_key,
                &object_ref.content_sha256,
            )
        }?,
        TRACE_COMMONS_FILE_OBJECT_STORE => {
            read_file_store_envelope_from_object_ref(state, object_ref)?
        }
        other => anyhow::bail!("unsupported trace object store: {other}"),
    };
    ensure_envelope_tenant_scope(&envelope, tenant_id)?;
    verify_envelope_tenant_drift(&envelope, tenant_id)?;
    Ok(envelope)
}

fn read_trace_vector_payload_from_object_ref(
    state: &AppState,
    tenant_id: &str,
    object_ref: &StorageTraceObjectRefRecord,
) -> anyhow::Result<TraceVectorPayloadArtifact> {
    anyhow::ensure!(
        object_ref.tenant_id == tenant_id,
        "trace vector payload object ref tenant mismatch"
    );
    anyhow::ensure!(
        object_ref.artifact_kind == StorageTraceObjectArtifactKind::WorkerIntermediate,
        "trace vector payload object ref artifact kind mismatch"
    );
    anyhow::ensure!(
        object_ref.compression.is_none(),
        "compressed trace vector payload object refs are not supported"
    );
    ensure_local_trace_object_ref_key_ref(object_ref, tenant_id)?;
    let store = state
        .artifact_store
        .as_ref()
        .context("encrypted trace vector payload store is not configured")?;
    anyhow::ensure!(
        store.object_store_name() == object_ref.object_store,
        TRACE_OBJECT_REF_STORE_MISMATCH
    );
    let payload = store
        .get_json_by_object_key::<TraceVectorPayloadArtifact>(
            &tenant_storage_ref(tenant_id),
            TraceArtifactKind::VectorPayload,
            &object_ref.object_key,
            &object_ref.content_sha256,
        )
        .context("failed to read trace vector payload object ref")?;
    ensure_vector_payload_tenant(&payload, tenant_id)?;
    anyhow::ensure!(
        payload.artifact_schema_version == TRACE_VECTOR_PAYLOAD_SCHEMA_VERSION
            && payload.submission_id == object_ref.submission_id
            && object_ref.created_by_job_id == Some(payload.vector_entry_id),
        "trace vector payload object ref payload mismatch"
    );
    Ok(payload)
}

fn ensure_local_trace_object_ref_key_ref(
    object_ref: &StorageTraceObjectRefRecord,
    tenant_id: &str,
) -> anyhow::Result<()> {
    if matches!(
        object_ref.object_store.as_str(),
        TRACE_COMMONS_LEGACY_ENCRYPTED_OBJECT_STORE
            | TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE
            | TRACE_COMMONS_SERVICE_REMOTE_OBJECT_STORE
    ) {
        anyhow::ensure!(
            object_ref.encryption_key_ref == format!("tenant:{}", tenant_storage_ref(tenant_id)),
            TRACE_OBJECT_REF_ENCRYPTION_KEY_REF_MISMATCH
        );
    }
    Ok(())
}

fn is_encrypted_trace_object_store(object_store: &str) -> bool {
    matches!(
        object_store,
        TRACE_COMMONS_LEGACY_ENCRYPTED_OBJECT_STORE
            | TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE
            | TRACE_COMMONS_SERVICE_REMOTE_OBJECT_STORE
    )
}

fn is_service_owned_trace_object_store(object_store: &str) -> bool {
    matches!(
        object_store,
        TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE
            | TRACE_COMMONS_SERVICE_REMOTE_OBJECT_STORE
    )
}

fn revocation_payload_delete_skip_reason_for_object_store(object_store: &str) -> &'static str {
    if object_store == TRACE_COMMONS_SERVICE_REMOTE_DISABLED_OBJECT_STORE {
        "object payload deletion skipped because remote object-store IO is disabled"
    } else {
        "object payload deletion currently supports only enabled service-owned encrypted objects"
    }
}

fn is_supported_service_owned_physical_delete_artifact_kind(
    artifact_kind: StorageTraceObjectArtifactKind,
) -> bool {
    matches!(
        artifact_kind,
        StorageTraceObjectArtifactKind::SubmittedEnvelope
            | StorageTraceObjectArtifactKind::RescrubbedEnvelope
            | StorageTraceObjectArtifactKind::ReviewSnapshot
            | StorageTraceObjectArtifactKind::WorkerIntermediate
            | StorageTraceObjectArtifactKind::BenchmarkArtifact
            | StorageTraceObjectArtifactKind::ExportArtifact
    )
}

fn read_file_store_envelope_from_object_ref(
    state: &AppState,
    object_ref: &StorageTraceObjectRefRecord,
) -> anyhow::Result<TraceContributionEnvelope> {
    let path = trace_object_ref_file_path(&state.root, &object_ref.object_key)?;
    let body = std::fs::read_to_string(&path)
        .with_context(|| format!("failed to read trace object {}", path.display()))?;
    let content_sha256 = sha256_prefixed(&body);
    anyhow::ensure!(
        content_sha256 == object_ref.content_sha256,
        TRACE_OBJECT_REF_CONTENT_HASH_MISMATCH
    );
    serde_json::from_str(&body)
        .with_context(|| format!("failed to parse trace object {}", path.display()))
}

const TRACE_OBJECT_REF_CONTENT_HASH_MISMATCH: &str = "trace object ref content hash mismatch";
const TRACE_OBJECT_REF_ENCRYPTION_KEY_REF_MISMATCH: &str =
    "trace object ref encryption key ref mismatch";
const TRACE_OBJECT_REF_STORE_MISMATCH: &str = "trace object ref store mismatch";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TraceObjectRefReadFailureKind {
    HashMismatch,
    KeyRefMismatch,
    StoreMismatch,
    Unreadable,
}

fn classify_trace_object_ref_read_failure(error: &anyhow::Error) -> TraceObjectRefReadFailureKind {
    if error.chain().any(|cause| {
        cause
            .to_string()
            .contains(TRACE_OBJECT_REF_CONTENT_HASH_MISMATCH)
    }) {
        TraceObjectRefReadFailureKind::HashMismatch
    } else if error.chain().any(|cause| {
        cause
            .to_string()
            .contains(TRACE_OBJECT_REF_ENCRYPTION_KEY_REF_MISMATCH)
    }) {
        TraceObjectRefReadFailureKind::KeyRefMismatch
    } else if error
        .chain()
        .any(|cause| cause.to_string().contains(TRACE_OBJECT_REF_STORE_MISMATCH))
    {
        TraceObjectRefReadFailureKind::StoreMismatch
    } else {
        TraceObjectRefReadFailureKind::Unreadable
    }
}

fn trace_object_ref_file_path(root: &Path, object_key: &str) -> anyhow::Result<PathBuf> {
    let relative_path = Path::new(object_key);
    anyhow::ensure!(
        relative_path.is_relative(),
        "trace object ref file key must be relative"
    );
    anyhow::ensure!(
        relative_path
            .components()
            .all(|component| matches!(component, std::path::Component::Normal(_))),
        "trace object ref file key contains unsafe path components"
    );
    Ok(root.join(relative_path))
}

#[derive(Debug, Default)]
struct TraceObjectDeletionCounts {
    file_deleted: bool,
    encrypted_artifact_deleted: bool,
    deleted_targets: Vec<TraceObjectDeletionTarget>,
}

#[derive(Debug)]
struct TraceObjectDeletionTarget {
    object_store: String,
    object_key: String,
}

fn delete_trace_objects_for_record(
    state: &AppState,
    record: &TraceCommonsSubmissionRecord,
) -> anyhow::Result<TraceObjectDeletionCounts> {
    let mut counts = TraceObjectDeletionCounts::default();
    let path = state.root.join(&record.object_key);
    if path.exists() {
        std::fs::remove_file(&path)
            .with_context(|| format!("failed to delete trace object {}", path.display()))?;
        counts.file_deleted = true;
        counts.deleted_targets.push(TraceObjectDeletionTarget {
            object_store: TRACE_COMMONS_FILE_OBJECT_STORE.to_string(),
            object_key: record.object_key.clone(),
        });
    }
    if let (Some(store), Some(receipt)) = (
        state.artifact_store.as_ref(),
        record.artifact_receipt.as_ref(),
    ) {
        counts.encrypted_artifact_deleted =
            store.delete_artifact(&record.tenant_storage_ref, receipt)?;
        if counts.encrypted_artifact_deleted {
            counts.deleted_targets.push(TraceObjectDeletionTarget {
                object_store: store.object_store_name().to_string(),
                object_key: receipt.object_key.clone(),
            });
        }
    }
    Ok(counts)
}

fn cleanup_submission_file_side_writes(
    state: &AppState,
    record: &TraceCommonsSubmissionRecord,
) -> anyhow::Result<()> {
    remove_file_if_exists(&submission_metadata_path(
        &state.root,
        &record.tenant_id,
        record.submission_id,
    ))?;
    remove_file_if_exists(&derived_record_path(
        &state.root,
        &record.tenant_id,
        record.submission_id,
    ))?;
    delete_trace_objects_for_record(state, record)?;
    Ok(())
}

fn cleanup_export_artifact_publication(
    state: &AppState,
    tenant_id: &str,
    artifact_kind: TraceArtifactKind,
    artifact_object_ref_material: Option<&TraceExportArtifactObjectRefMaterial>,
    file_paths: &[PathBuf],
) -> anyhow::Result<()> {
    for path in file_paths {
        remove_file_if_exists(path)?;
    }

    let (Some(store), Some(material)) =
        (state.artifact_store.as_ref(), artifact_object_ref_material)
    else {
        return Ok(());
    };
    if material.object_store != store.object_store_name() {
        return Ok(());
    }
    let tenant_ref = tenant_storage_ref(tenant_id);
    let receipt = EncryptedTraceArtifactReceipt {
        tenant_storage_ref: tenant_ref.clone(),
        artifact_kind,
        object_key: material.object_key.clone(),
        ciphertext_sha256: material
            .content_sha256
            .strip_prefix("sha256:")
            .unwrap_or(&material.content_sha256)
            .to_string(),
        encrypted_at: Utc::now(),
    };
    store.delete_artifact(&tenant_ref, &receipt)?;
    Ok(())
}

async fn rollback_db_export_manifest_publication(
    state: &AppState,
    tenant_id: &str,
    export_manifest_id: Uuid,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    db.delete_trace_export_manifest_mirror(tenant_id, export_manifest_id)
        .await
        .with_context(|| {
            format!("failed to roll back trace export manifest publication {export_manifest_id}")
        })
}

fn remove_file_if_exists(path: &Path) -> anyhow::Result<bool> {
    if !path.exists() {
        return Ok(false);
    }
    std::fs::remove_file(path)
        .with_context(|| format!("failed to remove trace file-side state {}", path.display()))?;
    Ok(true)
}

fn read_all_submission_records(
    root: &Path,
    tenant_id: &str,
) -> anyhow::Result<Vec<TraceCommonsSubmissionRecord>> {
    let tenant_key = tenant_storage_key(tenant_id);
    let dir = root.join("tenants").join(tenant_key).join("metadata");
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in std::fs::read_dir(&dir)
        .with_context(|| format!("failed to read trace metadata dir {}", dir.display()))?
    {
        let entry = entry.context("failed to read trace metadata entry")?;
        let path = entry.path();
        if path.extension().is_none_or(|ext| ext != "json") {
            continue;
        }
        let body = std::fs::read_to_string(&path)
            .with_context(|| format!("failed to read trace metadata {}", path.display()))?;
        let record: TraceCommonsSubmissionRecord = serde_json::from_str(&body)
            .with_context(|| format!("failed to parse trace metadata {}", path.display()))?;
        ensure_submission_record_tenant(&record, tenant_id)?;
        records.push(record);
    }
    records.sort_by_key(|record| record.received_at);
    Ok(records)
}

#[derive(Debug)]
struct TraceBackfillFileRead<T> {
    records: Vec<T>,
    failures: Vec<TraceBackfillFailure>,
}

impl<T> Default for TraceBackfillFileRead<T> {
    fn default() -> Self {
        Self {
            records: Vec::new(),
            failures: Vec::new(),
        }
    }
}

fn read_all_submission_records_for_backfill(
    root: &Path,
    tenant_id: &str,
) -> anyhow::Result<TraceBackfillFileRead<TraceCommonsSubmissionRecord>> {
    let tenant_key = tenant_storage_key(tenant_id);
    let dir = root.join("tenants").join(tenant_key).join("metadata");
    if !dir.exists() {
        return Ok(TraceBackfillFileRead::default());
    }

    let mut read = TraceBackfillFileRead::default();
    for entry in std::fs::read_dir(&dir)
        .with_context(|| format!("failed to read trace metadata dir {}", dir.display()))?
    {
        let entry = entry.context("failed to read trace metadata entry")?;
        let path = entry.path();
        if path.extension().is_none_or(|ext| ext != "json") {
            continue;
        }
        let item_ref = trace_backfill_file_item_ref(&path);
        let body = match std::fs::read_to_string(&path) {
            Ok(body) => body,
            Err(error) => {
                read.failures.push(TraceBackfillFailure {
                    item_kind: "submission_metadata".to_string(),
                    item_ref,
                    reason: format!("failed to read trace metadata: {error}"),
                });
                continue;
            }
        };
        let record: TraceCommonsSubmissionRecord = match serde_json::from_str(&body) {
            Ok(record) => record,
            Err(error) => {
                read.failures.push(TraceBackfillFailure {
                    item_kind: "submission_metadata".to_string(),
                    item_ref,
                    reason: format!("failed to parse trace metadata: {error}"),
                });
                continue;
            }
        };
        if let Err(error) = ensure_submission_record_tenant(&record, tenant_id) {
            read.failures.push(TraceBackfillFailure {
                item_kind: "submission_metadata".to_string(),
                item_ref,
                reason: error.to_string(),
            });
            continue;
        }
        read.records.push(record);
    }
    read.records.sort_by_key(|record| record.received_at);
    Ok(read)
}

fn trace_backfill_file_item_ref(path: &Path) -> String {
    let Some(file_stem) = path
        .file_stem()
        .and_then(|value| value.to_str())
        .filter(|value| !value.is_empty())
    else {
        return "unknown".to_string();
    };
    if Uuid::parse_str(file_stem).is_ok() {
        file_stem.to_string()
    } else {
        format!("file_name_hash:{}", sha256_prefixed(file_stem))
    }
}

const TRACE_SIMILARITY_NEIGHBOR_THRESHOLD: f32 = 0.25;
const TRACE_SIMILARITY_MAX_NEIGHBORS: usize = 5;

#[derive(Debug, Clone)]
struct TraceSimilarityCandidate<'a> {
    submission_id: Uuid,
    trace_id: Uuid,
    canonical_summary: Option<&'a str>,
    canonical_summary_hash: Option<&'a str>,
}

#[derive(Debug, Clone)]
struct TraceSimilarityNeighbor {
    trace_id: String,
    source_hash: Option<String>,
    score: f32,
}

fn nearest_trace_neighbors<'a>(
    target_submission_id: Uuid,
    target_summary: &str,
    target_hash: &str,
    candidates: impl IntoIterator<Item = TraceSimilarityCandidate<'a>>,
) -> Vec<TraceSimilarityNeighbor> {
    let mut neighbors = candidates
        .into_iter()
        .filter(|candidate| candidate.submission_id != target_submission_id)
        .filter_map(|candidate| {
            let score = trace_summary_similarity_score(
                target_summary,
                target_hash,
                candidate.canonical_summary,
                candidate.canonical_summary_hash,
            );
            (score >= TRACE_SIMILARITY_NEIGHBOR_THRESHOLD).then(|| TraceSimilarityNeighbor {
                trace_id: candidate.trace_id.to_string(),
                source_hash: candidate.canonical_summary_hash.map(str::to_string),
                score,
            })
        })
        .collect::<Vec<_>>();
    neighbors.sort_by(|left, right| {
        right
            .score
            .partial_cmp(&left.score)
            .unwrap_or(Ordering::Equal)
            .then_with(|| left.trace_id.cmp(&right.trace_id))
    });
    neighbors.truncate(TRACE_SIMILARITY_MAX_NEIGHBORS);
    neighbors
}

fn trace_summary_similarity_score(
    target_summary: &str,
    target_hash: &str,
    candidate_summary: Option<&str>,
    candidate_hash: Option<&str>,
) -> f32 {
    if candidate_hash.is_some_and(|hash| hash == target_hash) {
        return 1.0;
    }
    let Some(candidate_summary) = candidate_summary else {
        return 0.0;
    };
    let target_embedding = trace_redacted_summary_embedding(target_summary);
    let candidate_embedding = trace_redacted_summary_embedding(candidate_summary);
    trace_summary_embedding_similarity(&target_embedding, &candidate_embedding).max(
        trace_summary_token_similarity(target_summary, candidate_summary),
    )
}

fn trace_summary_token_similarity(left: &str, right: &str) -> f32 {
    let left_tokens = trace_similarity_tokens(left);
    let right_tokens = trace_similarity_tokens(right);
    if left_tokens.is_empty() || right_tokens.is_empty() {
        return 0.0;
    }
    let intersection = left_tokens.intersection(&right_tokens).count() as f32;
    let union = left_tokens.union(&right_tokens).count() as f32;
    if union == 0.0 {
        0.0
    } else {
        (intersection / union).clamp(0.0, 1.0)
    }
}

fn trace_vector_embedding_input(record: &StorageTraceDerivedRecord) -> String {
    let mut input = String::new();
    input.push_str("canonical_summary:\n");
    input.push_str(record.canonical_summary.as_deref().unwrap_or_default());
    input.push_str("\nsummary_model:\n");
    input.push_str(&record.summary_model);
    input.push_str("\ntask_success:\n");
    input.push_str(record.task_success.as_deref().unwrap_or_default());
    input.push_str("\nprivacy_risk:\n");
    input.push_str(record.privacy_risk.as_deref().unwrap_or_default());
    input.push_str("\ntools:\n");
    input.push_str(&record.tool_sequence.join(" "));
    input.push_str("\ntool_categories:\n");
    input.push_str(&record.tool_categories.join(" "));
    input.push_str("\ncoverage_tags:\n");
    input.push_str(&record.coverage_tags.join(" "));
    input
}

fn trace_redacted_summary_embedding(input: &str) -> Vec<f32> {
    let mut values = vec![0.0f32; TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_DIMENSION];
    for token in trace_similarity_tokens(input) {
        let digest = Sha256::digest(token.as_bytes());
        let mut index_bytes = [0u8; 8];
        index_bytes.copy_from_slice(&digest[..8]);
        let index = (u64::from_le_bytes(index_bytes) as usize)
            % TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_DIMENSION;
        let sign = if digest[8] & 1 == 0 { 1.0 } else { -1.0 };
        values[index] += sign;
    }
    let norm = values.iter().map(|value| value * value).sum::<f32>().sqrt();
    if norm > 0.0 {
        for value in &mut values {
            *value /= norm;
        }
    }
    values
}

fn trace_summary_embedding_similarity(left: &[f32], right: &[f32]) -> f32 {
    if left.is_empty() || right.is_empty() || left.len() != right.len() {
        return 0.0;
    }
    left.iter()
        .zip(right)
        .map(|(left, right)| left * right)
        .sum::<f32>()
        .clamp(0.0, 1.0)
}

fn trace_redacted_summary_embedding_sha256(values: &[f32]) -> String {
    trace_embedding_sha256(
        TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_MODEL,
        TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_ALGORITHM,
        TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_VERSION,
        values,
    )
}

fn trace_embedding_sha256(
    embedding_model: &str,
    embedding_algorithm: &str,
    embedding_version: &str,
    values: &[f32],
) -> String {
    let mut payload = format!(
        "{}:{}:{}:{}:",
        embedding_model,
        embedding_algorithm,
        embedding_version,
        values.len()
    );
    for value in values {
        payload.push_str(&format!("{:08x}", value.to_bits()));
    }
    sha256_prefixed(&payload)
}

#[derive(Debug)]
struct TraceVectorEmbeddingMaterial {
    vector_store: String,
    embedding_model: String,
    embedding_dimension: i32,
    embedding_version: String,
    embedding_algorithm: Option<String>,
    embedding_input_hash: String,
    embedding_values: Vec<f32>,
    embedding_sha256: String,
}

fn trace_vector_local_embedding_material(
    embedding_input_hash: String,
    embedding_input: &str,
) -> TraceVectorEmbeddingMaterial {
    let embedding_values = trace_redacted_summary_embedding(embedding_input);
    let embedding_sha256 = trace_redacted_summary_embedding_sha256(&embedding_values);
    TraceVectorEmbeddingMaterial {
        vector_store: "trace_commons_metadata_precheck".to_string(),
        embedding_model: TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_MODEL.to_string(),
        embedding_dimension: i32::try_from(TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_DIMENSION)
            .unwrap_or(i32::MAX),
        embedding_version: TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_VERSION.to_string(),
        embedding_algorithm: Some(TRACE_LOCAL_REDACTED_SUMMARY_EMBEDDING_ALGORITHM.to_string()),
        embedding_input_hash,
        embedding_values,
        embedding_sha256,
    }
}

fn validate_trace_vector_embedding_response(
    response: TraceVectorEmbeddingResponse,
) -> anyhow::Result<TraceVectorEmbeddingResponse> {
    let embedding_model = response.embedding_model.trim();
    anyhow::ensure!(
        !embedding_model.is_empty() && embedding_model.len() <= 512,
        "trace vector embedder response requires a bounded embedding_model"
    );
    let embedding_version = response.embedding_version.trim();
    anyhow::ensure!(
        !embedding_version.is_empty() && embedding_version.len() <= 256,
        "trace vector embedder response requires a bounded embedding_version"
    );
    anyhow::ensure!(
        !response.embedding_values.is_empty() && response.embedding_values.len() <= 8192,
        "trace vector embedder response embedding_values must contain 1..=8192 values"
    );
    anyhow::ensure!(
        response
            .embedding_values
            .iter()
            .all(|value| value.is_finite()),
        "trace vector embedder response embedding_values must be finite"
    );
    if let Some(algorithm) = response.embedding_algorithm.as_deref() {
        anyhow::ensure!(
            !algorithm.trim().is_empty() && algorithm.len() <= 256,
            "trace vector embedder response embedding_algorithm is not bounded"
        );
    }
    if let Some(vector_store) = response.vector_store.as_deref() {
        anyhow::ensure!(
            !vector_store.trim().is_empty() && vector_store.len() <= 256,
            "trace vector embedder response vector_store is not bounded"
        );
    }
    Ok(response)
}

fn trace_vector_external_embedding_material(
    embedding_input_hash: String,
    response: TraceVectorEmbeddingResponse,
) -> anyhow::Result<TraceVectorEmbeddingMaterial> {
    let response = validate_trace_vector_embedding_response(response)?;
    let embedding_dimension = i32::try_from(response.embedding_values.len())
        .context("trace vector embedding dimension does not fit storage schema")?;
    let embedding_model = response.embedding_model.trim().to_string();
    let embedding_version = response.embedding_version.trim().to_string();
    let embedding_algorithm = response
        .embedding_algorithm
        .as_deref()
        .map(str::trim)
        .map(str::to_string)
        .unwrap_or_else(|| "external_private_embedding".to_string());
    let embedding_sha256 = trace_embedding_sha256(
        &embedding_model,
        &embedding_algorithm,
        &embedding_version,
        &response.embedding_values,
    );
    Ok(TraceVectorEmbeddingMaterial {
        vector_store: response
            .vector_store
            .as_deref()
            .map(str::trim)
            .map(str::to_string)
            .unwrap_or_else(|| "trace_commons_private_embedding_adapter".to_string()),
        embedding_model,
        embedding_dimension,
        embedding_version,
        embedding_algorithm: Some(embedding_algorithm),
        embedding_input_hash,
        embedding_values: response.embedding_values,
        embedding_sha256,
    })
}

fn validate_trace_vector_search_response(
    response: TraceVectorSearchResponse,
) -> anyhow::Result<TraceVectorSearchResponse> {
    anyhow::ensure!(
        response.neighbors.len() <= 100,
        "trace vector searcher response neighbors must contain at most 100 entries"
    );
    for neighbor in &response.neighbors {
        anyhow::ensure!(
            neighbor.score.is_finite() && (0.0..=1.0).contains(&neighbor.score),
            "trace vector searcher response neighbor scores must be finite values between 0 and 1"
        );
    }
    Ok(response)
}

fn trace_vector_search_neighbors_from_response(
    target_submission_id: Uuid,
    target: &TraceVectorEmbeddingMaterial,
    active_entries: &[StorageTraceVectorEntryRecord],
    trace_ids_by_vector_entry: &BTreeMap<Uuid, Uuid>,
    response: TraceVectorSearchResponse,
) -> Vec<TraceSimilarityNeighbor> {
    let active_entries_by_id = active_entries
        .iter()
        .filter(|entry| entry.status == StorageTraceVectorEntryStatus::Active)
        .filter(|entry| entry.invalidated_at.is_none() && entry.deleted_at.is_none())
        .map(|entry| (entry.vector_entry_id, entry))
        .collect::<BTreeMap<_, _>>();
    let mut neighbors_by_trace_id: BTreeMap<String, TraceSimilarityNeighbor> = BTreeMap::new();
    for neighbor in response.neighbors {
        if !neighbor.score.is_finite()
            || !(TRACE_SIMILARITY_NEIGHBOR_THRESHOLD..=1.0).contains(&neighbor.score)
        {
            continue;
        }
        let Some(entry) = active_entries_by_id.get(&neighbor.vector_entry_id) else {
            continue;
        };
        if entry.submission_id == target_submission_id
            || entry.vector_store != target.vector_store
            || entry.embedding_model != target.embedding_model
            || entry.embedding_dimension != target.embedding_dimension
            || entry.embedding_version != target.embedding_version
        {
            continue;
        }
        let Some(trace_id) = trace_ids_by_vector_entry.get(&neighbor.vector_entry_id) else {
            continue;
        };
        let trace_id = trace_id.to_string();
        let candidate = TraceSimilarityNeighbor {
            trace_id: trace_id.clone(),
            source_hash: Some(entry.source_hash.clone()),
            score: neighbor.score,
        };
        match neighbors_by_trace_id.get(&trace_id) {
            Some(existing) if existing.score >= candidate.score => {}
            _ => {
                neighbors_by_trace_id.insert(trace_id, candidate);
            }
        }
    }
    let mut neighbors = neighbors_by_trace_id.into_values().collect::<Vec<_>>();
    neighbors.sort_by(|left, right| {
        right
            .score
            .partial_cmp(&left.score)
            .unwrap_or(Ordering::Equal)
            .then_with(|| left.trace_id.cmp(&right.trace_id))
    });
    neighbors.truncate(TRACE_SIMILARITY_MAX_NEIGHBORS);
    neighbors
}

#[derive(Debug, Clone)]
struct TraceVectorPayloadNeighborCandidate {
    submission_id: Uuid,
    trace_id: Uuid,
    source_hash: String,
    embedding_sha256: Option<String>,
    vector_store: String,
    embedding_model: String,
    embedding_dimension: i32,
    embedding_version: String,
    embedding_algorithm: Option<String>,
    embedding_values: Vec<f32>,
}

fn nearest_trace_vector_payload_neighbors(
    target_submission_id: Uuid,
    target: &TraceVectorEmbeddingMaterial,
    candidates: impl IntoIterator<Item = TraceVectorPayloadNeighborCandidate>,
) -> Vec<TraceSimilarityNeighbor> {
    let mut neighbors = candidates
        .into_iter()
        .filter(|candidate| candidate.submission_id != target_submission_id)
        .filter(|candidate| trace_vector_payload_candidate_is_compatible(target, candidate))
        .filter_map(|candidate| {
            let score = if candidate.embedding_sha256.as_deref() == Some(&target.embedding_sha256) {
                1.0
            } else {
                trace_summary_embedding_similarity(
                    &target.embedding_values,
                    &candidate.embedding_values,
                )
            };
            (score >= TRACE_SIMILARITY_NEIGHBOR_THRESHOLD).then(|| TraceSimilarityNeighbor {
                trace_id: candidate.trace_id.to_string(),
                source_hash: Some(
                    candidate
                        .embedding_sha256
                        .clone()
                        .unwrap_or(candidate.source_hash),
                ),
                score,
            })
        })
        .collect::<Vec<_>>();
    neighbors.sort_by(|left, right| {
        right
            .score
            .partial_cmp(&left.score)
            .unwrap_or(Ordering::Equal)
            .then_with(|| left.trace_id.cmp(&right.trace_id))
    });
    neighbors.truncate(TRACE_SIMILARITY_MAX_NEIGHBORS);
    neighbors
}

fn trace_vector_payload_candidate_is_compatible(
    target: &TraceVectorEmbeddingMaterial,
    candidate: &TraceVectorPayloadNeighborCandidate,
) -> bool {
    candidate.vector_store == target.vector_store
        && candidate.embedding_model == target.embedding_model
        && candidate.embedding_dimension == target.embedding_dimension
        && candidate.embedding_version == target.embedding_version
        && candidate.embedding_algorithm == target.embedding_algorithm
        && usize::try_from(candidate.embedding_dimension)
            .is_ok_and(|dimension| dimension == candidate.embedding_values.len())
        && candidate.embedding_values.len() == target.embedding_values.len()
        && !candidate.embedding_values.is_empty()
        && candidate
            .embedding_values
            .iter()
            .all(|value| value.is_finite())
}

fn trace_similarity_tokens(input: &str) -> BTreeSet<String> {
    const STOP_WORDS: &[&str] = &[
        "and", "are", "for", "from", "that", "the", "this", "trace", "with",
    ];

    let mut tokens = BTreeSet::new();
    let mut current = String::new();
    for ch in input.chars() {
        if ch.is_ascii_alphanumeric() || ch == '_' {
            current.push(ch.to_ascii_lowercase());
        } else {
            push_trace_similarity_token(&mut tokens, &mut current, STOP_WORDS);
        }
    }
    push_trace_similarity_token(&mut tokens, &mut current, STOP_WORDS);
    tokens
}

fn push_trace_similarity_token(
    tokens: &mut BTreeSet<String>,
    current: &mut String,
    stop_words: &[&str],
) {
    if current.len() > 1 && !stop_words.contains(&current.as_str()) {
        tokens.insert(std::mem::take(current));
    } else {
        current.clear();
    }
}

fn build_derived_precheck(
    envelope: &TraceContributionEnvelope,
    existing: &[TraceCommonsDerivedRecord],
) -> TraceCommonsDerivedPrecheck {
    let canonical_summary = canonical_summary_for_embedding(envelope);
    let canonical_summary_hash = sha256_prefixed(&canonical_summary);
    let neighbors = nearest_trace_neighbors(
        envelope.submission_id,
        &canonical_summary,
        &canonical_summary_hash,
        existing.iter().map(|record| TraceSimilarityCandidate {
            submission_id: record.submission_id,
            trace_id: record.trace_id,
            canonical_summary: Some(record.canonical_summary.as_str()),
            canonical_summary_hash: Some(record.canonical_summary_hash.as_str()),
        }),
    );
    let duplicate_score = neighbors
        .first()
        .map(|neighbor| neighbor.score)
        .unwrap_or_default();
    let novelty_score = if neighbors.is_empty() {
        0.65
    } else {
        (1.0 - duplicate_score).clamp(0.05, 0.95)
    };
    let coverage_tags = coverage_tags_for_envelope(envelope);

    TraceCommonsDerivedPrecheck {
        canonical_summary,
        canonical_summary_hash,
        nearest_trace_ids: neighbors
            .iter()
            .map(|neighbor| neighbor.trace_id.clone())
            .collect(),
        novelty_score,
        duplicate_score,
        coverage_tags,
    }
}

fn apply_embedding_precheck(
    envelope: &mut TraceContributionEnvelope,
    precheck: &TraceCommonsDerivedPrecheck,
) {
    let mut embedding = envelope
        .embedding_analysis
        .take()
        .unwrap_or(EmbeddingAnalysisMetadata {
            embedding_model: Some("redacted-summary-hash-precheck-v1".to_string()),
            canonical_summary_hash: String::new(),
            trace_vector_id: None,
            nearest_trace_ids: Vec::new(),
            cluster_id: None,
            nearest_cluster_id: None,
            novelty_score: None,
            duplicate_score: None,
            coverage_tags: Vec::new(),
        });

    if embedding.embedding_model.is_none() {
        embedding.embedding_model = Some("redacted-summary-hash-precheck-v1".to_string());
    }
    embedding.canonical_summary_hash = precheck.canonical_summary_hash.clone();
    embedding.nearest_trace_ids = precheck.nearest_trace_ids.clone();
    embedding.novelty_score = Some(precheck.novelty_score);
    embedding.duplicate_score = Some(precheck.duplicate_score);
    embedding.coverage_tags = precheck.coverage_tags.clone();
    envelope.embedding_analysis = Some(embedding);
}

fn build_derived_record(
    tenant_id: &str,
    status: TraceCorpusStatus,
    envelope: &TraceContributionEnvelope,
    precheck: TraceCommonsDerivedPrecheck,
) -> TraceCommonsDerivedRecord {
    TraceCommonsDerivedRecord {
        tenant_id: tenant_id.to_string(),
        tenant_storage_ref: tenant_storage_ref(tenant_id),
        derived_id: Some(deterministic_trace_uuid_for(
            "derived-precheck",
            tenant_id,
            envelope.submission_id,
        )),
        submission_id: envelope.submission_id,
        trace_id: envelope.trace_id,
        status,
        privacy_risk: envelope.privacy.residual_pii_risk,
        task_success: format!("{:?}", envelope.outcome.task_success),
        canonical_summary: precheck.canonical_summary,
        canonical_summary_hash: precheck.canonical_summary_hash,
        summary_model: "redacted-summary-hash-precheck-v1".to_string(),
        event_count: envelope.events.len(),
        tool_sequence: envelope.replay.required_tools.clone(),
        tool_categories: envelope
            .events
            .iter()
            .filter_map(|event| event.tool_category.clone())
            .collect::<std::collections::BTreeSet<_>>()
            .into_iter()
            .collect(),
        coverage_tags: precheck.coverage_tags,
        duplicate_score: precheck.duplicate_score,
        novelty_score: precheck.novelty_score,
        created_at: Utc::now(),
    }
}

fn coverage_tags_for_envelope(envelope: &TraceContributionEnvelope) -> Vec<String> {
    let mut tags = std::collections::BTreeSet::new();
    tags.insert(format!("channel:{:?}", envelope.ironclaw.channel).to_ascii_lowercase());
    tags.insert(format!("outcome:{:?}", envelope.outcome.task_success).to_ascii_lowercase());
    tags.insert(format!("privacy:{:?}", envelope.privacy.residual_pii_risk).to_ascii_lowercase());

    for tool in &envelope.replay.required_tools {
        tags.insert(format!("tool:{tool}"));
    }
    for event in &envelope.events {
        if let Some(category) = &event.tool_category {
            tags.insert(format!("tool_category:{category}"));
        }
        for failure_mode in &event.failure_modes {
            tags.insert(format!("failure:{failure_mode:?}").to_ascii_lowercase());
        }
    }
    for failure_mode in &envelope.outcome.failure_modes {
        tags.insert(format!("failure:{failure_mode:?}").to_ascii_lowercase());
    }
    if let Some(process_evaluation) = &envelope.process_evaluation {
        for label in &process_evaluation.labels {
            tags.insert(format!("process_label:{}", serde_enum_tag(label)));
        }
        insert_process_eval_rating_tag(
            &mut tags,
            "tool_selection",
            process_evaluation.tool_selection,
        );
        insert_process_eval_rating_tag(
            &mut tags,
            "tool_argument_quality",
            process_evaluation.tool_argument_quality,
        );
        insert_process_eval_rating_tag(
            &mut tags,
            "tool_ordering",
            process_evaluation.tool_ordering,
        );
        insert_process_eval_rating_tag(&mut tags, "verification", process_evaluation.verification);
        insert_process_eval_rating_tag(
            &mut tags,
            "side_effect_safety",
            process_evaluation.side_effect_safety,
        );
        if let Some(score) = process_evaluation.overall_score {
            tags.insert(format!("process_eval:{}", process_eval_score_band(score)));
        }
    }
    if let Some(training_dynamics) = &envelope.training_dynamics
        && let Some(bucket) = training_dynamics.cartography_bucket
    {
        tags.insert(format!("cartography:{bucket:?}").to_ascii_lowercase());
    }
    if let Some(hindsight) = &envelope.hindsight {
        if hindsight.benchmark_candidate {
            tags.insert("hindsight:benchmark_candidate".to_string());
        }
        if hindsight.relabeled_training_candidate {
            tags.insert("hindsight:relabeled_training_candidate".to_string());
        }
        if let Some(failure_type) = &hindsight.failure_type {
            tags.insert(format!("hindsight_failure:{failure_type:?}").to_ascii_lowercase());
        }
    }
    tags.into_iter().collect()
}

fn insert_process_eval_rating_tag(
    tags: &mut BTreeSet<String>,
    axis: &str,
    rating: Option<ProcessEvalRating>,
) {
    if let Some(rating) = rating {
        tags.insert(format!("process_{axis}:{}", serde_enum_tag(&rating)));
    }
}

fn process_eval_score_band(score: f32) -> &'static str {
    if score >= 0.8 {
        "high"
    } else if score >= 0.5 {
        "medium"
    } else {
        "low"
    }
}

fn serde_enum_tag<T>(value: &T) -> String
where
    T: Serialize + std::fmt::Debug,
{
    serde_json::to_value(value)
        .ok()
        .and_then(|value| value.as_str().map(ToOwned::to_owned))
        .unwrap_or_else(|| format!("{value:?}").to_ascii_lowercase())
}

fn write_derived_record(root: &Path, record: &TraceCommonsDerivedRecord) -> anyhow::Result<()> {
    ensure_derived_record_tenant(record, &record.tenant_id)?;
    let path = derived_record_path(root, &record.tenant_id, record.submission_id);
    write_json_file(&path, record, "trace derived record")
}

fn derived_record_path(root: &Path, tenant_id: &str, submission_id: Uuid) -> PathBuf {
    let tenant_key = tenant_storage_key(tenant_id);
    root.join("tenants")
        .join(tenant_key)
        .join("derived")
        .join(format!("{submission_id}.json"))
}

fn read_derived_record(
    root: &Path,
    tenant_id: &str,
    submission_id: Uuid,
) -> anyhow::Result<Option<TraceCommonsDerivedRecord>> {
    let path = derived_record_path(root, tenant_id, submission_id);
    if !path.exists() {
        return Ok(None);
    }
    let body = std::fs::read_to_string(&path)
        .with_context(|| format!("failed to read trace derived record {}", path.display()))?;
    let record = serde_json::from_str(&body)
        .with_context(|| format!("failed to parse trace derived record {}", path.display()))?;
    ensure_derived_record_tenant(&record, tenant_id)?;
    Ok(Some(record))
}

fn ensure_derived_record_tenant(
    record: &TraceCommonsDerivedRecord,
    tenant_id: &str,
) -> anyhow::Result<()> {
    anyhow::ensure!(
        record.tenant_id == tenant_id,
        "trace derived record tenant mismatch"
    );
    anyhow::ensure!(
        record.tenant_storage_ref == tenant_storage_ref(tenant_id),
        "trace derived record tenant storage ref mismatch"
    );
    Ok(())
}

fn read_all_derived_records(
    root: &Path,
    tenant_id: &str,
) -> anyhow::Result<Vec<TraceCommonsDerivedRecord>> {
    let tenant_key = tenant_storage_key(tenant_id);
    let dir = root.join("tenants").join(tenant_key).join("derived");
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in std::fs::read_dir(&dir)
        .with_context(|| format!("failed to read trace derived dir {}", dir.display()))?
    {
        let entry = entry.context("failed to read trace derived entry")?;
        let path = entry.path();
        if path.extension().is_none_or(|ext| ext != "json") {
            continue;
        }
        let body = std::fs::read_to_string(&path)
            .with_context(|| format!("failed to read trace derived record {}", path.display()))?;
        let record: TraceCommonsDerivedRecord = serde_json::from_str(&body)
            .with_context(|| format!("failed to parse trace derived record {}", path.display()))?;
        ensure_derived_record_tenant(&record, tenant_id)?;
        records.push(record);
    }
    records.sort_by_key(|record| record.created_at);
    Ok(records)
}

fn read_all_derived_records_for_backfill(
    root: &Path,
    tenant_id: &str,
) -> anyhow::Result<TraceBackfillFileRead<TraceCommonsDerivedRecord>> {
    let tenant_key = tenant_storage_key(tenant_id);
    let dir = root.join("tenants").join(tenant_key).join("derived");
    if !dir.exists() {
        return Ok(TraceBackfillFileRead::default());
    }

    let mut read = TraceBackfillFileRead::default();
    for entry in std::fs::read_dir(&dir)
        .with_context(|| format!("failed to read trace derived dir {}", dir.display()))?
    {
        let entry = entry.context("failed to read trace derived entry")?;
        let path = entry.path();
        if path.extension().is_none_or(|ext| ext != "json") {
            continue;
        }
        let item_ref = trace_backfill_file_item_ref(&path);
        let body = match std::fs::read_to_string(&path) {
            Ok(body) => body,
            Err(error) => {
                read.failures.push(TraceBackfillFailure {
                    item_kind: "derived_record".to_string(),
                    item_ref,
                    reason: format!("failed to read trace derived record: {error}"),
                });
                continue;
            }
        };
        let record: TraceCommonsDerivedRecord = match serde_json::from_str(&body) {
            Ok(record) => record,
            Err(error) => {
                read.failures.push(TraceBackfillFailure {
                    item_kind: "derived_record".to_string(),
                    item_ref,
                    reason: format!("failed to parse trace derived record: {error}"),
                });
                continue;
            }
        };
        if let Err(error) = ensure_derived_record_tenant(&record, tenant_id) {
            read.failures.push(TraceBackfillFailure {
                item_kind: "derived_record".to_string(),
                item_ref,
                reason: error.to_string(),
            });
            continue;
        }
        read.records.push(record);
    }
    read.records.sort_by_key(|record| record.created_at);
    Ok(read)
}

fn append_credit_event(
    root: &Path,
    tenant_id: &str,
    event: &TraceCommonsCreditLedgerRecord,
) -> anyhow::Result<()> {
    ensure_credit_event_tenant(event, tenant_id)?;
    let path = credit_ledger_path(root, tenant_id);
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("failed to create credit ledger dir {}", parent.display()))?;
    }
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
        .with_context(|| format!("failed to open credit ledger {}", path.display()))?;
    let line = serde_json::to_string(event).context("failed to serialize credit ledger event")?;
    writeln!(file, "{line}")
        .with_context(|| format!("failed to append credit ledger {}", path.display()))
}

fn credit_ledger_path(root: &Path, tenant_id: &str) -> PathBuf {
    let tenant_key = tenant_storage_key(tenant_id);
    root.join("tenants")
        .join(tenant_key)
        .join("credit_ledger")
        .join("events.jsonl")
}

fn read_all_credit_events(
    root: &Path,
    tenant_id: &str,
) -> anyhow::Result<Vec<TraceCommonsCreditLedgerRecord>> {
    let path = credit_ledger_path(root, tenant_id);
    if !path.exists() {
        return Ok(Vec::new());
    }

    let body = std::fs::read_to_string(&path)
        .with_context(|| format!("failed to read credit ledger {}", path.display()))?;
    let mut events = Vec::new();
    for (index, line) in body.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let event = serde_json::from_str(line).with_context(|| {
            format!(
                "failed to parse credit ledger event {} line {}",
                path.display(),
                index + 1
            )
        })?;
        ensure_credit_event_tenant(&event, tenant_id)?;
        events.push(event);
    }
    events.sort_by_key(|event: &TraceCommonsCreditLedgerRecord| event.created_at);
    Ok(events)
}

