const RANKING_CALIBRATION_DATASET_IMMUTABLE_MANIFEST_MESSAGE: &str =
    "ranking calibration dataset manifest is immutable for this target use and policy";
const RANKING_CALIBRATION_DATASET_MANIFEST_CONFLICT_REASON: &str =
    "calibration_dataset_manifest_conflict";
const RANKING_ADJUDICATION_ISSUES_REASON: &str = "ranking_adjudication_issues_present";

#[derive(Debug)]
struct RankingCalibrationDatasetReconciliationRead {
    records: Vec<TraceRankingCalibrationDatasetRecord>,
    manifest_conflict_keys: Vec<String>,
}

fn ensure_ranking_calibration_dataset_append_allowed(
    root: &Path,
    tenant_id: &str,
    record: &TraceRankingCalibrationDatasetRecord,
) -> anyhow::Result<()> {
    let existing_records = read_all_ranking_calibration_datasets(root, tenant_id)?;
    anyhow::ensure!(
        !ranking_calibration_dataset_manifest_rewrite(&existing_records, record),
        RANKING_CALIBRATION_DATASET_IMMUTABLE_MANIFEST_MESSAGE
    );
    Ok(())
}

fn ranking_calibration_dataset_manifest_rewrite(
    existing_records: &[TraceRankingCalibrationDatasetRecord],
    record: &TraceRankingCalibrationDatasetRecord,
) -> bool {
    existing_records.iter().any(|existing| {
        existing.calibration_dataset_hash == record.calibration_dataset_hash
            && existing.target_use == record.target_use
            && existing.policy_version == record.policy_version
            && (existing.source_manifest_hash != record.source_manifest_hash
                || existing.source_count != record.source_count
                || existing.label_source_count != record.label_source_count
                || existing.label_actor_count != record.label_actor_count)
    })
}

fn read_all_ranking_calibration_datasets(
    root: &Path,
    tenant_id: &str,
) -> anyhow::Result<Vec<TraceRankingCalibrationDatasetRecord>> {
    let read = read_ranking_calibration_datasets_for_reconciliation(root, tenant_id)?;
    anyhow::ensure!(
        read.manifest_conflict_keys.is_empty(),
        RANKING_CALIBRATION_DATASET_IMMUTABLE_MANIFEST_MESSAGE
    );
    Ok(read.records)
}

fn read_ranking_calibration_datasets_for_reconciliation(
    root: &Path,
    tenant_id: &str,
) -> anyhow::Result<RankingCalibrationDatasetReconciliationRead> {
    let path = ranking_calibration_datasets_path(root, tenant_id);
    if !path.exists() {
        return Ok(RankingCalibrationDatasetReconciliationRead {
            records: Vec::new(),
            manifest_conflict_keys: Vec::new(),
        });
    }
    let records: Vec<TraceRankingCalibrationDatasetRecord> =
        read_jsonl_records(&path, "ranking calibration dataset")?;
    let mut latest_by_key = BTreeMap::new();
    let mut manifest_by_key = BTreeMap::new();
    let mut manifest_conflict_keys_by_key = BTreeMap::new();
    for record in records {
        ensure_ranking_calibration_dataset_tenant(&record, tenant_id)?;
        let key = (
            record.calibration_dataset_hash.clone(),
            record.target_use,
            record.policy_version.clone(),
        );
        let key_string = ranking_calibration_dataset_file_key(&record)?;
        let manifest = (
            record.source_manifest_hash.clone(),
            record.source_count,
            record.label_source_count,
            record.label_actor_count,
        );
        if let Some(existing_manifest) = manifest_by_key.get(&key) {
            if existing_manifest != &manifest {
                manifest_conflict_keys_by_key.insert(key.clone(), key_string);
            }
        } else {
            manifest_by_key.insert(key.clone(), manifest);
        }
        latest_by_key.insert(key, record);
    }
    let manifest_conflict_keys = manifest_conflict_keys_by_key
        .into_iter()
        .filter_map(|(key, key_string)| {
            latest_by_key
                .get(&key)
                .is_none_or(|record| !ranking_calibration_dataset_status_is_retired(record.status))
                .then_some(key_string)
        })
        .collect::<BTreeSet<_>>();
    let mut records = latest_by_key.into_values().collect::<Vec<_>>();
    records.sort_by_key(|record| record.created_at);
    Ok(RankingCalibrationDatasetReconciliationRead {
        records,
        manifest_conflict_keys: manifest_conflict_keys.into_iter().collect(),
    })
}

