fn append_jsonl_record<T: Serialize>(path: &Path, value: &T, label: &str) -> anyhow::Result<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("failed to create {label} dir {}", parent.display()))?;
    }
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .with_context(|| format!("failed to open {label} {}", path.display()))?;
    let line =
        serde_json::to_string(value).with_context(|| format!("failed to serialize {label}"))?;
    writeln!(file, "{line}").with_context(|| format!("failed to append {label} {}", path.display()))
}

fn read_jsonl_records<T: DeserializeOwned>(path: &Path, label: &str) -> anyhow::Result<Vec<T>> {
    let body = std::fs::read_to_string(path)
        .with_context(|| format!("failed to read {label} {}", path.display()))?;
    let mut records = Vec::new();
    for (index, line) in body.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let record = serde_json::from_str(line).with_context(|| {
            format!(
                "failed to parse {label} {} line {}",
                path.display(),
                index + 1
            )
        })?;
        records.push(record);
    }
    Ok(records)
}

fn source_credit_event_ids_hash(policy_version: &str, source_credit_event_ids: &[Uuid]) -> String {
    let mut payload = format!("trace_credit_settlement:{policy_version}");
    for event_id in source_credit_event_ids {
        payload.push('\n');
        payload.push_str(&event_id.to_string());
    }
    sha256_prefixed(&payload)
}

fn write_revocation(root: &Path, tombstone: &TraceCommonsRevocation) -> anyhow::Result<()> {
    ensure_revocation_tenant(tombstone, &tombstone.tenant_id)?;
    let tenant_key = tenant_storage_key(&tombstone.tenant_id);
    let path = root
        .join("tenants")
        .join(tenant_key)
        .join("revocations")
        .join(format!("{}.json", tombstone.submission_id));
    if path.exists() {
        return Ok(());
    }
    write_json_file(&path, tombstone, "trace revocation tombstone")
}

fn read_revocation(
    root: &Path,
    tenant_id: &str,
    submission_id: Uuid,
) -> anyhow::Result<Option<TraceCommonsRevocation>> {
    let tenant_key = tenant_storage_key(tenant_id);
    let path = root
        .join("tenants")
        .join(tenant_key)
        .join("revocations")
        .join(format!("{submission_id}.json"));
    if !path.exists() {
        return Ok(None);
    }
    let body = std::fs::read_to_string(&path)
        .with_context(|| format!("failed to read revocation {}", path.display()))?;
    let revocation = serde_json::from_str(&body)
        .with_context(|| format!("failed to parse revocation {}", path.display()))?;
    ensure_revocation_tenant(&revocation, tenant_id)?;
    Ok(Some(revocation))
}

fn append_audit_event(
    root: &Path,
    tenant_id: &str,
    mut event: TraceCommonsAuditEvent,
) -> anyhow::Result<TraceCommonsAuditEvent> {
    ensure_audit_event_tenant(&event, tenant_id)?;
    let path = audit_events_path(root, tenant_id);
    let previous_event_hash = latest_audit_event_hash(&path, tenant_id)?
        .unwrap_or_else(|| TRACE_AUDIT_EVENT_GENESIS_HASH.to_string());
    event.previous_event_hash = Some(previous_event_hash.clone());
    event.event_hash = None;
    event.event_hash = Some(compute_audit_event_hash(&previous_event_hash, &event)?);
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("failed to create audit dir {}", parent.display()))?;
    }
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
        .with_context(|| format!("failed to open audit log {}", path.display()))?;
    let line = serde_json::to_string(&event).context("failed to serialize audit event")?;
    writeln!(file, "{line}")
        .with_context(|| format!("failed to append audit log {}", path.display()))?;
    Ok(event)
}

fn audit_events_path(root: &Path, tenant_id: &str) -> PathBuf {
    let tenant_key = tenant_storage_key(tenant_id);
    root.join("tenants")
        .join(tenant_key)
        .join("audit")
        .join("events.jsonl")
}

const TRACE_AUDIT_EVENT_GENESIS_HASH: &str = "sha256:genesis";
const TRACE_AUDIT_EVENT_HASH_DOMAIN: &str = "trace_commons_audit_event:v1";

fn is_audit_chain_previous_hash(value: &str) -> bool {
    value == TRACE_AUDIT_EVENT_GENESIS_HASH || is_canonical_sha256_prefixed_hash(value)
}

fn latest_audit_event_hash(path: &Path, tenant_id: &str) -> anyhow::Result<Option<String>> {
    if !path.exists() {
        return Ok(None);
    }
    let body = std::fs::read_to_string(path)
        .with_context(|| format!("failed to read audit log {}", path.display()))?;
    let Some(line) = body
        .lines()
        .rev()
        .map(str::trim)
        .find(|line| !line.is_empty())
    else {
        return Ok(None);
    };
    let event: TraceCommonsAuditEvent = serde_json::from_str(line).with_context(|| {
        format!(
            "failed to parse latest audit event for hash chain {}",
            path.display()
        )
    })?;
    ensure_audit_event_tenant(&event, tenant_id)?;
    Ok(event.event_hash)
}

fn compute_audit_event_hash(
    previous_event_hash: &str,
    event: &TraceCommonsAuditEvent,
) -> anyhow::Result<String> {
    let canonical_event = canonical_audit_event_json(previous_event_hash, event)?;
    Ok(compute_audit_event_hash_from_canonical(
        previous_event_hash,
        &canonical_event,
    ))
}

fn canonical_audit_event_json(
    previous_event_hash: &str,
    event: &TraceCommonsAuditEvent,
) -> anyhow::Result<String> {
    let mut event_for_hash = event.clone();
    event_for_hash.previous_event_hash = Some(previous_event_hash.to_string());
    event_for_hash.event_hash = None;
    serde_json::to_string(&event_for_hash).context("failed to serialize audit event hash")
}

fn compute_audit_event_hash_from_canonical(
    previous_event_hash: &str,
    canonical_event: &str,
) -> String {
    sha256_prefixed(&format!(
        "{TRACE_AUDIT_EVENT_HASH_DOMAIN}\n{previous_event_hash}\n{canonical_event}"
    ))
}

async fn append_audit_event_with_db_mirror(
    state: &AppState,
    tenant: &TenantAuth,
    event: TraceCommonsAuditEvent,
    action: StorageTraceAuditAction,
    metadata: StorageTraceAuditSafeMetadata,
) -> anyhow::Result<()> {
    if state.require_db_mirror_writes {
        let mirror_result = mirror_audit_event_to_db(state, tenant, &event, action, metadata).await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_display_error_hash(error),
                event_id = %event.event_id,
                "Trace Commons DB dual-write audit mirror failed"
            );
        }
        enforce_db_mirror_write_result(state, "audit event", mirror_result)?;
        append_audit_event(&state.root, &tenant.tenant_id, event)?;
        return Ok(());
    }

    let event = append_audit_event(&state.root, &tenant.tenant_id, event)?;
    let mirror_result = mirror_audit_event_to_db(state, tenant, &event, action, metadata).await;
    if let Err(error) = &mirror_result {
        tracing::warn!(
            error_hash = %safe_display_error_hash(error),
            event_id = %event.event_id,
            "Trace Commons DB dual-write audit mirror failed"
        );
    }
    enforce_db_mirror_write_result(state, "audit event", mirror_result)?;
    verify_mirrored_audit_event_after_file_append(state, tenant, &event).await?;
    Ok(())
}

async fn verify_mirrored_audit_event_after_file_append(
    state: &AppState,
    tenant: &TenantAuth,
    event: &TraceCommonsAuditEvent,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    // Verification only applies when the file append already produced a
    // canonical hash. The require_db_mirror_writes=true branch writes DB
    // before file, so event.event_hash may be None there; skip in that case.
    if event.event_hash.is_none() {
        return Ok(());
    }
    let actual = db
        .get_trace_audit_event_by_id(&tenant.tenant_id, event.event_id)
        .await
        .with_context(|| {
            format!(
                "failed to re-read mirrored audit event {} for chain verification",
                event.event_id
            )
        })?;
    if let Err(drift) = audit_event_matches_writeback(
        event.event_id,
        event.event_hash.as_deref(),
        event.previous_event_hash.as_deref(),
        actual.as_ref(),
    ) {
        tracing::error!(
            error_class = AUDIT_CHAIN_DRIFT_REJECTED_CLASS,
            error_hash = %safe_display_error_hash(&anyhow::anyhow!(drift.to_string())),
            event_id = %event.event_id,
            "Trace Commons DB audit mirror hash chain verification failed"
        );
        return Err(anyhow::anyhow!(drift));
    }
    Ok(())
}

/// Backward-compatible shim. Prefer `append_trace_content_read_audit_per_source`
/// when caller code can surface the list of `object_ref_id`s that were read.
#[allow(dead_code)]
async fn append_trace_content_read_audit(
    state: &AppState,
    tenant: &TenantAuth,
    submission_id: Uuid,
    object_ref_id: Option<Uuid>,
    surface: &str,
    purpose: Option<&str>,
) -> anyhow::Result<()> {
    let refs: &[Uuid] = match object_ref_id.as_ref() {
        Some(id) => std::slice::from_ref(id),
        None => &[],
    };
    append_trace_content_read_audit_per_source(state, tenant, submission_id, refs, surface, purpose)
        .await
}

/// Per-source variant of the trace-content read audit helper.
///
/// Emits one audit row per `(submission_id, object_ref_id)` pair when
/// `object_ref_ids` is non-empty. When `object_ref_ids` is empty the helper
/// emits a single row with `object_ref_id = NULL` (the historical shape used
/// by callers that do not yet know which stored sources were touched).
///
/// Each row is appended to the same per-tenant hash chain in sequence; the
/// canonical file-format audit event is unchanged (it still encodes
/// `submission_id` + surface/purpose in `reason` metadata), and the new
/// per-source granularity is carried in the `trace_audit_events.object_ref_id`
/// column.
async fn append_trace_content_read_audit_per_source(
    state: &AppState,
    tenant: &TenantAuth,
    submission_id: Uuid,
    object_ref_ids: &[Uuid],
    surface: &str,
    purpose: Option<&str>,
) -> anyhow::Result<()> {
    if object_ref_ids.is_empty() {
        return append_single_trace_content_read_audit_row(
            state,
            tenant,
            submission_id,
            None,
            surface,
            purpose,
        )
        .await;
    }
    let mut seen = BTreeSet::new();
    for object_ref_id in object_ref_ids.iter().copied() {
        if !seen.insert(object_ref_id) {
            continue;
        }
        append_single_trace_content_read_audit_row(
            state,
            tenant,
            submission_id,
            Some(object_ref_id),
            surface,
            purpose,
        )
        .await?;
    }
    Ok(())
}

async fn append_single_trace_content_read_audit_row(
    state: &AppState,
    tenant: &TenantAuth,
    submission_id: Uuid,
    object_ref_id: Option<Uuid>,
    surface: &str,
    purpose: Option<&str>,
) -> anyhow::Result<()> {
    let event = TraceCommonsAuditEvent::trace_content_read(tenant, submission_id, surface, purpose);
    let metadata = trace_content_read_audit_metadata(surface, purpose);
    if state.require_db_mirror_writes {
        let mirror_result = mirror_audit_event_to_db_with_object_ref(
            state,
            tenant,
            &event,
            StorageTraceAuditAction::Read,
            metadata,
            object_ref_id,
        )
        .await;
        if let Err(error) = &mirror_result {
            tracing::warn!(
                error_hash = %safe_display_error_hash(error),
                event_id = %event.event_id,
                "Trace Commons DB dual-write audit mirror failed"
            );
        }
        enforce_db_mirror_write_result(state, "trace content read audit event", mirror_result)?;
        append_audit_event(&state.root, &tenant.tenant_id, event)?;
        return Ok(());
    }

    let event = append_audit_event(&state.root, &tenant.tenant_id, event)?;
    let mirror_result = mirror_audit_event_to_db_with_object_ref(
        state,
        tenant,
        &event,
        StorageTraceAuditAction::Read,
        metadata,
        object_ref_id,
    )
    .await;
    if let Err(error) = &mirror_result {
        tracing::warn!(
            error_hash = %safe_display_error_hash(error),
            event_id = %event.event_id,
            "Trace Commons DB dual-write audit mirror failed"
        );
    }
    enforce_db_mirror_write_result(state, "trace content read audit event", mirror_result)?;
    verify_mirrored_audit_event_after_file_append(state, tenant, &event).await?;
    Ok(())
}

async fn append_derived_source_read_audits(
    state: &AppState,
    tenant: &TenantAuth,
    submission_ids: &[Uuid],
    object_ref_ids: &BTreeMap<Uuid, Uuid>,
    surface: &str,
    purpose: Option<&str>,
) -> anyhow::Result<usize> {
    let mut seen = BTreeSet::new();
    let mut appended = 0usize;
    for submission_id in submission_ids.iter().copied() {
        if !seen.insert(submission_id) {
            continue;
        }
        let object_ref = object_ref_ids.get(&submission_id).copied();
        let refs: &[Uuid] = match object_ref.as_ref() {
            Some(id) => std::slice::from_ref(id),
            None => &[],
        };
        append_trace_content_read_audit_per_source(
            state,
            tenant,
            submission_id,
            refs,
            surface,
            purpose,
        )
        .await?;
        appended += 1;
    }
    Ok(appended)
}

async fn revalidate_db_export_sources(
    state: &AppState,
    tenant: &TenantAuth,
    submission_ids: &[Uuid],
    require_object_refs: bool,
) -> anyhow::Result<BTreeMap<Uuid, Uuid>> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(BTreeMap::new());
    };

    let mut seen = BTreeSet::new();
    let mut object_ref_ids = BTreeMap::new();
    for submission_id in submission_ids.iter().copied() {
        if !seen.insert(submission_id) {
            continue;
        }
        let record = db
            .get_trace_submission(&tenant.tenant_id, submission_id)
            .await
            .with_context(|| format!("failed to revalidate export source {submission_id}"))?
            .with_context(|| format!("missing DB submission for export source {submission_id}"))?;
        anyhow::ensure!(
            record.status == StorageTraceCorpusStatus::Accepted
                && record.revoked_at.is_none()
                && record.purged_at.is_none(),
            "trace export source {submission_id} is no longer accepted"
        );
        let object_ref = db
            .get_latest_active_trace_object_ref(
                &tenant.tenant_id,
                submission_id,
                StorageTraceObjectArtifactKind::SubmittedEnvelope,
            )
            .await
            .with_context(|| {
                format!("failed to read active submitted-envelope object ref for {submission_id}")
            })?;
        if let Some(object_ref) = object_ref {
            read_envelope_from_object_ref(state, &tenant.tenant_id, &object_ref).with_context(
                || format!("failed to verify export source object ref for {submission_id}"),
            )?;
            object_ref_ids.insert(submission_id, object_ref.object_ref_id);
        } else if require_object_refs {
            anyhow::bail!("missing active submitted-envelope object ref for {submission_id}");
        }
    }
    Ok(object_ref_ids)
}

async fn mirror_audit_event_to_db(
    state: &AppState,
    tenant: &TenantAuth,
    event: &TraceCommonsAuditEvent,
    action: StorageTraceAuditAction,
    metadata: StorageTraceAuditSafeMetadata,
) -> anyhow::Result<()> {
    mirror_audit_event_to_db_with_object_ref(state, tenant, event, action, metadata, None).await
}

async fn mirror_audit_event_to_db_with_object_ref(
    state: &AppState,
    tenant: &TenantAuth,
    event: &TraceCommonsAuditEvent,
    action: StorageTraceAuditAction,
    metadata: StorageTraceAuditSafeMetadata,
    object_ref_id: Option<Uuid>,
) -> anyhow::Result<()> {
    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(());
    };
    let metadata = normalize_audit_event_metadata(event, action, metadata)?;
    let canonical_event_json = event
        .previous_event_hash
        .as_deref()
        .map(|previous_event_hash| canonical_audit_event_json(previous_event_hash, event))
        .transpose()?;
    db.append_trace_audit_event(StorageTraceAuditEventWrite {
        audit_event_id: event.event_id,
        tenant_id: tenant.tenant_id.clone(),
        actor_principal_ref: event
            .actor_principal_ref
            .clone()
            .unwrap_or_else(|| tenant.principal_ref.clone()),
        actor_role: event
            .actor_role
            .unwrap_or(tenant.role)
            .storage_name()
            .to_string(),
        action,
        reason: event.reason.clone(),
        request_id: None,
        submission_id: (event.submission_id != Uuid::nil()).then_some(event.submission_id),
        object_ref_id,
        export_manifest_id: event.export_id,
        decision_inputs_hash: event.decision_inputs_hash.clone(),
        previous_event_hash: event.previous_event_hash.clone(),
        event_hash: event.event_hash.clone(),
        canonical_event_json,
        metadata,
    })
    .await
    .context("failed to mirror trace audit event")
}

fn normalize_audit_event_metadata(
    event: &TraceCommonsAuditEvent,
    action: StorageTraceAuditAction,
    metadata: StorageTraceAuditSafeMetadata,
) -> anyhow::Result<StorageTraceAuditSafeMetadata> {
    if action == StorageTraceAuditAction::Submit && event.kind == "submitted" {
        let expected_status = event.status.map(storage_corpus_status).ok_or_else(|| {
            anyhow::anyhow!(
                "submitted audit event {} requires canonical status",
                event.event_id
            )
        })?;
        return match metadata {
            StorageTraceAuditSafeMetadata::Submission { status, .. }
                if status == expected_status =>
            {
                Ok(metadata)
            }
            StorageTraceAuditSafeMetadata::Submission { .. } => anyhow::bail!(
                "submitted audit event {} metadata status does not match canonical status",
                event.event_id
            ),
            _ => anyhow::bail!(
                "submitted audit event {} requires submission metadata",
                event.event_id
            ),
        };
    }
    if action == StorageTraceAuditAction::Read && event.kind == "read" {
        let expected =
            trace_read_audit_metadata_from_reason(event.reason.as_deref()).ok_or_else(|| {
                anyhow::anyhow!(
                    "aggregate read audit event {} requires surface and item_count reason fields",
                    event.event_id
                )
            })?;
        return match metadata {
            StorageTraceAuditSafeMetadata::Empty => Ok(expected),
            StorageTraceAuditSafeMetadata::Read { .. } if metadata == expected => Ok(metadata),
            StorageTraceAuditSafeMetadata::Read { .. } => anyhow::bail!(
                "aggregate read audit event {} metadata does not match reason fields",
                event.event_id
            ),
            _ => anyhow::bail!(
                "aggregate read audit event {} requires aggregate read metadata",
                event.event_id
            ),
        };
    }
    if action == StorageTraceAuditAction::Read && event.kind == "trace_content_read" {
        let expected = trace_content_read_audit_metadata_from_reason(event.reason.as_deref())
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "trace content read audit event {} requires surface reason fields",
                    event.event_id
                )
            })?;
        return match metadata {
            StorageTraceAuditSafeMetadata::Empty => Ok(expected),
            StorageTraceAuditSafeMetadata::TraceContentRead { .. } if metadata == expected => {
                Ok(metadata)
            }
            StorageTraceAuditSafeMetadata::TraceContentRead { .. } => anyhow::bail!(
                "trace content read audit event {} metadata does not match reason fields",
                event.event_id
            ),
            _ => anyhow::bail!(
                "trace content read audit event {} requires trace content read metadata",
                event.event_id
            ),
        };
    }
    if action == StorageTraceAuditAction::CreditMutate
        && event.kind == "credit_settlement_issuer_approval"
    {
        let expected =
            trace_credit_settlement_issuer_approval_audit_metadata_from_reason(
                event.reason.as_deref(),
            )
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "credit settlement issuer approval audit event {} requires canonical hash reason fields",
                    event.event_id
                )
            })?;
        return match metadata {
            StorageTraceAuditSafeMetadata::Empty => Ok(expected),
            StorageTraceAuditSafeMetadata::CreditSettlementIssuerApproval { .. }
                if metadata == expected =>
            {
                Ok(metadata)
            }
            StorageTraceAuditSafeMetadata::CreditSettlementIssuerApproval { .. } => {
                anyhow::bail!(
                    "credit settlement issuer approval audit event {} metadata does not match reason fields",
                    event.event_id
                )
            }
            _ => anyhow::bail!(
                "credit settlement issuer approval audit event {} requires issuer approval metadata",
                event.event_id
            ),
        };
    }
    if action == StorageTraceAuditAction::CreditMutate
        && matches!(event.kind.as_str(), "credit_hold" | "credit_hold_release")
    {
        let expected =
            trace_credit_hold_audit_metadata_from_reason(&event.kind, event.reason.as_deref())
                .ok_or_else(|| {
                    anyhow::anyhow!(
                        "credit hold audit event {} requires canonical hash reason fields",
                        event.event_id
                    )
                })?;
        return match metadata {
            StorageTraceAuditSafeMetadata::Empty => Ok(expected),
            StorageTraceAuditSafeMetadata::CreditHold { .. } if metadata == expected => {
                Ok(metadata)
            }
            StorageTraceAuditSafeMetadata::CreditHold { .. } => anyhow::bail!(
                "credit hold audit event {} metadata does not match reason fields",
                event.event_id
            ),
            _ => anyhow::bail!(
                "credit hold audit event {} requires credit hold metadata",
                event.event_id
            ),
        };
    }
    if action == StorageTraceAuditAction::CreditMutate && event.kind == "near_credit_outbox_status"
    {
        let expected = trace_near_credit_outbox_status_audit_metadata_from_reason(
            event.reason.as_deref(),
        )
        .ok_or_else(|| {
            anyhow::anyhow!(
                "NEAR credit outbox status audit event {} requires canonical hash reason fields",
                event.event_id
            )
        })?;
        return match metadata {
            StorageTraceAuditSafeMetadata::Empty => Ok(expected),
            StorageTraceAuditSafeMetadata::NearCreditOutboxStatus { .. }
                if metadata == expected =>
            {
                Ok(metadata)
            }
            StorageTraceAuditSafeMetadata::NearCreditOutboxStatus { .. } => anyhow::bail!(
                "NEAR credit outbox status audit event {} metadata does not match reason fields",
                event.event_id
            ),
            _ => anyhow::bail!(
                "NEAR credit outbox status audit event {} requires NEAR credit outbox status metadata",
                event.event_id
            ),
        };
    }
    if action == StorageTraceAuditAction::BenchmarkConvert
        && event.kind == "benchmark_registry_outbox_status"
    {
        let expected = trace_benchmark_registry_outbox_status_audit_metadata_from_reason(
            event.reason.as_deref(),
        )
        .ok_or_else(|| {
            anyhow::anyhow!(
                "benchmark registry outbox status audit event {} requires canonical hash reason fields",
                event.event_id
            )
        })?;
        return match metadata {
            StorageTraceAuditSafeMetadata::Empty => Ok(expected),
            StorageTraceAuditSafeMetadata::BenchmarkRegistryOutboxStatus { .. }
                if metadata == expected =>
            {
                Ok(metadata)
            }
            StorageTraceAuditSafeMetadata::BenchmarkRegistryOutboxStatus { .. } => {
                anyhow::bail!(
                    "benchmark registry outbox status audit event {} metadata does not match reason fields",
                    event.event_id
                )
            }
            _ => anyhow::bail!(
                "benchmark registry outbox status audit event {} requires benchmark registry outbox status metadata",
                event.event_id
            ),
        };
    }
    if action == StorageTraceAuditAction::Revoke && event.kind == "revoked" {
        let expected = trace_revocation_audit_metadata_from_reason(event.reason.as_deref())
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "revocation audit event {} requires a non-empty reason",
                    event.event_id
                )
            })?;
        return match metadata {
            StorageTraceAuditSafeMetadata::Empty => Ok(expected),
            StorageTraceAuditSafeMetadata::Revocation { .. } if metadata == expected => {
                Ok(metadata)
            }
            StorageTraceAuditSafeMetadata::Revocation { .. } => anyhow::bail!(
                "revocation audit event {} metadata does not match reason",
                event.event_id
            ),
            _ => anyhow::bail!(
                "revocation audit event {} requires revocation metadata",
                event.event_id
            ),
        };
    }
    if trace_maintenance_audit_kind(&event.kind) {
        if trace_audit_reason_value(event.reason.as_deref(), "purpose").is_some() {
            anyhow::bail!(
                "maintenance audit event {} requires hashed purpose reason fields",
                event.event_id
            );
        }
        if trace_maintenance_audit_reason_has_invalid_hash(event.reason.as_deref()) {
            anyhow::bail!(
                "maintenance audit event {} requires canonical hash reason fields",
                event.event_id
            );
        }
        if let Some(expected) =
            trace_maintenance_audit_metadata_from_reason(&event.kind, event.reason.as_deref())
        {
            return match metadata {
                StorageTraceAuditSafeMetadata::Empty => Ok(expected),
                StorageTraceAuditSafeMetadata::Maintenance { .. } if metadata == expected => {
                    Ok(metadata)
                }
                StorageTraceAuditSafeMetadata::Maintenance { .. } => anyhow::bail!(
                    "maintenance audit event {} metadata does not match reason fields",
                    event.event_id
                ),
                _ => anyhow::bail!(
                    "maintenance audit event {} requires maintenance metadata",
                    event.event_id
                ),
            };
        }
    }
    Ok(metadata)
}

fn read_all_audit_events(
    root: &Path,
    tenant_id: &str,
) -> anyhow::Result<Vec<TraceCommonsAuditEvent>> {
    let path = audit_events_path(root, tenant_id);
    if !path.exists() {
        return Ok(Vec::new());
    }

    let body = std::fs::read_to_string(&path)
        .with_context(|| format!("failed to read audit log {}", path.display()))?;
    let mut events = Vec::new();
    for (index, line) in body.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let event: TraceCommonsAuditEvent = serde_json::from_str(line).with_context(|| {
            format!(
                "failed to parse audit event {} line {}",
                path.display(),
                index + 1
            )
        })?;
        ensure_audit_event_tenant(&event, tenant_id)?;
        events.push(event);
    }
    events.sort_by_key(|event| event.created_at);
    Ok(events)
}

fn read_recent_audit_events_from_file(
    root: &Path,
    tenant_id: &str,
    limit: usize,
) -> anyhow::Result<Vec<TraceCommonsAuditEvent>> {
    if limit == 0 {
        return Ok(Vec::new());
    }
    let path = audit_events_path(root, tenant_id);
    if !path.exists() {
        return Ok(Vec::new());
    }

    let file = std::fs::File::open(&path)
        .with_context(|| format!("failed to read audit log {}", path.display()))?;
    let reader = std::io::BufReader::new(file);
    let mut recent_lines = VecDeque::with_capacity(limit);
    for (index, line) in reader.lines().enumerate() {
        let line = line.with_context(|| format!("failed to read audit log {}", path.display()))?;
        let line = line.trim().to_string();
        if line.is_empty() {
            continue;
        }
        if recent_lines.len() == limit {
            recent_lines.pop_front();
        }
        recent_lines.push_back((index + 1, line));
    }

    let mut events = Vec::with_capacity(recent_lines.len());
    for (line_number, line) in recent_lines.into_iter().rev() {
        let event: TraceCommonsAuditEvent = serde_json::from_str(&line).with_context(|| {
            format!(
                "failed to parse audit event {} line {}",
                path.display(),
                line_number
            )
        })?;
        ensure_audit_event_tenant(&event, tenant_id)?;
        events.push(event);
    }
    verify_recent_audit_event_hashes(&events)?;
    Ok(events)
}

fn ensure_audit_event_tenant(
    event: &TraceCommonsAuditEvent,
    tenant_id: &str,
) -> anyhow::Result<()> {
    anyhow::ensure!(event.tenant_id == tenant_id, "trace audit tenant mismatch");
    Ok(())
}

fn verify_recent_audit_event_hashes(events: &[TraceCommonsAuditEvent]) -> anyhow::Result<()> {
    for (index, event) in events.iter().enumerate() {
        let row_number = index + 1;
        match (
            event.previous_event_hash.as_deref(),
            event.event_hash.as_deref(),
        ) {
            (None, None) => continue,
            (Some(previous_event_hash), Some(event_hash)) => {
                anyhow::ensure!(
                    is_canonical_sha256_prefixed_hash(event_hash),
                    "audit reader row {row_number} event {}: event_hash has invalid format",
                    event.event_id
                );
                anyhow::ensure!(
                    is_audit_chain_previous_hash(previous_event_hash),
                    "audit reader row {row_number} event {}: previous_event_hash has invalid format",
                    event.event_id
                );
                let recomputed = compute_audit_event_hash(previous_event_hash, event)?;
                anyhow::ensure!(
                    recomputed == event_hash,
                    "audit reader row {row_number} event {}: canonical payload hash mismatch",
                    event.event_id
                );
            }
            _ => {
                anyhow::bail!(
                    "audit reader row {row_number} event {}: incomplete hash chain fields",
                    event.event_id
                );
            }
        }
    }

    for pair in events.windows(2) {
        let newer = &pair[0];
        let older = &pair[1];
        if let (Some(newer_previous_hash), Some(older_event_hash)) = (
            newer.previous_event_hash.as_deref(),
            older.event_hash.as_deref(),
        ) {
            anyhow::ensure!(
                newer_previous_hash == older_event_hash,
                "audit reader event {}: previous_event_hash does not match prior returned event",
                newer.event_id
            );
        }
    }
    Ok(())
}

fn remove_audit_event_by_id(root: &Path, tenant_id: &str, event_id: Uuid) -> anyhow::Result<bool> {
    let path = audit_events_path(root, tenant_id);
    if !path.exists() {
        return Ok(false);
    }
    let mut events = read_all_audit_events(root, tenant_id)?;
    let original_len = events.len();
    events.retain(|event| event.event_id != event_id);
    if events.len() == original_len {
        return Ok(false);
    }
    let mut previous_event_hash = TRACE_AUDIT_EVENT_GENESIS_HASH.to_string();
    for event in &mut events {
        event.previous_event_hash = Some(previous_event_hash.clone());
        event.event_hash = None;
        let event_hash = compute_audit_event_hash(&previous_event_hash, event)?;
        event.event_hash = Some(event_hash.clone());
        previous_event_hash = event_hash;
    }
    rewrite_jsonl_file(&path, &events, "audit log")
        .with_context(|| format!("failed to rewrite audit log {}", path.display()))?;
    Ok(true)
}

fn rewrite_jsonl_file<T: Serialize>(path: &Path, records: &[T], label: &str) -> anyhow::Result<()> {
    if records.is_empty() {
        if path.exists() {
            std::fs::remove_file(path)
                .with_context(|| format!("failed to remove empty {label} {}", path.display()))?;
        }
        return Ok(());
    }
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("failed to create {label} dir {}", parent.display()))?;
    }
    let mut body = String::new();
    for record in records {
        body.push_str(&serde_json::to_string(record).context("failed to serialize JSONL row")?);
        body.push('\n');
    }
    std::fs::write(path, body)
        .with_context(|| format!("failed to rewrite {label} {}", path.display()))
}

fn read_all_revocations(
    root: &Path,
    tenant_id: &str,
) -> anyhow::Result<Vec<TraceCommonsRevocation>> {
    let tenant_key = tenant_storage_key(tenant_id);
    let dir = root.join("tenants").join(tenant_key).join("revocations");
    if !dir.exists() {
        return Ok(Vec::new());
    }

    let mut revocations = Vec::new();
    for entry in std::fs::read_dir(&dir)
        .with_context(|| format!("failed to read revocation dir {}", dir.display()))?
    {
        let entry = entry.context("failed to read revocation entry")?;
        let path = entry.path();
        if path.extension().is_none_or(|ext| ext != "json") {
            continue;
        }
        let body = std::fs::read_to_string(&path)
            .with_context(|| format!("failed to read revocation {}", path.display()))?;
        let revocation: TraceCommonsRevocation = serde_json::from_str(&body)
            .with_context(|| format!("failed to parse revocation {}", path.display()))?;
        ensure_revocation_tenant(&revocation, tenant_id)?;
        revocations.push(revocation);
    }
    revocations.sort_by_key(|revocation| revocation.revoked_at);
    Ok(revocations)
}

fn ensure_revocation_tenant(
    revocation: &TraceCommonsRevocation,
    tenant_id: &str,
) -> anyhow::Result<()> {
    anyhow::ensure!(
        revocation.tenant_id == tenant_id,
        "trace revocation tenant mismatch"
    );
    anyhow::ensure!(
        revocation.tenant_storage_ref == tenant_storage_ref(tenant_id),
        "trace revocation tenant storage ref mismatch"
    );
    Ok(())
}

async fn read_revocations_for_submit(
    state: &AppState,
    tenant_id: &str,
) -> anyhow::Result<Vec<TraceCommonsRevocation>> {
    let mut revocations = read_all_revocations(&state.root, tenant_id)?;
    if let Some(db) = state.db_mirror.as_ref() {
        let db_revocations = db
            .list_trace_tombstones(tenant_id)
            .await
            .context("failed to list trace tombstones for submit preflight")?;
        revocations.extend(
            db_revocations
                .into_iter()
                .map(trace_revocation_from_storage_tombstone),
        );
        revocations.sort_by_key(|revocation| revocation.revoked_at);
    }
    Ok(revocations)
}

fn trace_revocation_from_storage_tombstone(
    tombstone: StorageTraceTombstoneRecord,
) -> TraceCommonsRevocation {
    TraceCommonsRevocation {
        tenant_storage_ref: tenant_storage_ref(&tombstone.tenant_id),
        tenant_id: tombstone.tenant_id,
        submission_id: tombstone.submission_id,
        revoked_at: tombstone.effective_at,
        reason: tombstone.reason,
        redaction_hash: tombstone.redaction_hash,
        canonical_summary_hash: tombstone.canonical_summary_hash,
    }
}

