async fn read_benchmark_conversion_artifact_with_ref_policy(
    state: &AppState,
    tenant: &TenantAuth,
    conversion_id: Uuid,
    allow_invalidated_object_refs: bool,
) -> anyhow::Result<Option<TraceBenchmarkConversionArtifact>> {
    let path = benchmark_artifact_path(&state.root, &tenant.tenant_id, conversion_id);
    if path.exists() {
        let body = std::fs::read_to_string(&path).with_context(|| {
            format!(
                "failed to read trace benchmark conversion artifact {}",
                path.display()
            )
        })?;
        let artifact = serde_json::from_str(&body).with_context(|| {
            format!(
                "failed to parse trace benchmark conversion artifact {}",
                path.display()
            )
        })?;
        ensure_benchmark_artifact_tenant(&artifact, &tenant.tenant_id)?;
        return Ok(Some(artifact));
    }

    let Some(db) = state.db_mirror.as_ref() else {
        return Ok(None);
    };
    let Some(store) = state.artifact_store.as_ref() else {
        return Ok(None);
    };
    let items = db
        .list_trace_export_manifest_items(&tenant.tenant_id, conversion_id)
        .await
        .context("failed to list benchmark export manifest items for artifact read")?;
    for item in items {
        let Some(object_ref_id) = item.object_ref_id else {
            continue;
        };
        let object_refs = db
            .list_trace_object_refs(&tenant.tenant_id, item.submission_id)
            .await
            .with_context(|| {
                format!(
                    "failed to list trace object refs for benchmark artifact source {}",
                    item.submission_id
                )
            })?;
        let Some(object_ref) = object_refs.into_iter().find(|object_ref| {
            object_ref.object_ref_id == object_ref_id
                && object_ref.artifact_kind == StorageTraceObjectArtifactKind::BenchmarkArtifact
                && (allow_invalidated_object_refs || object_ref.invalidated_at.is_none())
                && object_ref.deleted_at.is_none()
        }) else {
            continue;
        };
        ensure_local_trace_object_ref_key_ref(&object_ref, &tenant.tenant_id)?;
        let artifact: TraceBenchmarkConversionArtifact = store.get_json_by_object_key(
            &tenant_storage_ref(&tenant.tenant_id),
            TraceArtifactKind::BenchmarkConversion,
            &object_ref.object_key,
            &object_ref.content_sha256,
        )?;
        ensure_benchmark_artifact_tenant(&artifact, &tenant.tenant_id)?;
        return Ok(Some(artifact));
    }
    Ok(None)
}

async fn list_benchmark_conversion_artifacts_for_worker(
    state: &AppState,
    tenant: &TenantAuth,
) -> anyhow::Result<Vec<TraceBenchmarkConversionArtifact>> {
    let tenant_key = tenant_storage_key(&tenant.tenant_id);
    let benchmarks_dir = state
        .root
        .join("tenants")
        .join(tenant_key)
        .join("benchmarks");
    let mut artifacts_by_id = BTreeMap::new();
    if benchmarks_dir.exists() {
        for entry in std::fs::read_dir(&benchmarks_dir).with_context(|| {
            format!("failed to read benchmarks dir {}", benchmarks_dir.display())
        })? {
            let entry = entry.context("failed to read benchmark dir entry")?;
            if !entry
                .file_type()
                .context("failed to inspect benchmark dir entry")?
                .is_dir()
            {
                continue;
            }
            let artifact_path = entry.path().join("artifact.json");
            if !artifact_path.exists() {
                continue;
            }
            let body = std::fs::read_to_string(&artifact_path).with_context(|| {
                format!(
                    "failed to read trace benchmark conversion artifact {}",
                    artifact_path.display()
                )
            })?;
            let artifact: TraceBenchmarkConversionArtifact = serde_json::from_str(&body)
                .with_context(|| {
                    format!(
                        "failed to parse trace benchmark conversion artifact {}",
                        artifact_path.display()
                    )
                })?;
            ensure_benchmark_artifact_tenant(&artifact, &tenant.tenant_id)?;
            artifacts_by_id.insert(artifact.conversion_id, artifact);
        }
    }

    if let Some(db) = state.db_mirror.as_ref() {
        let manifests = db
            .list_trace_export_manifests(&tenant.tenant_id)
            .await
            .context("failed to list benchmark export manifests for evaluation worker")?;
        for manifest in manifests
            .into_iter()
            .filter(is_benchmark_conversion_storage_manifest)
        {
            if artifacts_by_id.contains_key(&manifest.export_manifest_id) {
                continue;
            }
            if let Some(artifact) =
                read_benchmark_conversion_artifact(state, tenant, manifest.export_manifest_id)
                    .await?
            {
                artifacts_by_id.insert(artifact.conversion_id, artifact);
            }
        }
    }

    let mut artifacts = artifacts_by_id.into_values().collect::<Vec<_>>();
    artifacts.sort_by_key(|artifact| (artifact.generated_at, artifact.conversion_id));
    Ok(artifacts)
}

fn is_benchmark_conversion_storage_manifest(record: &StorageTraceExportManifestRecord) -> bool {
    record.artifact_kind == StorageTraceObjectArtifactKind::BenchmarkArtifact
        && record.invalidated_at.is_none()
        && record.deleted_at.is_none()
}

