async fn run_maintenance(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceMaintenanceRequest,
    vector_tenant_policy: Option<&TenantSubmissionPolicy>,
) -> anyhow::Result<TraceMaintenanceResponse> {
    let purpose = request
        .purpose
        .as_deref()
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .unwrap_or("trace_commons_retention_revocation_maintenance")
        .to_string();
    require_db_reconciliation_clean_request(state, &request)?;
    let mut revocation_reasons = read_all_revocations(&state.root, &tenant.tenant_id)?
        .into_iter()
        .map(|revocation| (revocation.submission_id, revocation.reason))
        .collect::<BTreeMap<_, _>>();
    let mut revoked_submission_ids = revocation_reasons.keys().copied().collect::<BTreeSet<_>>();
    let mut expired_submission_ids = BTreeSet::new();
    let mut retention_ledger = TraceMaintenanceLedgerAccumulator::default();
    let maintenance_started_at = Utc::now();
    let backfill_only_request = request.is_db_mirror_backfill_only_request();
    let mut db_mirror_backfill_input_failures = Vec::new();

    let mut records = if backfill_only_request {
        let read = read_all_submission_records_for_backfill(&state.root, &tenant.tenant_id)?;
        db_mirror_backfill_input_failures.extend(read.failures);
        read.records
    } else {
        read_all_submission_records(&state.root, &tenant.tenant_id)?
    };
    let mut records_marked_revoked = 0usize;
    let mut records_marked_expired = 0usize;
    let now = Utc::now();
    for record in &mut records {
        ensure_retention_metadata_within_server_policy(record)?;
        if record.is_revoked() {
            revoked_submission_ids.insert(record.submission_id);
            let revocation_reason = revocation_reasons
                .entry(record.submission_id)
                .or_insert_with(|| TRACE_DEFAULT_REVOCATION_REASON.to_string())
                .clone();
            if !request.dry_run {
                mirror_revocation_to_db(
                    state,
                    TraceRevocationDbMirrorInput {
                        tenant,
                        submission_id: record.submission_id,
                        record: Some(record),
                        db_record: None,
                        revocation_reason: &revocation_reason,
                        retention_ledger: Some(&mut retention_ledger),
                        prepared_tombstone: None,
                    },
                )
                .await?;
            }
            continue;
        }
        if record.status == TraceCorpusStatus::Expired {
            expired_submission_ids.insert(record.submission_id);
            continue;
        }
        if revoked_submission_ids.contains(&record.submission_id) {
            records_marked_revoked += 1;
            let revocation_reason = revocation_reasons
                .entry(record.submission_id)
                .or_insert_with(|| TRACE_DEFAULT_REVOCATION_REASON.to_string())
                .clone();
            if !request.dry_run {
                record.status = TraceCorpusStatus::Revoked;
                record.credit_points_final = Some(0.0);
                write_submission_record(&state.root, record)?;
                mirror_revocation_to_db(
                    state,
                    TraceRevocationDbMirrorInput {
                        tenant,
                        submission_id: record.submission_id,
                        record: Some(record),
                        db_record: None,
                        revocation_reason: &revocation_reason,
                        retention_ledger: Some(&mut retention_ledger),
                        prepared_tombstone: None,
                    },
                )
                .await?;
            }
            continue;
        }
        if record.is_expired_at(now) && !retention_policy_is_on_legal_hold(state, record)? {
            records_marked_expired += 1;
            expired_submission_ids.insert(record.submission_id);
            if !request.dry_run {
                record.status = TraceCorpusStatus::Expired;
                record.credit_points_final = Some(record.credit_points_final.unwrap_or(0.0));
                write_submission_record(&state.root, record)?;
                mirror_expiration_to_db(
                    state,
                    tenant,
                    record.submission_id,
                    Some(&mut retention_ledger),
                )
                .await?;
            }
        }
    }

    let mut derived = if backfill_only_request {
        let read = read_all_derived_records_for_backfill(&state.root, &tenant.tenant_id)?;
        db_mirror_backfill_input_failures.extend(read.failures);
        read.records
    } else {
        read_all_derived_records(&state.root, &tenant.tenant_id)?
    };
    let mut derived_marked_revoked = 0usize;
    let mut derived_marked_expired = 0usize;
    for record in &mut derived {
        if revoked_submission_ids.contains(&record.submission_id)
            && record.status != TraceCorpusStatus::Revoked
        {
            derived_marked_revoked += 1;
            if !request.dry_run {
                record.status = TraceCorpusStatus::Revoked;
                write_derived_record(&state.root, record)?;
            }
        } else if expired_submission_ids.contains(&record.submission_id)
            && !matches!(
                record.status,
                TraceCorpusStatus::Revoked | TraceCorpusStatus::Expired
            )
        {
            derived_marked_expired += 1;
            if !request.dry_run {
                record.status = TraceCorpusStatus::Expired;
                write_derived_record(&state.root, record)?;
            }
        }
    }

    let mut records_marked_purged = 0usize;
    let mut trace_object_files_deleted = 0usize;
    let mut encrypted_artifacts_deleted = 0usize;
    if let Some(purge_cutoff) = request.purge_expired_before {
        for record in &mut records {
            if retention_policy_is_on_legal_hold(state, record)? {
                continue;
            }
            if record.status != TraceCorpusStatus::Expired
                || record
                    .expires_at
                    .is_none_or(|expires_at| expires_at > purge_cutoff)
            {
                continue;
            }
            records_marked_purged += 1;
            if request.dry_run {
                continue;
            }
            let deletion_counts = delete_trace_objects_for_record(state, record)?;
            trace_object_files_deleted += usize::from(deletion_counts.file_deleted);
            encrypted_artifacts_deleted += usize::from(deletion_counts.encrypted_artifact_deleted);
            record.status = TraceCorpusStatus::Purged;
            record.purged_at = Some(now);
            write_submission_record(&state.root, record)?;
            mirror_purge_to_db(
                state,
                tenant,
                record.submission_id,
                &deletion_counts.deleted_targets,
                Some(&mut retention_ledger),
            )
            .await?;
        }
    }

    let export_cache_files_pruned = if request.prune_export_cache {
        prune_export_cache_files(
            &state.root,
            &tenant.tenant_id,
            &revoked_submission_ids,
            &expired_submission_ids,
            request.max_export_age_hours,
            request.dry_run,
        )?
    } else {
        0
    };
    let export_provenance_invalidated =
        if !revoked_submission_ids.is_empty() || !expired_submission_ids.is_empty() {
            invalidate_export_provenance_for_sources(
                &state.root,
                &tenant.tenant_id,
                &revocation_reasons,
                &expired_submission_ids,
                request.dry_run,
            )?
        } else {
            0
        };
    let benchmark_artifacts_invalidated =
        if !revoked_submission_ids.is_empty() || !expired_submission_ids.is_empty() {
            propagate_benchmark_artifact_source_invalidation(
                state,
                tenant,
                &revocation_reasons,
                &expired_submission_ids,
                request.dry_run,
            )
            .await?
        } else {
            0
        };
    let mut db_mirror_backfill = backfill_db_mirror_from_files(
        state,
        tenant,
        &records,
        &derived,
        request.backfill_db_mirror,
        request.dry_run,
    )
    .await?;
    for failure in db_mirror_backfill_input_failures {
        db_mirror_backfill.record_existing_failure(failure);
    }
    let db_mirror_backfilled = db_mirror_backfill.backfilled;
    let db_mirror_backfill_failed = db_mirror_backfill.failed;
    let vector_index_report = index_vector_metadata_from_db(
        state,
        tenant,
        request.index_vectors,
        request.dry_run,
        &purpose,
        vector_tenant_policy,
        None,
    )
    .await?;
    let vector_entries_indexed = vector_index_report.vector_entries_indexed;
    let maintenance_counts = TraceMaintenanceAuditCounts {
        records_marked_revoked,
        records_marked_expired,
        records_marked_purged,
        derived_marked_revoked,
        derived_marked_expired,
        export_cache_files_pruned,
        export_provenance_invalidated,
        benchmark_artifacts_invalidated,
        trace_object_files_deleted,
        encrypted_artifacts_deleted,
        db_mirror_backfilled,
        db_mirror_backfill_failed,
        vector_entries_indexed,
    };
    let audit_event =
        TraceCommonsAuditEvent::maintenance(tenant, &purpose, request.dry_run, maintenance_counts);
    let audit_event_id = audit_event.event_id;
    append_audit_event_with_db_mirror(
        state,
        tenant,
        audit_event,
        StorageTraceAuditAction::Retain,
        StorageTraceAuditSafeMetadata::Maintenance {
            surface: Some("maintenance".to_string()),
            purpose_hash: Some(sha256_prefixed(&purpose)),
            dry_run: request.dry_run,
            action_counts: maintenance_counts.action_counts(),
        },
    )
    .await?;
    if request.index_vectors {
        let mut vector_action_counts = BTreeMap::new();
        vector_action_counts.insert(
            "vector_entries_indexed".to_string(),
            vector_entries_indexed.min(u32::MAX as usize) as u32,
        );
        append_audit_event_with_db_mirror(
            state,
            tenant,
            TraceCommonsAuditEvent::vector_index(
                tenant,
                request.dry_run,
                Some(&purpose),
                vector_action_counts.clone(),
            ),
            StorageTraceAuditAction::VectorIndex,
            StorageTraceAuditSafeMetadata::Maintenance {
                surface: Some("vector_index".to_string()),
                purpose_hash: Some(sha256_prefixed(&purpose)),
                dry_run: request.dry_run,
                action_counts: vector_action_counts,
            },
        )
        .await?;
    }
    let ledger_result = write_retention_maintenance_ledger_to_db(
        state,
        tenant,
        TraceMaintenanceLedgerWriteInput {
            retention_job_id: audit_event_id,
            purpose: &purpose,
            dry_run: request.dry_run,
            purge_expired_before: request.purge_expired_before,
            prune_export_cache: request.prune_export_cache,
            max_export_age_hours: request.max_export_age_hours,
            audit_event_id,
            maintenance_counts,
            selected_revoked_count: revoked_submission_ids.len(),
            selected_expired_count: expired_submission_ids.len(),
            started_at: maintenance_started_at,
            completed_at: Utc::now(),
        },
        &retention_ledger,
    )
    .await;
    enforce_db_mirror_write_result(state, "retention maintenance ledger", ledger_result)?;
    let db_reconciliation = reconcile_db_mirror(
        state,
        tenant,
        &records,
        &derived,
        request.reconcile_db_mirror,
        Some(TraceRetentionLedgerExpectation {
            retention_job_id: audit_event_id,
            expected_item_count: retention_ledger.items.len(),
        }),
    )
    .await?;
    enforce_db_reconciliation_clean(state, db_reconciliation.as_ref())?;
    let audit_chain = if request.verify_audit_chain {
        Some(verify_audit_chain(state, &tenant.tenant_id).await?)
    } else {
        None
    };

    Ok(TraceMaintenanceResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        purpose,
        dry_run: request.dry_run,
        audit_event_id,
        revoked_submission_count: revoked_submission_ids.len(),
        expired_submission_count: expired_submission_ids.len(),
        records_marked_revoked,
        records_marked_expired,
        records_marked_purged,
        derived_marked_revoked,
        derived_marked_expired,
        export_cache_files_pruned,
        export_provenance_invalidated,
        benchmark_artifacts_invalidated,
        trace_object_files_deleted,
        encrypted_artifacts_deleted,
        db_mirror_backfilled,
        db_mirror_backfill_failed,
        db_mirror_backfill_failures: db_mirror_backfill.failures,
        vector_entries_indexed,
        audit_chain,
        db_reconciliation,
    })
}

fn retention_policy_is_on_legal_hold(
    state: &AppState,
    record: &TraceCommonsSubmissionRecord,
) -> anyhow::Result<bool> {
    let is_on_legal_hold = state
        .legal_hold_retention_policy_ids
        .contains(&record.retention_policy_id);
    if is_on_legal_hold {
        let expected_policy = retention_policy_for_submission_record(record);
        anyhow::ensure!(
            record.retention_policy_id == expected_policy.name,
            "trace retention policy metadata mismatch"
        );
    }
    Ok(is_on_legal_hold)
}

fn ensure_retention_metadata_within_server_policy(
    record: &TraceCommonsSubmissionRecord,
) -> anyhow::Result<()> {
    let expected_policy = retention_policy_for_submission_record(record);
    if is_server_retention_policy_id(&record.retention_policy_id) {
        anyhow::ensure!(
            record.retention_policy_id == expected_policy.name,
            "trace retention policy metadata mismatch"
        );
    }
    if record.retention_policy_id == expected_policy.name
        && let Some(max_age_days) = expected_policy.max_age_days
    {
        let expected_expires_at = record.received_at + Duration::days(i64::from(max_age_days));
        let Some(expires_at) = record.expires_at else {
            anyhow::bail!("trace retention expiration metadata missing");
        };
        anyhow::ensure!(
            expires_at <= expected_expires_at,
            "trace retention expiration metadata exceeds server policy"
        );
    }
    Ok(())
}

fn retention_policy_for_submission_record(
    record: &TraceCommonsSubmissionRecord,
) -> trace_commons_protocol::trace_contribution::TraceRetentionPolicy {
    let strongest = record
        .allowed_uses
        .iter()
        .copied()
        .max_by_key(trace_allowed_use_retention_rank)
        .unwrap_or(TraceAllowedUse::Debugging);
    retention_policy_for_allowed_use(strongest)
}

fn is_server_retention_policy_id(policy_id: &str) -> bool {
    matches!(
        policy_id,
        "private_corpus_revocable"
            | "benchmark_revocable"
            | "training_revocable"
            | "aggregate_only"
    )
}

fn trace_allowed_use_retention_rank(allowed_use: &TraceAllowedUse) -> u8 {
    match allowed_use {
        TraceAllowedUse::ModelTraining => 5,
        TraceAllowedUse::RankingModelTraining => 4,
        TraceAllowedUse::BenchmarkGeneration => 3,
        TraceAllowedUse::Evaluation => 2,
        TraceAllowedUse::Debugging => 1,
        TraceAllowedUse::AggregateAnalytics => 0,
    }
}

async fn verify_audit_chain(
    state: &AppState,
    tenant_id: &str,
) -> anyhow::Result<TraceAuditChainReport> {
    let mut report = verify_file_audit_chain(&state.root, tenant_id)?;
    if let Some(db) = state.db_mirror.as_ref() {
        report.db_mirror = Some(verify_db_audit_chain(db.as_ref(), tenant_id).await?);
    }
    Ok(report)
}

fn verify_file_audit_chain(root: &Path, tenant_id: &str) -> anyhow::Result<TraceAuditChainReport> {
    let path = root
        .join("tenants")
        .join(tenant_storage_key(tenant_id))
        .join("audit")
        .join("events.jsonl");
    if !path.exists() {
        return Ok(TraceAuditChainReport::default());
    }

    let body = std::fs::read_to_string(&path)
        .with_context(|| format!("failed to read audit log {}", path.display()))?;
    let mut report = TraceAuditChainReport::default();
    let mut expected_previous_hash = TRACE_AUDIT_EVENT_GENESIS_HASH.to_string();
    for (index, line) in body.lines().enumerate() {
        let line_number = index + 1;
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        report.event_count += 1;
        let event: TraceCommonsAuditEvent = serde_json::from_str(line).with_context(|| {
            format!(
                "failed to parse audit event {} line {}",
                path.display(),
                line_number
            )
        })?;
        if let Err(error) = ensure_audit_event_tenant(&event, tenant_id) {
            report.failures.push(format!("line {line_number}: {error}"));
        }
        let Some(event_hash) = event.event_hash.as_deref() else {
            report.legacy_event_count += 1;
            expected_previous_hash = TRACE_AUDIT_EVENT_GENESIS_HASH.to_string();
            continue;
        };
        let previous_event_hash = event
            .previous_event_hash
            .as_deref()
            .unwrap_or(TRACE_AUDIT_EVENT_GENESIS_HASH);
        if !is_canonical_sha256_prefixed_hash(event_hash) {
            report
                .failures
                .push(format!("line {line_number}: event_hash has invalid format"));
        }
        if !is_audit_chain_previous_hash(previous_event_hash) {
            report.failures.push(format!(
                "line {line_number}: previous_event_hash has invalid format"
            ));
        }
        if previous_event_hash != expected_previous_hash {
            report
                .failures
                .push(format!("line {line_number}: previous_event_hash mismatch"));
        }
        let recomputed = compute_audit_event_hash(previous_event_hash, &event)?;
        if recomputed != event_hash {
            report
                .failures
                .push(format!("line {line_number}: event_hash mismatch"));
        }
        expected_previous_hash = event_hash.to_string();
        report.last_event_hash = Some(event_hash.to_string());
    }
    report.mismatch_count = report.failures.len();
    report.verified = report.mismatch_count == 0;
    Ok(report)
}

async fn verify_db_audit_chain(
    db: &dyn Database,
    tenant_id: &str,
) -> anyhow::Result<TraceDbAuditChainReport> {
    let events = db
        .list_trace_audit_events(tenant_id)
        .await
        .context("failed to list DB audit events for hash-chain verification")?;
    verify_db_audit_chain_records(&events)
}

fn verify_db_audit_chain_records(
    events: &[StorageTraceAuditEventRecord],
) -> anyhow::Result<TraceDbAuditChainReport> {
    let mut report = TraceDbAuditChainReport::default();
    let mut expected_previous_hash = TRACE_AUDIT_EVENT_GENESIS_HASH.to_string();
    for (index, event) in events.iter().enumerate() {
        let row_number = index + 1;
        report.event_count += 1;
        let Some(event_hash) = event.event_hash.as_deref() else {
            report.legacy_event_count += 1;
            expected_previous_hash = TRACE_AUDIT_EVENT_GENESIS_HASH.to_string();
            continue;
        };
        if !is_canonical_sha256_prefixed_hash(event_hash) {
            report.failures.push(format!(
                "db row {row_number} event {}: event_hash has invalid format",
                event.audit_event_id
            ));
        }
        let previous_event_hash = event
            .previous_event_hash
            .as_deref()
            .unwrap_or(TRACE_AUDIT_EVENT_GENESIS_HASH);
        if !is_audit_chain_previous_hash(previous_event_hash) {
            report.failures.push(format!(
                "db row {row_number} event {}: previous_event_hash has invalid format",
                event.audit_event_id
            ));
        }
        if previous_event_hash != expected_previous_hash {
            report.failures.push(format!(
                "db row {row_number} event {}: previous_event_hash mismatch",
                event.audit_event_id
            ));
        }
        if let Some(canonical_event_json) = event.canonical_event_json.as_deref() {
            report.payload_verified_event_count += 1;
            let recomputed =
                compute_audit_event_hash_from_canonical(previous_event_hash, canonical_event_json);
            if recomputed != event_hash {
                report.failures.push(format!(
                    "db row {row_number} event {}: canonical payload hash mismatch",
                    event.audit_event_id
                ));
            }
            let canonical_event: TraceCommonsAuditEvent =
                serde_json::from_str(canonical_event_json).with_context(|| {
                    format!(
                        "failed to parse canonical audit payload for DB audit event {}",
                        event.audit_event_id
                    )
                })?;
            verify_db_audit_projection(row_number, event, &canonical_event, &mut report);
        } else {
            report.payload_unverified_event_count += 1;
        }
        expected_previous_hash = event_hash.to_string();
        report.last_event_hash = Some(event_hash.to_string());
    }
    report.mismatch_count = report.failures.len();
    report.verified = report.mismatch_count == 0;
    Ok(report)
}

fn verify_db_audit_projection(
    row_number: usize,
    event: &StorageTraceAuditEventRecord,
    canonical_event: &TraceCommonsAuditEvent,
    report: &mut TraceDbAuditChainReport,
) {
    let event_ref = event.audit_event_id;
    if canonical_event.event_id != event.audit_event_id {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical event_id mismatch"
        ));
    }
    if canonical_event.tenant_id != event.tenant_id {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical tenant_id mismatch"
        ));
    }
    if Some(canonical_event.submission_id).filter(|id| *id != Uuid::nil()) != event.submission_id {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical submission_id mismatch"
        ));
    }
    if canonical_event.kind != storage_audit_canonical_kind(event) {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical kind/action mismatch"
        ));
    }
    if canonical_event.status != storage_audit_canonical_status(event) {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical status mismatch"
        ));
    }
    if let Some(actor_role) = canonical_event.actor_role
        && actor_role.storage_name() != event.actor_role
    {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical actor_role mismatch"
        ));
    }
    if let Some(actor_principal_ref) = canonical_event.actor_principal_ref.as_deref()
        && actor_principal_ref != event.actor_principal_ref
    {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical actor_principal_ref mismatch"
        ));
    }
    if canonical_event.reason != event.reason {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical reason mismatch"
        ));
    }
    if let Some(projected_reason) = storage_audit_canonical_reason(event)
        && canonical_event.reason.as_deref() != Some(projected_reason.as_str())
    {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical metadata reason mismatch"
        ));
    }
    if let Some(expected_reason_hash) = storage_audit_canonical_reason_hash(event)
        && canonical_event
            .reason
            .as_deref()
            .map(sha256_prefixed)
            .as_deref()
            != Some(expected_reason_hash.as_str())
    {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical metadata reason hash mismatch"
        ));
    }
    if canonical_event.export_id != event.export_manifest_id {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical export_id mismatch"
        ));
    }
    if canonical_event.decision_inputs_hash != event.decision_inputs_hash {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical decision_inputs_hash mismatch"
        ));
    }
    if canonical_event.previous_event_hash != event.previous_event_hash {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical previous_event_hash mismatch"
        ));
    }
    if canonical_event.event_hash.is_some() {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical payload should not include event_hash"
        ));
    }
    if let Some(projected_export_count) = storage_audit_canonical_export_count(event)
        && canonical_event.export_count != Some(projected_export_count)
    {
        report.failures.push(format!(
            "db row {row_number} event {event_ref}: canonical export_count mismatch"
        ));
    }
}

fn storage_audit_canonical_kind(event: &StorageTraceAuditEventRecord) -> String {
    if event.action == StorageTraceAuditAction::Read
        && event.submission_id.is_some()
        && event
            .reason
            .as_deref()
            .is_some_and(|reason| reason.contains("surface=replay_dataset_export"))
    {
        return "trace_content_read".to_string();
    }
    if event.action == StorageTraceAuditAction::Read
        && trace_audit_reason_is_rollout_smoke_evidence(event.reason.as_deref())
    {
        return "rollout_smoke_evidence".to_string();
    }
    if event.action == StorageTraceAuditAction::CreditMutate
        && trace_audit_reason_is_credit_settlement_issuer_approval(event.reason.as_deref())
    {
        return "credit_settlement_issuer_approval".to_string();
    }
    if event.action == StorageTraceAuditAction::Retain
        && matches!(
            &event.metadata,
            StorageTraceAuditSafeMetadata::Maintenance { surface: None, .. }
        )
        && event.reason.as_deref().is_some_and(|reason| {
            reason.starts_with("purpose=") || reason.starts_with("purpose_hash=")
        })
    {
        return "maintenance".to_string();
    }
    storage_audit_event_kind(event.action, &event.metadata)
}

fn storage_audit_canonical_status(
    event: &StorageTraceAuditEventRecord,
) -> Option<TraceCorpusStatus> {
    match &event.metadata {
        StorageTraceAuditSafeMetadata::Submission { status, .. }
        | StorageTraceAuditSafeMetadata::ReviewDecision {
            resulting_status: status,
            ..
        } => trace_corpus_status_from_storage(*status),
        StorageTraceAuditSafeMetadata::ReviewLease { .. } => Some(TraceCorpusStatus::Quarantined),
        StorageTraceAuditSafeMetadata::Revocation { .. } => Some(TraceCorpusStatus::Revoked),
        _ => None,
    }
}

fn storage_audit_canonical_export_count(event: &StorageTraceAuditEventRecord) -> Option<usize> {
    match &event.metadata {
        StorageTraceAuditSafeMetadata::Read { item_count, .. } => Some(*item_count as usize),
        StorageTraceAuditSafeMetadata::Export { item_count, .. } => Some(*item_count as usize),
        _ => None,
    }
}

fn storage_maintenance_audit_reason(event: &StorageTraceAuditEventRecord) -> Option<String> {
    let StorageTraceAuditSafeMetadata::Maintenance {
        surface,
        purpose_hash,
        dry_run,
        action_counts,
    } = &event.metadata
    else {
        return None;
    };
    if let Some(reason) = event.reason.as_deref() {
        let parsed = trace_maintenance_audit_metadata_from_reason(
            surface.as_deref().unwrap_or("maintenance"),
            Some(reason),
        );
        if let Some(StorageTraceAuditSafeMetadata::Maintenance {
            surface: parsed_surface,
            purpose_hash: parsed_purpose_hash,
            dry_run: parsed_dry_run,
            action_counts: parsed_action_counts,
        }) = parsed
        {
            let surface_matches = surface
                .as_deref()
                .zip(parsed_surface.as_deref())
                .is_none_or(|(expected, parsed)| expected == parsed);
            let purpose_hash_matches = purpose_hash
                .as_deref()
                .is_none_or(|expected| parsed_purpose_hash.as_deref() == Some(expected));
            if surface_matches
                && purpose_hash_matches
                && parsed_dry_run == *dry_run
                && parsed_action_counts == *action_counts
            {
                return Some(reason.to_string());
            }
        }
    }
    Some(trace_maintenance_audit_reason(
        purpose_hash.as_deref(),
        *dry_run,
        action_counts,
    ))
}

fn storage_audit_canonical_reason(event: &StorageTraceAuditEventRecord) -> Option<String> {
    match &event.metadata {
        StorageTraceAuditSafeMetadata::Read {
            surface,
            item_count,
        } => Some(trace_read_audit_reason(surface, *item_count as usize)),
        StorageTraceAuditSafeMetadata::TraceContentRead {
            surface,
            purpose_hash,
        } => Some(trace_content_read_audit_reason(
            surface,
            purpose_hash.as_deref(),
        )),
        StorageTraceAuditSafeMetadata::CreditSettlementIssuerApproval {
            policy_version,
            source_list_hash,
            evidence_hash,
            reason_hash,
            evidence_ref_hash,
        } => Some(
            trace_credit_settlement_issuer_approval_audit_reason_from_parts(
                policy_version,
                source_list_hash,
                evidence_hash,
                reason_hash,
                evidence_ref_hash.as_deref(),
            ),
        ),
        StorageTraceAuditSafeMetadata::CreditHold {
            action,
            hold_id,
            credit_account_hash,
            hold_reason,
            reason_hash,
        } => Some(trace_credit_hold_audit_reason_from_parts(
            *action,
            *hold_id,
            credit_account_hash,
            *hold_reason,
            reason_hash,
        )),
        StorageTraceAuditSafeMetadata::NearCreditOutboxStatus {
            near_outbox_id,
            settlement_batch_id,
            credit_account_hash,
            status,
            near_transaction_hash_hash,
            last_error_hash,
        } => Some(trace_near_credit_outbox_status_audit_reason_from_parts(
            *near_outbox_id,
            *settlement_batch_id,
            credit_account_hash,
            *status,
            near_transaction_hash_hash.as_deref(),
            last_error_hash.as_deref(),
        )),
        StorageTraceAuditSafeMetadata::BenchmarkRegistryOutboxStatus {
            benchmark_outbox_id,
            conversion_id,
            operation,
            registry_ref_hash,
            artifact_payload_hash,
            source_submission_ids_hash,
            evaluator_ref_hash,
            status,
            external_receipt_ref_hash,
            last_error_hash,
        } => Some(
            trace_benchmark_registry_outbox_status_audit_reason_from_parts(
                TraceBenchmarkRegistryOutboxStatusAuditReasonParts {
                    benchmark_outbox_id: *benchmark_outbox_id,
                    conversion_id: *conversion_id,
                    operation: *operation,
                    registry_ref_hash,
                    artifact_payload_hash,
                    source_submission_ids_hash,
                    evaluator_ref_hash: evaluator_ref_hash.as_deref(),
                    status: *status,
                    external_receipt_ref_hash: external_receipt_ref_hash.as_deref(),
                    last_error_hash: last_error_hash.as_deref(),
                },
            ),
        ),
        StorageTraceAuditSafeMetadata::Maintenance { .. } => {
            storage_maintenance_audit_reason(event)
        }
        _ => None,
    }
}

fn storage_audit_canonical_reason_hash(event: &StorageTraceAuditEventRecord) -> Option<String> {
    match &event.metadata {
        StorageTraceAuditSafeMetadata::Revocation { reason_hash } => Some(reason_hash.clone()),
        _ => None,
    }
}

async fn backfill_db_mirror_from_files(
    state: &AppState,
    tenant: &TenantAuth,
    records: &[TraceCommonsSubmissionRecord],
    derived: &[TraceCommonsDerivedRecord],
    enabled: bool,
    dry_run: bool,
) -> anyhow::Result<TraceBackfillReport> {
    let mut report = TraceBackfillReport::default();
    if !enabled {
        return Ok(report);
    }
    if state.db_mirror.is_none() && !dry_run {
        anyhow::bail!(
            "Trace Commons DB mirror backfill requested but TRACE_COMMONS_DB_DUAL_WRITE is not configured"
        );
    }
    let db = state.db_mirror.as_ref();
    let derived_by_submission = derived
        .iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let records_by_submission = records
        .iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    for record in records {
        if record.status == TraceCorpusStatus::Purged {
            continue;
        }
        if let Some(db) = db
            && !dry_run
            && db
                .get_trace_submission(&tenant.tenant_id, record.submission_id)
                .await
                .with_context(|| {
                    format!(
                        "failed to query existing DB submission for backfill {}",
                        record.submission_id
                    )
                })?
                .is_some()
        {
            continue;
        }

        let envelope = match read_envelope_by_record(state, record)
            .with_context(|| format!("failed to validate envelope {}", record.submission_id))
        {
            Ok(envelope) => envelope,
            Err(error) => {
                report.record_failure(
                    "submission",
                    record.submission_id.to_string(),
                    error.to_string(),
                );
                continue;
            }
        };
        let derived_record = derived_by_submission
            .get(&record.submission_id)
            .copied()
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "trace submission {} is missing a derived precheck record",
                    record.submission_id
                )
            });
        let derived_record = match derived_record {
            Ok(record) => record,
            Err(error) => {
                report.record_failure(
                    "submission",
                    record.submission_id.to_string(),
                    error.to_string(),
                );
                continue;
            }
        };
        if dry_run {
            report.backfilled += 1;
            continue;
        }
        if let Err(error) = mirror_submission_to_db_with_options(
            state,
            tenant,
            record,
            derived_record,
            &envelope,
            false,
        )
        .await
        {
            report.record_failure(
                "submission",
                record.submission_id.to_string(),
                error.to_string(),
            );
            continue;
        }
        if record.is_revoked()
            && let Err(error) = mirror_revocation_to_db(
                state,
                TraceRevocationDbMirrorInput {
                    tenant,
                    submission_id: record.submission_id,
                    record: Some(record),
                    db_record: None,
                    revocation_reason: TRACE_DEFAULT_REVOCATION_REASON,
                    retention_ledger: None,
                    prepared_tombstone: None,
                },
            )
            .await
        {
            report.record_failure(
                "submission",
                record.submission_id.to_string(),
                error.to_string(),
            );
            continue;
        }
        report.backfilled += 1;
    }

    let file_credit_events = read_all_credit_events(&state.root, &tenant.tenant_id)?;
    let file_audit_events = read_all_audit_events(&state.root, &tenant.tenant_id)?;
    let file_export_manifests = read_all_export_manifests(&state.root, &tenant.tenant_id)?;
    let file_utility_attestations = read_all_utility_attestations(&state.root, &tenant.tenant_id)?;
    let file_credit_settlement_batches =
        read_all_credit_settlement_batches(&state.root, &tenant.tenant_id)?;
    let file_credit_holds = read_all_credit_holds(&state.root, &tenant.tenant_id)?;
    let file_near_credit_outbox_items =
        read_all_near_credit_outbox_items(&state.root, &tenant.tenant_id)?;
    let file_benchmark_registry_outbox_items =
        read_all_benchmark_registry_outbox_items(&state.root, &tenant.tenant_id)?;
    let file_ranking_model_versions =
        read_all_ranking_model_versions(&state.root, &tenant.tenant_id)?;
    let file_latest_ranking_model_versions =
        latest_ranking_model_versions(&file_ranking_model_versions);
    let file_ranking_calibration_datasets =
        read_all_ranking_calibration_datasets(&state.root, &tenant.tenant_id)?;
    let file_ranking_features = read_all_ranking_features(&state.root, &tenant.tenant_id)?;
    let file_ranking_predictions = read_all_ranking_predictions(&state.root, &tenant.tenant_id)?;
    let file_ranking_labels = read_all_ranking_labels(&state.root, &tenant.tenant_id)?;
    let file_ranking_preference_labels =
        read_all_ranking_preference_labels(&state.root, &tenant.tenant_id)?;
    let file_ranking_calibration_runs =
        read_all_ranking_calibration_runs(&state.root, &tenant.tenant_id)?;
    let file_ranking_worker_runs = read_all_ranking_worker_runs(&state.root, &tenant.tenant_id)?;
    if dry_run {
        report.backfilled += file_credit_events.len()
            + file_audit_events.len()
            + file_utility_attestations.len()
            + file_credit_settlement_batches.len()
            + file_credit_holds.len()
            + file_near_credit_outbox_items.len()
            + file_benchmark_registry_outbox_items.len()
            + file_latest_ranking_model_versions.len()
            + file_ranking_calibration_datasets.len()
            + file_ranking_features.len()
            + file_ranking_predictions.len()
            + file_ranking_labels.len()
            + file_ranking_preference_labels.len()
            + file_ranking_calibration_runs.len()
            + file_ranking_worker_runs.len();
        for manifest in &file_export_manifests {
            match replay_export_items_for_manifest_backfill(
                state,
                manifest,
                &records_by_submission,
                &derived_by_submission,
            ) {
                Ok(_) => report.backfilled += 1,
                Err(error) => report.record_failure(
                    "replay_export_manifest",
                    manifest.export_id.to_string(),
                    error.to_string(),
                ),
            }
        }
        return Ok(report);
    }

    let Some(db) = db else {
        return Ok(report);
    };
    let existing_credit_event_ids = db
        .list_trace_credit_events(&tenant.tenant_id)
        .await
        .context("failed to list trace credit events for DB backfill")?
        .into_iter()
        .map(|event| event.credit_event_id)
        .collect::<BTreeSet<_>>();
    for event in &file_credit_events {
        if existing_credit_event_ids.contains(&event.event_id) {
            continue;
        }
        match mirror_credit_event_to_db(state, event).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => report.record_failure(
                "credit_event",
                event.event_id.to_string(),
                error.to_string(),
            ),
        }
    }

    let existing_audit_event_ids = db
        .list_trace_audit_events(&tenant.tenant_id)
        .await
        .context("failed to list trace audit events for DB backfill")?
        .into_iter()
        .map(|event| event.audit_event_id)
        .collect::<BTreeSet<_>>();
    for event in &file_audit_events {
        if existing_audit_event_ids.contains(&event.event_id) {
            continue;
        }
        let (action, metadata) =
            audit_backfill_storage_projection_for_records(event, &records_by_submission);
        match mirror_audit_event_to_db(state, tenant, event, action, metadata).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => {
                report.record_failure("audit_event", event.event_id.to_string(), error.to_string())
            }
        }
    }

    let existing_utility_attestation_ids = db
        .list_trace_utility_attestations(&tenant.tenant_id)
        .await
        .context("failed to list utility attestations for DB backfill")?
        .into_iter()
        .map(|attestation| attestation.attestation_id)
        .collect::<BTreeSet<_>>();
    for attestation in &file_utility_attestations {
        if existing_utility_attestation_ids.contains(&attestation.attestation_id) {
            continue;
        }
        match mirror_utility_attestation_to_db(state, attestation).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => report.record_failure(
                "utility_attestation",
                attestation.attestation_id.to_string(),
                error.to_string(),
            ),
        }
    }

    let existing_credit_settlement_batch_ids = db
        .list_trace_credit_settlement_batches(&tenant.tenant_id)
        .await
        .context("failed to list credit settlement batches for DB backfill")?
        .into_iter()
        .map(|batch| batch.settlement_batch_id)
        .collect::<BTreeSet<_>>();
    for batch in &file_credit_settlement_batches {
        if existing_credit_settlement_batch_ids.contains(&batch.settlement_batch_id) {
            continue;
        }
        match mirror_credit_settlement_batch_to_db(state, batch).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => report.record_failure(
                "credit_settlement_batch",
                batch.settlement_batch_id.to_string(),
                error.to_string(),
            ),
        }
    }

    let existing_credit_hold_ids = db
        .list_trace_credit_holds(&tenant.tenant_id)
        .await
        .context("failed to list credit holds for DB backfill")?
        .into_iter()
        .map(|hold| hold.hold_id)
        .collect::<BTreeSet<_>>();
    for hold in &file_credit_holds {
        if existing_credit_hold_ids.contains(&hold.hold_id) {
            continue;
        }
        match mirror_credit_hold_to_db(state, hold).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => {
                report.record_failure("credit_hold", hold.hold_id.to_string(), error.to_string())
            }
        }
    }

    let existing_near_credit_outbox_ids = db
        .list_trace_near_credit_outbox_items(&tenant.tenant_id)
        .await
        .context("failed to list NEAR credit outbox items for DB backfill")?
        .into_iter()
        .map(|item| item.near_outbox_id)
        .collect::<BTreeSet<_>>();
    for item in &file_near_credit_outbox_items {
        let item_already_mirrored = existing_near_credit_outbox_ids.contains(&item.near_outbox_id);
        let mirror_result = async {
            if !item_already_mirrored {
                mirror_near_credit_outbox_item_to_db(state, item).await?;
            }
            if matches!(
                item.status,
                StorageTraceCreditSettlementNearStatus::Submitted
                    | StorageTraceCreditSettlementNearStatus::Confirmed
                    | StorageTraceCreditSettlementNearStatus::Failed
            ) {
                mirror_near_credit_outbox_item_status_to_db(
                    state,
                    &tenant.tenant_id,
                    item.near_outbox_id,
                    item.status,
                    item.near_transaction_hash.clone(),
                    item.last_error_hash.clone(),
                )
                .await?;
            }
            Ok::<_, anyhow::Error>(())
        }
        .await;
        match mirror_result {
            Ok(()) if !item_already_mirrored => report.backfilled += 1,
            Ok(()) => {}
            Err(error) => report.record_failure(
                if item_already_mirrored {
                    "near_credit_outbox_item_status"
                } else {
                    "near_credit_outbox_item"
                },
                item.near_outbox_id.to_string(),
                error.to_string(),
            ),
        }
    }

    let existing_benchmark_registry_outbox_ids = db
        .list_trace_benchmark_registry_outbox_items(&tenant.tenant_id)
        .await
        .context("failed to list benchmark registry outbox items for DB backfill")?
        .into_iter()
        .map(|item| item.benchmark_outbox_id)
        .collect::<BTreeSet<_>>();
    for item in &file_benchmark_registry_outbox_items {
        let item_already_mirrored =
            existing_benchmark_registry_outbox_ids.contains(&item.benchmark_outbox_id);
        let mirror_result = async {
            if !item_already_mirrored {
                mirror_benchmark_registry_outbox_item_to_db(state, item).await?;
            }
            if matches!(
                item.status,
                StorageTraceBenchmarkRegistryOutboxStatus::Submitted
                    | StorageTraceBenchmarkRegistryOutboxStatus::Confirmed
                    | StorageTraceBenchmarkRegistryOutboxStatus::Failed
            ) {
                mirror_benchmark_registry_outbox_item_status_to_db(
                    state,
                    &tenant.tenant_id,
                    item.benchmark_outbox_id,
                    item.status,
                    item.external_receipt_ref.clone(),
                    item.last_error_hash.clone(),
                )
                .await?;
            }
            Ok::<_, anyhow::Error>(())
        }
        .await;
        match mirror_result {
            Ok(()) if !item_already_mirrored => report.backfilled += 1,
            Ok(()) => {}
            Err(error) => report.record_failure(
                if item_already_mirrored {
                    "benchmark_registry_outbox_item_status"
                } else {
                    "benchmark_registry_outbox_item"
                },
                item.benchmark_outbox_id.to_string(),
                error.to_string(),
            ),
        }
    }

    let existing_ranking_model_versions = db
        .list_trace_ranking_model_versions(&tenant.tenant_id)
        .await
        .context("failed to list ranking model versions for DB backfill")?
        .into_iter()
        .map(|record| (record.model_version.clone(), record))
        .collect::<BTreeMap<_, _>>();
    for record in &file_latest_ranking_model_versions {
        if existing_ranking_model_versions
            .get(&record.model_version)
            .is_some_and(|db_record| db_record.status == record.status)
        {
            continue;
        }
        match mirror_ranking_model_version_to_db(state, record).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => report.record_failure(
                "ranking_model_version",
                record.model_version.clone(),
                error.to_string(),
            ),
        }
    }

    let existing_ranking_calibration_dataset_keys = db
        .list_trace_ranking_calibration_datasets(&tenant.tenant_id)
        .await
        .context("failed to list ranking calibration datasets for DB backfill")?
        .into_iter()
        .map(|record| (ranking_calibration_dataset_storage_key(&record), record))
        .collect::<BTreeMap<_, _>>();
    for record in &file_ranking_calibration_datasets {
        let key = ranking_calibration_dataset_file_key(record)?;
        if existing_ranking_calibration_dataset_keys
            .get(&key)
            .is_some_and(|db_record| {
                db_record.status == record.status
                    && db_record.source_manifest_hash == record.source_manifest_hash
            })
        {
            continue;
        }
        match mirror_ranking_calibration_dataset_to_db(state, record).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => {
                report.record_failure("ranking_calibration_dataset", key, error.to_string())
            }
        }
    }

    let existing_ranking_feature_ids = db
        .list_trace_ranking_features(&tenant.tenant_id)
        .await
        .context("failed to list ranking features for DB backfill")?
        .into_iter()
        .map(|record| record.ranking_feature_id)
        .collect::<BTreeSet<_>>();
    for record in &file_ranking_features {
        if existing_ranking_feature_ids.contains(&record.ranking_feature_id) {
            continue;
        }
        match mirror_ranking_feature_to_db(state, record).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => report.record_failure(
                "ranking_feature",
                record.ranking_feature_id.to_string(),
                error.to_string(),
            ),
        }
    }

    let existing_ranking_prediction_ids = db
        .list_trace_ranking_predictions(&tenant.tenant_id)
        .await
        .context("failed to list ranking predictions for DB backfill")?
        .into_iter()
        .map(|record| record.ranking_prediction_id)
        .collect::<BTreeSet<_>>();
    for record in &file_ranking_predictions {
        if existing_ranking_prediction_ids.contains(&record.ranking_prediction_id) {
            continue;
        }
        match mirror_ranking_prediction_to_db(state, record).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => report.record_failure(
                "ranking_prediction",
                record.ranking_prediction_id.to_string(),
                error.to_string(),
            ),
        }
    }

    let existing_ranking_label_ids = db
        .list_trace_ranking_labels(&tenant.tenant_id)
        .await
        .context("failed to list ranking labels for DB backfill")?
        .into_iter()
        .map(|record| record.ranking_label_id)
        .collect::<BTreeSet<_>>();
    for record in &file_ranking_labels {
        if existing_ranking_label_ids.contains(&record.ranking_label_id) {
            continue;
        }
        match mirror_ranking_label_to_db(state, record).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => report.record_failure(
                "ranking_label",
                record.ranking_label_id.to_string(),
                error.to_string(),
            ),
        }
    }

    let existing_ranking_preference_label_ids = db
        .list_trace_ranking_preference_labels(&tenant.tenant_id)
        .await
        .context("failed to list ranking preference labels for DB backfill")?
        .into_iter()
        .map(|record| record.preference_label_id)
        .collect::<BTreeSet<_>>();
    for record in &file_ranking_preference_labels {
        if existing_ranking_preference_label_ids.contains(&record.preference_label_id) {
            continue;
        }
        match mirror_ranking_preference_label_to_db(state, record).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => report.record_failure(
                "ranking_preference_label",
                record.preference_label_id.to_string(),
                error.to_string(),
            ),
        }
    }

    let existing_ranking_calibration_runs = db
        .list_trace_ranking_calibration_runs(&tenant.tenant_id)
        .await
        .context("failed to list ranking calibration runs for DB backfill")?
        .into_iter()
        .map(|record| (record.calibration_run_id, record))
        .collect::<BTreeMap<_, _>>();
    for record in &file_ranking_calibration_runs {
        if existing_ranking_calibration_runs
            .get(&record.calibration_run_id)
            .is_some_and(|db_record| db_record.report_hash == record.report_hash)
        {
            continue;
        }
        match mirror_ranking_calibration_run_to_db(state, record).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => report.record_failure(
                "ranking_calibration_run",
                record.calibration_run_id.to_string(),
                error.to_string(),
            ),
        }
    }

    let existing_ranking_worker_runs = db
        .list_trace_ranking_worker_runs(&tenant.tenant_id)
        .await
        .context("failed to list ranking worker runs for DB backfill")?
        .into_iter()
        .map(|record| (record.ranking_worker_run_id, record))
        .collect::<BTreeMap<_, _>>();
    for record in &file_ranking_worker_runs {
        if existing_ranking_worker_runs
            .get(&record.ranking_worker_run_id)
            .is_some_and(|db_record| db_record.status == record.status)
        {
            continue;
        }
        match mirror_ranking_worker_run_to_db(state, record).await {
            Ok(()) => report.backfilled += 1,
            Err(error) => report.record_failure(
                "ranking_worker_run",
                record.ranking_worker_run_id.to_string(),
                error.to_string(),
            ),
        }
    }

    let existing_export_manifest_ids = db
        .list_trace_export_manifests(&tenant.tenant_id)
        .await
        .context("failed to list trace export manifests for DB backfill")?
        .into_iter()
        .map(|manifest| manifest.export_manifest_id)
        .collect::<BTreeSet<_>>();
    for manifest in &file_export_manifests {
        if existing_export_manifest_ids.contains(&manifest.export_id) {
            continue;
        }
        let items = match replay_export_items_for_manifest_backfill(
            state,
            manifest,
            &records_by_submission,
            &derived_by_submission,
        ) {
            Ok(items) => items,
            Err(error) => {
                report.record_failure(
                    "replay_export_manifest",
                    manifest.export_id.to_string(),
                    error.to_string(),
                );
                continue;
            }
        };
        match mirror_export_manifest_to_db(
            state,
            StorageTraceObjectArtifactKind::ExportArtifact,
            manifest,
            &items,
        )
        .await
        {
            Ok(()) => report.backfilled += 1,
            Err(error) => report.record_failure(
                "replay_export_manifest",
                manifest.export_id.to_string(),
                error.to_string(),
            ),
        }
    }
    Ok(report)
}

fn audit_backfill_storage_projection(
    event: &TraceCommonsAuditEvent,
) -> (StorageTraceAuditAction, StorageTraceAuditSafeMetadata) {
    let action = match event.kind.as_str() {
        "submitted" => StorageTraceAuditAction::Submit,
        "read" | "trace_content_read" => StorageTraceAuditAction::Read,
        "review_decision" | "review_lease" => StorageTraceAuditAction::Review,
        "credit_mutate"
        | "credit_settlement_issuer_approval"
        | "credit_hold"
        | "credit_hold_release"
        | "near_credit_outbox_status" => StorageTraceAuditAction::CreditMutate,
        "benchmark_registry_outbox_status" => StorageTraceAuditAction::BenchmarkConvert,
        "revoked" | "revocation_propagation" => StorageTraceAuditAction::Revoke,
        "dataset_export" | "ranker_training_candidates_export" | "ranker_training_pairs_export" => {
            StorageTraceAuditAction::Export
        }
        "maintenance"
        | "near_credit_outbox_submit"
        | "near_credit_outbox_confirm"
        | "benchmark_registry_outbox_submit"
        | "benchmark_registry_outbox_confirm" => StorageTraceAuditAction::Retain,
        "purge" => StorageTraceAuditAction::Purge,
        "vector_index" => StorageTraceAuditAction::VectorIndex,
        "benchmark_conversion" | "benchmark_lifecycle_update" => {
            StorageTraceAuditAction::BenchmarkConvert
        }
        "process_evaluation" => StorageTraceAuditAction::ProcessEvaluate,
        "tenant_policy_update" | "tenant_access_grant_update" => {
            StorageTraceAuditAction::PolicyUpdate
        }
        "export_job_recovery" => StorageTraceAuditAction::ExportJobRecovery,
        "ranking_worker_run_recovery" => StorageTraceAuditAction::RankingWorkerRunRecovery,
        "ranking_calibration_dataset_quarantine" => {
            StorageTraceAuditAction::RankingCalibrationDatasetQuarantine
        }
        _ => StorageTraceAuditAction::Read,
    };
    let metadata = match event.kind.as_str() {
        "submitted" => event
            .status
            .map(|status| StorageTraceAuditSafeMetadata::Submission {
                status: storage_corpus_status(status),
                privacy_risk: "unknown".to_string(),
            })
            .unwrap_or(StorageTraceAuditSafeMetadata::Empty),
        "review_lease" => trace_review_lease_audit_action_from_reason(event.reason.as_deref())
            .map(|action| StorageTraceAuditSafeMetadata::ReviewLease {
                action,
                lease_expires_at: trace_review_lease_timestamp_from_reason(
                    event.reason.as_deref(),
                    "lease_expires_at",
                ),
                review_due_at: trace_review_lease_timestamp_from_reason(
                    event.reason.as_deref(),
                    "review_due_at",
                ),
            })
            .unwrap_or(StorageTraceAuditSafeMetadata::Empty),
        "read" => trace_read_audit_metadata_from_reason(event.reason.as_deref())
            .unwrap_or(StorageTraceAuditSafeMetadata::Empty),
        "trace_content_read" => {
            trace_content_read_audit_metadata_from_reason(event.reason.as_deref())
                .unwrap_or(StorageTraceAuditSafeMetadata::Empty)
        }
        "credit_settlement_issuer_approval" => {
            trace_credit_settlement_issuer_approval_audit_metadata_from_reason(
                event.reason.as_deref(),
            )
            .unwrap_or(StorageTraceAuditSafeMetadata::Empty)
        }
        "credit_hold" | "credit_hold_release" => {
            trace_credit_hold_audit_metadata_from_reason(&event.kind, event.reason.as_deref())
                .unwrap_or(StorageTraceAuditSafeMetadata::Empty)
        }
        "near_credit_outbox_status" => {
            trace_near_credit_outbox_status_audit_metadata_from_reason(event.reason.as_deref())
                .unwrap_or(StorageTraceAuditSafeMetadata::Empty)
        }
        "benchmark_registry_outbox_status" => {
            trace_benchmark_registry_outbox_status_audit_metadata_from_reason(
                event.reason.as_deref(),
            )
            .unwrap_or(StorageTraceAuditSafeMetadata::Empty)
        }
        "revoked" => trace_revocation_audit_metadata_from_reason(event.reason.as_deref())
            .unwrap_or(StorageTraceAuditSafeMetadata::Empty),
        "dataset_export" | "ranker_training_candidates_export" | "ranker_training_pairs_export" => {
            StorageTraceAuditSafeMetadata::Export {
                artifact_kind: StorageTraceObjectArtifactKind::ExportArtifact,
                purpose_code: Some(event.kind.clone()),
                item_count: event
                    .export_count
                    .unwrap_or_default()
                    .min(u32::MAX as usize) as u32,
            }
        }
        "benchmark_conversion" | "benchmark_lifecycle_update" => {
            StorageTraceAuditSafeMetadata::Export {
                artifact_kind: StorageTraceObjectArtifactKind::BenchmarkArtifact,
                purpose_code: Some(event.kind.clone()),
                item_count: event
                    .export_count
                    .unwrap_or_default()
                    .min(u32::MAX as usize) as u32,
            }
        }
        "tenant_policy_update" => tenant_policy_audit_metadata_from_reason(event.reason.as_deref())
            .unwrap_or(StorageTraceAuditSafeMetadata::Empty),
        "tenant_access_grant_update" => {
            tenant_access_grant_audit_metadata_from_reason(event.reason.as_deref())
                .unwrap_or(StorageTraceAuditSafeMetadata::Empty)
        }
        "export_job_recovery" => {
            export_job_recovery_audit_metadata_from_reason(event.reason.as_deref())
                .unwrap_or(StorageTraceAuditSafeMetadata::Empty)
        }
        "ranking_worker_run_recovery" => {
            ranking_worker_run_recovery_audit_metadata_from_reason(event.reason.as_deref())
                .unwrap_or(StorageTraceAuditSafeMetadata::Empty)
        }
        "ranking_calibration_dataset_quarantine" => {
            ranking_calibration_dataset_quarantine_audit_metadata_from_reason(
                event.reason.as_deref(),
            )
            .unwrap_or(StorageTraceAuditSafeMetadata::Empty)
        }
        "maintenance"
        | "near_credit_outbox_submit"
        | "near_credit_outbox_confirm"
        | "benchmark_registry_outbox_submit"
        | "benchmark_registry_outbox_confirm"
        | "revocation_propagation"
        | "vector_index" => {
            trace_maintenance_audit_metadata_from_reason(&event.kind, event.reason.as_deref())
                .unwrap_or(StorageTraceAuditSafeMetadata::Empty)
        }
        _ => StorageTraceAuditSafeMetadata::Empty,
    };
    (action, metadata)
}

fn audit_backfill_storage_projection_for_records(
    event: &TraceCommonsAuditEvent,
    records_by_submission: &BTreeMap<Uuid, &TraceCommonsSubmissionRecord>,
) -> (StorageTraceAuditAction, StorageTraceAuditSafeMetadata) {
    let (action, metadata) = audit_backfill_storage_projection(event);
    if event.kind == "submitted"
        && let Some(record) = records_by_submission.get(&event.submission_id)
    {
        return (
            action,
            StorageTraceAuditSafeMetadata::Submission {
                status: storage_corpus_status(record.status),
                privacy_risk: serde_storage_string(&record.privacy_risk)
                    .unwrap_or_else(|_| "unknown".to_string()),
            },
        );
    }
    (action, metadata)
}

fn replay_export_items_for_manifest_backfill(
    state: &AppState,
    manifest: &TraceReplayExportManifest,
    records_by_submission: &BTreeMap<Uuid, &TraceCommonsSubmissionRecord>,
    derived_by_submission: &BTreeMap<Uuid, &TraceCommonsDerivedRecord>,
) -> anyhow::Result<Vec<TraceReplayDatasetItem>> {
    let mut items = Vec::new();
    for submission_id in &manifest.source_submission_ids {
        let Some(record) = records_by_submission.get(submission_id) else {
            continue;
        };
        let envelope = read_envelope_by_record(state, record).with_context(|| {
            format!(
                "failed to read envelope {} while backfilling replay export manifest {}",
                record.submission_id, manifest.export_id
            )
        })?;
        items.push(TraceReplayDatasetItem::from_record(
            record,
            derived_by_submission.get(submission_id).copied(),
            &envelope,
            None,
        ));
    }
    Ok(items)
}

#[derive(Debug, Default)]
struct TraceVectorIndexRunReport {
    checked_count: usize,
    vector_entries_indexed: usize,
    skipped_existing_count: usize,
    pending_after_count: usize,
}

struct TraceVectorIndexCandidate<'a> {
    record: &'a StorageTraceDerivedRecord,
    source_hash: String,
    vector_entry_id: Uuid,
}

struct TraceVectorEmbeddingMaterialRequest<'a> {
    record: &'a StorageTraceDerivedRecord,
    vector_entry_id: Uuid,
    source_projection: StorageTraceVectorEntrySourceProjection,
    source_hash: &'a str,
    purpose: &'a str,
    embedding_input_hash: String,
    embedding_input: String,
}

async fn trace_vector_embedding_material_for_record(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceVectorEmbeddingMaterialRequest<'_>,
) -> anyhow::Result<TraceVectorEmbeddingMaterial> {
    let Some(embedder) = state.vector_embedder.as_ref() else {
        anyhow::ensure!(
            !state.require_external_vector_embedder,
            "Trace Commons vector embedding requires TRACE_COMMONS_VECTOR_EMBEDDER_URL"
        );
        return Ok(trace_vector_local_embedding_material(
            request.embedding_input_hash,
            &request.embedding_input,
        ));
    };
    let response = embedder
        .embed(TraceVectorEmbeddingRequest {
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            vector_entry_id: request.vector_entry_id,
            source_projection: request.source_projection,
            source_hash: request.source_hash.to_string(),
            canonical_summary_hash: request.record.canonical_summary_hash.clone(),
            summary_model: request.record.summary_model.clone(),
            worker_kind: request.record.worker_kind,
            worker_version: request.record.worker_version.clone(),
            purpose_hash: sha256_prefixed(request.purpose),
            embedding_input_hash: request.embedding_input_hash.clone(),
            embedding_input: request.embedding_input,
            tool_sequence: request.record.tool_sequence.clone(),
            tool_categories: request.record.tool_categories.clone(),
            coverage_tags: request.record.coverage_tags.clone(),
        })
        .await?;
    trace_vector_external_embedding_material(request.embedding_input_hash, response)
}

async fn active_trace_vector_payload_neighbor_candidates(
    state: &AppState,
    db: &dyn Database,
    tenant_id: &str,
    active_vector_entries: &[StorageTraceVectorEntryRecord],
    target: &TraceVectorEmbeddingMaterial,
) -> anyhow::Result<Vec<TraceVectorPayloadNeighborCandidate>> {
    if state.artifact_store.is_none() {
        return Ok(Vec::new());
    }
    let mut candidates = Vec::new();
    for entry in active_vector_entries
        .iter()
        .filter(|entry| entry.status == StorageTraceVectorEntryStatus::Active)
        .filter(|entry| entry.invalidated_at.is_none() && entry.deleted_at.is_none())
        .filter(|entry| entry.vector_store == target.vector_store)
        .filter(|entry| entry.embedding_model == target.embedding_model)
        .filter(|entry| entry.embedding_dimension == target.embedding_dimension)
        .filter(|entry| entry.embedding_version == target.embedding_version)
    {
        let object_refs = db
            .list_trace_object_refs(tenant_id, entry.submission_id)
            .await
            .with_context(|| {
                format!(
                    "failed to list trace vector payload object refs for submission {}",
                    entry.submission_id
                )
            })?;
        let Some(object_ref) = object_refs.into_iter().rev().find(|object_ref| {
            object_ref.artifact_kind == StorageTraceObjectArtifactKind::WorkerIntermediate
                && object_ref.invalidated_at.is_none()
                && object_ref.deleted_at.is_none()
                && object_ref.created_by_job_id == Some(entry.vector_entry_id)
        }) else {
            continue;
        };
        let payload = match read_trace_vector_payload_from_object_ref(state, tenant_id, &object_ref)
        {
            Ok(payload) => payload,
            Err(error) => {
                tracing::warn!(
                    tenant_id = %tenant_id,
                    submission_id = %entry.submission_id,
                    vector_entry_id = %entry.vector_entry_id,
                    error_hash = %safe_display_error_hash(&error),
                    "Skipping unreadable trace vector payload neighbor"
                );
                continue;
            }
        };
        if payload.vector_entry_id != entry.vector_entry_id
            || payload.source_hash != entry.source_hash
            || payload.vector_store != entry.vector_store
            || payload.embedding_model != entry.embedding_model
            || payload.embedding_dimension != entry.embedding_dimension
            || payload.embedding_version != entry.embedding_version
        {
            tracing::warn!(
                tenant_id = %tenant_id,
                submission_id = %entry.submission_id,
                vector_entry_id = %entry.vector_entry_id,
                "Skipping trace vector payload neighbor with stale entry metadata"
            );
            continue;
        }
        candidates.push(TraceVectorPayloadNeighborCandidate {
            submission_id: payload.submission_id,
            trace_id: payload.trace_id,
            source_hash: payload.source_hash,
            embedding_sha256: payload.embedding_sha256,
            vector_store: payload.vector_store,
            embedding_model: payload.embedding_model,
            embedding_dimension: payload.embedding_dimension,
            embedding_version: payload.embedding_version,
            embedding_algorithm: payload.embedding_algorithm,
            embedding_values: payload.embedding_values,
        });
    }
    Ok(candidates)
}

async fn run_vector_index_worker(
    state: &AppState,
    tenant: &TenantAuth,
    request: TraceVectorIndexRequest,
    limit: usize,
    tenant_policy: Option<&TenantSubmissionPolicy>,
) -> anyhow::Result<TraceVectorIndexResponse> {
    let purpose = request
        .purpose
        .as_deref()
        .map(str::trim)
        .filter(|purpose| !purpose.is_empty())
        .unwrap_or("trace_commons_vector_index_worker")
        .to_string();
    let report = index_vector_metadata_from_db(
        state,
        tenant,
        true,
        request.dry_run,
        &purpose,
        tenant_policy,
        Some(limit),
    )
    .await?;
    let mut action_counts = BTreeMap::new();
    action_counts.insert(
        "vector_entries_checked".to_string(),
        report.checked_count.min(u32::MAX as usize) as u32,
    );
    action_counts.insert(
        "vector_entries_indexed".to_string(),
        report.vector_entries_indexed.min(u32::MAX as usize) as u32,
    );
    action_counts.insert(
        "vector_entries_skipped_existing".to_string(),
        report.skipped_existing_count.min(u32::MAX as usize) as u32,
    );
    action_counts.insert(
        "vector_entries_pending_after".to_string(),
        report.pending_after_count.min(u32::MAX as usize) as u32,
    );
    let audit_event = TraceCommonsAuditEvent::vector_index(
        tenant,
        request.dry_run,
        Some(&purpose),
        action_counts.clone(),
    );
    let audit_event_id = audit_event.event_id;
    append_audit_event_with_db_mirror(
        state,
        tenant,
        audit_event,
        StorageTraceAuditAction::VectorIndex,
        StorageTraceAuditSafeMetadata::Maintenance {
            surface: Some("vector_index".to_string()),
            purpose_hash: Some(sha256_prefixed(&purpose)),
            dry_run: request.dry_run,
            action_counts,
        },
    )
    .await?;
    Ok(TraceVectorIndexResponse {
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        purpose,
        dry_run: request.dry_run,
        audit_event_id,
        checked_count: report.checked_count,
        vector_entries_indexed: report.vector_entries_indexed,
        skipped_existing_count: report.skipped_existing_count,
        pending_after_count: report.pending_after_count,
    })
}

async fn index_vector_metadata_from_db(
    state: &AppState,
    tenant: &TenantAuth,
    enabled: bool,
    dry_run: bool,
    purpose: &str,
    tenant_policy: Option<&TenantSubmissionPolicy>,
    limit: Option<usize>,
) -> anyhow::Result<TraceVectorIndexRunReport> {
    if !enabled {
        return Ok(TraceVectorIndexRunReport::default());
    }
    let db = state
        .db_mirror
        .as_ref()
        .context("Trace Commons vector indexing requires TRACE_COMMONS_DB_DUAL_WRITE")?;
    let submissions = db
        .list_trace_submissions(&tenant.tenant_id)
        .await
        .context("failed to list trace submissions for vector indexing")?;
    let mut accepted_submissions_by_id = BTreeMap::new();
    for storage_record in submissions {
        if storage_record.status != StorageTraceCorpusStatus::Accepted
            || storage_record.revoked_at.is_some()
            || storage_record.purged_at.is_some()
        {
            continue;
        }
        let Some(record) = trace_commons_record_from_storage_submission(storage_record) else {
            continue;
        };
        let record = record.context("failed to parse DB trace submission for vector indexing")?;
        if !record_matches_vector_policy_abac(&record, tenant, tenant_policy) {
            tracing::warn!(
                tenant_id = %tenant.tenant_id,
                submission_id = %record.submission_id,
                "Trace Commons tenant policy rejected vector indexing source"
            );
            continue;
        }
        accepted_submissions_by_id.insert(record.submission_id, record);
    }
    let derived_records = db
        .list_trace_derived_records(&tenant.tenant_id)
        .await
        .context("failed to list trace derived records for vector indexing")?;
    let mut active_vector_entries = db
        .list_trace_vector_entries(&tenant.tenant_id)
        .await
        .context("failed to list trace vector entries for vector indexing")?;
    let active_vector_ids = active_vector_entries
        .iter()
        .filter(|entry| entry.status == StorageTraceVectorEntryStatus::Active)
        .filter(|entry| entry.invalidated_at.is_none() && entry.deleted_at.is_none())
        .map(|entry| entry.vector_entry_id)
        .collect::<BTreeSet<_>>();
    active_vector_entries = active_vector_entries
        .into_iter()
        .filter(|entry| entry.status == StorageTraceVectorEntryStatus::Active)
        .filter(|entry| entry.invalidated_at.is_none() && entry.deleted_at.is_none())
        .collect::<Vec<_>>();

    let mut eligible = Vec::new();
    for record in derived_records
        .iter()
        .filter(|record| record.status == StorageTraceDerivedStatus::Current)
        .filter(|record| record.worker_kind == StorageTraceWorkerKind::DuplicatePrecheck)
        .filter(|record| accepted_submissions_by_id.contains_key(&record.submission_id))
    {
        let Some(source_hash) = record.canonical_summary_hash.clone() else {
            continue;
        };
        let vector_entry_id = deterministic_vector_entry_uuid(
            &tenant.tenant_id,
            record.submission_id,
            record.derived_id,
            &source_hash,
        );
        eligible.push(TraceVectorIndexCandidate {
            record,
            source_hash,
            vector_entry_id,
        });
    }
    eligible.sort_by_key(|candidate| (candidate.record.submission_id, candidate.record.derived_id));
    let trace_ids_by_vector_entry = eligible
        .iter()
        .map(|candidate| (candidate.vector_entry_id, candidate.record.trace_id))
        .collect::<BTreeMap<_, _>>();
    let pending_candidates = eligible
        .iter()
        .filter(|candidate| !active_vector_ids.contains(&candidate.vector_entry_id))
        .collect::<Vec<_>>();
    let limit = limit.unwrap_or(usize::MAX);
    let mut report = TraceVectorIndexRunReport {
        skipped_existing_count: eligible.len().saturating_sub(pending_candidates.len()),
        pending_after_count: pending_candidates.len().saturating_sub(limit),
        ..TraceVectorIndexRunReport::default()
    };

    for candidate in pending_candidates.into_iter().take(limit) {
        let record = candidate.record;
        let source_hash = candidate.source_hash.as_str();
        let vector_entry_id = candidate.vector_entry_id;
        report.checked_count += 1;
        report.vector_entries_indexed += 1;
        if dry_run {
            continue;
        }
        let body_read = read_envelope_from_active_db_object_ref(
            state,
            &tenant.tenant_id,
            record.submission_id,
        )
        .await?
        .with_context(|| {
            format!(
                "missing active submitted envelope object ref for vector indexing source {}",
                record.submission_id
            )
        })?;
        let summary_neighbors = nearest_trace_neighbors(
            record.submission_id,
            record.canonical_summary.as_deref().unwrap_or_default(),
            source_hash,
            eligible.iter().map(|candidate| TraceSimilarityCandidate {
                submission_id: candidate.record.submission_id,
                trace_id: candidate.record.trace_id,
                canonical_summary: candidate.record.canonical_summary.as_deref(),
                canonical_summary_hash: candidate.record.canonical_summary_hash.as_deref(),
            }),
        );
        let indexed_at = Utc::now();
        let embedding_input = trace_vector_embedding_input(record);
        let embedding_input_hash = sha256_prefixed(&embedding_input);
        let source_projection = StorageTraceVectorEntrySourceProjection::CanonicalSummary;
        let embedding_material = trace_vector_embedding_material_for_record(
            state,
            tenant,
            TraceVectorEmbeddingMaterialRequest {
                record,
                vector_entry_id,
                source_projection,
                source_hash,
                purpose,
                embedding_input_hash,
                embedding_input,
            },
        )
        .await
        .context("failed to resolve trace vector embedding material")?;
        let vector_search_neighbors = if let Some(searcher) = state.vector_searcher.as_ref() {
            let response = searcher
                .search(TraceVectorSearchRequest {
                    tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
                    vector_entry_id,
                    source_projection,
                    source_hash: source_hash.to_string(),
                    vector_store: embedding_material.vector_store.clone(),
                    embedding_model: embedding_material.embedding_model.clone(),
                    embedding_dimension: embedding_material.embedding_dimension,
                    embedding_version: embedding_material.embedding_version.clone(),
                    embedding_algorithm: embedding_material.embedding_algorithm.clone(),
                    embedding_input_hash: embedding_material.embedding_input_hash.clone(),
                    embedding_sha256: embedding_material.embedding_sha256.clone(),
                    embedding_values: embedding_material.embedding_values.clone(),
                    purpose_hash: sha256_prefixed(purpose),
                    top_k: TRACE_SIMILARITY_MAX_NEIGHBORS,
                })
                .await
                .context("failed to query trace vector search adapter")?;
            trace_vector_search_neighbors_from_response(
                record.submission_id,
                &embedding_material,
                &active_vector_entries,
                &trace_ids_by_vector_entry,
                response,
            )
        } else {
            Vec::new()
        };
        let vector_payload_neighbors = nearest_trace_vector_payload_neighbors(
            record.submission_id,
            &embedding_material,
            active_trace_vector_payload_neighbor_candidates(
                state,
                db.as_ref(),
                &tenant.tenant_id,
                &active_vector_entries,
                &embedding_material,
            )
            .await?,
        );
        let used_vector_neighbors =
            !vector_search_neighbors.is_empty() || !vector_payload_neighbors.is_empty();
        let neighbors = if !vector_search_neighbors.is_empty() {
            vector_search_neighbors
        } else if !vector_payload_neighbors.is_empty() {
            vector_payload_neighbors
        } else {
            summary_neighbors
        };
        let nearest_trace_ids = neighbors
            .iter()
            .map(|neighbor| neighbor.trace_id.clone())
            .collect::<Vec<_>>();
        let duplicate_score = record.duplicate_score.unwrap_or_default().max(
            neighbors
                .first()
                .map(|neighbor| neighbor.score)
                .unwrap_or_default(),
        );
        let novelty_score = if neighbors.is_empty() {
            record.novelty_score.unwrap_or(0.5)
        } else {
            (1.0 - duplicate_score).clamp(0.05, 0.95)
        };
        let cluster_id = record.cluster_id.clone().or_else(|| {
            let cluster_hash = neighbors
                .first()
                .filter(|neighbor| neighbor.score >= 0.5)
                .and_then(|neighbor| neighbor.source_hash.as_deref())
                .unwrap_or(if used_vector_neighbors {
                    &embedding_material.embedding_sha256
                } else {
                    source_hash
                });
            Some(format!(
                "{}:{}",
                if used_vector_neighbors {
                    "embedding"
                } else {
                    "summary"
                },
                hash_fragment(cluster_hash, 16)
            ))
        });
        let vector_entry = db
            .upsert_trace_vector_entry(StorageTraceVectorEntryWrite {
                tenant_id: tenant.tenant_id.clone(),
                submission_id: record.submission_id,
                derived_id: record.derived_id,
                vector_entry_id,
                vector_store: embedding_material.vector_store.clone(),
                embedding_model: embedding_material.embedding_model.clone(),
                embedding_dimension: embedding_material.embedding_dimension,
                embedding_version: embedding_material.embedding_version.clone(),
                source_projection,
                source_hash: source_hash.to_string(),
                status: StorageTraceVectorEntryStatus::Active,
                nearest_trace_ids: nearest_trace_ids.clone(),
                cluster_id: cluster_id.clone(),
                duplicate_score: Some(duplicate_score),
                novelty_score: Some(novelty_score),
                indexed_at: Some(indexed_at),
                invalidated_at: None,
                deleted_at: None,
            })
            .await
            .context("failed to upsert trace vector entry")?;
        let payload = TraceVectorPayloadArtifact {
            artifact_schema_version: TRACE_VECTOR_PAYLOAD_SCHEMA_VERSION.to_string(),
            tenant_id: tenant.tenant_id.clone(),
            tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
            submission_id: record.submission_id,
            trace_id: record.trace_id,
            derived_id: record.derived_id,
            vector_entry_id,
            source_projection,
            source_hash: source_hash.to_string(),
            vector_store: embedding_material.vector_store,
            embedding_model: embedding_material.embedding_model,
            embedding_dimension: embedding_material.embedding_dimension,
            embedding_version: embedding_material.embedding_version,
            embedding_algorithm: embedding_material.embedding_algorithm,
            embedding_input_hash: Some(embedding_material.embedding_input_hash),
            embedding_values: embedding_material.embedding_values,
            embedding_sha256: Some(embedding_material.embedding_sha256),
            canonical_summary: record.canonical_summary.clone(),
            canonical_summary_hash: record.canonical_summary_hash.clone(),
            summary_model: record.summary_model.clone(),
            worker_kind: record.worker_kind,
            worker_version: record.worker_version.clone(),
            tool_sequence: record.tool_sequence.clone(),
            tool_categories: record.tool_categories.clone(),
            coverage_tags: record.coverage_tags.clone(),
            nearest_trace_ids,
            cluster_id,
            duplicate_score: Some(duplicate_score),
            novelty_score: Some(novelty_score),
            indexed_at,
        };
        if let Some(object_ref) = trace_vector_payload_object_ref_write(
            state,
            &tenant.tenant_id,
            record.submission_id,
            vector_entry_id,
            &payload,
        )? {
            db.append_trace_object_ref(object_ref)
                .await
                .context("failed to mirror trace vector payload object ref")?;
        }
        active_vector_entries.push(vector_entry);
        let refs: &[Uuid] = match body_read.object_ref_id.as_ref() {
            Some(id) => std::slice::from_ref(id),
            None => &[],
        };
        append_trace_content_read_audit_per_source(
            state,
            tenant,
            record.submission_id,
            refs,
            "vector_index",
            Some(purpose),
        )
        .await?;
    }
    Ok(report)
}

async fn reconcile_db_mirror(
    state: &AppState,
    tenant: &TenantAuth,
    file_records: &[TraceCommonsSubmissionRecord],
    file_derived: &[TraceCommonsDerivedRecord],
    enabled: bool,
    retention_ledger_expectation: Option<TraceRetentionLedgerExpectation>,
) -> anyhow::Result<Option<TraceDbReconciliationReport>> {
    if !enabled {
        return Ok(None);
    }
    let db = state
        .db_mirror
        .as_ref()
        .ok_or_else(|| anyhow::Error::new(TraceDbDualWriteRequiredForReconciliation))?;
    let db_records = db
        .list_trace_submissions(&tenant.tenant_id)
        .await
        .context("failed to list trace submissions for DB reconciliation")?;
    let db_derived = db
        .list_trace_derived_records(&tenant.tenant_id)
        .await
        .context("failed to list trace derived records for DB reconciliation")?;
    let db_vectors = db
        .list_trace_vector_entries(&tenant.tenant_id)
        .await
        .context("failed to list trace vector entries for DB reconciliation")?;
    let db_credit_events = db
        .list_trace_credit_events(&tenant.tenant_id)
        .await
        .context("failed to list trace credit events for DB reconciliation")?;
    let db_utility_attestations = db
        .list_trace_utility_attestations(&tenant.tenant_id)
        .await
        .context("failed to list utility attestations for DB reconciliation")?;
    let db_credit_settlement_batches = db
        .list_trace_credit_settlement_batches(&tenant.tenant_id)
        .await
        .context("failed to list credit settlement batches for DB reconciliation")?;
    let db_credit_holds = db
        .list_trace_credit_holds(&tenant.tenant_id)
        .await
        .context("failed to list credit holds for DB reconciliation")?;
    let db_near_credit_outbox_items = db
        .list_trace_near_credit_outbox_items(&tenant.tenant_id)
        .await
        .context("failed to list NEAR credit outbox items for DB reconciliation")?;
    let db_benchmark_registry_outbox_items = db
        .list_trace_benchmark_registry_outbox_items(&tenant.tenant_id)
        .await
        .context("failed to list benchmark registry outbox items for DB reconciliation")?;
    let db_ranking_model_versions = db
        .list_trace_ranking_model_versions(&tenant.tenant_id)
        .await
        .context("failed to list ranking model versions for DB reconciliation")?;
    let db_ranking_calibration_datasets = db
        .list_trace_ranking_calibration_datasets(&tenant.tenant_id)
        .await
        .context("failed to list ranking calibration datasets for DB reconciliation")?;
    let db_ranking_features = db
        .list_trace_ranking_features(&tenant.tenant_id)
        .await
        .context("failed to list ranking features for DB reconciliation")?;
    let db_ranking_predictions = db
        .list_trace_ranking_predictions(&tenant.tenant_id)
        .await
        .context("failed to list ranking predictions for DB reconciliation")?;
    let db_ranking_labels = db
        .list_trace_ranking_labels(&tenant.tenant_id)
        .await
        .context("failed to list ranking labels for DB reconciliation")?;
    let db_ranking_preference_labels = db
        .list_trace_ranking_preference_labels(&tenant.tenant_id)
        .await
        .context("failed to list ranking preference labels for DB reconciliation")?;
    let db_ranking_calibration_runs = db
        .list_trace_ranking_calibration_runs(&tenant.tenant_id)
        .await
        .context("failed to list ranking calibration runs for DB reconciliation")?;
    let db_ranking_worker_runs = db
        .list_trace_ranking_worker_runs(&tenant.tenant_id)
        .await
        .context("failed to list ranking worker runs for DB reconciliation")?;
    let db_audit_events = db
        .list_trace_audit_events(&tenant.tenant_id)
        .await
        .context("failed to list trace audit events for DB reconciliation")?;
    let db_export_manifests = db
        .list_trace_export_manifests(&tenant.tenant_id)
        .await
        .context("failed to list trace export manifests for DB reconciliation")?;
    let db_tombstones = db
        .list_trace_tombstones(&tenant.tenant_id)
        .await
        .context("failed to list trace tombstones for DB reconciliation")?;
    let db_retention_jobs = db
        .list_trace_retention_jobs(&tenant.tenant_id)
        .await
        .context("failed to list trace retention jobs for DB reconciliation")?;
    let mut db_retention_job_item_count = 0usize;
    let mut db_retention_job_item_counts = BTreeMap::new();
    for job in &db_retention_jobs {
        let items = db
            .list_trace_retention_job_items(&tenant.tenant_id, job.retention_job_id)
            .await
            .with_context(|| {
                format!(
                    "failed to list trace retention job items for job {}",
                    job.retention_job_id
                )
            })?;
        db_retention_job_item_count += items.len();
        db_retention_job_item_counts.insert(job.retention_job_id, items.len());
    }
    let mut missing_current_retention_job_ids_in_db = Vec::new();
    let mut current_retention_job_item_count_mismatches = Vec::new();
    if let Some(expectation) = retention_ledger_expectation {
        match db_retention_job_item_counts.get(&expectation.retention_job_id) {
            Some(db_item_count) if *db_item_count == expectation.expected_item_count => {}
            Some(db_item_count) => current_retention_job_item_count_mismatches.push(
                TraceDbRetentionJobItemCountMismatch {
                    retention_job_id: expectation.retention_job_id,
                    expected_item_count: expectation.expected_item_count,
                    db_item_count: *db_item_count,
                },
            ),
            None => missing_current_retention_job_ids_in_db.push(expectation.retention_job_id),
        }
    }
    let db_submission_export_eligibility = db_records
        .iter()
        .map(|record| {
            (
                record.submission_id,
                storage_submission_is_export_source_eligible(record),
            )
        })
        .collect::<BTreeMap<_, _>>();
    let invalid_source_submission_ids = db_submission_export_eligibility
        .iter()
        .filter_map(|(submission_id, eligible)| (!eligible).then_some(*submission_id))
        .collect::<BTreeSet<_>>();
    let mut db_export_manifest_item_count = 0usize;
    let mut db_export_manifest_item_missing_object_ref_count = 0usize;
    let mut db_export_manifest_ids_with_missing_object_refs = BTreeSet::new();
    let mut active_export_manifest_ids_for_invalid_sources = BTreeSet::new();
    let mut active_export_manifest_items_for_invalid_sources = Vec::new();
    for manifest in &db_export_manifests {
        let items = db
            .list_trace_export_manifest_items(&tenant.tenant_id, manifest.export_manifest_id)
            .await
            .with_context(|| {
                format!(
                    "failed to list trace export manifest items for manifest {}",
                    manifest.export_manifest_id
                )
            })?;
        db_export_manifest_item_count += items.len();
        let missing_object_ref_count = items
            .iter()
            .filter(|item| item.object_ref_id.is_none())
            .count();
        db_export_manifest_item_missing_object_ref_count += missing_object_ref_count;
        if missing_object_ref_count > 0 {
            db_export_manifest_ids_with_missing_object_refs.insert(manifest.export_manifest_id);
        }
        let manifest_active = manifest.invalidated_at.is_none() && manifest.deleted_at.is_none();
        if manifest_active
            && manifest.source_submission_ids.iter().any(|submission_id| {
                !db_submission_export_eligibility
                    .get(submission_id)
                    .copied()
                    .unwrap_or(false)
            })
        {
            active_export_manifest_ids_for_invalid_sources.insert(manifest.export_manifest_id);
        }
        active_export_manifest_items_for_invalid_sources.extend(
            items
                .iter()
                .filter(|item| item.source_invalidated_at.is_none())
                .filter(|item| {
                    !db_submission_export_eligibility
                        .get(&item.submission_id)
                        .copied()
                        .unwrap_or(false)
                })
                .map(|item| TraceDbExportManifestItemInvalidSource {
                    export_manifest_id: item.export_manifest_id,
                    submission_id: item.submission_id,
                    derived_id: item.derived_id,
                    object_ref_id: item.object_ref_id,
                    vector_entry_id: item.vector_entry_id,
                    source_status_at_export: item.source_status_at_export,
                    source_invalidation_reason: item.source_invalidation_reason,
                }),
        );
    }
    let active_derived_submission_ids_for_invalid_sources = db_derived
        .iter()
        .filter(|record| record.status == StorageTraceDerivedStatus::Current)
        .filter_map(|record| {
            (invalid_source_submission_ids.contains(&record.submission_id))
                .then_some(record.submission_id)
        })
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    active_export_manifest_items_for_invalid_sources.sort_by_key(|item| {
        (
            item.export_manifest_id,
            item.submission_id,
            item.derived_id,
            item.object_ref_id,
        )
    });
    let active_export_manifest_ids_with_ineligible_items =
        active_export_manifest_items_for_invalid_sources
            .iter()
            .map(|item| item.export_manifest_id)
            .collect::<BTreeSet<_>>();
    active_export_manifest_ids_for_invalid_sources.extend(
        active_export_manifest_items_for_invalid_sources
            .iter()
            .filter(|item| {
                !db_submission_export_eligibility
                    .get(&item.submission_id)
                    .copied()
                    .unwrap_or(false)
            })
            .map(|item| item.export_manifest_id),
    );
    let db_replay_export_manifest_count = db_export_manifests
        .iter()
        .filter(|manifest| is_replay_dataset_storage_manifest(manifest))
        .count();
    let db_benchmark_export_manifest_count = db_export_manifests
        .iter()
        .filter(|manifest| {
            manifest.artifact_kind == StorageTraceObjectArtifactKind::BenchmarkArtifact
        })
        .count();
    let db_ranker_export_manifest_count = db_export_manifests
        .iter()
        .filter(|manifest| is_ranker_training_storage_manifest(manifest))
        .count();
    let db_other_export_manifest_count = db_export_manifests.len().saturating_sub(
        db_replay_export_manifest_count
            + db_benchmark_export_manifest_count
            + db_ranker_export_manifest_count,
    );
    let file_credit_events = read_all_credit_events(&state.root, &tenant.tenant_id)?;
    let file_utility_attestations = read_all_utility_attestations(&state.root, &tenant.tenant_id)?;
    let file_credit_settlement_batches =
        read_all_credit_settlement_batches(&state.root, &tenant.tenant_id)?;
    let file_credit_holds = read_all_credit_holds(&state.root, &tenant.tenant_id)?;
    let file_near_credit_outbox_items =
        read_all_near_credit_outbox_items(&state.root, &tenant.tenant_id)?;
    let file_benchmark_registry_outbox_items =
        read_all_benchmark_registry_outbox_items(&state.root, &tenant.tenant_id)?;
    let file_ranking_model_versions =
        read_all_ranking_model_versions(&state.root, &tenant.tenant_id)?;
    let file_ranking_calibration_dataset_read =
        read_ranking_calibration_datasets_for_reconciliation(&state.root, &tenant.tenant_id)?;
    let file_ranking_calibration_dataset_manifest_conflict_keys =
        file_ranking_calibration_dataset_read.manifest_conflict_keys;
    let file_ranking_calibration_datasets = file_ranking_calibration_dataset_read.records;
    let file_ranking_features = read_all_ranking_features(&state.root, &tenant.tenant_id)?;
    let file_ranking_predictions = read_all_ranking_predictions(&state.root, &tenant.tenant_id)?;
    let file_ranking_labels = read_all_ranking_labels(&state.root, &tenant.tenant_id)?;
    let file_ranking_preference_labels =
        read_all_ranking_preference_labels(&state.root, &tenant.tenant_id)?;
    let file_ranking_calibration_runs =
        read_all_ranking_calibration_runs(&state.root, &tenant.tenant_id)?;
    let file_ranking_worker_runs = read_all_ranking_worker_runs(&state.root, &tenant.tenant_id)?;
    let file_audit_events = read_all_audit_events(&state.root, &tenant.tenant_id)?;
    let file_replay_export_manifests = read_all_export_manifests(&state.root, &tenant.tenant_id)?;
    let file_revocations = read_all_revocations(&state.root, &tenant.tenant_id)?;
    let file_credit_event_ids = file_credit_events
        .iter()
        .map(|event| event.event_id)
        .collect::<BTreeSet<_>>();
    let db_credit_event_ids = db_credit_events
        .iter()
        .map(|event| event.credit_event_id)
        .collect::<BTreeSet<_>>();
    let db_file_projected_credit_event_ids = db_credit_events
        .iter()
        .filter(|event| trace_credit_event_type_from_storage(event.event_type).is_some())
        .map(|event| event.credit_event_id)
        .collect::<BTreeSet<_>>();
    let missing_credit_event_ids_in_db = file_credit_event_ids
        .difference(&db_credit_event_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_credit_event_ids_in_files = db_file_projected_credit_event_ids
        .difference(&file_credit_event_ids)
        .copied()
        .collect::<Vec<_>>();
    let file_utility_attestation_ids = file_utility_attestations
        .iter()
        .map(|attestation| attestation.attestation_id)
        .collect::<BTreeSet<_>>();
    let db_utility_attestation_ids = db_utility_attestations
        .iter()
        .map(|attestation| attestation.attestation_id)
        .collect::<BTreeSet<_>>();
    let missing_utility_attestation_ids_in_db = file_utility_attestation_ids
        .difference(&db_utility_attestation_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_utility_attestation_ids_in_files = db_utility_attestation_ids
        .difference(&file_utility_attestation_ids)
        .copied()
        .collect::<Vec<_>>();
    let file_credit_settlement_batch_ids = file_credit_settlement_batches
        .iter()
        .map(|batch| batch.settlement_batch_id)
        .collect::<BTreeSet<_>>();
    let db_credit_settlement_batch_ids = db_credit_settlement_batches
        .iter()
        .map(|batch| batch.settlement_batch_id)
        .collect::<BTreeSet<_>>();
    let missing_credit_settlement_batch_ids_in_db = file_credit_settlement_batch_ids
        .difference(&db_credit_settlement_batch_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_credit_settlement_batch_ids_in_files = db_credit_settlement_batch_ids
        .difference(&file_credit_settlement_batch_ids)
        .copied()
        .collect::<Vec<_>>();
    let db_credit_settlement_batches_by_id = db_credit_settlement_batches
        .iter()
        .map(|batch| (batch.settlement_batch_id, batch))
        .collect::<BTreeMap<_, _>>();
    let credit_settlement_batch_status_mismatch_ids = file_credit_settlement_batches
        .iter()
        .filter_map(|batch| {
            db_credit_settlement_batches_by_id
                .get(&batch.settlement_batch_id)
                .filter(|db_batch| db_batch.status != batch.status)
                .map(|_| batch.settlement_batch_id)
        })
        .collect::<Vec<_>>();
    let file_credit_hold_ids = file_credit_holds
        .iter()
        .map(|hold| hold.hold_id)
        .collect::<BTreeSet<_>>();
    let db_credit_hold_ids = db_credit_holds
        .iter()
        .map(|hold| hold.hold_id)
        .collect::<BTreeSet<_>>();
    let missing_credit_hold_ids_in_db = file_credit_hold_ids
        .difference(&db_credit_hold_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_credit_hold_ids_in_files = db_credit_hold_ids
        .difference(&file_credit_hold_ids)
        .copied()
        .collect::<Vec<_>>();
    let db_credit_holds_by_id = db_credit_holds
        .iter()
        .map(|hold| (hold.hold_id, hold))
        .collect::<BTreeMap<_, _>>();
    let credit_hold_release_mismatch_ids = file_credit_holds
        .iter()
        .filter_map(|hold| {
            db_credit_holds_by_id
                .get(&hold.hold_id)
                .filter(|db_hold| db_hold.released_at != hold.released_at)
                .map(|_| hold.hold_id)
        })
        .collect::<Vec<_>>();
    let file_near_credit_outbox_ids = file_near_credit_outbox_items
        .iter()
        .map(|item| item.near_outbox_id)
        .collect::<BTreeSet<_>>();
    let db_near_credit_outbox_ids = db_near_credit_outbox_items
        .iter()
        .map(|item| item.near_outbox_id)
        .collect::<BTreeSet<_>>();
    let missing_near_credit_outbox_ids_in_db = file_near_credit_outbox_ids
        .difference(&db_near_credit_outbox_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_near_credit_outbox_ids_in_files = db_near_credit_outbox_ids
        .difference(&file_near_credit_outbox_ids)
        .copied()
        .collect::<Vec<_>>();
    let db_near_credit_outbox_items_by_id = db_near_credit_outbox_items
        .iter()
        .map(|item| (item.near_outbox_id, item))
        .collect::<BTreeMap<_, _>>();
    let near_credit_outbox_status_mismatch_ids = file_near_credit_outbox_items
        .iter()
        .filter_map(|item| {
            db_near_credit_outbox_items_by_id
                .get(&item.near_outbox_id)
                .filter(|db_item| {
                    db_item.status != item.status
                        || db_item.near_transaction_hash != item.near_transaction_hash
                        || db_item.last_error_hash != item.last_error_hash
                })
                .map(|_| item.near_outbox_id)
        })
        .collect::<Vec<_>>();
    let file_benchmark_registry_outbox_ids = file_benchmark_registry_outbox_items
        .iter()
        .map(|item| item.benchmark_outbox_id)
        .collect::<BTreeSet<_>>();
    let db_benchmark_registry_outbox_ids = db_benchmark_registry_outbox_items
        .iter()
        .map(|item| item.benchmark_outbox_id)
        .collect::<BTreeSet<_>>();
    let missing_benchmark_registry_outbox_ids_in_db = file_benchmark_registry_outbox_ids
        .difference(&db_benchmark_registry_outbox_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_benchmark_registry_outbox_ids_in_files = db_benchmark_registry_outbox_ids
        .difference(&file_benchmark_registry_outbox_ids)
        .copied()
        .collect::<Vec<_>>();
    let db_benchmark_registry_outbox_items_by_id = db_benchmark_registry_outbox_items
        .iter()
        .map(|item| (item.benchmark_outbox_id, item))
        .collect::<BTreeMap<_, _>>();
    let benchmark_registry_outbox_status_mismatch_ids = file_benchmark_registry_outbox_items
        .iter()
        .filter_map(|item| {
            db_benchmark_registry_outbox_items_by_id
                .get(&item.benchmark_outbox_id)
                .filter(|db_item| {
                    db_item.status != item.status
                        || db_item.external_receipt_ref != item.external_receipt_ref
                        || db_item.last_error_hash != item.last_error_hash
                })
                .map(|_| item.benchmark_outbox_id)
        })
        .collect::<Vec<_>>();
    let file_latest_ranking_model_versions =
        latest_ranking_model_versions(&file_ranking_model_versions);
    let file_latest_ranking_model_version_ids = file_latest_ranking_model_versions
        .iter()
        .map(|record| record.model_version.clone())
        .collect::<BTreeSet<_>>();
    let db_ranking_model_version_ids = db_ranking_model_versions
        .iter()
        .map(|record| record.model_version.clone())
        .collect::<BTreeSet<_>>();
    let db_ranking_model_versions_by_id = db_ranking_model_versions
        .iter()
        .map(|record| (record.model_version.clone(), record))
        .collect::<BTreeMap<_, _>>();
    let missing_ranking_model_versions_in_db = file_latest_ranking_model_version_ids
        .difference(&db_ranking_model_version_ids)
        .cloned()
        .collect::<Vec<_>>();
    let missing_ranking_model_versions_in_files = db_ranking_model_version_ids
        .difference(&file_latest_ranking_model_version_ids)
        .cloned()
        .collect::<Vec<_>>();
    let ranking_model_status_mismatch_versions = file_latest_ranking_model_versions
        .iter()
        .filter_map(|file_record| {
            db_ranking_model_versions_by_id
                .get(&file_record.model_version)
                .filter(|db_record| db_record.status != file_record.status)
                .map(|_| file_record.model_version.clone())
        })
        .collect::<Vec<_>>();
    let file_ranking_calibration_dataset_keys = file_ranking_calibration_datasets
        .iter()
        .map(ranking_calibration_dataset_file_key)
        .collect::<anyhow::Result<BTreeSet<_>>>()?;
    let db_ranking_calibration_dataset_keys = db_ranking_calibration_datasets
        .iter()
        .map(ranking_calibration_dataset_storage_key)
        .collect::<BTreeSet<_>>();
    let db_ranking_calibration_datasets_by_key = db_ranking_calibration_datasets
        .iter()
        .map(|record| (ranking_calibration_dataset_storage_key(record), record))
        .collect::<BTreeMap<_, _>>();
    let missing_ranking_calibration_dataset_keys_in_db = file_ranking_calibration_dataset_keys
        .difference(&db_ranking_calibration_dataset_keys)
        .cloned()
        .collect::<Vec<_>>();
    let missing_ranking_calibration_dataset_keys_in_files = db_ranking_calibration_dataset_keys
        .difference(&file_ranking_calibration_dataset_keys)
        .cloned()
        .collect::<Vec<_>>();
    let mut ranking_calibration_dataset_status_mismatch_keys = Vec::new();
    for file_record in &file_ranking_calibration_datasets {
        let key = ranking_calibration_dataset_file_key(file_record)?;
        if db_ranking_calibration_datasets_by_key
            .get(&key)
            .is_some_and(|db_record| db_record.status != file_record.status)
        {
            ranking_calibration_dataset_status_mismatch_keys.push(key);
        }
    }
    let file_ranking_feature_ids = file_ranking_features
        .iter()
        .map(|record| record.ranking_feature_id)
        .collect::<BTreeSet<_>>();
    let db_ranking_feature_ids = db_ranking_features
        .iter()
        .map(|record| record.ranking_feature_id)
        .collect::<BTreeSet<_>>();
    let missing_ranking_feature_ids_in_db = file_ranking_feature_ids
        .difference(&db_ranking_feature_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_ranking_feature_ids_in_files = db_ranking_feature_ids
        .difference(&file_ranking_feature_ids)
        .copied()
        .collect::<Vec<_>>();
    let file_ranking_prediction_ids = file_ranking_predictions
        .iter()
        .map(|record| record.ranking_prediction_id)
        .collect::<BTreeSet<_>>();
    let db_ranking_prediction_ids = db_ranking_predictions
        .iter()
        .map(|record| record.ranking_prediction_id)
        .collect::<BTreeSet<_>>();
    let missing_ranking_prediction_ids_in_db = file_ranking_prediction_ids
        .difference(&db_ranking_prediction_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_ranking_prediction_ids_in_files = db_ranking_prediction_ids
        .difference(&file_ranking_prediction_ids)
        .copied()
        .collect::<Vec<_>>();
    let file_ranking_label_ids = file_ranking_labels
        .iter()
        .map(|record| record.ranking_label_id)
        .collect::<BTreeSet<_>>();
    let db_ranking_label_ids = db_ranking_labels
        .iter()
        .map(|record| record.ranking_label_id)
        .collect::<BTreeSet<_>>();
    let missing_ranking_label_ids_in_db = file_ranking_label_ids
        .difference(&db_ranking_label_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_ranking_label_ids_in_files = db_ranking_label_ids
        .difference(&file_ranking_label_ids)
        .copied()
        .collect::<Vec<_>>();
    let file_ranking_preference_label_ids = file_ranking_preference_labels
        .iter()
        .map(|record| record.preference_label_id)
        .collect::<BTreeSet<_>>();
    let db_ranking_preference_label_ids = db_ranking_preference_labels
        .iter()
        .map(|record| record.preference_label_id)
        .collect::<BTreeSet<_>>();
    let missing_ranking_preference_label_ids_in_db = file_ranking_preference_label_ids
        .difference(&db_ranking_preference_label_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_ranking_preference_label_ids_in_files = db_ranking_preference_label_ids
        .difference(&file_ranking_preference_label_ids)
        .copied()
        .collect::<Vec<_>>();
    let file_ranking_calibration_run_ids = file_ranking_calibration_runs
        .iter()
        .map(|record| record.calibration_run_id)
        .collect::<BTreeSet<_>>();
    let db_ranking_calibration_run_ids = db_ranking_calibration_runs
        .iter()
        .map(|record| record.calibration_run_id)
        .collect::<BTreeSet<_>>();
    let db_ranking_calibration_runs_by_id = db_ranking_calibration_runs
        .iter()
        .map(|record| (record.calibration_run_id, record))
        .collect::<BTreeMap<_, _>>();
    let missing_ranking_calibration_run_ids_in_db = file_ranking_calibration_run_ids
        .difference(&db_ranking_calibration_run_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_ranking_calibration_run_ids_in_files = db_ranking_calibration_run_ids
        .difference(&file_ranking_calibration_run_ids)
        .copied()
        .collect::<Vec<_>>();
    let ranking_calibration_report_hash_mismatch_ids = file_ranking_calibration_runs
        .iter()
        .filter_map(|file_record| {
            db_ranking_calibration_runs_by_id
                .get(&file_record.calibration_run_id)
                .filter(|db_record| db_record.report_hash != file_record.report_hash)
                .map(|_| file_record.calibration_run_id)
        })
        .collect::<Vec<_>>();
    let file_ranking_worker_run_ids = file_ranking_worker_runs
        .iter()
        .map(|record| record.ranking_worker_run_id)
        .collect::<BTreeSet<_>>();
    let db_ranking_worker_run_ids = db_ranking_worker_runs
        .iter()
        .map(|record| record.ranking_worker_run_id)
        .collect::<BTreeSet<_>>();
    let db_ranking_worker_runs_by_id = db_ranking_worker_runs
        .iter()
        .map(|record| (record.ranking_worker_run_id, record))
        .collect::<BTreeMap<_, _>>();
    let missing_ranking_worker_run_ids_in_db = file_ranking_worker_run_ids
        .difference(&db_ranking_worker_run_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_ranking_worker_run_ids_in_files = db_ranking_worker_run_ids
        .difference(&file_ranking_worker_run_ids)
        .copied()
        .collect::<Vec<_>>();
    let ranking_worker_run_status_mismatch_ids = file_ranking_worker_runs
        .iter()
        .filter_map(|file_record| {
            db_ranking_worker_runs_by_id
                .get(&file_record.ranking_worker_run_id)
                .filter(|db_record| db_record.status != file_record.status)
                .map(|_| file_record.ranking_worker_run_id)
        })
        .collect::<Vec<_>>();
    let file_audit_event_ids = file_audit_events
        .iter()
        .map(|event| event.event_id)
        .collect::<BTreeSet<_>>();
    let db_audit_event_ids = db_audit_events
        .iter()
        .map(|event| event.audit_event_id)
        .collect::<BTreeSet<_>>();
    let db_file_projected_audit_event_ids = db_audit_events
        .iter()
        .filter(|event| event.canonical_event_json.is_some())
        .map(|event| event.audit_event_id)
        .collect::<BTreeSet<_>>();
    let missing_audit_event_ids_in_db = file_audit_event_ids
        .difference(&db_audit_event_ids)
        .copied()
        .collect::<Vec<_>>();
    let missing_audit_event_ids_in_files = db_file_projected_audit_event_ids
        .difference(&file_audit_event_ids)
        .copied()
        .collect::<Vec<_>>();
    let db_audit_hash_chain_failures = collect_db_audit_hash_chain_failures(&db_audit_events);
    let db_audit_canonical_projection_failures =
        collect_db_audit_canonical_projection_failures(&db_audit_events);
    let mut db_object_ref_count = 0usize;
    let mut accepted_without_active_envelope_object_ref = Vec::new();
    let mut unreadable_active_envelope_object_refs = Vec::new();
    let mut hash_mismatched_active_envelope_object_refs = Vec::new();
    let mut key_ref_mismatched_active_envelope_object_refs = Vec::new();
    let mut store_mismatched_active_envelope_object_refs = Vec::new();
    for record in &db_records {
        let object_refs = db
            .list_trace_object_refs(&tenant.tenant_id, record.submission_id)
            .await
            .with_context(|| {
                format!(
                    "failed to list trace object refs for submission {}",
                    record.submission_id
                )
            })?;
        db_object_ref_count += object_refs.len();
        if record.status == StorageTraceCorpusStatus::Accepted
            && record.revoked_at.is_none()
            && record.purged_at.is_none()
        {
            let active_object_ref = db
                .get_latest_active_trace_object_ref(
                    &tenant.tenant_id,
                    record.submission_id,
                    StorageTraceObjectArtifactKind::SubmittedEnvelope,
                )
                .await
                .with_context(|| {
                    format!(
                        "failed to get latest active trace object ref for submission {}",
                        record.submission_id
                    )
                })?;
            if let Some(object_ref) = active_object_ref {
                if let Err(error) =
                    read_envelope_from_object_ref(state, &tenant.tenant_id, &object_ref)
                {
                    match classify_trace_object_ref_read_failure(&error) {
                        TraceObjectRefReadFailureKind::HashMismatch => {
                            hash_mismatched_active_envelope_object_refs.push(record.submission_id);
                        }
                        TraceObjectRefReadFailureKind::KeyRefMismatch => {
                            key_ref_mismatched_active_envelope_object_refs
                                .push(record.submission_id);
                        }
                        TraceObjectRefReadFailureKind::StoreMismatch => {
                            store_mismatched_active_envelope_object_refs.push(record.submission_id);
                        }
                        TraceObjectRefReadFailureKind::Unreadable => {
                            unreadable_active_envelope_object_refs.push(record.submission_id);
                        }
                    }
                }
            } else {
                accepted_without_active_envelope_object_ref.push(record.submission_id);
            }
        }
    }

    let file_by_submission = file_records
        .iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let db_by_submission = db_records
        .iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let db_audit_submission_metadata_mismatches =
        collect_db_audit_submission_metadata_mismatches(&db_audit_events, &db_by_submission);
    let file_derived_by_submission = file_derived
        .iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();
    let db_derived_by_submission = db_derived
        .iter()
        .map(|record| (record.submission_id, record))
        .collect::<BTreeMap<_, _>>();

    let mut missing_submission_ids_in_db = Vec::new();
    let mut status_mismatches = Vec::new();
    for (submission_id, file_record) in &file_by_submission {
        let Some(db_record) = db_by_submission.get(submission_id) else {
            missing_submission_ids_in_db.push(*submission_id);
            continue;
        };
        let file_status = storage_corpus_status(file_record.status);
        if db_record.status != file_status {
            status_mismatches.push(TraceDbStatusMismatch {
                submission_id: *submission_id,
                file_status,
                db_status: db_record.status,
            });
        }
    }

    let missing_submission_ids_in_files = db_by_submission
        .keys()
        .filter(|submission_id| !file_by_submission.contains_key(submission_id))
        .copied()
        .collect::<Vec<_>>();
    let missing_derived_submission_ids_in_db = file_derived_by_submission
        .keys()
        .filter(|submission_id| !db_derived_by_submission.contains_key(submission_id))
        .copied()
        .collect::<Vec<_>>();
    let missing_derived_submission_ids_in_files = db_derived_by_submission
        .keys()
        .filter(|submission_id| !file_derived_by_submission.contains_key(submission_id))
        .copied()
        .collect::<Vec<_>>();
    let mut derived_status_mismatches = Vec::new();
    let mut derived_hash_mismatches = Vec::new();
    for (submission_id, db_record) in &db_derived_by_submission {
        let Some(file_record) = file_derived_by_submission.get(submission_id) else {
            continue;
        };
        let file_status = storage_derived_status(file_record.status);
        if db_record.status != file_status {
            derived_status_mismatches.push(TraceDbDerivedStatusMismatch {
                submission_id: *submission_id,
                file_status,
                db_status: db_record.status,
            });
        }
        if db_record.canonical_summary_hash.as_deref()
            != Some(file_record.canonical_summary_hash.as_str())
        {
            derived_hash_mismatches.push(TraceDbDerivedHashMismatch {
                submission_id: *submission_id,
                file_canonical_summary_hash: file_record.canonical_summary_hash.clone(),
                db_canonical_summary_hash: db_record.canonical_summary_hash.clone(),
            });
        }
    }

    let accepted_submission_ids = db_records
        .iter()
        .filter(|record| record.status == StorageTraceCorpusStatus::Accepted)
        .filter(|record| record.revoked_at.is_none() && record.purged_at.is_none())
        .map(|record| record.submission_id)
        .collect::<BTreeSet<_>>();
    let current_derived_ids = db_derived
        .iter()
        .filter(|record| record.status == StorageTraceDerivedStatus::Current)
        .map(|record| (record.submission_id, record.derived_id))
        .collect::<BTreeSet<_>>();
    let active_vector_entries = db_vectors
        .iter()
        .filter(|entry| entry.status == StorageTraceVectorEntryStatus::Active)
        .count();
    let active_canonical_vector_keys = db_vectors
        .iter()
        .filter(|entry| entry.status == StorageTraceVectorEntryStatus::Active)
        .filter(|entry| {
            entry.source_projection == StorageTraceVectorEntrySourceProjection::CanonicalSummary
        })
        .map(|entry| {
            (
                entry.submission_id,
                entry.derived_id,
                entry.source_hash.clone(),
            )
        })
        .collect::<BTreeSet<_>>();
    let eligible_canonical_vector_keys = db_derived
        .iter()
        .filter(|record| record.status == StorageTraceDerivedStatus::Current)
        .filter(|record| record.worker_kind == StorageTraceWorkerKind::DuplicatePrecheck)
        .filter(|record| accepted_submission_ids.contains(&record.submission_id))
        .filter_map(|record| {
            record
                .canonical_summary_hash
                .as_ref()
                .map(|hash| (record.submission_id, record.derived_id, hash.clone()))
        })
        .collect::<BTreeSet<_>>();
    let accepted_current_derived_without_active_vector_entry = eligible_canonical_vector_keys
        .difference(&active_canonical_vector_keys)
        .map(|(submission_id, _, _)| *submission_id)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let invalid_active_vector_entries = db_vectors
        .iter()
        .filter(|entry| entry.status == StorageTraceVectorEntryStatus::Active)
        .filter(|entry| {
            !accepted_submission_ids.contains(&entry.submission_id)
                || !current_derived_ids.contains(&(entry.submission_id, entry.derived_id))
                || (entry.source_projection
                    == StorageTraceVectorEntrySourceProjection::CanonicalSummary
                    && !eligible_canonical_vector_keys.contains(&(
                        entry.submission_id,
                        entry.derived_id,
                        entry.source_hash.clone(),
                    )))
        })
        .count();

    let file_credit_view =
        contributor_credit_view_from_file_records(tenant, file_records, &file_credit_events);
    let db_credit_view = read_contributor_credit_view_from_db(state, tenant).await?;
    let file_metadata_view = metadata_view_from_file_records(file_records, file_derived);
    let db_metadata_view = read_reviewer_metadata_view_from_db(state, tenant).await?;
    let file_analytics = TraceCommonsAnalyticsResponse::from_records(
        tenant.tenant_id.clone(),
        file_metadata_view.records.clone(),
        file_metadata_view.derived.clone(),
    );
    let db_analytics = TraceCommonsAnalyticsResponse::from_records(
        tenant.tenant_id.clone(),
        db_metadata_view.records.clone(),
        db_metadata_view.derived.clone(),
    );
    let db_audit_events_for_reader = read_audit_events_from_db(state, tenant).await;
    let file_audit_sample = read_recent_audit_events_from_file(
        &state.root,
        &tenant.tenant_id,
        TRACE_DB_AUDIT_RECONCILIATION_SAMPLE_LIMIT,
    )?;
    let file_audit_sample_projection = audit_event_reader_projection(&file_audit_sample);
    let mut audit_reader_sample_failures = Vec::new();
    let audit_reader_sample_parity_ok = match db
        .list_recent_trace_audit_events(
            &tenant.tenant_id,
            TRACE_DB_AUDIT_RECONCILIATION_SAMPLE_LIMIT,
        )
        .await
    {
        Ok(db_sample) => {
            let db_sample_row_count = db_sample.len();
            let (db_audit_sample_projection, db_projection_error_hashes) =
                storage_audit_event_reader_projection(&tenant.tenant_id, db_sample);
            if !db_projection_error_hashes.is_empty() {
                audit_reader_sample_failures.push(format!(
                    "file_sample={} db_sample={} db_projection_error_hashes={}",
                    file_audit_sample_projection.len(),
                    db_sample_row_count,
                    db_projection_error_hashes.join(",")
                ));
                false
            } else if file_audit_sample_projection == db_audit_sample_projection {
                true
            } else {
                audit_reader_sample_failures.push(format!(
                    "file_sample={} db_sample={} file_latest_event_id={} db_latest_event_id={} file_projection_hash={} db_projection_hash={}",
                    file_audit_sample_projection.len(),
                    db_audit_sample_projection.len(),
                    latest_audit_projection_event_id(&file_audit_sample_projection),
                    latest_audit_projection_event_id(&db_audit_sample_projection),
                    audit_reader_projection_digest(&file_audit_sample_projection),
                    audit_reader_projection_digest(&db_audit_sample_projection)
                ));
                false
            }
        }
        Err(error) => {
            audit_reader_sample_failures.push(format!(
                "file_sample={} db_sample=unavailable db_error_hash={}",
                file_audit_sample_projection.len(),
                sha256_prefixed(&error.to_string())
            ));
            false
        }
    };
    let file_export_manifest_projection = export_manifest_reader_projection(
        file_replay_export_manifests
            .iter()
            .cloned()
            .map(TraceExportManifestSummary::from_replay_manifest)
            .collect(),
    );
    let db_export_manifest_projection = export_manifest_reader_projection(
        db_export_manifests
            .iter()
            .cloned()
            .map(TraceExportManifestSummary::from_storage_record)
            .filter(TraceExportManifestSummary::is_replay_dataset_manifest)
            .collect(),
    );

    let mut db_reader_parity_failures = Vec::new();
    let contributor_credit_reader_parity_ok = {
        let file_submissions = submission_reader_projection(&file_credit_view.records);
        let db_submissions = submission_reader_projection(&db_credit_view.records);
        let file_events = credit_event_reader_projection(&file_credit_view.credit_events);
        let db_events = credit_event_reader_projection(&db_credit_view.credit_events);
        record_reader_parity(
            &mut db_reader_parity_failures,
            "contributor_credit",
            file_submissions == db_submissions && file_events == db_events,
            format!(
                "file_submissions={} db_submissions={} file_events={} db_events={}",
                file_submissions.len(),
                db_submissions.len(),
                file_events.len(),
                db_events.len()
            ),
        )
    };
    let reviewer_metadata_reader_parity_ok = {
        let file_submissions = submission_reader_projection(&file_metadata_view.records);
        let db_submissions = submission_reader_projection(&db_metadata_view.records);
        let file_derived = derived_reader_projection(&file_metadata_view.derived);
        let db_derived = derived_reader_projection(&db_metadata_view.derived);
        record_reader_parity(
            &mut db_reader_parity_failures,
            "reviewer_metadata",
            file_submissions == db_submissions && file_derived == db_derived,
            format!(
                "file_submissions={} db_submissions={} file_derived={} db_derived={}",
                file_submissions.len(),
                db_submissions.len(),
                file_derived.len(),
                db_derived.len()
            ),
        )
    };
    let analytics_reader_parity_ok = {
        let file_projection = analytics_reader_projection(file_analytics);
        let db_projection = analytics_reader_projection(db_analytics);
        record_reader_parity(
            &mut db_reader_parity_failures,
            "analytics",
            file_projection == db_projection,
            format!(
                "file_submissions={} db_submissions={} file_duplicate_groups={} db_duplicate_groups={}",
                file_projection.submissions_total,
                db_projection.submissions_total,
                file_projection.duplicate_groups,
                db_projection.duplicate_groups
            ),
        )
    };
    let audit_reader_parity_ok = {
        let (reader_ok, reader_detail) = match db_audit_events_for_reader.as_ref() {
            Ok(db_events) => (
                file_audit_events.len() == db_events.len(),
                format!(
                    "file_events={} db_events={}",
                    file_audit_events.len(),
                    db_events.len()
                ),
            ),
            Err(error) => (
                false,
                format!(
                    "file_events={} db_events=unavailable db_error_hash={}",
                    file_audit_events.len(),
                    sha256_prefixed(&error.to_string())
                ),
            ),
        };
        record_reader_parity(
            &mut db_reader_parity_failures,
            "audit",
            reader_ok,
            reader_detail,
        )
    };
    let replay_export_manifest_reader_parity_ok = record_reader_parity(
        &mut db_reader_parity_failures,
        "replay_export_manifests",
        file_export_manifest_projection == db_export_manifest_projection,
        format!(
            "file_manifests={} db_manifests={}",
            file_export_manifest_projection.len(),
            db_export_manifest_projection.len()
        ),
    );

    let mut report = TraceDbReconciliationReport {
        file_submission_count: file_records.len(),
        db_submission_count: db_records.len(),
        missing_submission_ids_in_db,
        missing_submission_ids_in_files,
        status_mismatches,
        file_derived_count: file_derived.len(),
        db_derived_count: db_derived.len(),
        missing_derived_submission_ids_in_db,
        missing_derived_submission_ids_in_files,
        derived_status_mismatches,
        derived_hash_mismatches,
        file_credit_event_count: file_credit_events.len(),
        db_credit_event_count: db_credit_events.len(),
        missing_credit_event_ids_in_db,
        missing_credit_event_ids_in_files,
        file_utility_attestation_count: file_utility_attestations.len(),
        db_utility_attestation_count: db_utility_attestations.len(),
        missing_utility_attestation_ids_in_db,
        missing_utility_attestation_ids_in_files,
        file_credit_settlement_batch_count: file_credit_settlement_batches.len(),
        db_credit_settlement_batch_count: db_credit_settlement_batches.len(),
        missing_credit_settlement_batch_ids_in_db,
        missing_credit_settlement_batch_ids_in_files,
        credit_settlement_batch_status_mismatch_ids,
        file_credit_hold_count: file_credit_holds.len(),
        db_credit_hold_count: db_credit_holds.len(),
        missing_credit_hold_ids_in_db,
        missing_credit_hold_ids_in_files,
        credit_hold_release_mismatch_ids,
        file_near_credit_outbox_item_count: file_near_credit_outbox_items.len(),
        db_near_credit_outbox_item_count: db_near_credit_outbox_items.len(),
        missing_near_credit_outbox_ids_in_db,
        missing_near_credit_outbox_ids_in_files,
        near_credit_outbox_status_mismatch_ids,
        file_benchmark_registry_outbox_item_count: file_benchmark_registry_outbox_items.len(),
        db_benchmark_registry_outbox_item_count: db_benchmark_registry_outbox_items.len(),
        missing_benchmark_registry_outbox_ids_in_db,
        missing_benchmark_registry_outbox_ids_in_files,
        benchmark_registry_outbox_status_mismatch_ids,
        file_latest_ranking_model_version_count: file_latest_ranking_model_versions.len(),
        db_ranking_model_version_count: db_ranking_model_versions.len(),
        missing_ranking_model_versions_in_db,
        missing_ranking_model_versions_in_files,
        ranking_model_status_mismatch_versions,
        file_ranking_calibration_dataset_count: file_ranking_calibration_datasets.len(),
        db_ranking_calibration_dataset_count: db_ranking_calibration_datasets.len(),
        missing_ranking_calibration_dataset_keys_in_db,
        missing_ranking_calibration_dataset_keys_in_files,
        ranking_calibration_dataset_status_mismatch_keys,
        ranking_calibration_dataset_manifest_conflict_keys:
            file_ranking_calibration_dataset_manifest_conflict_keys,
        file_ranking_feature_count: file_ranking_features.len(),
        db_ranking_feature_count: db_ranking_features.len(),
        missing_ranking_feature_ids_in_db,
        missing_ranking_feature_ids_in_files,
        file_ranking_prediction_count: file_ranking_predictions.len(),
        db_ranking_prediction_count: db_ranking_predictions.len(),
        missing_ranking_prediction_ids_in_db,
        missing_ranking_prediction_ids_in_files,
        file_ranking_label_count: file_ranking_labels.len(),
        db_ranking_label_count: db_ranking_labels.len(),
        missing_ranking_label_ids_in_db,
        missing_ranking_label_ids_in_files,
        file_ranking_preference_label_count: file_ranking_preference_labels.len(),
        db_ranking_preference_label_count: db_ranking_preference_labels.len(),
        missing_ranking_preference_label_ids_in_db,
        missing_ranking_preference_label_ids_in_files,
        file_ranking_calibration_run_count: file_ranking_calibration_runs.len(),
        db_ranking_calibration_run_count: db_ranking_calibration_runs.len(),
        missing_ranking_calibration_run_ids_in_db,
        missing_ranking_calibration_run_ids_in_files,
        ranking_calibration_report_hash_mismatch_ids,
        file_ranking_worker_run_count: file_ranking_worker_runs.len(),
        db_ranking_worker_run_count: db_ranking_worker_runs.len(),
        missing_ranking_worker_run_ids_in_db,
        missing_ranking_worker_run_ids_in_files,
        ranking_worker_run_status_mismatch_ids,
        file_audit_event_count: file_audit_events.len(),
        db_audit_event_count: db_audit_events.len(),
        missing_audit_event_ids_in_db,
        missing_audit_event_ids_in_files,
        db_audit_hash_chain_failures,
        db_audit_canonical_projection_failures,
        db_audit_submission_metadata_mismatches,
        db_retention_job_count: db_retention_jobs.len(),
        db_retention_job_item_count,
        missing_current_retention_job_ids_in_db,
        current_retention_job_item_count_mismatches,
        file_replay_export_manifest_count: file_replay_export_manifests.len(),
        db_export_manifest_count: db_export_manifests.len(),
        db_replay_export_manifest_count,
        db_benchmark_export_manifest_count,
        db_ranker_export_manifest_count,
        db_other_export_manifest_count,
        db_export_manifest_item_count,
        db_export_manifest_item_missing_object_ref_count,
        db_export_manifest_ids_with_missing_object_refs:
            db_export_manifest_ids_with_missing_object_refs
                .into_iter()
                .collect(),
        active_derived_submission_ids_for_invalid_sources,
        active_export_manifest_ids_for_invalid_sources:
            active_export_manifest_ids_for_invalid_sources
                .into_iter()
                .collect(),
        active_export_manifest_items_for_invalid_sources,
        active_export_manifest_ids_with_ineligible_items:
            active_export_manifest_ids_with_ineligible_items
                .into_iter()
                .collect(),
        file_revocation_tombstone_count: file_revocations.len(),
        db_tombstone_count: db_tombstones.len(),
        db_object_ref_count,
        accepted_without_active_envelope_object_ref,
        unreadable_active_envelope_object_refs,
        hash_mismatched_active_envelope_object_refs,
        key_ref_mismatched_active_envelope_object_refs,
        store_mismatched_active_envelope_object_refs,
        contributor_credit_reader_parity_ok,
        reviewer_metadata_reader_parity_ok,
        analytics_reader_parity_ok,
        audit_reader_parity_ok,
        audit_reader_sample_parity_ok,
        audit_reader_sample_failures,
        replay_export_manifest_reader_parity_ok,
        db_reader_parity_failures,
        active_vector_entries,
        accepted_current_derived_without_active_vector_entry,
        invalid_active_vector_entries,
        blocking_gaps: Vec::new(),
    };
    report.blocking_gaps = report.compute_blocking_gap_summaries();
    Ok(Some(report))
}

fn require_db_reconciliation_clean_request(
    state: &AppState,
    request: &TraceMaintenanceRequest,
) -> anyhow::Result<()> {
    if state.require_db_reconciliation_clean && !request.reconcile_db_mirror {
        return Err(anyhow::Error::new(TraceDbReconciliationRequestRequired));
    }
    Ok(())
}

fn enforce_db_reconciliation_clean(
    state: &AppState,
    report: Option<&TraceDbReconciliationReport>,
) -> anyhow::Result<()> {
    if !state.require_db_reconciliation_clean {
        return Ok(());
    }
    let Some(report) = report else {
        return Ok(());
    };
    if !report.blocking_gaps.is_empty() {
        return Err(anyhow::Error::new(TraceDbReconciliationNotClean {
            gaps: report.blocking_gaps.clone(),
        }));
    }
    Ok(())
}

fn storage_submission_is_export_source_eligible(record: &StorageTraceSubmissionRecord) -> bool {
    record.status == StorageTraceCorpusStatus::Accepted
        && record.revoked_at.is_none()
        && record.purged_at.is_none()
}

fn is_ranker_training_storage_manifest(record: &StorageTraceExportManifestRecord) -> bool {
    record.artifact_kind == StorageTraceObjectArtifactKind::ExportArtifact
        && record
            .purpose_code
            .as_deref()
            .is_some_and(is_ranker_training_purpose_code)
}

fn is_replay_dataset_storage_manifest(record: &StorageTraceExportManifestRecord) -> bool {
    record.artifact_kind == StorageTraceObjectArtifactKind::ExportArtifact
        && !is_ranker_training_storage_manifest(record)
}

fn deterministic_vector_entry_uuid(
    tenant_id: &str,
    submission_id: Uuid,
    derived_id: Uuid,
    source_hash: &str,
) -> Uuid {
    let input = format!(
        "ironclaw.trace_commons.vector:{tenant_id}:{submission_id}:{derived_id}:{source_hash}"
    );
    Uuid::new_v5(&Uuid::NAMESPACE_URL, input.as_bytes())
}

#[derive(Debug, Default, Clone, Serialize)]
struct TraceBackfillReport {
    backfilled: usize,
    failed: usize,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    failures: Vec<TraceBackfillFailure>,
}

impl TraceBackfillReport {
    fn record_failure(&mut self, item_kind: &str, item_ref: String, reason: String) {
        self.failed += 1;
        tracing::warn!(
            %item_kind,
            %item_ref,
            reason_hash = %safe_display_error_hash(&reason),
            "Trace Commons DB mirror backfill skipped item"
        );
        if self.failures.len() < TRACE_BACKFILL_FAILURE_DETAIL_LIMIT {
            self.failures.push(TraceBackfillFailure {
                item_kind: item_kind.to_string(),
                item_ref,
                reason,
            });
        }
    }

    fn record_existing_failure(&mut self, failure: TraceBackfillFailure) {
        let TraceBackfillFailure {
            item_kind,
            item_ref,
            reason,
        } = failure;
        self.record_failure(&item_kind, item_ref, reason);
    }
}

#[derive(Debug, Clone, Serialize)]
struct TraceBackfillFailure {
    item_kind: String,
    item_ref: String,
    reason: String,
}

#[derive(Debug, Clone, Copy)]
