fn apply_benchmark_lifecycle_update(
    artifact: &mut TraceBenchmarkConversionArtifact,
    update: BenchmarkLifecycleUpdateRequest,
) -> ApiResult<()> {
    if let Some(registry) = update.registry {
        if let Some(status) = registry.status {
            artifact.registry.status = status;
        }
        if let Some(registry_ref) = registry.registry_ref {
            artifact.registry.registry_ref = normalize_benchmark_lifecycle_ref(registry_ref)?;
        }
        if let Some(published_at) = registry.published_at {
            artifact.registry.published_at = Some(published_at);
        }
    }

    if let Some(evaluation) = update.evaluation {
        if let Some(status) = evaluation.status {
            artifact.evaluation.status = status;
        }
        if let Some(evaluator_ref) = evaluation.evaluator_ref {
            artifact.evaluation.evaluator_ref = normalize_benchmark_lifecycle_ref(evaluator_ref)?;
        }
        if let Some(evaluated_at) = evaluation.evaluated_at {
            artifact.evaluation.evaluated_at = Some(evaluated_at);
        }
        if let Some(score) = evaluation.score {
            if !(0.0..=1.0).contains(&score) {
                return Err(api_error(
                    StatusCode::BAD_REQUEST,
                    "benchmark evaluation score must be between 0 and 1",
                ));
            }
            artifact.evaluation.score = Some(score);
        }
        if let Some(pass_count) = evaluation.pass_count {
            artifact.evaluation.pass_count = Some(pass_count);
        }
        if let Some(fail_count) = evaluation.fail_count {
            artifact.evaluation.fail_count = Some(fail_count);
        }
    }

    if let Some(reason) = update.reason.map(|reason| reason.trim().to_string())
        && !reason.is_empty()
    {
        artifact.evaluation.last_update_reason = Some(reason);
    }
    validate_benchmark_lifecycle_state(artifact)?;
    Ok(())
}

fn validate_benchmark_lifecycle_state(
    artifact: &TraceBenchmarkConversionArtifact,
) -> ApiResult<()> {
    if artifact.registry.status != TraceBenchmarkRegistryStatus::Published {
        return Ok(());
    }
    if artifact.evaluation.status != TraceBenchmarkEvaluationStatus::Passed {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "published benchmark requires passed evaluation metadata",
        ));
    }
    if artifact.registry.registry_ref.is_none() || artifact.registry.published_at.is_none() {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "published benchmark requires registry_ref and published_at",
        ));
    }
    if artifact.evaluation.evaluator_ref.is_none()
        || artifact.evaluation.evaluated_at.is_none()
        || artifact.evaluation.score.is_none()
    {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "published benchmark requires evaluator_ref, evaluated_at, and score",
        ));
    }
    Ok(())
}

fn benchmark_registry_publish_outbox_item_from_artifact(
    tenant: &TenantAuth,
    artifact: &TraceBenchmarkConversionArtifact,
) -> anyhow::Result<TraceBenchmarkRegistryOutboxItem> {
    anyhow::ensure!(
        artifact.registry.status == TraceBenchmarkRegistryStatus::Published,
        "benchmark registry outbox requires published artifact"
    );
    let registry_ref = artifact
        .registry
        .registry_ref
        .clone()
        .context("benchmark registry outbox requires registry_ref")?;
    let artifact_payload_hash = benchmark_artifact_payload_hash(artifact)?;
    let evaluation_score = artifact.evaluation.score;
    if let Some(score) = evaluation_score {
        anyhow::ensure!(
            score.is_finite() && (0.0..=1.0).contains(&score),
            "benchmark registry outbox evaluation score must be between 0 and 1"
        );
    }
    Ok(TraceBenchmarkRegistryOutboxItem {
        benchmark_outbox_id: deterministic_benchmark_registry_outbox_id(
            &tenant.tenant_id,
            artifact.conversion_id,
            StorageTraceBenchmarkRegistryOutboxOperation::Publish,
        ),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        conversion_id: artifact.conversion_id,
        operation: StorageTraceBenchmarkRegistryOutboxOperation::Publish,
        registry_ref,
        artifact_payload_hash,
        source_submission_ids_hash: artifact.source_submission_ids_hash.clone(),
        evaluator_ref: artifact.evaluation.evaluator_ref.clone(),
        evaluation_score,
        status: StorageTraceBenchmarkRegistryOutboxStatus::Pending,
        created_at: Utc::now(),
        submitted_at: None,
        external_receipt_ref: None,
        last_error_hash: None,
        confirmed_at: None,
    })
}

fn benchmark_registry_revoke_outbox_item_from_artifact(
    tenant: &TenantAuth,
    artifact: &TraceBenchmarkConversionArtifact,
) -> anyhow::Result<TraceBenchmarkRegistryOutboxItem> {
    anyhow::ensure!(
        artifact.registry.status == TraceBenchmarkRegistryStatus::Revoked,
        "benchmark registry revoke outbox requires revoked artifact"
    );
    let registry_ref = artifact
        .registry
        .registry_ref
        .clone()
        .context("benchmark registry revoke outbox requires registry_ref")?;
    let artifact_payload_hash = benchmark_artifact_payload_hash(artifact)?;
    let evaluation_score = artifact.evaluation.score;
    if let Some(score) = evaluation_score {
        anyhow::ensure!(
            score.is_finite() && (0.0..=1.0).contains(&score),
            "benchmark registry revoke outbox evaluation score must be between 0 and 1"
        );
    }
    Ok(TraceBenchmarkRegistryOutboxItem {
        benchmark_outbox_id: deterministic_benchmark_registry_outbox_id(
            &tenant.tenant_id,
            artifact.conversion_id,
            StorageTraceBenchmarkRegistryOutboxOperation::Revoke,
        ),
        tenant_id: tenant.tenant_id.clone(),
        tenant_storage_ref: tenant_storage_ref(&tenant.tenant_id),
        conversion_id: artifact.conversion_id,
        operation: StorageTraceBenchmarkRegistryOutboxOperation::Revoke,
        registry_ref,
        artifact_payload_hash,
        source_submission_ids_hash: artifact.source_submission_ids_hash.clone(),
        evaluator_ref: artifact.evaluation.evaluator_ref.clone(),
        evaluation_score,
        status: StorageTraceBenchmarkRegistryOutboxStatus::Pending,
        created_at: Utc::now(),
        submitted_at: None,
        external_receipt_ref: None,
        last_error_hash: None,
        confirmed_at: None,
    })
}

fn deterministic_benchmark_registry_outbox_id(
    tenant_id: &str,
    conversion_id: Uuid,
    operation: StorageTraceBenchmarkRegistryOutboxOperation,
) -> Uuid {
    let input = format!(
        "ironclaw.trace_commons.benchmark_registry_outbox:{tenant_id}:{conversion_id}:{operation:?}"
    );
    Uuid::new_v5(&Uuid::NAMESPACE_URL, input.as_bytes())
}

fn benchmark_artifact_payload_hash(
    artifact: &TraceBenchmarkConversionArtifact,
) -> anyhow::Result<String> {
    let json = serde_json::to_string(artifact)
        .context("failed to serialize benchmark artifact for outbox hash")?;
    Ok(sha256_prefixed(&json))
}

fn normalize_benchmark_lifecycle_ref(value: String) -> ApiResult<Option<String>> {
    let value = value.trim().to_string();
    if value.is_empty() {
        return Ok(None);
    }
    if value.len() > 512 {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "benchmark lifecycle references are limited to 512 characters",
        ));
    }
    Ok(Some(value))
}

